INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('interpretacao-e-inferencia', 'lingua-portuguesa', 'linguagens', 'Interpretação e inferência', 'Separar o que o texto diz do que ele sugere, e reconhecer a intenção de quem escreveu.', 'intro', 15, 95, 1);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('generos-textuais-e-funcao-social', 'lingua-portuguesa', 'linguagens', 'Gêneros textuais e função social', 'Relacionar formato, contexto, público e finalidade — e perceber quando um texto foge do esperado de propósito.', 'intro', 15, 85, 2);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('funcoes-da-linguagem', 'lingua-portuguesa', 'linguagens', 'Funções da linguagem', 'Reconhecer para que serve um texto — informar, convencer, emocionar, aproximar, explicar a própria língua — a partir de marcas concretas no enunciado.', 'intro', 20, 88, 3);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('variacao-linguistica', 'lingua-portuguesa', 'linguagens', 'Variação linguística', 'Entender que a língua varia com região, grupo social, situação e época — e que variedade diferente não é erro, mas adequação a um contexto.', 'intro', 20, 90, 4);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('recursos-expressivos', 'lingua-portuguesa', 'linguagens', 'Recursos expressivos', 'Reconhecer figuras de linguagem e recursos sonoros pelo efeito que produzem no texto, e não apenas pelo nome que recebem.', 'intermediate', 22, 84, 5);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('literatura-brasileira', 'literatura', 'linguagens', 'Literatura brasileira em contexto', 'Relacionar obra, momento histórico e projeto estético — lendo os movimentos literários brasileiros como respostas a questões do seu tempo.', 'intermediate', 25, 82, 1);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('porcentagem-e-variacao', 'matematica', 'matematica', 'Porcentagem e variação', 'Aumento, desconto, variação percentual e a diferença entre variação sobre o valor inicial e sobre o final.', 'intro', 20, 98, 1);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('leitura-de-graficos-e-tabelas', 'matematica', 'matematica', 'Leitura de gráficos e tabelas', 'Extrair, comparar e interpretar dados — e reconhecer quando a apresentação distorce a leitura.', 'intro', 20, 96, 2);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('funcoes-e-relacoes', 'matematica', 'matematica', 'Funções e relações', 'Interpretar relações entre grandezas em tabelas, gráficos e expressões — e reconhecer o que cada modelo permite prever.', 'intermediate', 25, 92, 3);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('razao-e-proporcao', 'matematica', 'matematica', 'Razão e proporção', 'Comparar grandezas por divisão, reconhecer proporcionalidade e usar escalas, densidades e taxas em situações do dia a dia.', 'intro', 20, 92, 4);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('regra-de-tres', 'matematica', 'matematica', 'Regra de três', 'Resolver problemas com grandezas proporcionais, simples ou compostas, decidindo corretamente entre proporção direta e inversa.', 'intro', 20, 90, 5);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('geometria-plana', 'matematica', 'matematica', 'Geometria plana', 'Calcular perímetros e áreas, aplicar o teorema de Pitágoras e resolver problemas reais de terreno, piso, cerca e deslocamento.', 'intermediate', 25, 88, 6);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('estatistica', 'matematica', 'matematica', 'Estatística', 'Calcular e interpretar média, mediana e moda, entender dispersão e reconhecer quando uma medida resume mal os dados.', 'intermediate', 22, 90, 7);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('probabilidade', 'matematica', 'matematica', 'Probabilidade', 'Calcular a chance de eventos simples e compostos, entender independência e ler probabilidade como informação para decisão.', 'intermediate', 22, 86, 8);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('matematica-financeira', 'matematica', 'matematica', 'Matemática financeira', 'Comparar juros simples e compostos, avaliar parcelamentos e descontos e decidir com base em custo total, não em impressão.', 'challenging', 25, 91, 9);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('cidadania-e-direitos', 'sociologia', 'ciencias-humanas', 'Cidadania e direitos', 'Relacionar conceitos sociais, históricos e políticos a situações concretas do cotidiano.', 'intro', 20, 94, 1);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('urbanizacao-e-desigualdade', 'geografia', 'ciencias-humanas', 'Urbanização e desigualdade', 'Interpretar fenômenos espaciais, sociais e econômicos das cidades brasileiras e suas desigualdades internas.', 'intermediate', 25, 90, 2);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('meio-ambiente-e-sociedade', 'geografia', 'ciencias-humanas', 'Meio ambiente e sociedade', 'Analisar impactos, conflitos, políticas e formas de uso do território a partir de casos concretos.', 'intermediate', 25, 88, 3);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('brasil-republica', 'historia', 'ciencias-humanas', 'Brasil República', 'Acompanhar as transformações políticas do Brasil republicano e reconhecer permanências e rupturas entre 1889 e a redemocratização.', 'intermediate', 25, 90, 1);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('industrializacao', 'historia', 'ciencias-humanas', 'Industrialização', 'Entender as transformações produzidas pela industrialização no mundo e no Brasil, e seus efeitos sobre trabalho, cidade e ambiente.', 'intermediate', 24, 87, 2);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('cartografia', 'geografia', 'ciencias-humanas', 'Cartografia', 'Ler mapas com autonomia: escala, projeção, legenda e orientação — e reconhecer que todo mapa é uma escolha, não uma foto do mundo.', 'intro', 20, 86, 3);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('globalizacao', 'geografia', 'ciencias-humanas', 'Globalização', 'Analisar a integração mundial de economia, informação e cultura — e por que ela produz efeitos tão desiguais entre lugares e grupos.', 'intermediate', 24, 88, 4);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('etica', 'filosofia', 'ciencias-humanas', 'Ética', 'Distinguir as principais formas de justificar uma ação — consequências, dever, caráter — e aplicá-las a dilemas concretos.', 'intermediate', 22, 85, 1);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('cultura-e-identidade', 'sociologia', 'ciencias-humanas', 'Cultura e identidade', 'Compreender cultura como construção social e identidade como processo — e reconhecer etnocentrismo, apropriação e diversidade.', 'intermediate', 22, 84, 2);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('trabalho-e-sociedade', 'sociologia', 'ciencias-humanas', 'Trabalho e sociedade', 'Analisar as formas de organização do trabalho, os direitos conquistados e as transformações recentes ligadas à tecnologia e à informalidade.', 'intermediate', 22, 88, 3);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('ecologia-e-ciclos', 'biologia', 'ciencias-natureza', 'Ecologia e ciclos', 'Relacionar seres vivos, energia, matéria e impactos ambientais em cadeias, teias e ciclos biogeoquímicos.', 'intro', 25, 93, 1);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('energia-e-transformacoes', 'fisica', 'ciencias-natureza', 'Energia e transformações', 'Interpretar conservação, consumo e transformação de energia em situações do cotidiano.', 'intermediate', 25, 91, 2);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('transformacoes-quimicas', 'quimica', 'ciencias-natureza', 'Transformações químicas', 'Identificar reagentes, produtos, evidências de reação e proporções básicas entre as substâncias.', 'intermediate', 25, 89, 3);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('genetica-basica', 'biologia', 'ciencias-natureza', 'Genética básica', 'Entender como características são transmitidas, resolver cruzamentos simples e interpretar heredogramas e resultados de exames genéticos.', 'intermediate', 24, 89, 2);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('saude-e-prevencao', 'biologia', 'ciencias-natureza', 'Saúde e prevenção', 'Relacionar agentes causadores, formas de transmissão e medidas de prevenção — e entender vacinação e saúde pública com base em evidência.', 'intro', 22, 91, 3);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('mecanica', 'fisica', 'ciencias-natureza', 'Mecânica', 'Descrever movimentos, aplicar as leis de Newton e usar conservação de energia em situações do cotidiano e do trânsito.', 'intermediate', 25, 88, 3);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('eletricidade', 'fisica', 'ciencias-natureza', 'Eletricidade', 'Relacionar tensão, corrente, resistência e potência, e interpretar consumo elétrico em contas de energia e aparelhos domésticos.', 'intermediate', 24, 90, 4);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('solucoes', 'quimica', 'ciencias-natureza', 'Soluções', 'Trabalhar com concentração, diluição e solubilidade em situações de laboratório, indústria e cotidiano.', 'intermediate', 22, 87, 2);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('estequiometria-introdutoria', 'quimica', 'ciencias-natureza', 'Estequiometria introdutória', 'Usar mol, massa molar e proporções de equações balanceadas para prever quanto se consome e quanto se produz em uma reação.', 'challenging', 25, 85, 3);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('quimica-ambiental', 'quimica', 'ciencias-natureza', 'Química ambiental', 'Entender a química por trás da poluição, do efeito estufa, da chuva ácida e do tratamento de água e resíduos.', 'intermediate', 24, 89, 4);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('tese-e-argumentacao', 'producao-textual', 'linguagens', 'Tese e argumentação', 'Formular um ponto de vista claro e sustentá-lo com argumentos pertinentes e repertório legítimo.', 'intermediate', 25, 97, 1);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('repertorio-sociocultural', 'producao-textual', 'linguagens', 'Repertório sociocultural', 'Selecionar e usar referências externas de forma produtiva — conectadas à tese, e não coladas ao texto como enfeite.', 'intermediate', 22, 89, 2);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('coesao-e-progressao', 'producao-textual', 'linguagens', 'Coesão e progressão textual', 'Amarrar as partes do texto e fazer a ideia avançar: conectivos com sentido correto, retomadas variadas e parágrafos que não repetem.', 'intermediate', 22, 90, 3);
INSERT INTO topics (slug, subject_slug, area_slug, name, summary, difficulty, estimated_minutes, curation_weight, display_order) VALUES ('proposta-de-intervencao', 'producao-textual', 'linguagens', 'Proposta de intervenção', 'Fechar o texto com uma solução concreta, viável e detalhada — ligada aos problemas que o próprio texto levantou.', 'challenging', 24, 93, 4);
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('identificar-informacao-explicita-e-implicita', 'interpretacao-e-inferencia', 'Identificar informações explícitas, implícitas e intenção comunicativa', 'Distinguir o que está escrito, o que é possível concluir com base no texto e o que é opinião de quem lê.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('relacionar-formato-contexto-publico-finalidade', 'generos-textuais-e-funcao-social', 'Relacionar formato, contexto, público e finalidade', 'Reconhecer o gênero de um texto e explicar como sua forma serve ao objetivo e ao leitor previsto.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('identificar-funcao-predominante-da-linguagem', 'funcoes-da-linguagem', 'Identificar a função predominante da linguagem', 'Relacionar marcas linguísticas ao elemento da comunicação em destaque e justificar a escolha com evidência do texto.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('analisar-variacao-e-adequacao-linguistica', 'variacao-linguistica', 'Analisar variação linguística e adequação ao contexto', 'Identificar tipos de variação, avaliar adequação ao contexto de uso e reconhecer o preconceito linguístico como julgamento social, não gramatical.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('relacionar-recurso-expressivo-e-efeito-de-sentido', 'recursos-expressivos', 'Relacionar recurso expressivo e efeito de sentido', 'Identificar figuras e recursos sonoros e explicar o efeito que produzem sobre a leitura, em textos literários e cotidianos.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('relacionar-obra-contexto-e-projeto-estetico', 'literatura-brasileira', 'Relacionar obra, contexto histórico e projeto estético', 'Identificar traços de cada movimento literário brasileiro e explicá-los como resposta a um contexto, sem reduzir a obra a uma lista de características.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('resolver-situacoes-com-variacao-percentual', 'porcentagem-e-variacao', 'Resolver situações com aumento, desconto, proporção e variação percentual', 'Aplicar fatores multiplicativos, calcular variação relativa e identificar sobre qual base o percentual incide.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('extrair-comparar-interpretar-dados', 'leitura-de-graficos-e-tabelas', 'Extrair, comparar e interpretar dados', 'Ler valores, comparar séries, calcular variações e identificar limitações e distorções da representação.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('interpretar-relacoes-entre-grandezas', 'funcoes-e-relacoes', 'Interpretar relações entre grandezas em tabelas, gráficos e expressões', 'Reconhecer padrões de variação, identificar o tipo de relação e traduzir entre as três representações.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('comparar-grandezas-por-razao-e-proporcao', 'razao-e-proporcao', 'Comparar grandezas por razão e proporção', 'Montar razões corretas, verificar proporcionalidade e aplicar escala, densidade e taxa em contextos reais.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('resolver-situacoes-com-regra-de-tres', 'regra-de-tres', 'Resolver situações com regra de três', 'Organizar grandezas, decidir o sentido de cada proporcionalidade e resolver regras de três simples e compostas.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('calcular-e-aplicar-medidas-em-figuras-planas', 'geometria-plana', 'Calcular e aplicar medidas em figuras planas', 'Aplicar perímetro, área e relações métricas do triângulo retângulo em problemas concretos, com atenção às unidades.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('interpretar-medidas-estatisticas-em-contexto', 'estatistica', 'Interpretar medidas estatísticas em contexto', 'Calcular média, mediana e moda, comparar seus significados e avaliar qual resume melhor um conjunto de dados.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('calcular-e-interpretar-probabilidades', 'probabilidade', 'Calcular e interpretar probabilidades', 'Determinar espaço amostral, calcular probabilidades simples e compostas e interpretar o resultado em contextos de decisão.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('avaliar-situacoes-financeiras-com-juros-e-descontos', 'matematica-financeira', 'Avaliar situações financeiras com juros e descontos', 'Calcular juros simples e compostos, comparar formas de pagamento e justificar decisões com base no custo total.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('relacionar-conceitos-a-situacoes-concretas', 'cidadania-e-direitos', 'Relacionar conceitos sociais, históricos e políticos a situações concretas', 'Reconhecer, em casos do dia a dia, quais direitos estão em jogo e que mecanismos existem para efetivá-los.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('interpretar-fenomenos-espaciais-sociais-economicos', 'urbanizacao-e-desigualdade', 'Interpretar fenômenos espaciais, sociais e econômicos', 'Relacionar processos de urbanização, segregação socioespacial e acesso desigual a serviços urbanos.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('analisar-impactos-conflitos-e-uso-do-territorio', 'meio-ambiente-e-sociedade', 'Analisar impactos, conflitos, políticas e formas de uso do território', 'Identificar interesses em disputa, distribuição desigual de custos ambientais e instrumentos de política pública.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('analisar-processos-da-republica-brasileira', 'brasil-republica', 'Analisar processos da República brasileira', 'Relacionar períodos, atores e conflitos da República brasileira a permanências e rupturas na estrutura política e social.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('relacionar-industrializacao-trabalho-e-territorio', 'industrializacao', 'Relacionar industrialização, trabalho e território', 'Analisar efeitos da industrialização sobre organização do trabalho, ocupação do espaço e desigualdade, no Brasil e no mundo.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('ler-e-interpretar-representacoes-cartograficas', 'cartografia', 'Ler e interpretar representações cartográficas', 'Usar escala, legenda, projeção e orientação para extrair informação de mapas e avaliar as escolhas de quem os produziu.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('analisar-processos-e-efeitos-da-globalizacao', 'globalizacao', 'Analisar processos e efeitos da globalização', 'Relacionar fluxos econômicos, tecnológicos e culturais a efeitos desiguais sobre territórios, trabalho e cultura.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('aplicar-teorias-eticas-a-situacoes-concretas', 'etica', 'Aplicar teorias éticas a situações concretas', 'Identificar o critério moral em jogo em um argumento e comparar as conclusões a que diferentes teorias éticas levariam.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('analisar-cultura-identidade-e-diversidade', 'cultura-e-identidade', 'Analisar cultura, identidade e diversidade', 'Aplicar conceitos de cultura, etnocentrismo e identidade a situações concretas de convivência e conflito.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('analisar-transformacoes-do-mundo-do-trabalho', 'trabalho-e-sociedade', 'Analisar transformações do mundo do trabalho', 'Relacionar formas de organização do trabalho, direitos sociais e mudanças tecnológicas a seus efeitos sobre trabalhadores.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('relacionar-seres-vivos-energia-materia-impactos', 'ecologia-e-ciclos', 'Relacionar seres vivos, energia, matéria e impactos ambientais', 'Interpretar fluxo de energia, ciclagem de matéria e efeitos de alterações em cadeias e ecossistemas.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('interpretar-conservacao-consumo-transformacao-energia', 'energia-e-transformacoes', 'Interpretar conservação, consumo e transformação de energia', 'Identificar transformações de energia, calcular consumo elétrico e avaliar eficiência em situações reais.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('identificar-reagentes-produtos-evidencias-proporcoes', 'transformacoes-quimicas', 'Identificar reagentes, produtos, evidências e proporções básicas', 'Distinguir transformação física de química, ler equações balanceadas e aplicar proporções estequiométricas simples.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('aplicar-principios-de-heranca-genetica', 'genetica-basica', 'Aplicar princípios de herança genética', 'Resolver cruzamentos, interpretar heredogramas e relacionar genótipo, fenótipo e probabilidade em situações concretas.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('relacionar-agente-transmissao-e-prevencao', 'saude-e-prevencao', 'Relacionar agente, transmissão e prevenção', 'Identificar agentes causadores, vias de transmissão e medidas de prevenção adequadas, individuais e coletivas.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('aplicar-leis-do-movimento-e-conservacao', 'mecanica', 'Aplicar leis do movimento e conservação de energia', 'Relacionar força, massa, aceleração e energia em situações concretas, interpretando gráficos de movimento.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('analisar-circuitos-e-consumo-eletrico', 'eletricidade', 'Analisar circuitos e consumo elétrico', 'Aplicar a lei de Ohm, calcular potência e consumo e interpretar informações de aparelhos e contas de energia.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('calcular-e-interpretar-concentracoes', 'solucoes', 'Calcular e interpretar concentrações de soluções', 'Aplicar concentração comum, molaridade e diluição, e interpretar curvas de solubilidade.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('calcular-quantidades-em-reacoes-quimicas', 'estequiometria-introdutoria', 'Calcular quantidades em reações químicas', 'Relacionar massa, mol e proporção estequiométrica para prever consumo e produção em reações balanceadas.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('relacionar-processos-quimicos-e-impactos-ambientais', 'quimica-ambiental', 'Relacionar processos químicos e impactos ambientais', 'Explicar fenômenos ambientais por seus processos químicos e avaliar medidas de mitigação e tratamento.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('formular-tese-e-sustentar-com-argumentos', 'tese-e-argumentacao', 'Formular ponto de vista e sustentá-lo com argumentos pertinentes', 'Construir tese clara e defensável, organizar argumentos com progressão e usar repertório de forma produtiva.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('selecionar-e-articular-repertorio-sociocultural', 'repertorio-sociocultural', 'Selecionar e articular repertório sociocultural', 'Escolher referências pertinentes e integrá-las ao argumento, explicitando a relação com a tese defendida.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('construir-coesao-e-progressao-no-texto', 'coesao-e-progressao', 'Construir coesão e progressão no texto', 'Empregar conectivos adequados ao sentido pretendido, retomar termos sem repetição e garantir avanço de ideias entre parágrafos.');
INSERT INTO skills (slug, topic_slug, name, description) VALUES ('elaborar-proposta-de-intervencao-detalhada', 'proposta-de-intervencao', 'Elaborar proposta de intervenção detalhada', 'Construir propostas com agente, ação, meio, finalidade e detalhamento, articuladas aos argumentos desenvolvidos.');
