INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-interp-1', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'intro', 'concept', false, 'Leia o trecho:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-1', 'A', 'A personagem estava atrasada para um compromisso.', false, 'Nada no trecho menciona horário, pressa ou compromisso. É informação acrescentada por quem lê.', 'extrapolação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-1', 'B', 'A personagem não gosta de usar casaco.', false, 'Tirar o casaco molhado ao chegar em casa é comportamento comum e não revela preferência alguma.', 'inferência sobre personalidade sem pista');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-1', 'C', 'O celular da personagem parou de funcionar.', false, 'O texto não menciona funcionamento do aparelho. Concluir isso exige uma cadeia de suposições que o trecho não sustenta.', 'encadeamento de suposições');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-1', 'D', 'A personagem estava na chuva antes de chegar em casa.', true, 'O casaco "encharcado" é a pista. O texto não diz "choveu", mas obriga a concluir que houve contato com muita água antes de entrar — a leitura mais direta e sustentada.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-1', 'E', 'A personagem perdeu o celular naquele dia.', false, 'O texto diz que ela percebeu que o celular estava no bolso, ou seja, ele está com ela. Perder é o oposto do que o texto informa.', 'leitura apressada do final da frase');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-interp-2', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'intermediate', 'applied', false, 'Uma placa em um parque público informa:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-2', 'A', 'Aproximar a consequência do descarte de uma situação concreta e imediata para quem lê.', true, 'Falar de "natureza" é abstrato e distante; falar da "próxima família" transforma a consequência em algo visível e próximo, aumentando a chance de adesão.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-2', 'B', 'Informar que o parque é destinado exclusivamente a famílias.', false, 'A menção é um exemplo de quem virá depois, não uma regra de acesso. O texto não restringe o público.', 'leitura literal de um exemplo como se fosse regra');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-2', 'C', 'Indicar que a limpeza do parque é responsabilidade da administração pública.', false, 'O texto faz o oposto: atribui a responsabilidade a quem trouxe o material ("recolha o que trouxe").', 'inverter o sujeito da responsabilidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-2', 'D', 'Criar um tom de ameaça para desestimular o uso do parque.', false, 'Não há ameaça: o verbo "agradece" e a construção afirmativa criam tom cordial, não punitivo.', 'atribuir tom que o vocabulário não sustenta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-2', 'E', 'Explicar tecnicamente o tempo de decomposição dos resíduos.', false, 'Não há nenhuma informação técnica no texto. A placa não explica processos, apenas pede um comportamento.', 'buscar informação que não está presente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-interp-3', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'intermediate', 'interpretation', false, 'Leia o comentário publicado em um site de notícias sobre transporte público:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-3', 'A', 'Dúvida quanto à veracidade do percentual divulgado.', false, 'O autor aceita o número de 4% e trabalha a partir dele. A crítica é ao efeito prático, não à veracidade.', 'deslocar o alvo da crítica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-3', 'B', 'Exagero técnico, próprio da linguagem estatística.', false, 'Linguagem estatística não usa adjetivos avaliativos como "gloriosos". A marca é de opinião, não de técnica.', 'confundir registro opinativo com técnico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-3', 'C', 'Ironia, que reforça a crítica à insuficiência da medida.', true, 'Um adjetivo grandioso ("gloriosos") aplicado a um ganho mínimo (2 minutos) cria contraste evidente. Esse contraste é a marca da ironia.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-3', 'D', 'Elogio sincero ao esforço de ampliação da frota.', false, 'O elogio não se sustenta: o próprio texto expõe que o ganho é de 2 minutos e usa "no melhor cenário possível", enfraquecendo ainda mais o resultado.', 'leitura literal de ironia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-3', 'E', 'Neutralidade, já que o autor apenas apresenta os números.', false, 'Se fosse neutro, o autor não escolheria um adjetivo carregado. A escolha lexical marca posição.', 'confundir presença de dados com neutralidade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-interp-4', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'challenging', 'comparison', false, 'Sobre o mesmo comentário ("Ampliaram a frota em 4%. Com isso, quem espera 40 minutos passará a esperar, no melhor cenário possível, uns gloriosos 38."), duas leituras foram propostas:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-4', 'A', 'II, apenas.', false, 'O próprio texto admite a redução de 2 minutos. Dizer "nenhuma melhora" contraria o que está escrito.', 'transformar crítica de grau em negação total');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-4', 'B', 'I e II.', false, 'I está correta, mas II extrapola. Basta uma afirmação falsa para invalidar a alternativa.', 'não verificar cada afirmação separadamente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-4', 'C', 'Nenhuma das duas.', false, 'I é sustentada com clareza pelo contraste entre o adjetivo grandioso e o ganho mínimo.', 'excesso de cautela');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-4', 'D', 'I e II, desde que o percentual seja confirmado.', false, 'A validade de II não depende do percentual: mesmo com os números aceitos, "nenhuma melhora" continua contrariando o texto.', 'condicionar a resposta a um dado irrelevante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-4', 'E', 'I, apenas.', true, 'O texto reconhece uma melhora (de 40 para 38 minutos) e a considera desproporcional ao problema. Isso valida I e invalida II, que nega qualquer melhora.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-interp-5', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'challenging', 'integration', false, 'Uma campanha de saúde pública sobre hidratação distribuiu dois materiais com a mesma informação:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-5', 'A', 'No grau de formalidade, sem qualquer efeito sobre a função do texto.', false, 'A formalidade realmente muda, mas ela não é neutra: a escolha do registro é justamente o que produz a diferença de função.', 'perceber a forma e ignorar o efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-5', 'B', 'Na função predominante: o primeiro prioriza informar com precisão; o segundo prioriza mobilizar a atenção do leitor.', true, 'O Material 1 traz dado numérico e ressalvas técnicas. O Material 2 usa pergunta direta e segunda pessoa para provocar reação imediata. A informação de fundo é a mesma; o que muda é o propósito da abordagem.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-5', 'C', 'Na veracidade: o segundo material apresenta informação incorreta.', false, 'A perda de líquido pela respiração é fato. Não há erro factual, apenas escolha de abordagem.', 'confundir informalidade com imprecisão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-5', 'D', 'No público: o primeiro se dirige a profissionais de saúde e o segundo, a pacientes.', false, 'Nada nos textos indica destinatário profissional. Ambos usam linguagem acessível ao público geral.', 'inferir público sem marca textual');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-5', 'E', 'Na quantidade de informação: o segundo material é incompleto por não trazer números.', false, '"Incompleto" pressupõe que o objetivo fosse informar quantidade. Para mobilizar atenção, o número não é necessário — a ausência é escolha, não falha.', 'avaliar um gênero pelos critérios de outro');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-interp-rec-1', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'intro', 'concept', true, 'Leia:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-rec-1', 'A', 'O bilhete contém uma má notícia.', false, 'O conteúdo do bilhete não é mencionado em momento algum.', 'extrapolação sobre conteúdo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-rec-1', 'B', 'A pessoa que escreveu saiu de casa.', false, 'O texto não informa onde está quem escreveu. Ela pode estar na sala ao lado.', 'inferência sobre ação não mencionada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-rec-1', 'C', 'A mesa fica em um escritório.', false, 'Nenhum elemento identifica o ambiente.', 'inferir cenário sem pista');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-rec-1', 'D', 'O bilhete era endereçado a mais de uma pessoa.', false, 'O destinatário não é mencionado.', 'inferir destinatário sem pista');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-rec-1', 'E', 'O bilhete foi escrito há pouco tempo.', true, 'A caneta "ainda destampada" é a pista: quem escreveu não teve tempo ou intenção de guardá-la, o que sugere proximidade temporal.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-interp-rec-2', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'intermediate', 'applied', true, 'Um cartaz de biblioteca diz: "Silêncio. Alguém aqui está começando a gostar de ler."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-rec-2', 'A', 'Informar quantas pessoas frequentam a biblioteca.', false, '"Alguém" é indefinido de propósito e não traz dado quantitativo.', 'ler "alguém" como número');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-rec-2', 'B', 'Restringir o acesso a leitores iniciantes.', false, 'Não há qualquer restrição de acesso no texto.', 'ler exemplo como regra');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-rec-2', 'C', 'Substituir a regra de silêncio por uma sugestão opcional.', false, 'A regra continua: a primeira frase é imperativa. A segunda apenas a justifica.', 'achar que justificar enfraquece a regra');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-rec-2', 'D', 'Indicar que a biblioteca oferece cursos de leitura.', false, 'Nenhum serviço é mencionado.', 'acrescentar informação ausente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-rec-2', 'E', 'Justificar o pedido, dando a ele um motivo concreto e simpático.', true, '"Silêncio" sozinho é ordem seca. A segunda frase transforma a ordem em pedido com razão visível, o que aumenta a adesão.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-interp-6', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'intro', 'concept', false, 'Em um aviso de biblioteca lê-se: “Os livros devolvidos após as 18h serão registrados no próximo dia útil. Planeje a devolução para evitar bloqueios temporários.” O aviso permite inferir que:', 'O aviso relaciona o registro posterior à possibilidade de bloqueio temporário. Essa é a inferência apoiada pelo texto, sem inventar horário, multa ou proibição.', 'O aviso relaciona o registro posterior à possibilidade de bloqueio temporário. Essa é a inferência apoiada pelo texto, sem inventar horário, multa ou proibição.', 'Localize as duas informações conectadas pelo aviso e rejeite conclusões que acrescentem uma penalidade não mencionada.', NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-6', 'A', 'A biblioteca fecha exatamente às 18h.', false, 'O horário de fechamento não foi informado; apenas o processamento muda após esse horário.', 'inferir dado ausente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-6', 'B', 'Toda devolução após as 18h gera multa financeira.', false, 'O texto menciona bloqueio temporário, não multa.', 'trocar consequência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-6', 'C', 'O momento do registro pode afetar temporariamente o acesso do usuário a novos empréstimos.', true, 'O encadeamento entre registro no dia seguinte e prevenção de bloqueios sustenta essa conclusão.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-6', 'D', 'Livros devolvidos após as 18h ficam sem registro definitivo.', false, 'O registro ocorre no próximo dia útil, portanto não é perdido.', 'ignorar marcador temporal');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-6', 'E', 'A devolução depois das 18h é proibida.', false, 'O aviso explica como ela será registrada, o que indica que a devolução é possível.', 'transformar orientação em proibição');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-interp-7', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'intermediate', 'applied', false, 'Uma campanha de economia de água afirma: “Cinco minutos a menos no banho não resolvem sozinhos a crise hídrica. Mas milhões de banhos menores mudam a escala do problema.” A estratégia argumentativa central é:', 'A campanha evita uma promessa exagerada e sustenta que pequenas reduções ganham impacto quando repetidas por muitas pessoas.', 'A campanha evita uma promessa exagerada e sustenta que pequenas reduções ganham impacto quando repetidas por muitas pessoas.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-7', 'A', 'Substituir políticas públicas por decisões privadas.', false, 'Nenhuma comparação com políticas públicas aparece no texto.', 'introduzir oposição ausente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-7', 'B', 'Apresentar uma medição científica do consumo nacional.', false, 'Não há dados, método ou resultado de medição; trata-se de argumento de escala.', 'confundir argumento com pesquisa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-7', 'C', 'Culpar exclusivamente o indivíduo pela crise.', false, 'O texto reconhece que uma ação individual isolada não resolve o problema.', 'generalização');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-7', 'D', 'Reconhecer o limite da ação individual e mostrar o efeito de sua repetição coletiva.', true, 'A primeira frase faz a ressalva; a segunda amplia o efeito pela escala coletiva.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-7', 'E', 'Negar que hábitos domésticos tenham qualquer relevância.', false, 'A segunda frase afirma justamente que a soma dos hábitos altera a escala.', 'ignorar contraste');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-interp-8', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'intermediate', 'interpretation', false, 'Leia: “A prefeitura inaugurou três pontos de internet gratuita. No bairro mais afastado, porém, o sinal só alcança a praça central, distante quarenta minutos a pé de parte dos moradores.” O conectivo “porém” orienta o leitor a:', '“Porém” introduz uma limitação que impede uma leitura triunfalista do anúncio: o serviço existe, mas não é igualmente acessível.', '“Porém” introduz uma limitação que impede uma leitura triunfalista do anúncio: o serviço existe, mas não é igualmente acessível.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-8', 'A', 'Entender que a praça central foi escolhida por votação popular.', false, 'Não há informação sobre processo de escolha.', 'inventar causa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-8', 'B', 'Concluir que os três pontos deixaram de funcionar.', false, 'O texto discute alcance, não funcionamento.', 'trocar alcance por falha total');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-8', 'C', 'Interpretar a distância como vantagem do serviço.', false, 'A distância aparece como obstáculo para parte dos moradores.', 'inverter avaliação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-8', 'D', 'Reavaliar o anúncio positivo à luz de uma limitação concreta de acesso.', true, 'O contraste desloca o foco da inauguração para a dificuldade de acesso em um bairro.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-8', 'E', 'Desconsiderar a primeira frase por ela ser falsa.', false, 'O contraste não torna a inauguração falsa; apenas a qualifica.', 'confundir ressalva com refutação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-interp-9', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'challenging', 'comparison', false, 'Dois títulos descrevem o mesmo dado: I. “Desemprego cai 0,2 ponto e mantém tendência de melhora.” II. “Desemprego quase não muda e ainda atinge milhões.” A comparação mostra que:', 'Os dois títulos podem ser factualmente compatíveis e ainda orientar leituras distintas ao destacar direção ou magnitude da mudança.', 'Os dois títulos podem ser factualmente compatíveis e ainda orientar leituras distintas ao destacar direção ou magnitude da mudança.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-9', 'A', 'O mesmo dado pode ser enquadrado como tendência positiva ou como mudança insuficiente.', true, '“Melhora” destaca direção; “quase não muda” destaca pequena magnitude.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-9', 'B', 'Somente o primeiro título contém informação quantitativa.', false, 'Ambos partem do mesmo dado, embora só o primeiro explicite o valor no trecho.', 'confundir explicitação com existência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-9', 'C', 'O segundo título necessariamente inventa o número de desempregados.', false, 'Dizer que há milhões pode ser compatível com o mesmo dado; faltam elementos para acusar invenção.', 'julgar sem evidência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-9', 'D', 'Os títulos são equivalentes porque se referem ao mesmo indicador.', false, 'A seleção lexical orienta avaliações diferentes, apesar do dado comum.', 'ignorar escolha lexical');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-9', 'E', 'O primeiro é neutro, enquanto apenas o segundo expressa avaliação.', false, '“Mantém tendência de melhora” também enquadra o dado positivamente.', 'naturalizar um enquadramento');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-interp-10', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'challenging', 'integration', false, 'Um gráfico mostra aumento de matrículas em cursos técnicos, e o texto que o acompanha afirma: “O dado confirma que todo jovem agora prefere formação técnica à universidade.” A leitura crítica adequada é:', 'A expressão “todo jovem” universaliza um dado agregado, e “prefere” atribui motivação que o gráfico de matrículas não mede diretamente.', 'A expressão “todo jovem” universaliza um dado agregado, e “prefere” atribui motivação que o gráfico de matrículas não mede diretamente.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-10', 'A', 'O gráfico deveria ser ignorado porque números não ajudam a interpretar educação.', false, 'Dados são úteis; o problema é o salto entre o dado e uma conclusão absoluta.', 'rejeição total da evidência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-10', 'B', 'A universidade deixou de receber matrículas no mesmo período.', false, 'Nada foi informado sobre matrículas universitárias.', 'inferir série ausente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-10', 'C', 'Cursos técnicos e universidades têm necessariamente o mesmo público.', false, 'O dado não descreve perfil do público nem exige equivalência.', 'suposição demográfica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-10', 'D', 'O aumento de matrículas não basta para provar a preferência de todos nem a rejeição da universidade.', true, 'O dado registra comportamento agregado e não mede, sozinho, preferência universal ou escolha exclusiva.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-interp-10', 'E', 'A conclusão é válida porque todo crescimento numérico revela preferência individual.', false, 'Matrícula pode crescer por oferta, políticas, renda ou mercado; preferência não é a única causa.', 'causalidade simplificada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-int-1', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'intro', 'concept', false, 'Um texto afirma: "Mesmo com a chuva, o estádio estava cheio". A palavra "mesmo" indica que o autor considera a chuva um fator que:', 'Conectivos concessivos marcam um obstáculo cujo efeito esperado não se confirmou. Ler o conectivo é ler a relação entre as duas partes.', 'Conectivos concessivos marcam um obstáculo cujo efeito esperado não se confirmou. Ler o conectivo é ler a relação entre as duas partes.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-1', 'A', 'tornou o jogo mais atraente para o público.', false, 'O texto não sugere que a chuva tenha atraído alguém.', 'inferência sem base');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-1', 'B', 'causou a lotação do estádio.', false, 'Se a chuva causasse a lotação, o conectivo seria de causa, não de concessão.', 'trocar concessão por causa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-1', 'C', 'normalmente esvaziaria o estádio, mas não esvaziou.', true, 'A concessão apresenta um obstáculo esperado cujo efeito previsto não se realizou.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-1', 'D', 'não teve relação alguma com o público presente.', false, 'Se não houvesse relação, mencioná-la seria irrelevante.', 'anular a relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-1', 'E', 'é a informação principal do enunciado.', false, 'A informação principal é o estádio cheio; a chuva é o pano de fundo.', 'inverter a hierarquia');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-int-2', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'intermediate', 'applied', false, 'Leia: "A prefeitura informou que as obras seriam concluídas em março. Em julho, os moradores ainda desviavam do buraco." A segunda frase cumpre no texto a função de:', 'Textos constroem sentido também pela ordem em que colocam as informações. Aqui o contraste é inferido pela justaposição, e não afirmado.', 'Textos constroem sentido também pela ordem em que colocam as informações. Aqui o contraste é inferido pela justaposição, e não afirmado.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-2', 'A', 'confirmar a informação dada pela prefeitura.', false, 'Ela faz o oposto: mostra que o prazo não se cumpriu.', 'inverter a relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-2', 'B', 'contrapor o prazo anunciado ao que se observa na rua.', true, 'A justaposição de "março" e "em julho ainda" cria o contraste sem que ele seja dito com todas as letras.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-2', 'C', 'explicar as causas do atraso da obra.', false, 'Nenhuma causa é mencionada.', 'atribuir explicação ausente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-2', 'D', 'detalhar tecnicamente o cronograma da obra.', false, 'Nenhum detalhe técnico é apresentado.', 'atribuir função inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-2', 'E', 'apresentar a opinião dos moradores sobre a prefeitura.', false, 'Não há fala nem avaliação dos moradores no texto.', 'inventar voz');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-int-3', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'intermediate', 'interpretation', false, 'Uma crônica termina assim: "Fechei o caderno, olhei a janela e decidi que amanhã eu ligaria para ela — como venho decidindo há três anos." O efeito final construído pelo trecho é o de:', 'O fecho de um texto pode reconfigurar tudo o que veio antes. Aqui um complemento curto converte decisão em procrastinação.', 'O fecho de um texto pode reconfigurar tudo o que veio antes. Aqui um complemento curto converte decisão em procrastinação.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-3', 'A', 'reforçar a determinação do narrador em resolver a situação.', false, 'O trecho final retira justamente a força da decisão.', 'ler sem o complemento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-3', 'B', 'informar ao leitor há quanto tempo os dois não se falam.', false, 'O período citado se refere às decisões, não necessariamente ao último contato.', 'leitura literal parcial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-3', 'C', 'indicar que o narrador esqueceu o assunto ao longo dos anos.', false, 'Ele não esqueceu: decide de novo, repetidamente.', 'contradizer o texto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-3', 'D', 'sugerir que a interlocutora se recusa a atender.', false, 'Nada no trecho fala sobre a reação dela.', 'inferência sem base');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-3', 'E', 'desmentir a decisão anunciada, revelando um adiamento repetido.', true, 'O complemento "há três anos" transforma a decisão em hábito de adiar, invertendo o que a frase parecia afirmar.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-int-4', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'intermediate', 'comparison', false, 'Sobre a diferença entre uma informação explícita e uma inferência válida em um texto, é correto afirmar que:', 'Inferência não é palpite. Ela se distingue da leitura explícita pelo modo de apresentação, e da invenção pela possibilidade de ser justificada no texto.', 'Inferência não é palpite. Ela se distingue da leitura explícita pelo modo de apresentação, e da invenção pela possibilidade de ser justificada no texto.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-4', 'A', 'a informação explícita é sempre mais importante que a inferida.', false, 'Importância depende do texto, não do modo como a informação aparece.', 'hierarquia inventada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-4', 'B', 'a explícita está escrita; a inferência válida não está escrita, mas é sustentada por elementos do texto.', true, 'O critério de validade é a ancoragem: uma inferência precisa ser defensável com trechos do próprio texto.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-4', 'C', 'inferir é preencher lacunas com conhecimento de mundo, independentemente do texto.', false, 'Conhecimento de mundo ajuda, mas a inferência precisa se apoiar no que o texto oferece.', 'desconectar do texto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-4', 'D', 'quem infere corretamente sempre chega à intenção do autor.', false, 'A intenção do autor nem sempre é recuperável; o que se recupera é o sentido construído.', 'confundir sentido com intenção');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-4', 'E', 'toda inferência é uma opinião do leitor sobre o texto.', false, 'Opinião pessoal não se sustenta no texto; inferência válida, sim.', 'confundir inferência com opinião');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-int-5', 'interpretacao-e-inferencia', 'identificar-informacao-explicita-e-implicita', 'challenging', 'integration', false, 'Uma notícia informa: "Segundo a empresa, o vazamento foi contido em duas horas". Um comentarista escreve que "o vazamento durou apenas duas horas". Sobre a passagem de um enunciado ao outro:', 'Marcadores de fonte não são enfeite: eles dizem quem responde pela informação. Apagá-los muda o que o texto afirma.', 'Marcadores de fonte não são enfeite: eles dizem quem responde pela informação. Apagá-los muda o que o texto afirma.', 'Ao reescrever ou resumir, verifique se a atribuição de fonte sobreviveu. É o primeiro elemento a se perder e o que mais muda o sentido.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-5', 'A', 'o primeiro é tendencioso por citar a empresa.', false, 'Citar a fonte é o procedimento correto, não um viés.', 'inverter o critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-5', 'B', 'o segundo apaga a fonte e transforma uma declaração da parte interessada em fato apurado.', true, '"Segundo a empresa" marca de quem é a afirmação; sem essa marca, a declaração passa a valer como fato verificado.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-5', 'C', 'são equivalentes, pois trazem o mesmo dado numérico.', false, 'O dado é o mesmo, mas o estatuto dele muda.', 'reduzir texto a número');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-5', 'D', 'o segundo é mais preciso, por ser mais direto.', false, 'Ser mais direto aqui significa omitir quem afirma.', 'confundir concisão com precisão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-int-5', 'E', 'o segundo corrige o primeiro, que era vago.', false, 'O primeiro não é vago: ele atribui a informação a uma fonte.', 'inverter a avaliação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-gen-1', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'intro', 'concept', false, 'Um texto apresenta a seguinte estrutura: título curto em destaque, primeiro parágrafo respondendo quem, o quê, quando e onde, e os parágrafos seguintes com detalhes em ordem decrescente de importância.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-1', 'A', 'Artigo de opinião — apresenta a tese no início para depois sustentá-la.', false, 'Artigo de opinião abre com um ponto de vista a ser defendido, não com quem/o quê/quando/onde. Faltam as marcas de posicionamento.', 'confundir "informação primeiro" com "tese primeiro"');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-1', 'B', 'Relatório técnico — organiza os dados por ordem cronológica de coleta.', false, 'O texto descrito organiza por importância, não por cronologia, e relatórios técnicos costumam ter seções fixas.', 'confundir ordem de importância com ordem cronológica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-1', 'C', 'Crônica — parte de um fato cotidiano para uma reflexão pessoal.', false, 'Não há marca de subjetividade nem de reflexão na estrutura descrita.', 'identificar gênero sem verificar as marcas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-1', 'D', 'Edital — precisa listar requisitos de forma exaustiva e sem ambiguidade.', false, 'Edital não usa pirâmide invertida: ele precisa ser completo e é organizado por itens normativos.', 'associar formalidade a qualquer gênero institucional');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-1', 'E', 'Notícia — permite que o leitor obtenha o essencial mesmo se interromper a leitura no início.', true, 'A estrutura descrita é a pirâmide invertida, característica da notícia: o mais importante vem primeiro justamente porque a leitura pode parar a qualquer momento.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-gen-2', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'intermediate', 'applied', false, 'Uma prefeitura precisa comunicar a mudança do ponto final de uma linha de ônibus. Foram produzidos: (1) um aviso impresso colado no ponto antigo e (2) uma publicação no perfil oficial da prefeitura em uma rede social.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-2', 'A', 'O aviso impresso deve conter opinião da administração sobre a mudança.', false, 'Um aviso operacional informa; opinião é função de outro gênero.', 'atribuir função de opinião a texto informativo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-2', 'B', 'O suporte e a situação de leitura são diferentes: no ponto, lê-se de pé e com pressa; na rede, a leitura é voluntária e pode incluir mais contexto.', true, 'A forma acompanha a condição real de leitura. No ponto, a informação precisa ser imediata e visual; na rede, cabe explicação, imagem e resposta a comentários.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-2', 'C', 'O aviso impresso precisa ser formal e a rede social exige linguagem incorreta.', false, 'Informalidade não é incorreção. Um perfil institucional escreve de forma adequada, apenas com registro mais próximo.', 'confundir informalidade com erro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-2', 'D', 'A publicação em rede social não tem valor oficial, então pode omitir a informação principal.', false, 'Um comunicado oficial não pode omitir o essencial em nenhum suporte — isso frustraria a função.', 'confundir informalidade com falta de compromisso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-2', 'E', 'O público é o mesmo, portanto a diferença é apenas estética.', false, 'A situação de leitura muda mesmo quando o público é o mesmo, e isso tem efeito funcional, não estético.', 'reduzir adequação a estilo');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-gen-3', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'intermediate', 'interpretation', false, 'Leia a peça de campanha:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-3', 'A', 'Informar corretamente a composição química de um medicamento.', false, 'Não há medicamento algum: "composição: 2 segundos de distração" é uso figurado do campo.', 'leitura literal da quebra de expectativa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-3', 'B', 'Confundir o leitor para que ele leia o texto até o final por engano.', false, 'O recurso depende do reconhecimento imediato do formato — se confundisse, não funcionaria.', 'confundir estranhamento com confusão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-3', 'C', 'Substituir a legislação de trânsito por uma recomendação médica.', false, 'A campanha não trata de norma legal nem propõe substituição de regra.', 'extrapolar consequência institucional');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-3', 'D', 'Demonstrar que campanhas de trânsito devem sempre usar linguagem técnica.', false, 'Uma peça isolada não estabelece regra geral, e o texto não faz essa defesa.', 'generalizar a partir de um caso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-3', 'E', 'Aproximar o uso do celular ao volante de um risco médico, emprestando a seriedade técnica associada à bula.', true, 'O formato de bula carrega autoridade e sobriedade. Ao vestir a campanha com ele, o texto trata a distração como risco à saúde, evitando o tom de sermão.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-gen-4', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'challenging', 'comparison', false, 'Compare os dois trechos, ambos sobre a mesma vaga de emprego:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-4', 'A', 'O trecho I é inadequado por ser impessoal demais para um anúncio.', false, 'Impessoalidade é adequada quando o objetivo é filtrar candidatos por critérios objetivos.', 'julgar adequação sem considerar a finalidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-4', 'B', 'O trecho II se dirige a um público mais velho, por usar linguagem coloquial.', false, 'Não há marca no texto que permita definir faixa etária do público.', 'inferir público sem evidência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-4', 'C', 'O trecho I prioriza precisão verificável; o II prioriza aproximação, ao custo de deixar critérios menos definidos.', true, 'I lista requisitos objetivamente verificáveis. II cria identificação, mas "alguns sábados" e "curte lidar com gente" não são critérios checáveis. Cada escolha tem ganho e custo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-4', 'D', 'O trecho II está incorreto por não usar norma padrão.', false, 'O trecho II é adequado ao registro escolhido; informalidade planejada não é incorreção.', 'confundir registro com erro gramatical');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-4', 'E', 'Os dois trechos transmitem exatamente a mesma informação.', false, 'II omite escolaridade e experiência mínima — informações presentes em I.', 'não conferir o conteúdo item a item');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-gen-5', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'challenging', 'integration', false, 'Uma escola pediu que os estudantes transformassem uma reportagem sobre desperdício de alimentos em um cartaz para o refeitório.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-5', 'A', 'Selecionar um dado de impacto, escrever uma frase curta orientada à ação e usar hierarquia visual forte.', true, 'O cartaz é lido de passagem, por quem está prestes a servir o prato. Precisa de um dado que impacte, uma ação clara e leitura em segundos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-5', 'B', 'Reproduzir a reportagem integralmente para preservar a informação original.', false, 'Um texto longo no refeitório não será lido: preservar o texto destrói a função.', 'confundir fidelidade ao conteúdo com fidelidade à forma');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-5', 'C', 'Manter a estrutura de pirâmide invertida com título, lide e parágrafos de apoio.', false, 'A pirâmide invertida serve à notícia, não ao cartaz. O suporte mudou, a estrutura precisa mudar.', 'transportar a estrutura do gênero de origem');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-5', 'D', 'Substituir todos os dados por opiniões dos estudantes para tornar o texto mais pessoal.', false, 'Trocar dados por opinião enfraquece a credibilidade sem ganho de função.', 'confundir aproximação com abandono da informação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-5', 'E', 'Usar linguagem técnica sobre cadeia produtiva para demonstrar profundidade.', false, 'Linguagem técnica afasta o público previsto e não gera a ação pretendida.', 'confundir profundidade com adequação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-gen-rec-1', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'intro', 'concept', true, 'Um texto começa assim: "Art. 1º Fica instituído, no âmbito do município, o programa de..." 
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-rec-1', 'A', 'Brevidade máxima, para caber em um único parágrafo.', false, 'Normas costumam ser longas: completude importa mais que brevidade.', 'associar clareza a tamanho');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-rec-1', 'B', 'Uso de linguagem coloquial para ampliar o alcance.', false, 'Coloquialidade aumentaria a ambiguidade, o que é incompatível com a função normativa.', 'confundir acessibilidade com informalidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-rec-1', 'C', 'Apresentação de opinião do autor sobre o programa.', false, 'Norma não expressa opinião individual; ela institui regra.', 'confundir texto oficial com texto opinativo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-rec-1', 'D', 'Precisão sem ambiguidade, porque o texto produz efeitos obrigatórios.', true, 'Textos normativos precisam ser interpretados da mesma forma por qualquer leitor, já que criam obrigações. Daí a linguagem repetitiva e delimitada.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-rec-1', 'E', 'Emoção, para aproximar o leitor do tema tratado.', false, 'Texto normativo evita apelo emocional justamente para não abrir interpretação.', 'atribuir função de outro gênero');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-gen-rec-2', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'intermediate', 'applied', true, 'Uma mesma informação — o horário de funcionamento de uma unidade de saúde — aparece em um cartaz na porta e em uma mensagem automática de atendimento por telefone.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-rec-2', 'A', 'Um texto é lido e o outro é ouvido, o que muda ritmo, repetição e ordem da informação.', true, 'Quem ouve não pode reler: a mensagem falada precisa repetir o essencial e usar frases mais curtas e pausadas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-rec-2', 'B', 'O cartaz pode conter informação incorreta, já que não é oficial.', false, 'Ambos são comunicações da mesma unidade e devem ser corretos.', 'associar suporte a confiabilidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-rec-2', 'C', 'A mensagem telefônica se dirige a profissionais de saúde.', false, 'Nada indica público profissional; o atendimento é ao público geral.', 'inferir público sem evidência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-rec-2', 'D', 'O cartaz precisa de linguagem mais rebuscada por estar exposto ao público.', false, 'Exposição pública pede clareza, não rebuscamento.', 'associar formalidade a qualidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-rec-2', 'E', 'Não há diferença real: os dois textos podem ser idênticos.', false, 'Podem até trazer as mesmas palavras, mas a mensagem falada perde eficiência sem repetição e pausa.', 'ignorar a diferença entre ler e ouvir');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-gen-6', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'intro', 'concept', false, 'Um aplicativo exibe a mensagem: “Atualização disponível. Instale agora ou escolha um horário; durante o processo, o aparelho reiniciará.” Esse texto cumpre principalmente a função de:', 'O aviso combina instrução e antecipação de consequência para apoiar uma escolha imediata do usuário.', 'O aviso combina instrução e antecipação de consequência para apoiar uma escolha imediata do usuário.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-6', 'A', 'Orientar uma decisão imediata e antecipar uma consequência da ação.', true, 'A mensagem oferece escolhas e informa o reinício para que o usuário decida.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-6', 'B', 'Divulgar uma opinião sobre a qualidade do aparelho.', false, 'Não há avaliação do produto.', 'atribuir opinião ausente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-6', 'C', 'Ensinar detalhadamente o funcionamento do sistema operacional.', false, 'A instrução é breve e operacional, não uma aula técnica.', 'confundir aviso com manual');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-6', 'D', 'Registrar oficialmente uma reclamação.', false, 'Não há relato de problema nem destinatário institucional.', 'identificar gênero incompatível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-6', 'E', 'Narrar como o sistema foi desenvolvido.', false, 'Não há sequência narrativa sobre desenvolvimento.', 'confundir tema tecnológico com narrativa');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-gen-7', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'intermediate', 'applied', false, 'Uma associação de moradores quer registrar formalmente pedidos, responsáveis e prazos acordados com a prefeitura em uma reunião. O gênero mais adequado é:', 'A necessidade de memória formal, responsáveis e prazos corresponde à função social de uma ata.', 'A necessidade de memória formal, responsáveis e prazos corresponde à função social de uma ata.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-7', 'A', 'Crônica.', false, 'A crônica pode refletir sobre a reunião, mas não formaliza compromissos.', 'privilegiar tema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-7', 'B', 'Tutorial.', false, 'Tutorial ensina um procedimento; não documenta o que foi decidido.', 'trocar instrução por documentação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-7', 'C', 'Ata de reunião.', true, 'A ata registra participantes, decisões, responsabilidades e encaminhamentos com valor documental.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-7', 'D', 'Resenha.', false, 'Resenha avalia uma obra ou produção, não um acordo administrativo.', 'gênero sem relação funcional');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-7', 'E', 'Anúncio publicitário.', false, 'Publicidade busca promover algo, não produzir registro verificável de decisões.', 'confundir divulgação com registro');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-gen-8', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'intermediate', 'interpretation', false, 'Em uma reportagem, um quadro lateral reúne “O que muda”, “Quem tem direito” e “Como solicitar”. A presença desse quadro indica uma estratégia de:', 'Quadros de serviço segmentam orientações práticas e facilitam consulta, enquanto o corpo da reportagem contextualiza o tema.', 'Quadros de serviço segmentam orientações práticas e facilitam consulta, enquanto o corpo da reportagem contextualiza o tema.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-8', 'A', 'Restringir o texto a leitores especialistas.', false, 'A organização em perguntas diretas tende a ampliar, não restringir, o acesso.', 'inverter efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-8', 'B', 'Separar informações operacionais para consulta rápida sem substituir o desenvolvimento da reportagem.', true, 'Os títulos organizam respostas práticas e permitem localizar dados rapidamente.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-8', 'C', 'Ocultar a fonte das informações apresentadas.', false, 'A disposição lateral não implica ausência de fonte.', 'inferir intenção oculta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-8', 'D', 'Transformar a reportagem em texto literário.', false, 'O quadro reforça função informativa, não literária.', 'confundir formato visual com gênero literário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-8', 'E', 'Eliminar a necessidade de ler qualquer parte do texto principal.', false, 'O quadro resume aspectos específicos, mas não necessariamente todo o contexto.', 'generalização');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-gen-9', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'challenging', 'comparison', false, 'Compare: I. um vídeo curto com passos para emitir um documento; II. uma página oficial com requisitos, prazos e base legal. Em relação à função social, é correto afirmar que:', 'Demonstração audiovisual e referência normativa atendem necessidades distintas e complementares.', 'Demonstração audiovisual e referência normativa atendem necessidades distintas e complementares.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-9', 'A', 'A página oficial não pode orientar ações práticas.', false, 'Requisitos e prazos são precisamente orientações para ação.', 'separação artificial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-9', 'B', 'Os textos podem se complementar: um demonstra o procedimento e o outro documenta condições oficiais.', true, 'Cada formato favorece uma necessidade, e o uso combinado reduz dúvidas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-9', 'C', 'A existência do vídeo torna dispensável verificar atualizações.', false, 'Procedimentos mudam; a página oficial continua sendo referência de requisitos vigentes.', 'desconsiderar atualização');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-9', 'D', 'A diferença entre eles é apenas o tamanho.', false, 'Canal, forma de consulta e grau de formalização também diferem.', 'redução formal');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-9', 'E', 'O vídeo sempre tem maior validade jurídica que a página.', false, 'Validade depende da fonte e do conteúdo oficial, não do formato audiovisual.', 'confundir formato com autoridade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-gen-10', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'challenging', 'integration', false, 'Uma mensagem de defesa civil combina mapa de risco, sirene sonora, texto curto e botão “ver rota segura”. A integração desses recursos é adequada porque:', 'Em um alerta urgente, redundância entre linguagens amplia acesso e transforma informação em orientação acionável.', 'Em um alerta urgente, redundância entre linguagens amplia acesso e transforma informação em orientação acionável.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-10', 'A', 'A multiplicidade de recursos transforma o alerta em entretenimento.', false, 'Os recursos estão vinculados a uma ação de segurança, não ao lazer.', 'ignorar contexto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-10', 'B', 'O mapa substitui totalmente o texto e a sirene.', false, 'Usuários e situações de acesso variam; nenhum canal sozinho atende a todos.', 'exclusividade de canal');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-10', 'C', 'O som garante que toda pessoa compreenderá a rota.', false, 'Som chama atenção, mas não comunica sozinho o percurso visual.', 'superestimar um recurso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-10', 'D', 'O botão serve apenas para aumentar o tempo de permanência no aplicativo.', false, 'Ele conduz a uma ação operacional diretamente ligada à segurança.', 'atribuir lógica publicitária');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-gen-10', 'E', 'Diferentes modos de percepção ajudam a chamar atenção, localizar o risco e orientar uma ação imediata.', true, 'Som, mapa, texto e ação interativa distribuem funções complementares.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-gen3-1', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'intro', 'concept', false, 'Um mesmo conteúdo — a suspensão de uma linha de ônibus — pode aparecer em um aviso no ponto, em uma notícia e em uma carta de reclamação. O que distingue esses três gêneros é principalmente:', 'Gênero se define pela prática social que o texto realiza: quem fala, com quem, para quê. Assunto e tamanho são consequência, não critério.', 'Gênero se define pela prática social que o texto realiza: quem fala, com quem, para quê. Assunto e tamanho são consequência, não critério.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-1', 'A', 'o assunto tratado em cada um deles.', false, 'O assunto aqui é o mesmo nos três.', 'critério de tema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-1', 'B', 'a finalidade de cada texto e a relação que estabelece com o leitor.', true, 'Avisar, informar e reivindicar são propósitos diferentes, e cada um organiza o texto de um jeito.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-1', 'C', 'o suporte físico em que o texto circula.', false, 'O suporte influencia, mas o mesmo gênero circula em suportes variados.', 'confundir suporte com gênero');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-1', 'D', 'o número de palavras de cada texto.', false, 'Extensão varia dentro de um mesmo gênero e não o define.', 'critério de tamanho');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-1', 'E', 'o grau de correção gramatical exigido.', false, 'Todos podem exigir norma padrão; isso não os separa.', 'critério de correção');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-gen3-2', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'intro', 'applied', false, 'Uma escola quer comunicar aos responsáveis a mudança no horário de saída, garantindo registro e possibilidade de consulta posterior. O gênero mais adequado é:', 'A escolha do gênero segue a finalidade. Aqui é preciso informar com registro e responsabilidade declarada, o que o comunicado oficial atende.', 'A escolha do gênero segue a finalidade. Aqui é preciso informar com registro e responsabilidade declarada, o que o comunicado oficial atende.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-2', 'A', 'um cartaz apenas com o novo horário, sem assinatura.', false, 'Sem identificação do emissor, o aviso perde valor institucional.', 'faltar elemento essencial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-2', 'B', 'uma pesquisa de opinião sobre o horário.', false, 'Pesquisa consulta; o caso pede comunicar uma decisão já tomada.', 'confundir consultar com informar');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-2', 'C', 'um comunicado oficial enviado à família e publicado no mural.', true, 'Ele registra a informação, identifica o emissor e fica disponível para consulta.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-2', 'D', 'um recado oral dado aos alunos na saída.', false, 'Um recado oral não deixa registro nem chega com segurança aos responsáveis.', 'meio sem registro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-2', 'E', 'uma crônica publicada no jornal da escola.', false, 'A crônica trabalha com reflexão e estilo, não com aviso operacional.', 'gênero incompatível');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-gen3-3', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'intermediate', 'interpretation', false, 'Uma postagem começa com "conteúdo pago" e traz um relato pessoal elogioso sobre um produto. Essa marcação inicial serve para:', 'Marcas de enquadramento dizem ao leitor que tipo de texto ele tem diante de si. "Conteúdo pago" transforma um relato em publicidade.', 'Marcas de enquadramento dizem ao leitor que tipo de texto ele tem diante de si. "Conteúdo pago" transforma um relato em publicidade.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-3', 'A', 'sinalizar que o autor não recebeu o produto.', false, 'É o contrário: a marcação indica remuneração ou patrocínio.', 'inverter o sentido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-3', 'B', 'indicar que o texto é mais confiável, pois foi revisado.', false, 'A marcação não fala em revisão nem em confiabilidade.', 'inferência sem base');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-3', 'C', 'informar que o produto é pago, e não gratuito.', false, 'A expressão qualifica o conteúdo, não o produto.', 'referência trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-3', 'D', 'avisar que o texto é publicidade, o que muda o modo de lê-lo.', true, 'A marcação reposiciona o relato: não é experiência espontânea, e sim peça contratada.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-3', 'E', 'cumprir uma exigência de estilo das redes sociais.', false, 'Trata-se de exigência de transparência, não de estilo.', 'confundir norma com estilo');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-gen3-4', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'intermediate', 'comparison', false, 'Comparando uma bula de remédio e uma reportagem sobre o mesmo medicamento, é correto afirmar que:', 'Gêneros não se distinguem por serem mais fáceis ou difíceis, e sim pelo que fazem: a bula instrui o uso, a reportagem informa sobre o tema.', 'Gêneros não se distinguem por serem mais fáceis ou difíceis, e sim pelo que fazem: a bula instrui o uso, a reportagem informa sobre o tema.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-4', 'A', 'a bula orienta o uso correto e a reportagem contextualiza o assunto para o público geral.', true, 'Uma existe para guiar a ação de quem usa; a outra, para informar e situar quem lê.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-4', 'B', 'as duas têm a mesma finalidade, mudando só a linguagem.', false, 'Instruir o uso e informar sobre o tema são finalidades diferentes.', 'igualar finalidades');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-4', 'C', 'a reportagem substitui a bula quando é bem escrita.', false, 'Nenhum texto jornalístico substitui a instrução de uso do fabricante.', 'substituição indevida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-4', 'D', 'a bula é dirigida a médicos e a reportagem a pacientes.', false, 'A bula tem versão para o paciente, escrita para ele.', 'público atribuído incorretamente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-4', 'E', 'a bula é sempre mais confiável, por ser técnica.', false, 'Confiabilidade depende da fonte e do uso, não do grau de tecnicidade.', 'critério de tecnicidade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-gen3-5', 'generos-textuais-e-funcao-social', 'relacionar-formato-contexto-publico-finalidade', 'challenging', 'integration', false, 'Um estudante copia o texto de um manifesto estudantil e o entrega como redação dissertativo-argumentativa. Independentemente da qualidade do conteúdo, o problema central dessa escolha é que:', 'Cada gênero pressupõe um interlocutor. O manifesto mobiliza quem já compartilha a causa; a dissertação argumenta para quem ainda não foi convencido.', 'Cada gênero pressupõe um interlocutor. O manifesto mobiliza quem já compartilha a causa; a dissertação argumenta para quem ainda não foi convencido.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-5', 'A', 'o manifesto não tem parágrafos e a redação precisa ter cinco.', false, 'Número de parágrafos é convenção de formato, não a questão de fundo.', 'reduzir a formato');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-5', 'B', 'o manifesto não pode ser usado como repertório em uma redação.', false, 'Ele pode perfeitamente servir de repertório; o problema é entregá-lo como o texto pedido.', 'confundir uso com substituição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-5', 'C', 'manifestos não circulam no ambiente escolar.', false, 'Eles circulam, inclusive na escola.', 'afirmação factualmente incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-5', 'D', 'o manifesto convoca à adesão, enquanto a redação precisa sustentar uma tese diante de quem discorda.', true, 'A situação de produção é outra: o manifesto fala a quem já concorda, e a dissertação precisa convencer quem duvida.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gen3-5', 'E', 'o manifesto usa linguagem informal e a redação exige norma padrão.', false, 'Manifestos podem ser escritos em norma padrão; o problema não é esse.', 'reduzir a registro');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-linguagem-1', 'funcoes-da-linguagem', 'identificar-funcao-predominante-da-linguagem', 'intro', 'concept', false, 'Em uma conversa por telefone, um dos falantes repete: "Alô? Você está me ouvindo? Alô?" A função da linguagem predominante nessas falas é:', 'Quando a fala serve para abrir, testar ou manter o contato — sem informar, emocionar ou pedir ação —, a função é fática.', NULL, 'Pergunte: se a frase sumisse, o que se perderia? Se for o contato, é fática.', NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-1', 'A', 'Referencial, porque informa a situação da ligação.', false, 'Nenhuma informação sobre o mundo é transmitida; a fala serve ao contato.', 'confundir contexto com referente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-1', 'B', 'Metalinguística, porque comenta a própria conversa.', false, 'Metalinguagem explica o código, não verifica se a mensagem está chegando.', 'confundir canal com código');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-1', 'C', 'Fática, porque testa e tenta manter o canal de comunicação.', true, '"Alô?" e "está me ouvindo?" existem para verificar se a ligação funciona: o foco está no canal.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-1', 'D', 'Poética, porque há repetição de palavras.', false, 'A repetição aqui é funcional, não trabalho estético sobre a forma da mensagem.', 'tratar toda repetição como recurso poético');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-1', 'E', 'Emotiva, porque expressa a ansiedade do falante.', false, 'Não há marca de expressão de sentimento: o falante testa o contato, não fala de si.', 'ver emoção onde há teste de canal');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-linguagem-2', 'funcoes-da-linguagem', 'identificar-funcao-predominante-da-linguagem', 'intermediate', 'applied', false, 'Um cartaz de campanha de trânsito traz: "Você tem pressa. Sua família tem você. Reduza a velocidade."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-2', 'A', 'Poética, sustentada pelo paralelismo entre as duas primeiras frases.', false, 'O paralelismo é um recurso a serviço da persuasão, não o centro do texto.', 'confundir recurso com função');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-2', 'B', 'Metalinguística, sustentada pelo uso de "você" em dois sentidos.', false, 'Não há explicação do código linguístico em nenhum ponto.', 'chamar de metalinguagem qualquer jogo de palavras');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-2', 'C', 'Emotiva, sustentada por "Sua família tem você".', false, 'A frase mobiliza afeto, mas está a serviço do pedido final; sozinha, ela não organiza o texto.', 'tomar o meio pelo fim');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-2', 'D', 'Conativa, sustentada pelo imperativo "Reduza".', true, 'Todo o cartaz converge para uma ação do leitor. O imperativo dirigido a "você" é a marca que prova a função.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-2', 'E', 'Referencial, sustentada pela menção ao trânsito.', false, 'Não há dado ou informação objetiva sobre trânsito no texto.', 'inferir informação ausente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-linguagem-3', 'funcoes-da-linguagem', 'identificar-funcao-predominante-da-linguagem', 'intermediate', 'interpretation', false, 'Leia o verbete: "**Saudade**, substantivo feminino. Sentimento de falta de alguém ou de algo distante ou perdido."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-3', 'A', 'O verbete é metalinguístico e o diário é emotivo.', true, 'O verbete usa a língua para definir uma palavra da própria língua; o diário coloca em destaque quem fala e o que sente.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-3', 'B', 'Os dois são metalinguísticos, porque tratam do significado de uma palavra.', false, 'Só o verbete explica o código; o diário usa a palavra para falar de si.', 'confundir tema com função');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-3', 'C', 'Os dois são emotivos, porque saudade é um sentimento.', false, 'O verbete define o termo sem expressar sentimento algum.', 'deduzir a função pelo assunto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-3', 'D', 'O verbete é emotivo e o diário é referencial.', false, 'A relação está invertida: o verbete é objetivo e o diário é subjetivo.', 'inverter as funções');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-3', 'E', 'O verbete é conativo e o diário é poético.', false, 'O verbete não pede ação, e o diário não organiza a forma da mensagem como centro.', 'escolher duas funções não sustentadas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-linguagem-4', 'funcoes-da-linguagem', 'identificar-funcao-predominante-da-linguagem', 'challenging', 'comparison', false, 'Considere dois textos sobre o mesmo aplicativo:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-4', 'A', 'I é referencial e II é conativa, porque o primeiro descreve o funcionamento e o segundo pede uma ação do leitor.', true, 'I apresenta o que o produto faz, em 3ª pessoa e sem apelo; II usa imperativos dirigidos ao leitor ("Descubra", "Baixe").', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-4', 'B', 'I e II são conativos, porque ambos falam de um produto vendido.', false, 'Falar de um produto não torna um texto persuasivo: I não pede nada ao leitor.', 'deduzir a função pelo contexto comercial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-4', 'C', 'I é emotivo e II é referencial.', false, 'I não expressa subjetividade e II não é objetivo: a classificação está trocada.', 'inverter as duas funções');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-4', 'D', 'I é metalinguístico, porque explica um sistema.', false, 'Explicar um aplicativo não é explicar o código linguístico.', 'ampliar indevidamente a metalinguagem');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-4', 'E', 'II é poético, porque cria expectativa no leitor.', false, 'Criar expectativa é efeito persuasivo; não há trabalho formal sobre a mensagem.', 'confundir efeito com função poética');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-linguagem-5', 'funcoes-da-linguagem', 'identificar-funcao-predominante-da-linguagem', 'challenging', 'integration', false, 'Uma escola publica um mural com três materiais sobre reciclagem: um infográfico com percentuais de coleta seletiva no município; um poema escrito por estudantes, com rimas sobre o lixo do rio; e um cartaz com a frase "Separe o seu. Cobre o do vizinho."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-5', 'A', 'O infográfico predomina como referencial, o poema como poético e o cartaz como conativo, e a combinação amplia o alcance da campanha.', true, 'Cada material põe em destaque um elemento diferente — referente, mensagem e receptor — e o conjunto atinge quem responde melhor a dado, a forma ou a chamado direto.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-5', 'B', 'O poema é o material mais eficiente, porque a linguagem poética é mais persuasiva que a referencial.', false, 'Eficiência depende do público e do objetivo; não há hierarquia fixa entre funções.', 'atribuir superioridade a uma função');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-5', 'C', 'O infográfico é metalinguístico, porque traduz números em linguagem visual.', false, 'Metalinguagem é a língua explicando a própria língua, não a tradução de dados em imagem.', 'estender metalinguagem a qualquer tradução de código');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-5', 'D', 'Os três materiais cumprem a mesma função, já que compartilham o tema da reciclagem.', false, 'Tema comum não implica função comum: cada material coloca um elemento diferente em destaque.', 'confundir tema com função');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-5', 'E', 'Apenas o cartaz comunica de fato, porque é o único que pede uma ação concreta.', false, 'Informar e emocionar também são formas de comunicar; a campanha se apoia nas três.', 'hierarquizar funções por utilidade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-linguagem-rec-1', 'funcoes-da-linguagem', 'identificar-funcao-predominante-da-linguagem', 'intro', 'concept', true, 'Em um manual, lê-se: "Pressione o botão lateral por três segundos para ligar o aparelho." A função predominante é:', 'Instruções técnicas usam imperativo, mas informam um procedimento: predomina a função referencial.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-rec-1', 'A', 'Metalinguística, porque explica o uso de um código técnico.', false, 'Explicar um aparelho não é explicar a língua.', 'ampliar a metalinguagem');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-rec-1', 'B', 'Conativa, pelo uso do imperativo.', false, 'O imperativo aqui descreve um procedimento técnico, não persuade o leitor a agir por convencimento.', 'associar imperativo a persuasão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-rec-1', 'C', 'Referencial, porque transmite uma informação objetiva sobre o funcionamento do aparelho.', true, 'O manual informa como o objeto funciona, em linguagem objetiva e verificável: o foco está no referente.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-rec-1', 'D', 'Emotiva, porque orienta o usuário com cuidado.', false, 'Não há marca de subjetividade do emissor.', 'ler intenção afetiva sem marca');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-linguagem-rec-1', 'E', 'Fática, porque estabelece contato com o usuário.', false, 'Não há teste ou manutenção de canal.', 'confundir instrução com contato');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fl-1', 'funcoes-da-linguagem', 'identificar-funcao-predominante-da-linguagem', 'intro', 'concept', false, 'Um cartaz na rodovia traz apenas: "Reduza a velocidade. Salve uma vida." A função da linguagem predominante nesse enunciado é a:', 'A função predominante se identifica pelo elemento em foco. Aqui o foco é o receptor e sua ação, o que caracteriza a função conativa.', 'A função predominante se identifica pelo elemento em foco. Aqui o foco é o receptor e sua ação, o que caracteriza a função conativa.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-1', 'A', 'poética, porque tem ritmo nas duas frases curtas.', false, 'O ritmo existe, mas está a serviço do apelo, que domina.', 'confundir recurso com função predominante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-1', 'B', 'referencial, porque informa um dado de trânsito.', false, 'Nenhum dado é apresentado; há um pedido de ação.', 'confundir apelo com informação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-1', 'C', 'emotiva, porque expressa o sentimento do autor.', false, 'O enunciado não fala do emissor nem de seus sentimentos.', 'foco no emissor');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-1', 'D', 'metalinguística, porque explica o significado de velocidade.', false, 'Não há explicação de termo nem reflexão sobre a linguagem.', 'função trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-1', 'E', 'conativa, porque busca influenciar o comportamento do leitor.', true, 'Os verbos no imperativo e o foco no receptor caracterizam a função conativa.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fl-2', 'funcoes-da-linguagem', 'identificar-funcao-predominante-da-linguagem', 'intermediate', 'applied', false, 'Em uma entrevista, o convidado diz: "Quando eu falo em crise, estou usando a palavra no sentido econômico, não no sentido pessoal." Nessa passagem, a linguagem cumpre função:', 'Metalinguagem é a linguagem falando de si mesma. Ela aparece em dicionários, mas também em qualquer momento em que alguém explica como está usando uma palavra.', 'Metalinguagem é a linguagem falando de si mesma. Ela aparece em dicionários, mas também em qualquer momento em que alguém explica como está usando uma palavra.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-2', 'A', 'conativa, porque tenta convencer o público.', false, 'O objetivo imediato é evitar ambiguidade, não pedir adesão.', 'função trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-2', 'B', 'poética, porque escolhe as palavras com cuidado.', false, 'Cuidado na escolha não caracteriza função poética, que enfoca a própria mensagem.', 'confundir cuidado com função');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-2', 'C', 'emotiva, porque o convidado fala de si.', false, 'Ele fala do próprio uso de uma palavra, e não de seus sentimentos.', 'confundir sujeito com sentimento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-2', 'D', 'fática, porque mantém o contato com o entrevistador.', false, 'Não há teste de canal nem manutenção de contato.', 'função trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-2', 'E', 'metalinguística, porque o falante explica o sentido em que emprega um termo.', true, 'Usar a linguagem para esclarecer o próprio uso de uma palavra é a definição de metalinguagem.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fl-3', 'funcoes-da-linguagem', 'identificar-funcao-predominante-da-linguagem', 'intermediate', 'interpretation', false, 'Um locutor de rádio interrompe a música e diz: "Alô, alô, você está me ouvindo aí? Aumenta o volume que agora vem a melhor parte." As expressões iniciais cumprem função predominantemente:', 'A função fática cuida do canal: abrir, testar e manter a comunicação. É comum no rádio, no telefone e nas conversas de rua.', 'A função fática cuida do canal: abrir, testar e manter a comunicação. É comum no rádio, no telefone e nas conversas de rua.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-3', 'A', 'referencial, porque informam a programação.', false, 'A informação vem depois; a abertura serve para estabelecer contato.', 'foco no referente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-3', 'B', 'metalinguística, porque explicam o funcionamento do rádio.', false, 'Não há explicação sobre a linguagem nem sobre o meio.', 'função trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-3', 'C', 'emotiva, porque o locutor demonstra entusiasmo.', false, 'O entusiasmo existe, mas o que estrutura o trecho inicial é o contato.', 'confundir tom com função');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-3', 'D', 'poética, porque repete a palavra "alô".', false, 'A repetição aqui serve ao contato, não à elaboração da mensagem.', 'confundir recurso com função');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-3', 'E', 'fática, porque testam e mantêm o canal de comunicação.', true, 'Chamar a atenção e confirmar o contato antes de prosseguir é o papel da função fática.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fl-4', 'funcoes-da-linguagem', 'identificar-funcao-predominante-da-linguagem', 'intermediate', 'comparison', false, 'Dois textos tratam de uma enchente. O primeiro registra volume de chuva, bairros atingidos e número de desabrigados. O segundo descreve a água subindo pela escada de uma casa, com repetições e imagens sensoriais. Comparando as funções predominantes:', 'Funções coexistem; o que se identifica é a predominante. Dado organizado aponta para o referente; elaboração da forma aponta para a mensagem.', 'Funções coexistem; o que se identifica é a predominante. Dado organizado aponta para o referente; elaboração da forma aponta para a mensagem.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-4', 'A', 'os dois são referenciais, pois falam do mesmo fato.', false, 'Falar do mesmo fato não implica o mesmo foco linguístico.', 'igualar pelo tema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-4', 'B', 'o primeiro é referencial e o segundo, poético, pela elaboração da própria mensagem.', true, 'Um enfoca o dado sobre o mundo; o outro enfoca como o texto é construído.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-4', 'C', 'o primeiro é conativo e o segundo, emotivo.', false, 'O primeiro não pede ação e o segundo não centra no emissor.', 'duas funções trocadas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-4', 'D', 'o segundo é metalinguístico, por usar recursos de estilo.', false, 'Usar recursos não é falar sobre a linguagem.', 'confundir estilo com metalinguagem');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-4', 'E', 'nenhum tem função definida, pois textos misturam funções.', false, 'Textos misturam funções, mas quase sempre há uma predominante.', 'negar a predominância');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fl-5', 'funcoes-da-linguagem', 'identificar-funcao-predominante-da-linguagem', 'challenging', 'integration', false, 'Uma campanha de vacinação usa a frase: "Eu me protegi. E você?". Sobre as funções da linguagem nessa frase, a análise mais precisa é que:', 'Enunciados curtos de campanha costumam encadear funções: o emissor se expõe para tornar legítimo o pedido que dirige ao receptor.', 'Enunciados curtos de campanha costumam encadear funções: o emissor se expõe para tornar legítimo o pedido que dirige ao receptor.', 'Ao analisar funções, identifique todas as presentes e depois pergunte qual delas organiza o enunciado. As outras costumam servir a ela.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-5', 'A', 'há apenas função referencial, por tratar de saúde pública.', false, 'O tema é de saúde, mas o enunciado não organiza informação sobre ele.', 'classificar pelo tema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-5', 'B', 'há apenas função fática, porque a pergunta busca resposta.', false, 'A pergunta não testa o canal: ela cobra uma posição.', 'função trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-5', 'C', 'a função emotiva abre a frase e serve de apoio à conativa, que predomina.', true, 'O relato em primeira pessoa constrói a credibilidade que sustenta o apelo dirigido ao leitor.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-5', 'D', 'há apenas função emotiva, pela primeira pessoa.', false, 'A primeira pessoa abre a frase, mas a pergunta final desloca o foco para o interlocutor.', 'parar na primeira metade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fl-5', 'E', 'há apenas função conativa, pela pergunta.', false, 'A pergunta é o ponto de chegada, mas o relato inicial prepara o apelo.', 'ignorar a primeira metade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-var-1', 'variacao-linguistica', 'analisar-variacao-e-adequacao-linguistica', 'intro', 'concept', false, 'Em diferentes regiões do Brasil, o mesmo alimento é chamado de mandioca, macaxeira ou aipim. Esse fenômeno é um exemplo de variação:', 'Variação no espaço geográfico é diatópica. As três palavras são igualmente corretas nas suas regiões.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-1', 'A', 'Diafásica, ligada à situação de uso.', false, 'A mudança não depende de o falante estar em situação formal ou informal.', 'trocar espaço por situação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-1', 'B', 'Diacrônica, ligada à passagem do tempo.', false, 'As três formas convivem hoje, em lugares diferentes.', 'trocar espaço por tempo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-1', 'C', 'Diatópica, ligada à distribuição geográfica dos falantes.', true, 'O que determina a escolha do termo é a região do falante: é variação no espaço.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-1', 'D', 'Diastrática, ligada ao grupo social do falante.', false, 'Pessoas de qualquer grupo social usam o termo da sua região.', 'trocar espaço por grupo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-1', 'E', 'Não é variação, e sim erro de vocabulário em duas das três formas.', false, 'As três formas são legítimas e usadas por comunidades inteiras de falantes.', 'tratar variedade como erro');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-var-2', 'variacao-linguistica', 'analisar-variacao-e-adequacao-linguistica', 'intermediate', 'applied', false, 'Um estudante escreve, em uma mensagem para o grupo da turma: "gente, alguém tem o resumo de bio? tô sem nada aqui 😭". Na semana seguinte, redige em uma prova: "A ausência de material de apoio prejudicou a preparação da turma."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-2', 'A', 'Deveria usar o mesmo registro nos dois casos para manter coerência.', false, 'Manter registro único em contextos opostos produziria textos inadequados nos dois lados.', 'confundir coerência com uniformidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-2', 'B', 'Escreve corretamente apenas na prova, e de forma inadequada no grupo.', false, 'A mensagem é adequada ao seu contexto: informal, rápida e entre iguais.', 'aplicar a norma formal a todo contexto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-2', 'C', 'Domina a norma-padrão, mas perde qualidade linguística no ambiente digital.', false, 'Não há perda: há troca de registro conforme a situação.', 'ver adequação como deterioração');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-2', 'D', 'Usa duas variedades regionais distintas.', false, 'A diferença não é de região, e sim de situação de uso.', 'confundir os tipos de variação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-2', 'E', 'Adequa o registro à situação, o que demonstra competência linguística.', true, 'Transitar entre registros conforme o contexto — informal com colegas, formal na prova — é exatamente o que se espera de um falante competente.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-var-3', 'variacao-linguistica', 'analisar-variacao-e-adequacao-linguistica', 'intermediate', 'interpretation', false, 'Leia o comentário publicado sob um vídeo: "Não aguento mais ouvir gente falando ‘nóis vai’. Isso é falta de estudo, tinha que ter aula de português obrigatória para adulto."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-3', 'A', 'É apenas uma opinião sobre estilo, sem implicações sociais.', false, 'Julgar a fala é uma das formas mais comuns de julgar origem e classe social.', 'minimizar o efeito social do julgamento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-3', 'B', 'Expressa preconceito linguístico, ao converter uma diferença entre variedades em julgamento sobre as pessoas.', true, 'A concordância "nóis vai" segue uma regra regular de outra variedade. Chamá-la de "falta de estudo" transfere para a pessoa um julgamento que é social, não gramatical.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-3', 'C', 'Está tecnicamente correto, já que a concordância mencionada contraria a gramática.', false, 'Contrariar a norma-padrão não torna uma construção agramatical: ela é sistemática dentro de sua variedade.', 'tomar norma-padrão como a única gramática');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-3', 'D', 'Defende a variação linguística ao pedir mais acesso ao ensino.', false, 'O pedido de "aula obrigatória" aparece como punição, não como ampliação de repertório.', 'ler intenção inclusiva onde há julgamento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-3', 'E', 'Trata de variação diacrônica, já que a forma citada é antiga.', false, 'A forma é atual e corrente, não histórica.', 'classificar o tipo errado de variação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-var-4', 'variacao-linguistica', 'analisar-variacao-e-adequacao-linguistica', 'challenging', 'comparison', false, 'Considere duas afirmações:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-4', 'A', 'I e II.', false, 'I é correta, mas II é falsa: nenhuma variedade tem "menos regras" — tem regras diferentes.', 'aceitar a hierarquia entre variedades');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-4', 'B', 'II, apenas.', false, 'II é justamente a afirmação incorreta.', 'inverter a avaliação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-4', 'C', 'Nenhuma das duas.', false, 'I está correta: o domínio da norma-padrão amplia o acesso a esferas formais.', 'excesso de recusa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-4', 'D', 'I e II, desde que se considere o contexto escolar.', false, 'Contexto algum torna II verdadeira do ponto de vista linguístico.', 'relativizar um erro factual');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-4', 'E', 'I, apenas.', true, 'Dominar a norma-padrão amplia oportunidades — isso é verdade social. Já a ideia de variedade "incompleta" não se sustenta: toda variedade é um sistema regular e completo.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-var-5', 'variacao-linguistica', 'analisar-variacao-e-adequacao-linguistica', 'challenging', 'integration', false, 'Uma prefeitura vai publicar uma cartilha sobre prevenção de dengue para moradores de bairros com baixa escolaridade formal. A equipe discute a linguagem a ser usada.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-5', 'A', 'Reproduzir a variedade falada no bairro, inclusive nos desvios de concordância, para criar identificação.', false, 'Imitar a fala do leitor em documento público costuma soar condescendente e não aumenta a compreensão.', 'confundir aproximação com imitação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-5', 'B', 'Publicar duas versões, uma "certa" e outra "simplificada", indicando qual é a correta.', false, 'Rotular uma versão como a correta reinstala a hierarquia que a decisão deveria evitar.', 'hierarquizar as versões');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-5', 'C', 'Evitar qualquer termo técnico, substituindo todos por aproximações populares.', false, 'Alguns termos técnicos precisam aparecer: o caminho é explicá-los, não apagá-los.', 'trocar precisão por simplificação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-5', 'D', 'Usar a norma-padrão em sua forma mais formal, para garantir a autoridade do documento.', false, 'Autoridade que não é compreendida não protege ninguém; o texto perderia a função.', 'privilegiar prestígio sobre eficácia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-5', 'E', 'Escrever em português claro, com frases curtas e vocabulário cotidiano, mantendo a precisão das informações de saúde.', true, 'A finalidade é fazer a informação chegar. Isso pede clareza e vocabulário partilhado, sem abrir mão da precisão técnica onde ela salva vidas.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-var-rec-1', 'variacao-linguistica', 'analisar-variacao-e-adequacao-linguistica', 'intro', 'concept', true, 'A expressão "vossa mercê", que deu origem a "você", é um exemplo de variação linguística:', 'Mudanças ao longo do tempo caracterizam a variação diacrônica.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-rec-1', 'A', 'Diatópica.', false, 'A mudança não se deve à região do falante.', 'trocar tempo por espaço');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-rec-1', 'B', 'Diastrática.', false, 'A mudança atravessou todos os grupos sociais.', 'trocar tempo por grupo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-rec-1', 'C', 'Diacrônica.', true, 'A forma mudou ao longo do tempo: "vossa mercê" → "vosmecê" → "você". É variação histórica.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-rec-1', 'D', 'Diafásica.', false, 'Não se trata de mudança conforme a situação de fala.', 'trocar tempo por situação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-var-rec-1', 'E', 'Não é variação, e sim abreviação incorreta.', false, 'A redução foi um processo histórico regular da língua, não um erro.', 'tratar mudança histórica como erro');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-var-1', 'variacao-linguistica', 'analisar-variacao-e-adequacao-linguistica', 'intro', 'concept', false, 'Sobre a afirmação "existe uma única forma correta de falar português", a posição sustentada pelos estudos linguísticos é que ela:', 'Norma padrão é uma variedade entre outras, socialmente prestigiada e exigida em certos contextos. Confundi-la com a língua toda apaga a variação real.', 'Norma padrão é uma variedade entre outras, socialmente prestigiada e exigida em certos contextos. Confundi-la com a língua toda apaga a variação real.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-1', 'A', 'depende do estado em que a pessoa nasceu.', false, 'A variação não se resume à origem geográfica do falante.', 'reduzir a região');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-1', 'B', 'está correta, pois a gramática define a língua.', false, 'A gramática normativa descreve uma variedade de prestígio, não a totalidade da língua.', 'igualar norma e língua');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-1', 'C', 'está correta apenas na escrita.', false, 'Também na escrita há variação legítima conforme gênero e situação.', 'restrição parcial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-1', 'D', 'é equivocada: há variedades diferentes, e a norma padrão é uma delas, associada a certos usos.', true, 'Toda língua viva varia por região, grupo e situação; a norma padrão é a variedade codificada para usos formais.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-1', 'E', 'é equivocada porque não existe certo e errado em língua.', false, 'Existe adequação: uma forma pode ser inadequada a uma situação sem ser um erro do sistema.', 'relativismo absoluto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-var-2', 'variacao-linguistica', 'analisar-variacao-e-adequacao-linguistica', 'intro', 'applied', false, 'Um candidato escreve em uma carta de apresentação para uma vaga formal: "Tô mandando meu currículo pra vocês darem uma olhada". A principal razão para reescrever esse trecho é que ele:', 'A escolha entre registros não é entre certo e errado, e sim entre adequado e inadequado à situação. A carta profissional pede formalidade.', 'A escolha entre registros não é entre certo e errado, e sim entre adequado e inadequado à situação. A carta profissional pede formalidade.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-2', 'A', 'usa a primeira pessoa, proibida em textos profissionais.', false, 'A primeira pessoa é comum e aceita nesse gênero.', 'regra inventada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-2', 'B', 'revela a região de origem do candidato.', false, 'As formas usadas são de registro informal, não marcas regionais.', 'confundir registro com região');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-2', 'C', 'contém erros de português que comprometem o sentido.', false, 'O sentido está claro; a questão é de adequação, não de compreensão.', 'julgar como erro de sistema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-2', 'D', 'usa registro coloquial em um gênero que pede formalidade.', true, 'A carta de apresentação circula em contexto profissional e espera registro formal.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-2', 'E', 'é curto demais para uma carta.', false, 'A extensão não é o problema apontado.', 'critério de tamanho');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-var-3', 'variacao-linguistica', 'analisar-variacao-e-adequacao-linguistica', 'intermediate', 'interpretation', false, 'Um personagem de novela fala com marcas do português rural mineiro e é retratado como ingênuo e pouco instruído. Essa associação, repetida em várias produções, indica:', 'Preconceito linguístico é o julgamento do falante a partir de sua variedade. Ele se sustenta pela repetição, sobretudo em produções de grande alcance.', 'Preconceito linguístico é o julgamento do falante a partir de sua variedade. Ele se sustenta pela repetição, sobretudo em produções de grande alcance.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-3', 'A', 'um preconceito linguístico: atribui-se valor social a traços da fala que não têm relação com competência.', true, 'A repetição da associação transforma marca de variedade em marca de inferioridade, que é a definição do preconceito linguístico.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-3', 'B', 'que a variedade rural é mais expressiva e por isso rende bons personagens.', false, 'A justificativa estética não explica a associação sistemática com ingenuidade.', 'racionalização');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-3', 'C', 'que a variedade rural realmente limita o raciocínio de quem a fala.', false, 'Nenhuma variedade linguística limita a capacidade de raciocínio.', 'preconceito assumido como fato');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-3', 'D', 'que a produção buscou fidelidade linguística ao interior do país.', false, 'Fidelidade linguística não exige associar a variedade a um estereótipo de caráter.', 'confundir registro com estereótipo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-3', 'E', 'que o público não entenderia a variedade padrão nesse personagem.', false, 'A questão não é compreensão, e sim a imagem construída.', 'deslocar o problema');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-var-4', 'variacao-linguistica', 'analisar-variacao-e-adequacao-linguistica', 'intermediate', 'comparison', false, 'Comparando a fala de um jovem em um grupo de amigos e a mesma pessoa apresentando um trabalho em sala, as diferenças observadas são explicadas principalmente por:', 'Um mesmo falante domina vários registros e transita entre eles. Essa é a variação situacional, distinta da regional, social e histórica.', 'Um mesmo falante domina vários registros e transita entre eles. Essa é a variação situacional, distinta da regional, social e histórica.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-4', 'A', 'variação histórica: a língua mudou entre um momento e outro.', false, 'Variação histórica se observa entre gerações, não entre duas cenas do mesmo dia.', 'tipo de variação trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-4', 'B', 'variação social: o jovem pertence a duas classes diferentes.', false, 'Não há mudança de grupo social entre as duas situações.', 'tipo de variação trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-4', 'C', 'falta de domínio da norma padrão no ambiente informal.', false, 'Usar registro informal entre amigos é adequação, não falta de domínio.', 'julgar adequação como falha');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-4', 'D', 'variação situacional: o mesmo falante ajusta o registro conforme o contexto.', true, 'A pessoa é a mesma, a região é a mesma e a idade também; o que muda é a situação.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-4', 'E', 'variação regional: a sala e o grupo pertencem a lugares diferentes.', false, 'Não há mudança de região entre as duas situações.', 'tipo de variação trocado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-var-5', 'variacao-linguistica', 'analisar-variacao-e-adequacao-linguistica', 'challenging', 'integration', false, 'Uma escola decide corrigir a fala dos alunos que usam variedades estigmatizadas, substituindo-as pela norma padrão em todas as situações. Uma alternativa pedagógica mais consistente com os estudos linguísticos seria:', 'Respeitar a variação e ensinar a norma padrão não se opõem. O ganho está em somar registros ao repertório, deixando claro quando cada um é esperado.', 'Respeitar a variação e ensinar a norma padrão não se opõem. O ganho está em somar registros ao repertório, deixando claro quando cada um é esperado.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-5', 'A', 'classificar as variedades por grau de correção e ensinar da pior para a melhor.', false, 'Não há escala de correção entre variedades de uma língua.', 'hierarquia inventada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-5', 'B', 'substituir o ensino de gramática pelo de literatura.', false, 'A troca de conteúdo não trata da questão da variação.', 'deslocar o problema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-5', 'C', 'ensinar a norma padrão como mais uma variedade a dominar, explicando em que situações ela é esperada.', true, 'Ampliar o repertório do aluno sem desqualificar sua fala é o que a pesquisa em ensino de língua vem defendendo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-5', 'D', 'deixar de ensinar a norma padrão, para não estigmatizar ninguém.', false, 'Isso privaria o aluno de uma variedade exigida em concursos, trabalho e vida pública.', 'abandonar o ensino da norma');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-var-5', 'E', 'ensinar apenas a norma padrão, mas sem corrigir a fala em casa.', false, 'A separação por local não resolve: o ponto é reconhecer a legitimidade das variedades.', 'solução parcial');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rec-1', 'recursos-expressivos', 'relacionar-recurso-expressivo-e-efeito-de-sentido', 'intro', 'concept', false, 'Em "o relógio da sala roubava minhas horas em silêncio", o recurso expressivo predominante é:', 'Atribuir intenção e ação humanas a um objeto caracteriza prosopopeia (personificação).', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-1', 'A', 'Metonímia, que substitui o todo pela parte.', false, 'Não há substituição por contiguidade: o relógio continua sendo o relógio.', 'aplicar metonímia sem relação de vizinhança');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-1', 'B', 'Hipérbole, que exagera uma quantidade.', false, 'Não há exagero numérico; há atribuição de conduta.', 'confundir efeito de intensidade com exagero');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-1', 'C', 'Eufemismo, que suaviza uma ideia desagradável.', false, 'A construção intensifica o incômodo, em vez de suavizá-lo.', 'inverter o efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-1', 'D', 'Antítese, que aproxima ideias opostas.', false, 'Não há par de opostos no trecho.', 'ver oposição inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-1', 'E', 'Prosopopeia, que atribui ação humana a um objeto.', true, 'Roubar é ação humana e intencional, atribuída a um relógio: é personificação.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rec-2', 'recursos-expressivos', 'relacionar-recurso-expressivo-e-efeito-de-sentido', 'intermediate', 'applied', false, 'Um comunicado de uma escola informa: "Em razão de um reordenamento pedagógico, o programa de reforço passará por um período de suspensão temporária."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-2', 'A', 'Usa eufemismo, o que suaviza a informação de que o reforço foi interrompido.', true, '"Reordenamento pedagógico" e "suspensão temporária" substituem "corte" e "fim". O recurso reduz a carga negativa e a chance de reação das famílias.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-2', 'B', 'Usa ironia para criticar a própria decisão administrativa.', false, 'Não há descompasso entre dito e pretendido: a nota adere ao que comunica.', 'ver ironia sem marca de contraste');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-2', 'C', 'Não usa recurso expressivo, por ser um texto administrativo.', false, 'Textos administrativos usam recursos expressivos com frequência — inclusive para controlar repercussão.', 'supor neutralidade do gênero');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-2', 'D', 'Usa hipérbole para dar dimensão ao problema.', false, 'Não há exagero: o texto faz o contrário, reduz a dimensão do fato.', 'inverter o sentido do recurso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-2', 'E', 'Usa metáfora para tornar a comunicação mais didática.', false, 'Não há transferência por semelhança em "reordenamento" ou "suspensão temporária".', 'nomear figura ausente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rec-3', 'recursos-expressivos', 'relacionar-recurso-expressivo-e-efeito-de-sentido', 'intermediate', 'interpretation', false, 'Leia os versos autorais:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-3', 'A', 'É paronomásia, pois aproxima palavras de sentidos opostos.', false, 'Paronomásia aproxima palavras parecidas no som e diferentes no sentido, e não é o recurso central aqui.', 'nomear recurso secundário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-3', 'B', 'É rima interna e serve apenas para marcar o ritmo, sem relação com o sentido.', false, 'A sonoridade está diretamente ligada ao que os versos descrevem.', 'separar som e sentido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-3', 'C', 'É assonância e produz efeito de aceleração na leitura.', false, 'A repetição é de consoantes, não de vogais, e o efeito é de suavidade, não de aceleração.', 'trocar consoante por vogal');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-3', 'D', 'É aliteração e sugere, pelo próprio som, a suavidade descrita nos versos.', true, 'A repetição do /s/ produz um som contínuo e sibilante que imita sussurro e silêncio: a sonoridade reforça o sentido.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-3', 'E', 'É onomatopeia, pois reproduz literalmente o ruído do vento.', false, 'Onomatopeia é palavra criada para imitar som ("tic-tac"); aqui a imitação é indireta, pela escolha das consoantes.', 'confundir sugestão sonora com onomatopeia');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rec-4', 'recursos-expressivos', 'relacionar-recurso-expressivo-e-efeito-de-sentido', 'challenging', 'comparison', false, 'Compare os dois trechos:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-4', 'A', 'Metáfora e hipérbole.', false, 'Nenhum dos trechos se organiza por semelhança ou por exagero numérico.', 'nomear figuras ausentes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-4', 'B', 'Antítese e paradoxo.', true, 'Em I, "amor" e "briga" são opostos que convivem sem contradição lógica: antítese. Em II, "silêncio cheio de vozes" contradiz a si mesmo dentro da mesma ideia: paradoxo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-4', 'C', 'Ironia e prosopopeia.', false, 'Não há inversão entre dito e pretendido nem atribuição de traço humano a algo não humano.', 'escolher figuras sem marca no texto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-4', 'D', 'Antítese e antítese.', false, 'Em II a contradição está dentro da mesma ideia — silêncio cheio de vozes —, o que caracteriza paradoxo.', 'ignorar a contradição interna');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-4', 'E', 'Paradoxo e antítese.', false, 'A ordem está invertida: I contrapõe dois termos que coexistem; II é o que desafia a lógica.', 'inverter as figuras');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rec-5', 'recursos-expressivos', 'relacionar-recurso-expressivo-e-efeito-de-sentido', 'challenging', 'integration', false, 'Uma marca de água mineral lança a campanha: "Beba a montanha." Em entrevista, a agência afirma que a frase "traduz pureza e origem em duas palavras".
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-5', 'A', 'Há catacrese, pois falta na língua uma palavra específica para essa água.', false, 'A palavra "água" existe e é corrente; não há lacuna lexical a preencher.', 'aplicar catacrese sem lacuna');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-5', 'B', 'Não há figura: trata-se apenas de um slogan curto e direto.', false, 'A frase só funciona porque opera uma substituição figurada; lida ao pé da letra, não faz sentido.', 'negar a figura por brevidade do texto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-5', 'C', 'Há metonímia — a montanha pela água que dela vem — e o recurso transfere para o produto os atributos do lugar de origem.', true, 'A relação é de origem e contiguidade, não de semelhança. Ao nomear a fonte no lugar do produto, a campanha empresta à água a pureza atribuída à montanha.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-5', 'D', 'Há metáfora, pois a água é comparada à montanha por semelhança de pureza.', false, 'Não há comparação por parecença: a montanha é a origem real da água, o que caracteriza metonímia.', 'confundir contiguidade com semelhança');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-5', 'E', 'Há hipérbole, pois seria impossível beber uma montanha.', false, 'A impossibilidade literal é consequência da metonímia, não exagero quantitativo.', 'confundir impossibilidade com exagero');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rec-rec-1', 'recursos-expressivos', 'relacionar-recurso-expressivo-e-efeito-de-sentido', 'intro', 'concept', true, 'Na frase "esperei uma eternidade na fila do banco", o recurso expressivo utilizado é:', 'Hipérbole é o exagero deliberado usado para intensificar uma impressão.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-rec-1', 'A', 'Metonímia.', false, 'Não há substituição por contiguidade.', 'aplicar metonímia sem relação de vizinhança');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-rec-1', 'B', 'Antítese.', false, 'Não há par de opostos.', 'ver oposição inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-rec-1', 'C', 'Prosopopeia.', false, 'Nada não humano recebe traço humano.', 'confundir com personificação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-rec-1', 'D', 'Hipérbole.', true, 'O exagero intencional ("uma eternidade") intensifica a sensação de espera.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rec-rec-1', 'E', 'Eufemismo.', false, 'Eufemismo suaviza; a frase faz o contrário.', 'inverter o efeito');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rec-1', 'recursos-expressivos', 'relacionar-recurso-expressivo-e-efeito-de-sentido', 'intro', 'concept', false, 'Em "a cidade acordou irritada com o barulho das obras", o recurso expressivo empregado e seu efeito são:', 'Nomear a figura resolve metade da questão. A outra metade é dizer o que ela faz com o sentido — aqui, transformar muitas reações individuais em uma só.', 'Nomear a figura resolve metade da questão. A outra metade é dizer o que ela faz com o sentido — aqui, transformar muitas reações individuais em uma só.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-1', 'A', 'ironia, que diz o contrário do que se quer dizer.', false, 'Não há inversão de sentido no enunciado.', 'figura trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-1', 'B', 'personificação, que atribui à cidade ações e sentimentos humanos e sugere um incômodo coletivo.', true, 'Acordar e ficar irritada são ações de pessoa; ao transferi-las à cidade, o texto condensa a reação de muitos em um só sujeito.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-1', 'C', 'hipérbole, que exagera o barulho das obras.', false, 'Não há exagero de quantidade ou intensidade declarado.', 'figura trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-1', 'D', 'eufemismo, que suaviza o incômodo dos moradores.', false, 'O texto não suaviza nada; o incômodo é afirmado.', 'figura trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-1', 'E', 'metonímia, que troca a parte pelo todo sem outro efeito.', false, 'Há metonímia possível em "cidade", mas o traço dominante é atribuir ação e emoção humanas.', 'parar na figura secundária');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rec-2', 'recursos-expressivos', 'relacionar-recurso-expressivo-e-efeito-de-sentido', 'intermediate', 'applied', false, 'Um cartaz de campanha contra o desperdício traz: "Cada gota que escorre é um copo que falta". O recurso central e sua função persuasiva são:', 'O contraste entre a gota e o copo transforma uma perda invisível em imagem mensurável, que é o que faz o argumento funcionar.', 'O contraste entre a gota e o copo transforma uma perda invisível em imagem mensurável, que é o que faz o argumento funcionar.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-2', 'A', 'prosopopeia, que dá vida à água.', false, 'A água não recebe ação nem sentimento humano.', 'figura trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-2', 'B', 'gradação, que enumera perdas em ordem crescente.', false, 'Não há enumeração no enunciado.', 'figura trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-2', 'C', 'aliteração, que cria musicalidade e facilita a memorização.', false, 'Não há repetição de sons consonantais marcante no enunciado.', 'figura trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-2', 'D', 'pleonasmo, que reforça a ideia por repetição.', false, 'Não há repetição redundante de sentido.', 'figura trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-2', 'E', 'antítese entre gota e copo, que aproxima o gesto mínimo da perda concreta.', true, 'O contraste entre o menor volume e um volume útil torna palpável o efeito de um descuido pequeno.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rec-3', 'recursos-expressivos', 'relacionar-recurso-expressivo-e-efeito-de-sentido', 'intermediate', 'interpretation', false, 'Um narrador comenta, ao descrever uma reunião que terminou sem decisão: "Foi uma tarde extremamente produtiva". No contexto, esse enunciado deve ser lido como:', 'Ironia só existe com contexto: é o descompasso entre o que se diz e o que o leitor sabe que aconteceu que produz o sentido invertido.', 'Ironia só existe com contexto: é o descompasso entre o que se diz e o que o leitor sabe que aconteceu que produz o sentido invertido.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-3', 'A', 'ironia, que avalia negativamente a reunião ao afirmar o contrário.', true, 'O contraste entre o elogio e o resultado nulo instrui o leitor a inverter o sentido.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-3', 'B', 'hipérbole, que exagera a produtividade real da reunião.', false, 'A hipérbole ampliaria algo existente; aqui não houve produtividade a ampliar.', 'figura trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-3', 'C', 'eufemismo, que suaviza a crítica aos participantes.', false, 'O enunciado não suaviza: ele critica por inversão.', 'figura trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-3', 'D', 'metáfora, que compara a tarde a um processo produtivo.', false, 'Não há transferência de sentido entre dois campos.', 'figura trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-3', 'E', 'elogio sincero, já que reuniões longas costumam render.', false, 'O contexto informa que nada foi decidido.', 'leitura literal');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rec-4', 'recursos-expressivos', 'relacionar-recurso-expressivo-e-efeito-de-sentido', 'intermediate', 'comparison', false, 'Duas manchetes sobre o mesmo aumento de tarifa: "Tarifa sobe 12%" e "Passagem pesa mais no bolso do trabalhador". Comparando os efeitos de sentido:', 'Enquadramento é escolha de palavras. Um mesmo fato vira dado técnico ou experiência vivida conforme o vocabulário adotado.', 'Enquadramento é escolha de palavras. Um mesmo fato vira dado técnico ou experiência vivida conforme o vocabulário adotado.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-4', 'A', 'a segunda é imprecisa, porque não traz o número.', false, 'Ela é menos precisa no dado, mas isso não esgota a comparação pedida.', 'avaliação parcial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-4', 'B', 'a primeira é tendenciosa, por destacar o percentual.', false, 'Apresentar o percentual é o registro mais neutro dos dois.', 'inverter a avaliação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-4', 'C', 'a primeira registra o dado; a segunda enquadra o fato pela perspectiva de quem paga, com metáfora de peso.', true, 'A escolha das palavras define de que ponto de vista o fato é apresentado ao leitor.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-4', 'D', 'a segunda usa linguagem figurada e por isso é inadequada ao jornalismo.', false, 'Linguagem figurada é comum e legítima em manchetes.', 'regra inventada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-4', 'E', 'são equivalentes, pois informam o mesmo fato.', false, 'Informar o mesmo fato não é produzir o mesmo efeito.', 'igualar pelo referente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rec-5', 'recursos-expressivos', 'relacionar-recurso-expressivo-e-efeito-de-sentido', 'challenging', 'integration', false, 'Um poema repete o verso "e a água continuava subindo" ao fim de cada estrofe, enquanto as estrofes descrevem objetos cada vez mais altos da casa. A articulação entre os dois procedimentos produz:', 'Recursos raramente agem sozinhos. Um refrão constante contra uma série crescente transforma repetição em ameaça que se aproxima.', 'Recursos raramente agem sozinhos. Um refrão constante contra uma série crescente transforma repetição em ameaça que se aproxima.', 'Quando o texto usa mais de um recurso, pergunte o que um faz com o outro. O efeito costuma estar na relação, não em cada um isolado.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-5', 'A', 'apenas musicalidade, pela repetição regular.', false, 'A musicalidade existe, mas é a interação com a gradação que constrói o sentido.', 'analisar um recurso só');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-5', 'B', 'a sensação de avanço inevitável, porque o refrão fixo contrasta com a gradação dos objetos.', true, 'O que se repete marca o tempo; o que muda marca o avanço. Juntos, produzem a impressão de algo que não se pode deter.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-5', 'C', 'a ideia de que a água parou de subir ao fim do poema.', false, 'O refrão afirma justamente a continuidade.', 'contradizer o texto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-5', 'D', 'um efeito de dúvida sobre a veracidade do relato.', false, 'Nada no procedimento coloca o relato em suspeita.', 'inferência sem base');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rec-5', 'E', 'a impressão de desordem, pela quebra da estrutura das estrofes.', false, 'A estrutura é regular, e é a regularidade que produz o efeito.', 'inverter a descrição');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-lit-1', 'literatura-brasileira', 'relacionar-obra-contexto-e-projeto-estetico', 'intro', 'concept', false, 'A idealização da amada, o herói nacional construído a partir da figura indígena e a exuberância da natureza brasileira como símbolo de identidade são traços característicos do:', 'O Romantismo brasileiro responde à pergunta "que país é este?" idealizando natureza, herói e sentimento.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-1', 'A', 'Realismo, que analisa criticamente a sociedade brasileira.', false, 'O Realismo desmonta idealizações em vez de construí-las.', 'inverter os projetos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-1', 'B', 'Parnasianismo, centrado no rigor formal do verso.', false, 'O parnasianismo prioriza a forma, não a construção de identidade nacional idealizada.', 'trocar projeto por forma');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-1', 'C', 'Barroco, marcado pelo conflito entre fé e razão.', false, 'O conflito barroco é religioso e existencial, não de identidade nacional.', 'trocar época');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-1', 'D', 'Romantismo, que buscava construir uma identidade nacional após a independência.', true, 'Idealização, natureza nacional e herói indígena compõem o projeto romântico brasileiro de fundar uma literatura própria.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-1', 'E', 'Modernismo, que valorizou elementos brasileiros na literatura.', false, 'O Modernismo também trata do Brasil, mas com ironia e recusa da idealização romântica.', 'confundir valorização com idealização');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-lit-2', 'literatura-brasileira', 'relacionar-obra-contexto-e-projeto-estetico', 'intermediate', 'applied', false, 'Leia o trecho autoral, escrito no espírito de um movimento literário brasileiro:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-2', 'A', 'Modernista, pela liberdade formal do texto.', false, 'A prosa é convencional na sintaxe; a marca aqui é a ironia sobre a hipocrisia social.', 'confundir tom com forma');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-2', 'B', 'Romântico, pela intensidade emocional da despedida.', false, 'A emoção aparece para ser desmontada logo em seguida, não para ser celebrada.', 'parar na primeira frase');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-2', 'C', 'Parnasiano, pelo cuidado com a construção das frases.', false, 'O trabalho formal do Parnasianismo é métrico e poético, não narrativo e irônico.', 'confundir esmero com escola');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-2', 'D', 'Realista, pela análise irônica das aparências e das conveniências sociais.', true, 'O narrador expõe a distância entre o gesto e o interesse ("o que lhe conveio perfeitamente"): é a ironia analítica típica do projeto realista.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-2', 'E', 'Simbolista, pela sugestão de estados de alma.', false, 'Não há musicalidade nem sugestão do indizível; há observação social.', 'trocar análise por sugestão');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-lit-3', 'literatura-brasileira', 'relacionar-obra-contexto-e-projeto-estetico', 'intermediate', 'interpretation', false, 'Leia o poema autoral:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-3', 'A', 'Romantismo, pela subjetividade do eu lírico.', false, 'Há subjetividade, mas sem idealização, natureza grandiosa ou exaltação sentimental.', 'tomar subjetividade por romantismo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-3', 'B', 'Simbolismo, pela musicalidade dos versos.', false, 'Não há aliterações, sinestesias ou sugestão do indizível.', 'atribuir musicalidade ausente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-3', 'C', 'Barroco, pelo contraste entre a rua e a calçada.', false, 'O contraste é de escala e observação, não conflito espiritual construído com antíteses.', 'confundir contraste com antítese barroca');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-3', 'D', 'Parnasianismo, pelo cuidado com a imagem visual.', false, 'Falta exatamente o que define o Parnasianismo: métrica rigorosa, rima e vocabulário elevado.', 'confundir imagem com forma fixa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-3', 'E', 'Modernismo, pela combinação de verso livre, cena cotidiana e linguagem coloquial.', true, 'Verso livre, cotidiano urbano, vocabulário simples e um fecho de humor discreto compõem o conjunto característico do projeto modernista.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-lit-4', 'literatura-brasileira', 'relacionar-obra-contexto-e-projeto-estetico', 'challenging', 'comparison', false, 'Compare os dois projetos literários:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-4', 'A', 'Hierárquica: o segundo projeto é esteticamente superior ao primeiro.', false, 'Superioridade estética não é uma conclusão que a análise literária sustenta.', 'hierarquizar projetos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-4', 'B', 'Sem relação, por pertencerem a áreas distintas da literatura.', false, 'O segundo se constrói justamente em oposição ao primeiro: há relação direta.', 'negar a relação histórica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-4', 'C', 'De ruptura: o segundo projeto se constrói recusando os critérios do primeiro e propondo outros em seu lugar.', true, 'A relação entre o Parnasianismo e o Modernismo é de ruptura deliberada: a recusa da métrica, da rima e do vocabulário elevado é parte do programa modernista, e no lugar deles entram a fala brasileira e o verso livre.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-4', 'D', 'Complementar: os dois grupos defendem os mesmos valores por caminhos diferentes.', false, 'Os valores são opostos quanto à forma e à língua literária.', 'apagar o conflito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-4', 'E', 'Idêntica em objetivo, já que ambos buscam a beleza formal.', false, 'O segundo projeto recusa a beleza formal como critério central.', 'igualar critérios opostos');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-lit-5', 'literatura-brasileira', 'relacionar-obra-contexto-e-projeto-estetico', 'challenging', 'integration', false, 'Um professor propõe que a turma leia um romance da Geração de 30 sobre a seca no Nordeste ao lado de reportagens atuais sobre migração climática.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-5', 'A', 'A literatura da Geração de 30 elabora esteticamente a relação entre território, desigualdade e deslocamento, o que oferece uma chave de leitura para fenômenos atuais sem confundir obra e reportagem.', true, 'O romance social de 30 não é reportagem: é elaboração estética de um problema. Colocá-lo ao lado de textos jornalísticos ilumina permanências históricas e, ao mesmo tempo, evidencia o que a linguagem literária faz que o jornalismo não faz.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-5', 'B', 'O romance descreve exatamente os mesmos fatos das reportagens, o que comprova a veracidade da obra.', false, 'A obra literária não precisa nem pretende ser verificada como notícia.', 'confundir literatura com documento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-5', 'C', 'A literatura deve ser lida apenas por seu valor estético, sem relação com contextos sociais.', false, 'Isolar a obra do contexto empobrece justamente o projeto da Geração de 30.', 'separar obra e contexto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-5', 'D', 'O romance antecipa acontecimentos futuros, funcionando como previsão social.', false, 'Literatura não é previsão; permanências sociais explicam a atualidade do tema.', 'tratar obra como profecia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-5', 'E', 'As reportagens tornam o romance dispensável, por trazerem dados mais atualizados.', false, 'Dado e elaboração estética cumprem funções diferentes e não se substituem.', 'hierarquizar os dois tipos de texto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-lit-rec-1', 'literatura-brasileira', 'relacionar-obra-contexto-e-projeto-estetico', 'intro', 'concept', true, 'A Semana de Arte Moderna de 1922 teve como um de seus objetivos centrais:', 'O projeto de 1922 recusa o modelo importado e busca uma expressão brasileira — na forma, na língua e nos temas.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-rec-1', 'A', 'Eliminar qualquer referência ao Brasil na literatura.', false, 'O objetivo era o contrário: colocar o Brasil no centro da criação.', 'inverter o objeto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-rec-1', 'B', 'Romper com os modelos europeus importados e construir uma expressão artística brasileira.', true, 'O programa de 1922 recusa a cópia do modelo estrangeiro e busca uma linguagem própria, com material e fala brasileiros.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-rec-1', 'C', 'Substituir a literatura pela pintura como arte principal do país.', false, 'A Semana reuniu várias linguagens, sem hierarquia entre elas.', 'atribuir objetivo inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-rec-1', 'D', 'Restaurar a métrica clássica na poesia brasileira.', false, 'O movimento recusou a métrica fixa como critério de valor.', 'inverter o programa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-lit-rec-1', 'E', 'Consolidar o Romantismo como estética nacional.', false, 'O Romantismo já pertencia ao século anterior e foi objeto de crítica modernista.', 'trocar o movimento');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-lit-1', 'literatura-brasileira', 'relacionar-obra-contexto-e-projeto-estetico', 'intro', 'concept', false, 'A afirmação de que uma obra literária "dialoga com seu contexto histórico" significa, em termos de análise, que:', 'Contexto não é moldura nem causa única. A análise procura como as tensões do período reaparecem transformadas na construção do texto.', 'Contexto não é moldura nem causa única. A análise procura como as tensões do período reaparecem transformadas na construção do texto.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-1', 'A', 'o autor precisa ter participado dos fatos que narra.', false, 'Participação biográfica não é requisito para o diálogo com o contexto.', 'exigência biográfica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-1', 'B', 'as questões, os valores e as tensões do período aparecem transformados pelas escolhas estéticas da obra.', true, 'A obra não copia o contexto: ela o reelabora por meio de forma, linguagem e ponto de vista.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-1', 'C', 'a obra só pode ser lida por quem conhece o período.', false, 'O conhecimento do período enriquece a leitura, mas não é condição para ela.', 'condição excessiva');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-1', 'D', 'o contexto determina integralmente o sentido da obra.', false, 'Determinismo apaga o trabalho estético e a possibilidade de leituras novas.', 'determinismo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-1', 'E', 'a obra descreve fielmente os acontecimentos do período.', false, 'Descrição fiel é tarefa da historiografia, não condição da literatura.', 'reduzir a documento');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-lit-2', 'literatura-brasileira', 'relacionar-obra-contexto-e-projeto-estetico', 'intermediate', 'applied', false, 'Machado de Assis, em suas obras da fase madura, adota narradores que interrompem a história para conversar com o leitor e comentar a própria narrativa. Esse procedimento produz principalmente:', 'O narrador que se mostra construindo a história rompe a ilusão de relato neutro. O leitor passa a avaliar quem conta, e não só o que é contado.', 'O narrador que se mostra construindo a história rompe a ilusão de relato neutro. O leitor passa a avaliar quem conta, e não só o que é contado.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-2', 'A', 'a desconfiança do leitor em relação ao próprio narrador e ao que ele conta.', true, 'Ao exibir que a narrativa é construída por alguém com interesses, o texto convida o leitor a duvidar do relato.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-2', 'B', 'maior fidelidade psicológica das personagens secundárias.', false, 'A intromissão do narrador não se dirige à caracterização das secundárias.', 'efeito trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-2', 'C', 'perda de unidade, prejudicando a compreensão do enredo.', false, 'O procedimento é deliberado e organiza o livro, em vez de desorganizá-lo.', 'julgar como falha');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-2', 'D', 'aproximação com o romance de folhetim, que exige capítulos curtos.', false, 'Capítulos curtos existem, mas a conversa com o leitor não vem dessa exigência.', 'causa trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-2', 'E', 'neutralidade do narrador diante dos fatos narrados.', false, 'É o contrário: o narrador se expõe e toma posição.', 'inverter o efeito');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-lit-3', 'literatura-brasileira', 'relacionar-obra-contexto-e-projeto-estetico', 'intermediate', 'interpretation', false, 'A primeira fase do Modernismo brasileiro adotou linguagem coloquial, verso livre e humor irreverente. Essas escolhas devem ser lidas como:', 'Em literatura, forma é posição. Verso livre e coloquialidade dizem contra o que o grupo escrevia e o que pretendia fundar.', 'Em literatura, forma é posição. Verso livre e coloquialidade dizem contra o que o grupo escrevia e o que pretendia fundar.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-3', 'A', 'imposição de uma política cultural do governo do período.', false, 'O movimento partiu de iniciativa de escritores e artistas.', 'atribuição incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-3', 'B', 'acaso de uma geração que escrevia sem planejamento.', false, 'As escolhas foram programáticas e defendidas em manifestos.', 'negar a intenção');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-3', 'C', 'tomada de posição contra o formalismo parnasiano e a favor de uma expressão brasileira própria.', true, 'Cada escolha formal responde a algo que se queria recusar e a algo que se queria afirmar.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-3', 'D', 'adaptação ao gosto do público leitor da época.', false, 'A recepção inicial foi de estranhamento e rejeição, não de adesão.', 'inverter a recepção');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-3', 'E', 'consequência da falta de domínio da métrica pelos autores.', false, 'Vários modernistas dominavam a métrica tradicional e a abandonaram por escolha.', 'julgar como incapacidade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-lit-4', 'literatura-brasileira', 'relacionar-obra-contexto-e-projeto-estetico', 'challenging', 'comparison', false, 'Comparando o indianismo romântico de José de Alencar e Gonçalves Dias com a representação do indígena na literatura brasileira posterior, uma diferença central é que:', 'O indianismo romântico produziu um símbolo para uma nação em formação. Leituras posteriores questionam a idealização e deslocam quem fala.', 'O indianismo romântico produziu um símbolo para uma nação em formação. Leituras posteriores questionam a idealização e deslocam quem fala.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-4', 'A', 'o indianismo tratou o indígena como personagem cômico.', false, 'O tratamento romântico é heroico e idealizado, não cômico.', 'caracterização trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-4', 'B', 'o indianismo construiu um herói idealizado para fundar um símbolo nacional, enquanto abordagens posteriores buscam o conflito e a voz dos próprios povos.', true, 'O projeto romântico servia à construção de uma identidade nacional; abordagens posteriores questionam essa idealização.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-4', 'C', 'as duas abordagens são equivalentes, mudando só o vocabulário.', false, 'Mudam o lugar do indígena no texto e a função que a representação cumpre.', 'igualar projetos distintos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-4', 'D', 'o indianismo descreveu com precisão etnográfica os povos originários.', false, 'A precisão etnográfica não era o objetivo nem o resultado do projeto romântico.', 'atribuir finalidade documental');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-4', 'E', 'a literatura posterior abandonou o tema indígena.', false, 'O tema reaparece em diferentes momentos e com outras abordagens.', 'afirmação factualmente incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-lit-5', 'literatura-brasileira', 'relacionar-obra-contexto-e-projeto-estetico', 'challenging', 'integration', false, 'Um estudante afirma que a literatura regionalista de 1930 "só interessa a quem conhece o Nordeste". Considerando o modo como esses romances articulam lugar e questão social, essa afirmação:', 'O particular bem construído é o caminho para o geral. Descrever com precisão um lugar e uma condição é o que torna a questão reconhecível fora dele.', 'O particular bem construído é o caminho para o geral. Descrever com precisão um lugar e uma condição é o que torna a questão reconhecível fora dele.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-5', 'A', 'desconhece que o cenário específico é o meio pelo qual a obra trata de questões amplas, como seca, fome, migração e poder.', true, 'A ambientação precisa é o que dá concretude ao problema social, e é justamente ela que permite o alcance mais amplo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-5', 'B', 'está correta, pois obras muito ambientadas perdem alcance.', false, 'Muitas obras de alcance duradouro são fortemente ambientadas.', 'confundir ambientação com limite');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-5', 'C', 'está correta, porque a linguagem regional impede a compreensão.', false, 'A linguagem regional pede atenção, mas não bloqueia a leitura.', 'obstáculo superestimado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-5', 'D', 'está errada, porque esses romances não têm ambientação definida.', false, 'Eles têm ambientação bastante definida; o ponto é o que ela permite dizer.', 'negar o traço');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-lit-5', 'E', 'está errada, porque literatura não trata de questões sociais.', false, 'Trata, e esse conjunto de obras é um exemplo claro disso.', 'negar o tema');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-porc-1', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'intro', 'concept', false, 'Um produto que custava R$ 250,00 passou a custar R$ 300,00.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-1', 'A', '16,7%', false, 'Esse é 50/300 — divide pelo valor final. A variação usa o valor inicial como base.', 'base errada na divisão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-1', 'B', '20%', true, '(300 − 250)/250 = 50/250 = 0,20 → 20%. O denominador é o valor de onde se partiu.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-1', 'C', '25%', false, 'Resultado de 50/200. Nem 200 nem qualquer outro valor do enunciado justifica esse denominador.', 'erro de leitura do valor inicial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-1', 'D', '50%', false, 'Confunde a diferença absoluta (50 reais) com o percentual.', 'usar a diferença absoluta como percentual');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-1', 'E', '83,3%', false, 'Corresponde a 250/300, que é a razão entre os preços, não a variação.', 'calcular razão em vez de variação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-porc-2', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'intermediate', 'applied', false, 'Uma loja anuncia: "30% de desconto e, na segunda peça, mais 20% sobre o valor já com desconto."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-2', 'A', 'R$ 112,00, com desconto total de 56%.', false, 'O valor final está correto, mas 56% é o fator que resta (0,56), não o desconto. O desconto é 1 − 0,56 = 44%.', 'confundir fator restante com desconto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-2', 'B', 'R$ 100,00, com desconto total de 50%.', false, 'Somar 30% + 20% é o erro clássico: o segundo desconto incide sobre um valor já reduzido, não sobre os R$ 200.', 'somar percentuais sucessivos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-2', 'C', 'R$ 112,00, com desconto total de 44%.', true, '200 × 0,70 = 140; 140 × 0,80 = 112. Como 0,70 × 0,80 = 0,56, o desconto equivalente é 44%.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-2', 'D', 'R$ 140,00, com desconto total de 30%.', false, 'Esse é o valor após apenas o primeiro desconto — o segundo foi ignorado.', 'esquecer a segunda etapa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-2', 'E', 'R$ 120,00, com desconto total de 40%.', false, 'Corresponde a um único desconto de 40%, que não é o resultado da composição dos dois.', 'estimar sem calcular');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-porc-3', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'intermediate', 'interpretation', false, 'Uma pesquisa sobre transporte apresentou os dados:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-3', 'A', 'Ambas estão erradas, pois o crescimento foi de 11%.', false, '11% é o valor final, não o crescimento.', 'confundir valor final com variação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-3', 'B', 'A segunda está errada, pois percentual de percentual não existe.', false, 'Variação relativa entre dois percentuais é operação válida e comum em estatística.', 'rejeitar operação válida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-3', 'C', 'A primeira está correta e a segunda exagera o resultado.', false, 'A primeira erra a unidade; a segunda aplica corretamente a fórmula de variação.', 'julgar pelo tamanho do número');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-3', 'D', 'A primeira confunde ponto percentual com porcentagem; a segunda calcula corretamente a variação relativa.', true, 'A diferença é de 3 pontos percentuais. Em variação relativa: (11−8)/8 = 0,375 → 37,5%. A primeira manchete usa a unidade errada.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-3', 'E', 'Ambas estão corretas e dizem exatamente a mesma coisa.', false, 'Descrevem a mesma mudança, mas não a mesma medida: 3 pontos percentuais e 37,5% são grandezas distintas.', 'tratar pontos percentuais e porcentagem como sinônimos');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-porc-4', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'challenging', 'comparison', false, 'Considere duas situações:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-4', 'A', 'Os dois resultam no mesmo valor final.', true, '1,10 × 1,10 = 1,21, exatamente o fator de um aumento único de 21%. Ambos chegam a R$ 2.420.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-4', 'B', 'A situação I resulta em valor maior.', false, 'Seria verdade se o aumento único fosse de 20%. Com 21%, os fatores se igualam.', 'lembrar a regra geral sem conferir o número');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-4', 'C', 'A situação II resulta em valor maior.', false, 'Os fatores são idênticos (1,21), então não há vantagem para nenhuma das duas.', 'estimar sem multiplicar');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-4', 'D', 'A situação I resulta em R$ 2.400 e a II, em R$ 2.420.', false, 'R$ 2.400 corresponderia a somar os percentuais (20%), o que não é como aumentos sucessivos funcionam.', 'somar percentuais sucessivos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-4', 'E', 'Não é possível comparar sem saber o intervalo entre os aumentos.', false, 'O intervalo de tempo não altera o valor final quando os percentuais são dados.', 'introduzir variável irrelevante');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-porc-5', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'challenging', 'integration', false, 'Uma família gasta R$ 900 por mês em alimentação, o que corresponde a 30% da renda mensal. No mês seguinte, a renda cai 10% e o gasto com alimentação sobe 5%.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-5', 'A', 'Cerca de 35%.', true, 'Renda inicial = 900/0,30 = R$ 3.000. Nova renda = 2.700. Novo gasto = 945. 945/2.700 = 0,35 → 35%.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-5', 'B', 'Cerca de 32%.', false, 'Resultado de somar as duas variações (30% + 5% − ...), sem recalcular a razão entre os novos valores.', 'somar variações em vez de recalcular a razão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-5', 'C', 'Cerca de 31,5%.', false, 'Corresponde a aplicar apenas o aumento do gasto (30% × 1,05), ignorando a queda da renda.', 'considerar só uma das mudanças');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-5', 'D', 'Cerca de 27%.', false, 'Aplica a queda de 10% ao percentual, o que inverte o efeito: renda menor aumenta o peso do gasto.', 'inverter o sentido do efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-5', 'E', 'Continua em 30%, pois as variações se compensam.', false, 'As variações têm sentidos que se somam no mesmo efeito: renda menor e gasto maior aumentam o comprometimento.', 'supor compensação sem verificar');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-porc-rec-1', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'intro', 'concept', true, 'Um item de R$ 80,00 recebe 15% de desconto. Qual é o valor final?', 'Desconto de 15% → fator 0,85 → 80 × 0,85 = R$ 68,00.', NULL, NULL, NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-rec-1', 'A', 'R$ 12,00', false, 'Esse é o valor do desconto (15% de 80), não o preço final.', 'parar no cálculo da parte');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-rec-1', 'B', 'R$ 65,00', false, 'Corresponde a um desconto de R$ 15, e não de 15%.', 'confundir percentual com valor absoluto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-rec-1', 'C', 'R$ 68,00', true, '80 × 0,85 = 68. Usar o fator resolve em uma operação.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-rec-1', 'D', 'R$ 72,00', false, 'Corresponde a 10% de desconto.', 'arredondar o percentual');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-rec-1', 'E', 'R$ 92,00', false, 'Aplicou aumento em vez de desconto.', 'inverter o sentido da variação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-porc-rec-2', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'intermediate', 'applied', true, 'O número de inscritos em uma atividade caiu de 120 para 96.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-rec-2', 'A', '20%', true, '(96 − 120)/120 = −24/120 = −0,20 → queda de 20%.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-rec-2', 'B', '24%', false, 'Usa a diferença absoluta (24) como se fosse o percentual.', 'confundir diferença com percentual');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-rec-2', 'C', '25%', false, 'Resultado de 24/96 — divide pelo valor final em vez do inicial.', 'base errada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-rec-2', 'D', '80%', false, 'É a razão 96/120, ou seja, quanto restou, não quanto caiu.', 'confundir proporção restante com variação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-rec-2', 'E', '4%', false, 'Não corresponde a nenhuma operação válida com os dados.', 'chute');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-porc-6', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'intro', 'concept', false, 'Um produto de R$ 200 recebe aumento de 20% e, na semana seguinte, desconto de 20% sobre o novo preço. Ao final, o produto custa:', 'Variações sucessivas são multiplicativas: 200 × 1,20 × 0,80 = 192. O resultado fica 4% abaixo do valor inicial.', 'Variações sucessivas são multiplicativas: 200 × 1,20 × 0,80 = 192. O resultado fica 4% abaixo do valor inicial.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-6', 'A', 'R$ 160,00.', false, 'Esse valor corresponderia a aplicar apenas 20% de desconto sobre o preço inicial.', 'usar uma única variação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-6', 'B', 'R$ 180,00.', false, 'O desconto não é de R$ 60; ele vale 20% de R$ 240, isto é, R$ 48.', 'erro de base');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-6', 'C', 'R$ 192,00.', true, 'O preço sobe para R$ 240 e depois cai R$ 48: 240 × 0,80 = 192.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-6', 'D', 'R$ 200,00.', false, 'Percentuais iguais não se anulam porque são aplicados sobre bases diferentes.', 'cancelar percentuais');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-6', 'E', 'R$ 208,00.', false, 'O cálculo mistura diferença percentual com soma em reais.', 'procedimento incompatível');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-porc-7', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'intermediate', 'applied', false, 'Uma cozinha escolar usava 500 kg de alimentos por mês e descartava 18% desse total. Após uma mudança, o consumo caiu para 480 kg e o descarte passou a 10% do novo total. Quantos quilogramas de descarte foram evitados por mês?', 'É preciso converter cada percentual em massa na sua própria base: 90 kg antes e 48 kg depois, resultando em 42 kg evitados.', 'É preciso converter cada percentual em massa na sua própria base: 90 kg antes e 48 kg depois, resultando em 42 kg evitados.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-7', 'A', '8 kg.', false, 'Oito é a queda em pontos percentuais, não uma massa.', 'confundir unidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-7', 'B', '20 kg.', false, 'Esse é apenas o decréscimo do consumo total.', 'usar dado irrelevante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-7', 'C', '40 kg.', false, 'Esse valor aplica 8% sobre 500, sem recalcular o descarte final na nova base.', 'manter base antiga');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-7', 'D', '38 kg.', false, 'Esse valor resulta de subtrair percentuais como se fossem quilogramas.', 'confundir pontos percentuais e massa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-7', 'E', '42 kg.', true, 'Antes eram 90 kg (18% de 500); depois são 48 kg (10% de 480). A diferença é 42 kg.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-porc-8', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'intermediate', 'interpretation', false, 'Uma tabela informa que a participação de fontes renováveis passou de 40% para 46% em uma matriz energética. Nesse período, o consumo total de energia aumentou de 100 para 120 unidades. A quantidade de energia renovável passou de:', 'Percentual é uma proporção do total de cada momento. Como a participação e o consumo total cresceram, a quantidade renovável aumentou para 55,2 unidades.', 'Percentual é uma proporção do total de cada momento. Como a participação e o consumo total cresceram, a quantidade renovável aumentou para 55,2 unidades.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-8', 'A', '48 para 55,2 unidades.', false, 'O valor inicial é 40% de 100, não 40% de 120.', 'usar base final no início');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-8', 'B', '40 para 52 unidades.', false, '52 não corresponde a 46% de 120.', 'produto incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-8', 'C', '46 para 60 unidades.', false, 'Os percentuais foram tratados como quantidades sem respeitar os totais.', 'confundir proporção e quantidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-8', 'D', '40 para 46 unidades.', false, 'O valor final precisa considerar 46% de 120, não 46% de 100.', 'ignorar mudança do total');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-8', 'E', '40 para 55,2 unidades.', true, 'No início: 40% de 100 = 40. No fim: 46% de 120 = 55,2.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-porc-9', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'challenging', 'comparison', false, 'Uma compra de R$ 1.000 pode ser paga por duas ofertas: I. desconto de 8% à vista; II. entrada de R$ 500 e parcela de R$ 540 em 30 dias. Desconsiderando rendimento do dinheiro, a comparação correta é:', 'A comparação deve ser feita pelos valores pagos: R$ 920 contra R$ 1.040, uma diferença de R$ 120.', 'A comparação deve ser feita pelos valores pagos: R$ 920 contra R$ 1.040, uma diferença de R$ 120.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-9', 'A', 'Não é possível comparar sem saber a taxa mensal.', false, 'Os valores finais já foram informados e o enunciado manda desconsiderar rendimentos.', 'criar dado necessário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-9', 'B', 'A oferta à vista custa R$ 920 e economiza R$ 120 em relação à parcelada.', true, 'À vista: 1000 × 0,92 = 920. Parcelada: 500 + 540 = 1040. Diferença: 120.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-9', 'C', 'As duas ofertas custam R$ 960.', false, 'O desconto foi calculado incorretamente e a soma da parcelada ignorada.', 'dois cálculos incorretos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-9', 'D', 'A oferta parcelada é 4% mais barata que o preço original.', false, 'Ela custa 4% a mais: R$ 1.040.', 'inverter acréscimo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-9', 'E', 'A oferta à vista economiza apenas R$ 80 em relação à parcelada.', false, 'R$ 80 é o desconto sobre o preço de referência; a diferença para R$ 1.040 é R$ 120.', 'comparar com base errada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-porc-10', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'challenging', 'integration', false, 'Uma praça retangular de 40 m por 25 m terá 30% de sua área destinada a jardins. Dos jardins, 20% serão ocupados por caminhos permeáveis. Qual será a área efetivamente plantada?', 'A área total é 1.000 m². O jardim ocupa 300 m²; retirando 20% para caminhos, restam 80% de 300, isto é, 240 m².', 'A área total é 1.000 m². O jardim ocupa 300 m²; retirando 20% para caminhos, restam 80% de 300, isto é, 240 m².', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-10', 'A', '260 m².', false, 'Esse resultado retira apenas 40 m² dos 300, em vez de calcular 20% de 300.', 'percentual incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-10', 'B', '300 m².', false, 'Essa é a área total destinada a jardins antes de retirar os caminhos.', 'parar antes da segunda etapa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-10', 'C', '240 m².', true, 'A praça tem 1.000 m²; jardins ocupam 300 m² e a parte plantada é 80% disso: 240 m².', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-10', 'D', '760 m².', false, 'Esse é o complemento de 24% da praça, não a área plantada.', 'usar complemento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-porc-10', 'E', '200 m².', false, 'Esse valor é 20% da praça toda, mas os caminhos ocupam 20% apenas da área de jardins.', 'base incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-porc-1', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'intro', 'concept', false, 'Um aplicativo mostra que a bateria caiu de 80% para 60% em uma hora de uso. Sobre essa queda, é correto dizer que ela foi de:', 'Ponto percentual e porcentagem são coisas diferentes. A carga caiu 20 pontos percentuais, mas essa queda representa 25% da carga que existia no início.', 'Ponto percentual e porcentagem são coisas diferentes. A carga caiu 20 pontos percentuais, mas essa queda representa 25% da carga que existia no início.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-1', 'A', '25%, porque 20 dividido por 80 é 0,25.', true, 'A variação relativa compara a queda com a carga inicial: 20 ÷ 80 = 0,25, isto é, 25%.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-1', 'B', '33%, porque 20 dividido por 60 é aproximadamente 0,33.', false, 'O denominador de uma queda é o valor inicial, não o final.', 'usar base final');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-1', 'C', 'Não dá para calcular sem saber a capacidade em miliampère-hora.', false, 'A comparação é entre percentuais de uma mesma bateria, e a capacidade se cancela.', 'exigir dado desnecessário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-1', 'D', '20%, porque 80 menos 60 é 20.', false, 'Vinte é a diferença em pontos percentuais; a variação relativa usa o valor inicial como base.', 'confundir ponto percentual com variação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-1', 'E', '40%, porque a bateria caiu quase pela metade.', false, 'A metade de 80 seria 40, e a carga parou em 60, não em 40.', 'estimativa sem cálculo');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-porc-2', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'intermediate', 'applied', false, 'Uma padaria vendia 400 pães por dia a R$ 0,50. Ao subir o preço em 10%, a quantidade vendida caiu 10%. O faturamento diário passou a ser:', 'Faturamento é preço vezes quantidade. Com fatores 1,10 e 0,90, o produto é 0,99: o faturamento cai 1%, e não fica igual.', 'Faturamento é preço vezes quantidade. Com fatores 1,10 e 0,90, o produto é 0,99: o faturamento cai 1%, e não fica igual.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-2', 'A', 'R$ 220,00, porque o preço subiu 10%.', false, 'Esse valor ignora a queda na quantidade vendida.', 'usar só uma variação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-2', 'B', 'R$ 180,00, porque a quantidade caiu 10%.', false, 'Esse valor ignora o aumento de preço.', 'usar só uma variação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-2', 'C', 'R$ 202,00, porque o preço pesa mais que a quantidade.', false, 'As duas grandezas entram no faturamento com o mesmo peso, por multiplicação.', 'hierarquia inventada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-2', 'D', 'R$ 198,00, ou seja, 1% menor que antes.', true, 'O novo faturamento é 360 × 0,55 = 198, contra 200 antes: uma queda de 1%.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-2', 'E', 'R$ 200,00, porque a alta e a queda se anulam.', false, 'Elas incidem sobre grandezas diferentes, então o produto muda: 1,10 × 0,90 = 0,99.', 'cancelar percentuais');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-porc-3', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'intermediate', 'interpretation', false, 'Uma reportagem afirma: "o número de casos aumentou 200%". Um leitor entende que os casos dobraram. Sobre essa leitura, pode-se afirmar que:', 'Aumentar 200% é somar duas vezes o valor inicial ao valor inicial: o total fica três vezes maior. Dobrar corresponde a aumentar 100%.', 'Aumentar 200% é somar duas vezes o valor inicial ao valor inicial: o total fica três vezes maior. Dobrar corresponde a aumentar 100%.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-3', 'A', 'O leitor está certo: 200% é o dobro.', false, 'Dobrar corresponde a um aumento de 100%, que leva o total a 200% do inicial.', 'confundir aumento e total');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-3', 'B', 'O leitor está certo, porque percentual acima de 100% não existe.', false, 'Aumentos maiores que 100% existem e são comuns quando a base é pequena.', 'regra inventada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-3', 'C', 'O leitor está errado: os casos caíram para um terço.', false, 'O texto fala em aumento, não em queda.', 'inverter o sentido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-3', 'D', 'O leitor está errado: os casos triplicaram.', true, 'Um aumento de 200% soma duas vezes o valor inicial ao próprio valor inicial, chegando a três vezes.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-3', 'E', 'Não é possível decidir sem o número absoluto de casos.', false, 'A relação entre inicial e final é percentual e independe do valor absoluto.', 'exigir dado desnecessário');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-porc-4', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'challenging', 'comparison', false, 'Duas lojas anunciam o mesmo tênis de R$ 300. A primeira dá 30% de desconto. A segunda dá dois descontos sucessivos de 15% e 15%. Comparando as duas ofertas:', 'Descontos sucessivos multiplicam fatores: 0,85 × 0,85 = 0,7225, equivalente a um único desconto de 27,75%. É menos vantajoso que 30% de uma vez.', 'Descontos sucessivos multiplicam fatores: 0,85 × 0,85 = 0,7225, equivalente a um único desconto de 27,75%. É menos vantajoso que 30% de uma vez.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-4', 'A', 'A segunda sai mais barata, por R$ 22,50.', false, 'Esse valor não corresponde a nenhuma das duas contas.', 'operação incompatível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-4', 'B', 'Só é possível comparar sabendo se há frete.', false, 'O enunciado compara apenas os preços anunciados, e ambos partem de R$ 300.', 'criar dado necessário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-4', 'C', 'As duas cobram o mesmo, porque 15 mais 15 é 30.', false, 'O segundo desconto incide sobre um preço já reduzido, então retira menos em reais.', 'somar percentuais');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-4', 'D', 'A primeira sai mais barata, por R$ 6,75.', true, 'Desconto único: 300 × 0,70 = 210. Sucessivos: 300 × 0,85 × 0,85 = 216,75. A diferença é 6,75.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-4', 'E', 'A segunda sai mais barata, por R$ 6,75.', false, 'O cálculo está certo em valor, mas invertido: descontos sucessivos deixam o preço mais alto.', 'inverter a comparação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-porc-5', 'porcentagem-e-variacao', 'resolver-situacoes-com-variacao-percentual', 'challenging', 'integration', false, 'Uma escola tinha 250 alunos, dos quais 40% no período da tarde. No ano seguinte, a escola cresceu 20% no total e o número de alunos da tarde passou a 130. A participação da tarde no total:', 'A tarde cresceu 30% enquanto a escola cresceu 20%, então sua participação sobe. O cálculo final usa o total novo: 130 ÷ 300 ≈ 43%.', 'A tarde cresceu 30% enquanto a escola cresceu 20%, então sua participação sobe. O cálculo final usa o total novo: 130 ÷ 300 ≈ 43%.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-5', 'A', 'subiu para 52%, porque 130 é 52% de 250.', false, 'O denominador precisa ser o total novo, 300, e não o antigo.', 'usar base antiga');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-5', 'B', 'subiu para 45%, porque a tarde ganhou 30 alunos.', false, 'O ganho absoluto não define a participação; é preciso dividir pelo novo total.', 'confundir ganho e proporção');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-5', 'C', 'subiu de 40% para cerca de 43%.', true, 'O total passou a 300 alunos e a tarde a 130: 130 ÷ 300 ≈ 0,433, isto é, cerca de 43%.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-5', 'D', 'caiu, porque a escola cresceu mais que a tarde.', false, 'A tarde saiu de 100 para 130 alunos, um crescimento de 30%, acima dos 20% do total.', 'comparar apenas totais');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-porc-5', 'E', 'ficou igual, em 40%.', false, 'Se a participação não mudasse, a tarde teria 120 alunos, e não 130.', 'supor proporção constante');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-graf-1', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'intro', 'concept', false, 'A tabela mostra o número de atendimentos em duas unidades de saúde:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-1', 'A', 'Norte, pois realizou mais atendimentos.', false, 'O número absoluto é maior, mas a população também é o dobro. A comparação precisa ser proporcional.', 'comparar absolutos com bases diferentes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-1', 'B', 'Sul, com 0,20 atendimento por habitante contra 0,15 da Norte.', true, 'Norte: 4.500/30.000 = 0,15. Sul: 3.000/15.000 = 0,20. A Sul atende proporcionalmente mais.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-1', 'C', 'As duas têm a mesma taxa.', false, 'As taxas são 0,15 e 0,20 — diferentes.', 'assumir equivalência sem calcular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-1', 'D', 'Norte, com 6,67 habitantes por atendimento.', false, 'O cálculo está certo (30.000/4.500), mas a razão invertida favorece quem tem MENOS habitantes por atendimento: a Sul tem 5.', 'inverter a razão e ler ao contrário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-1', 'E', 'Não é possível comparar sem saber o número de profissionais.', false, 'A pergunta é sobre atendimentos por habitante, e os dois dados necessários estão na tabela.', 'exigir dado desnecessário');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-graf-2', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'intermediate', 'applied', false, 'Um relatório apresenta o consumo médio de energia de uma residência ao longo de um ano. Os valores de janeiro e julho são os mais altos; abril e outubro, os mais baixos.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-2', 'A', 'Séries temporais não permitem nenhum tipo de conclusão.', false, 'Permitem conclusões, desde que controlados os fatores que competem pela explicação.', 'generalizar a cautela');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-2', 'B', 'A queda pode refletir variação sazonal, e não o efeito da campanha.', true, 'A própria série indica padrão sazonal (picos em janeiro e julho). Sem comparar com o mesmo período de outros anos, não é possível separar a campanha do padrão.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-2', 'C', 'Os dados de consumo não podem ser comparados entre meses diferentes.', false, 'Podem ser comparados; a ressalva é sobre a interpretação causal, não sobre a comparabilidade.', 'rejeitar comparação válida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-2', 'D', 'O relatório não apresenta valores em reais, apenas em consumo.', false, 'A conclusão do leitor é sobre consumo, então a unidade é adequada.', 'exigir dado irrelevante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-2', 'E', 'A campanha começou em fevereiro, portanto não pode afetar abril.', false, 'Uma campanha de fevereiro pode, sim, afetar abril. O problema é outro: distinguir esse efeito da sazonalidade.', 'rejeitar por razão errada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-graf-3', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'intermediate', 'interpretation', false, 'Um gráfico de barras compara o índice de satisfação de dois serviços. As barras aparentam alturas muito diferentes. Consultando os eixos, verifica-se que o eixo vertical vai de 60 a 68, e que os valores são: Serviço A = 62 e Serviço B = 66.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-3', 'A', 'O gráfico é inválido e não permite nenhuma conclusão.', false, 'O gráfico é enganoso na forma, mas os valores dos eixos permitem a leitura correta.', 'descartar dado utilizável');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-3', 'B', 'A diferença é de 4%, calculada como 66 − 62 dividido por 100.', false, 'Dividir por 100 pressupõe que o índice vá de 0 a 100 como base de variação, o que não é a fórmula de variação relativa.', 'usar base arbitrária');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-3', 'C', 'A diferença real é de 4 pontos (cerca de 6,5%), bem menor do que a impressão visual sugere.', true, '66 − 62 = 4 pontos; em termos relativos, 4/62 ≈ 6,5%. O eixo iniciado em 60 amplia visualmente essa diferença.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-3', 'D', 'O serviço B tem satisfação aproximadamente duas vezes maior que o A.', false, 'Essa é exatamente a leitura induzida pelo eixo cortado. Os valores mostram diferença de 6,5%, não de 100%.', 'ler a altura em vez do número');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-3', 'E', 'Não há diferença entre os serviços, pois o gráfico está distorcido.', false, 'A distorção é da representação, não dos dados. A diferença de 4 pontos existe.', 'negar o dado por causa da forma');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-graf-4', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'challenging', 'comparison', false, 'Dois gráficos apresentam a mesma série de vendas mensais de uma empresa:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-4', 'A', 'Apenas o gráfico I pode ser usado em publicações sérias.', false, 'Escalas estreitas são legítimas quando o objetivo é examinar variações pequenas — desde que o eixo esteja visível.', 'regra rígida sem considerar o objetivo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-4', 'B', 'Os dois gráficos levarão qualquer leitor à mesma conclusão.', false, 'A percepção visual muda de forma significativa, mesmo com dados idênticos.', 'ignorar o efeito da representação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-4', 'C', 'O gráfico I exagera as variações da série.', false, 'É o contrário: a escala ampla reduz a percepção das variações.', 'inverter o efeito da escala');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-4', 'D', 'Ambos representam os mesmos dados; I favorece a percepção de estabilidade e II, a de oscilação.', true, 'A escala não altera os dados, mas altera a leitura: escala ampla achata as variações; escala estreita as amplia. Nenhum é falso, mas cada um sugere uma narrativa.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-4', 'E', 'O gráfico II apresenta dados incorretos, pois omite parte do eixo.', false, 'Omitir parte do eixo é escolha de escala, não erro de dado.', 'confundir escolha de escala com erro');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-graf-5', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'challenging', 'integration', false, 'Um estudo apresenta um gráfico de dispersão relacionando, para 40 municípios, o número de bibliotecas públicas e o índice de desempenho escolar. Os pontos indicam associação positiva.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-5', 'A', 'O desempenho escolar determina quantas bibliotecas um município constrói.', false, 'Inverte a direção, mas comete o mesmo erro: atribuir causalidade a partir de associação.', 'causalidade invertida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-5', 'B', 'Como há exceções entre os pontos, não existe relação alguma entre as variáveis.', false, 'Dispersão com exceções ainda pode indicar associação. A presença de casos fora do padrão não anula a tendência.', 'exigir relação perfeita');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-5', 'C', 'A associação observada só teria validade com mais de 100 municípios.', false, 'Não existe limiar fixo de 100 observações; o tamanho adequado depende do desenho do estudo.', 'inventar critério estatístico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-5', 'D', 'Existe associação positiva entre as variáveis, o que não permite concluir, isoladamente, que uma cause a outra.', true, 'O gráfico mostra associação. Municípios com mais recursos podem ter simultaneamente mais bibliotecas e melhor desempenho — uma terceira variável explicando as duas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-5', 'E', 'A construção de bibliotecas eleva o desempenho escolar dos municípios.', false, 'Essa é a conclusão causal que o gráfico não sustenta: correlação não distingue causa, causa comum e coincidência.', 'transformar correlação em causa');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-graf-rec-1', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'intro', 'concept', true, 'Em um gráfico de setores sobre meios de transporte usados para ir ao trabalho, a fatia "ônibus" corresponde a 35% e a fatia "a pé" a 15%. O total de entrevistados foi 800.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-rec-1', 'A', '400 pessoas', false, 'Corresponde a metade dos entrevistados, valor não relacionado às fatias citadas.', 'chute');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-rec-1', 'B', '120 pessoas', false, 'É o número de quem vai a pé.', 'responder a outra fatia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-rec-1', 'C', '20 pessoas', false, 'Esse é o valor da diferença percentual (20), não o número de pessoas.', 'confundir pontos percentuais com pessoas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-rec-1', 'D', '160 pessoas', true, '20% de 800 = 160. Ou: 280 (ônibus) − 120 (a pé) = 160.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-rec-1', 'E', '280 pessoas', false, 'É o total de usuários de ônibus, não a diferença.', 'responder o valor de uma das fatias');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-graf-rec-2', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'intermediate', 'interpretation', true, 'Uma série mostra o número de inscrições em um curso: 120, 118, 125, 122 e 127 nos últimos cinco semestres.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-rec-2', 'A', 'Os valores oscilam em torno de um patamar, com leve tendência de alta.', true, 'A variação total é de 9 inscrições sobre ~120 (cerca de 7%), com subidas e descidas. Descrever como estabilidade com leve alta é a leitura mais fiel.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-rec-2', 'B', 'Há crescimento constante ao longo dos cinco semestres.', false, 'Não é constante: houve queda do primeiro para o segundo e do terceiro para o quarto.', 'ignorar as quedas intermediárias');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-rec-2', 'C', 'Há queda acentuada nas inscrições.', false, 'O último valor é o maior da série.', 'leitura contrária ao dado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-rec-2', 'D', 'A série indica que o curso dobrará de tamanho no próximo semestre.', false, 'Nada na série sustenta projeção de dobra.', 'extrapolar projeção');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-rec-2', 'E', 'Os dados são insuficientes para qualquer descrição.', false, 'Cinco pontos permitem descrever o comportamento observado, ainda que não permitam projeções firmes.', 'excesso de cautela');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-graf-6', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'intro', 'concept', false, 'Dois gráficos exibem vendas de 98 e 102 unidades. No primeiro, o eixo vertical começa em zero; no segundo, começa em 95. Sobre a leitura visual, é correto afirmar que:', 'A escala não muda a diferença de 4 unidades, mas pode fazê-la parecer muito maior. Por isso, eixos e intervalos fazem parte da leitura do dado.', 'A escala não muda a diferença de 4 unidades, mas pode fazê-la parecer muito maior. Por isso, eixos e intervalos fazem parte da leitura do dado.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-6', 'A', 'O segundo gráfico é sempre inválido.', false, 'Eixos truncados podem ser usados, desde que claramente indicados e interpretados com cuidado.', 'regra absoluta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-6', 'B', 'Os dois gráficos mostram variação de 95 unidades.', false, '95 é o início do eixo do segundo gráfico, não a variação.', 'ler marca do eixo como dado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-6', 'C', 'O segundo amplia visualmente uma diferença de 4 unidades sem mudar a diferença numérica.', true, 'O recorte do eixo faz a distância ocupar maior parte da altura do gráfico.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-6', 'D', 'O segundo gráfico altera os valores originais.', false, 'A escala muda a aparência, mas os valores plotados podem continuar 98 e 102.', 'confundir escala com dado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-6', 'E', 'O primeiro gráfico prova que não houve diferença.', false, 'A diferença existe, embora pareça pequena quando o eixo começa em zero.', 'negar diferença pequena');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-graf-7', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'intro', 'applied', false, 'Uma tabela de ônibus mostra saídas às 7h10, 7h35, 8h00 e 8h40. Uma estudante chega ao ponto às 7h38 e a viagem dura 50 minutos. No primeiro ônibus que pode pegar, ela chegará às:', 'É preciso primeiro selecionar a primeira saída posterior a 7h38 (8h00) e só então adicionar os 50 minutos de viagem.', 'É preciso primeiro selecionar a primeira saída posterior a 7h38 (8h00) e só então adicionar os 50 minutos de viagem.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-7', 'A', '8h25.', false, 'Esse cálculo usa a saída das 7h35, já perdida.', 'ignorar condição temporal');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-7', 'B', '8h50.', true, 'O primeiro ônibus possível sai às 8h00; somando 50 minutos, chega às 8h50.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-7', 'C', '9h00.', false, 'Foram somados 60 minutos em vez de 50.', 'erro de duração');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-7', 'D', '9h30.', false, 'Esse horário usa a saída seguinte, das 8h40, sem necessidade.', 'pular opção disponível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-7', 'E', '7h50.', false, 'A duração foi somada ao horário de chegada ao ponto, não ao de saída do ônibus.', 'base temporal errada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-graf-8', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'intermediate', 'interpretation', false, 'Uma tabela registra coleta seletiva (em toneladas): bairro A, 12 em janeiro e 18 em fevereiro; bairro B, 20 e 22; bairro C, 8 e 16. Qual afirmação é sustentada pelos dados?', 'A tabela permite distinguir crescimento relativo e valor final: C teve a maior variação percentual, e B manteve o maior total de fevereiro.', 'A tabela permite distinguir crescimento relativo e valor final: C teve a maior variação percentual, e B manteve o maior total de fevereiro.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-8', 'A', 'Os três bairros cresceram a mesma quantidade.', false, 'Os aumentos foram 6, 2 e 8 toneladas.', 'ignorar diferenças');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-8', 'B', 'A coleta total caiu de janeiro para fevereiro.', false, 'O total passou de 40 para 56 toneladas.', 'inverter tendência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-8', 'C', 'O bairro B teve o maior crescimento percentual.', false, 'B cresceu 10%, enquanto A cresceu 50% e C, 100%.', 'comparar apenas valor final');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-8', 'D', 'O bairro A coletou mais que B em fevereiro.', false, 'A coletou 18 e B, 22.', 'trocar valores');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-8', 'E', 'O bairro C dobrou a coleta, embora B tenha o maior valor final.', true, 'C passou de 8 para 16, aumento de 100%; B terminou com 22.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-graf-9', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'challenging', 'comparison', false, 'O conjunto I tem valores 4, 5, 5, 6 e 20. O conjunto II tem 7, 8, 8, 9 e 8. Para representar um valor típico sem ser muito afetado por extremos, a comparação mais adequada usa:', 'Quando há um extremo como 20, a mediana representa melhor o centro do conjunto porque depende da ordem, não da distância do extremo.', 'Quando há um extremo como 20, a mediana representa melhor o centro do conjunto porque depende da ordem, não da distância do extremo.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-9', 'A', 'A amplitude: 16 no conjunto I e 2 no conjunto II.', false, 'Amplitude mede dispersão, não valor típico.', 'confundir centro e dispersão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-9', 'B', 'A soma: 40 nos dois conjuntos.', false, 'A soma igual esconde distribuições muito diferentes e não representa um indivíduo típico.', 'usar total');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-9', 'C', 'O maior valor: 20 e 9.', false, 'Máximo descreve extremo, não tendência central.', 'escolher extremo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-9', 'D', 'A primeira observação: 4 e 7.', false, 'A posição de registro não tem função de medida central.', 'critério arbitrário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-9', 'E', 'A mediana: 5 no conjunto I e 8 no conjunto II.', true, 'A mediana usa a posição central e não é puxada pelo valor extremo 20.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-graf-10', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'challenging', 'integration', false, 'Um gráfico de linha mostra o volume de um reservatório caindo de 80% para 68% em 6 dias, em ritmo aproximadamente constante. Mantido esse ritmo por mais 4 dias, a estimativa do volume será:', 'A inclinação média é de -2 pontos percentuais por dia. Extrapolando por 4 dias, 68 - 8 = 60%.', 'A inclinação média é de -2 pontos percentuais por dia. Extrapolando por 4 dias, 68 - 8 = 60%.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-10', 'A', '48%.', false, 'Esse resultado supõe queda de 5 pontos por dia, não sustentada pelos dados.', 'taxa incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-10', 'B', '56%.', false, 'Esse valor prolonga a queda de 12 pontos por mais um bloco inteiro de 6 dias, não 4.', 'proporção temporal errada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-10', 'C', '62%.', false, 'Esse resultado considera queda de 1,5 ponto por dia, menor que a observada.', 'taxa incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-10', 'D', '60%.', true, 'A queda foi de 12 pontos em 6 dias, ou 2 pontos por dia. Em 4 dias: menos 8 pontos, chegando a 60%.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-graf-10', 'E', '64%.', false, 'Esse resultado aplica queda de 1 ponto por dia.', 'taxa pela metade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-graf-1', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'intro', 'concept', false, 'Um gráfico de setores mostra a distribuição de gastos de uma família: moradia 35%, alimentação 25%, transporte 15%, saúde 10% e outros 15%. Para saber quanto foi gasto com moradia em reais, é indispensável conhecer:', 'Gráfico de setores exibe proporções. Sem o total de referência, 35% é uma fatia, não uma quantia.', 'Gráfico de setores exibe proporções. Sem o total de referência, 35% é uma fatia, não uma quantia.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-1', 'A', 'a renda média do bairro.', false, 'A referência externa não informa o gasto desta família.', 'dado externo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-1', 'B', 'nada além do gráfico, que já traz o valor.', false, 'Um gráfico de setores em percentuais não contém valores absolutos.', 'supor dado inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-1', 'C', 'o gasto total da família no período.', true, 'Setores mostram participação; o valor em reais só aparece aplicando o percentual sobre o total.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-1', 'D', 'o número de pessoas na família.', false, 'O tamanho da família não converte percentual em reais.', 'dado irrelevante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-1', 'E', 'o ângulo de cada setor em graus.', false, 'O ângulo é outra forma de exibir o mesmo percentual, e não acrescenta o total.', 'informação redundante');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-graf-2', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'intermediate', 'applied', false, 'Uma tabela mostra a produção mensal de uma fábrica: janeiro 1.200, fevereiro 1.320, março 1.188 e abril 1.307 unidades. A maior variação percentual entre dois meses seguidos aconteceu de:', 'Cada variação é calculada sobre o mês anterior: +10,0%, −10,0% e +10,02%. Em módulo, a queda de fevereiro para março empata no topo e é a única queda, o que a torna a variação a destacar.', 'Cada variação é calculada sobre o mês anterior: +10,0%, −10,0% e +10,02%. Em módulo, a queda de fevereiro para março empata no topo e é a única queda, o que a torna a variação a destacar.', 'Em tabelas curtas, calcule as variações percentuais uma a uma antes de comparar: diferenças absolutas iguais podem esconder variações relativas diferentes.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-2', 'A', 'fevereiro para março, com queda de 10%.', true, 'A queda é de 132 sobre 1.320, exatamente 10%, a maior variação em módulo do período.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-2', 'B', 'janeiro para março, porque a produção caiu no acumulado.', false, 'O enunciado pede meses seguidos, e janeiro e março não são consecutivos.', 'ignorar a restrição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-2', 'C', 'Não houve variação relevante, pois todos os meses ficam perto de 1.250.', false, 'Proximidade da média não substitui o cálculo mês a mês.', 'estimativa sem cálculo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-2', 'D', 'janeiro para fevereiro, com alta de 120 unidades.', false, 'A alta é de 10%, menor em módulo que a queda seguinte.', 'comparar valores absolutos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-2', 'E', 'março para abril, porque a produção voltou a subir.', false, 'A alta é de 119 sobre 1.188, cerca de 10,0%.', 'confundir direção com magnitude');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-graf-3', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'intermediate', 'interpretation', false, 'Um gráfico de linhas cruza duas curvas: número de assinantes de um serviço e receita mensal. No ponto em que as curvas se cruzam, o que se pode afirmar com segurança?', 'Duas séries com unidades diferentes só se cruzam porque alguém escolheu as escalas. O cruzamento é um efeito de desenho, não um fato do fenômeno.', 'Duas séries com unidades diferentes só se cruzam porque alguém escolheu as escalas. O cruzamento é um efeito de desenho, não um fato do fenômeno.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-3', 'A', 'Apenas que os dois valores lidos naquele mês coincidem nas escalas usadas.', true, 'Séries com unidades diferentes só se cruzam por causa das escalas escolhidas; o encontro não tem significado próprio.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-3', 'B', 'Que o número de assinantes passou a superar a receita.', false, 'Comparar assinantes com reais é comparar unidades incompatíveis.', 'comparar unidades diferentes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-3', 'C', 'Que a receita passou a crescer mais que os assinantes.', false, 'O cruzamento não indica taxa de crescimento; para isso é preciso olhar a inclinação.', 'confundir ponto com tendência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-3', 'D', 'Que cada assinante passou a pagar mais.', false, 'Receita por assinante exige dividir uma série pela outra, e não observar um encontro visual.', 'inferência sem cálculo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-3', 'E', 'Que o serviço passou a dar lucro naquele mês.', false, 'Lucro depende de custos, que não estão no gráfico.', 'usar dado ausente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-graf-4', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'intermediate', 'comparison', false, 'Para mostrar como um orçamento de R$ 5.000 se reparte entre cinco rubricas, um analista hesita entre um gráfico de setores e um gráfico de barras. Comparando as duas escolhas:', 'A escolha do gráfico é uma escolha de pergunta. Participação no total pede setores; comparação entre categorias pede barras.', 'A escolha do gráfico é uma escolha de pergunta. Participação no total pede setores; comparação entre categorias pede barras.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-4', 'A', 'O de setores favorece ver a parte no todo; o de barras favorece comparar rubricas entre si.', true, 'Cada forma responde bem a uma pergunta diferente, e a escolha depende do que se quer mostrar.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-4', 'B', 'O de barras é sempre superior, porque usa eixos.', false, 'Eixos ajudam a comparar, mas não expressam bem a ideia de participação no total.', 'regra absoluta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-4', 'C', 'Os dois são equivalentes, pois carregam os mesmos números.', false, 'Carregar os mesmos números não é responder à mesma pergunta com a mesma clareza.', 'ignorar a leitura');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-4', 'D', 'Nenhum serve: só uma tabela é honesta.', false, 'A tabela é precisa, mas gráficos existem justamente para tornar padrões visíveis.', 'recusa sem critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-4', 'E', 'O de setores é sempre superior, porque mostra o todo.', false, 'Ele mostra o todo, mas dificulta comparar fatias de tamanho parecido.', 'regra absoluta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-graf-5', 'leitura-de-graficos-e-tabelas', 'extrair-comparar-interpretar-dados', 'challenging', 'integration', false, 'Uma tabela informa o número de atendimentos de dois postos de saúde e a população coberta por cada um: o posto do centro fez 4.800 atendimentos para 12.000 pessoas; o do bairro fez 3.000 para 6.000 pessoas. Sobre a comparação entre eles:', 'Quando as populações diferem, comparar totais engana. A taxa por habitante coloca os dois postos na mesma medida.', 'Quando as populações diferem, comparar totais engana. A taxa por habitante coloca os dois postos na mesma medida.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-5', 'A', 'Os dois atendem igual, pois a diferença é pequena.', false, 'As taxas são 0,40 e 0,50 por pessoa: uma difere da outra em 25%.', 'estimativa sem cálculo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-5', 'B', 'O posto do bairro atende melhor, pois tem menos gente.', false, 'População menor não é, por si, sinal de melhor atendimento.', 'inferência sem taxa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-5', 'C', 'Não é possível comparar sem saber o número de médicos.', false, 'Os dados disponíveis já permitem calcular atendimentos por habitante.', 'exigir dado desnecessário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-5', 'D', 'O posto do bairro tem taxa maior: 0,5 atendimento por habitante contra 0,4.', true, 'Dividindo atendimentos por população: 3.000 ÷ 6.000 = 0,5 e 4.800 ÷ 12.000 = 0,4.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-graf-5', 'E', 'O posto do centro atende melhor, pois fez mais atendimentos.', false, 'O total maior acompanha uma população maior e não indica melhor cobertura.', 'comparar valores brutos');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-func-1', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'intro', 'concept', false, 'Uma operadora cobra R$ 45,00 fixos por mês mais R$ 0,80 por minuto de ligação excedente.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-1', 'A', 'V = 45 − 0,80m', false, 'O sinal negativo faria a conta diminuir com o uso, o oposto do descrito.', 'errar o sinal da variação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-1', 'B', 'V = 0,80(m + 45)', false, 'Aqui os R$ 45 entrariam como minutos, sendo multiplicados por 0,80 — resultaria em R$ 36 fixos.', 'colocar o valor fixo dentro do parêntese');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-1', 'C', 'V = 45m + 0,80', false, 'Isso cobraria R$ 45 por minuto e R$ 0,80 fixos — troca os papéis dos dois valores.', 'inverter coeficiente e termo independente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-1', 'D', 'V = 0,80m + 45', true, 'R$ 0,80 multiplica os minutos (varia com o uso) e R$ 45 é a parte fixa (existe mesmo com m = 0).', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-1', 'E', 'V = 45,80m', false, 'Somar os dois valores em um único coeficiente faria a parte fixa ser cobrada a cada minuto.', 'somar valores de naturezas diferentes');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-func-2', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'intermediate', 'applied', false, 'Duas empresas de entrega cobram:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-2', 'A', 'A partir de 4 km.', false, 'Resultado de dividir 8 por 2 em vez de por 0,5.', 'erro na divisão final');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-2', 'B', 'A partir de 8 km.', false, 'Em 8 km os preços não se igualam: X custa R$ 28 e Y custa R$ 32.', 'erro de cálculo na equação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-2', 'C', 'A partir de 16 km, pois em 16 km os preços se igualam e, acima disso, Y fica menor.', true, '12 + 2k = 20 + 1,5k → 0,5k = 8 → k = 16. Em 16 km ambos custam R$ 44; acima disso, o menor custo por km faz Y ganhar.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-2', 'D', 'A partir de 16 km, pois abaixo disso Y já é mais barata.', false, 'O cálculo do ponto está certo, mas a leitura está invertida: abaixo de 16 km, X é mais barata por causa da taxa fixa menor.', 'inverter a leitura do gráfico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-2', 'E', 'Y nunca fica mais barata, pois sua taxa fixa é maior.', false, 'A taxa fixa maior é compensada pelo custo por km menor a partir de certa distância.', 'considerar apenas a parte fixa');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-func-3', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'intermediate', 'interpretation', false, 'A tabela mostra a população de uma colônia de bactérias:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-3', 'A', 'Linear, P(t) = 200t + 200.', false, 'Se fosse linear, a diferença seria constante. Aqui as diferenças são 200, 400 e 800 — crescentes.', 'aplicar modelo linear sem testar');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-3', 'B', 'Exponencial, P(t) = 200 · 2^t.', true, 'A cada hora a população é multiplicada por 2 (razão constante), e o valor inicial é 200. Confere: 200·2³ = 1.600.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-3', 'C', 'Exponencial, P(t) = 2 · 200^t.', false, 'Inverte base e valor inicial: em t = 0 daria 2, não 200.', 'trocar base por valor inicial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-3', 'D', 'Quadrática, P(t) = 200t² + 200.', false, 'Em t = 1 daria 400, mas em t = 2 daria 1.000, e não 800.', 'aceitar o modelo pelo primeiro ponto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-3', 'E', 'Linear, P(t) = 400t.', false, 'Em t = 0 daria 0, contrariando o valor inicial de 200.', 'ignorar o valor em t = 0');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-func-4', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'challenging', 'comparison', false, 'Duas descrições foram propostas para a função C(x) = 25x + 150, que representa o custo total de produção de x unidades:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-4', 'A', 'Nenhuma das duas.', false, 'Ambas descrevem corretamente aspectos diferentes da mesma função.', 'excesso de cautela');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-4', 'B', 'I e II, mas apenas para x maior que 150.', false, 'As duas afirmações valem para qualquer x positivo; 150 é o custo fixo, não um limiar.', 'confundir valor do custo fixo com limite de validade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-4', 'C', 'I, apenas.', false, 'I está correta, mas II também: o custo fixo de R$ 150 se dilui entre mais unidades, reduzindo a média.', 'não considerar a diluição do custo fixo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-4', 'D', 'II, apenas.', false, 'II está correta, mas I também: o coeficiente 25 é exatamente o acréscimo por unidade adicional.', 'não reconhecer o custo marginal');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-4', 'E', 'I e II.', true, 'I descreve o custo marginal (constante, R$ 25). II descreve o custo médio: C(x)/x = 25 + 150/x, que decresce à medida que x cresce.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-func-5', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'challenging', 'integration', false, 'Uma prefeitura ajustou a função D(t) = 3,5t + 42 para o número de dias com boa qualidade do ar por trimestre, com t medido em trimestres desde 2024, usando dados de 8 trimestres observados.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-5', 'A', 'A função deveria ter coeficiente angular negativo, pois a qualidade do ar tende a piorar.', false, 'O sinal do coeficiente vem dos dados observados, não de uma expectativa sobre o tema.', 'substituir dado por opinião');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-5', 'B', 'A projeção extrapola muito além do intervalo observado e, além disso, resulta em valor incompatível com o número de dias de um trimestre.', true, 'O ajuste vale para 8 trimestres; t = 40 está cinco vezes além. E 182 dias excede os ~91 dias de um trimestre, o que mostra que o modelo linear perde sentido físico muito antes disso.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-5', 'C', 'O cálculo está incorreto: 3,5 × 40 + 42 não resulta em 182.', false, '3,5 × 40 = 140; 140 + 42 = 182. O cálculo está certo — o problema é de interpretação, não de aritmética.', 'procurar erro de conta onde não há');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-5', 'D', 'Funções do 1º grau não podem ser usadas para projeções em nenhum caso.', false, 'Podem, dentro do intervalo observado e com ressalvas. A limitação é de alcance, não de tipo de função.', 'generalizar a restrição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-5', 'E', 'O valor de t deveria ser medido em anos, e não em trimestres.', false, 'A unidade está declarada no enunciado e é coerente com o ajuste.', 'inventar inconsistência de unidade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-func-rec-1', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'intro', 'concept', true, 'Na função f(x) = 7x + 25, qual é o valor de f(x) quando x = 0, e o que ele representa em uma situação de cobrança?', 'f(0) = 25 é o termo independente: a parte fixa da cobrança.', NULL, NULL, NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-rec-1', 'A', 'Não é possível calcular sem saber a unidade.', false, 'O valor numérico não depende da unidade escolhida.', 'exigir dado irrelevante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-rec-1', 'B', '25 — a parte fixa, cobrada mesmo sem consumo.', true, 'Com x = 0, o termo 7x desaparece e sobra 25: exatamente o valor que não depende do consumo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-rec-1', 'C', '7 — o valor cobrado por unidade.', false, '7 é o coeficiente angular, que só aparece quando x é maior que zero.', 'confundir coeficiente com termo independente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-rec-1', 'D', '0 — nada é cobrado sem consumo.', false, 'A existência do termo 25 garante cobrança mesmo com consumo zero.', 'ignorar o termo independente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-rec-1', 'E', '32 — a soma dos dois coeficientes.', false, 'Somar 7 e 25 corresponderia a f(1), não a f(0).', 'somar sem substituir x');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-func-rec-2', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'intermediate', 'applied', true, 'Observe a tabela:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-rec-2', 'A', 'y = x + 11', false, 'Em x = 2 daria 13, e não 19.', 'assumir coeficiente 1');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-rec-2', 'B', 'y = 7x', false, 'Em x = 1 daria 7, mas a tabela mostra 12. Falta o termo independente.', 'ignorar o valor inicial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-rec-2', 'C', 'y = 7x + 5', true, 'A diferença constante é 7, e em x = 1 temos 7 + 5 = 12. Confere em todos os pontos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-rec-2', 'D', 'y = 12x', false, 'Em x = 2 daria 24, e não 19.', 'usar o primeiro valor como coeficiente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-rec-2', 'E', 'y = 5x + 7', false, 'Troca coeficiente e termo independente: em x = 1 daria 12, mas em x = 2 daria 17, e não 19.', 'inverter os dois valores');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-func-6', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'intro', 'concept', false, 'Uma relação entre x e y é dada por y = 3x + 5. O número 5 representa:', 'Na função afim y = ax + b, b é o valor inicial ou intercepto vertical: o valor de y quando x é zero.', 'Na função afim y = ax + b, b é o valor inicial ou intercepto vertical: o valor de y quando x é zero.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-6', 'A', 'O valor de y quando x vale zero.', true, 'Substituindo x = 0, obtém-se y = 5.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-6', 'B', 'O valor de x quando y é zero.', false, 'Para descobrir isso seria necessário resolver 0 = 3x + 5.', 'trocar interceptos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-6', 'C', 'Quanto y diminui a cada unidade de x.', false, 'A taxa é +3, portanto y aumenta.', 'errar sinal');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-6', 'D', 'O maior valor possível de y.', false, 'A função não tem máximo informado.', 'inventar limite');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-6', 'E', 'A razão constante y/x para qualquer x.', false, 'Como há termo constante, y/x varia com x.', 'confundir com proporcionalidade direta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-func-7', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'intro', 'applied', false, 'Um serviço de entrega cobra R$ 7 fixos mais R$ 2,50 por quilômetro. Para uma entrega de 8 km, o preço é:', 'A cobrança combina um termo fixo com outro proporcional à distância: C(d) = 7 + 2,5d.', 'A cobrança combina um termo fixo com outro proporcional à distância: C(d) = 7 + 2,5d.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-7', 'A', 'R$ 20,00.', false, 'Esse valor considera apenas a parte variável, sem a taxa fixa.', 'omitir termo constante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-7', 'B', 'R$ 27,00.', true, 'O modelo é 7 + 2,50 × 8 = 27.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-7', 'C', 'R$ 56,00.', false, 'A taxa fixa foi multiplicada pela distância.', 'multiplicar valor fixo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-7', 'D', 'R$ 76,00.', false, 'Foram somados valores sem respeitar suas unidades.', 'modelo incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-7', 'E', 'R$ 87,50.', false, 'Oito quilômetros não significam multiplicar todo o preço por 8.', 'dupla contagem');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-func-8', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'intermediate', 'interpretation', false, 'Em um gráfico distância × tempo, uma linha reta passa pelos pontos (0 h, 0 km), (2 h, 120 km) e (3 h, 180 km). A inclinação representa:', 'A inclinação de um gráfico distância-tempo mede a taxa de variação da distância, isto é, a velocidade média constante.', 'A inclinação de um gráfico distância-tempo mede a taxa de variação da distância, isto é, a velocidade média constante.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-8', 'A', 'Uma parada entre a segunda e a terceira hora.', false, 'Uma parada apareceria como trecho horizontal, o que não ocorre.', 'interpretação geométrica errada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-8', 'B', 'Uma distância inicial de 60 km.', false, 'O gráfico começa em zero; 60 não é distância inicial.', 'trocar taxa e intercepto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-8', 'C', 'Um tempo total obrigatório de 3 horas.', false, 'O gráfico mostra observações até 3 horas, não um limite da relação.', 'confundir domínio observado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-8', 'D', 'Uma velocidade constante de 60 km/h.', true, 'A razão entre variação da distância e do tempo é 120/2 = 180/3 = 60 km/h.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-8', 'E', 'Uma aceleração de 60 km/h a cada hora.', false, 'Linha reta com inclinação constante representa velocidade constante, não aumento da velocidade.', 'confundir velocidade e aceleração');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-func-9', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'challenging', 'comparison', false, 'Plano A custa R$ 30 fixos mais R$ 2 por uso. Plano B custa R$ 50 fixos mais R$ 1 por uso. A partir de quantos usos o plano B passa a ser mais barato?', 'Igualando 30 + 2x = 50 + x, obtém-se x = 20. Como B precisa ser estritamente mais barato, isso ocorre a partir de 21 usos inteiros.', 'Igualando 30 + 2x = 50 + x, obtém-se x = 20. Como B precisa ser estritamente mais barato, isso ocorre a partir de 21 usos inteiros.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-9', 'A', 'A partir de 21 usos.', true, 'Em 20 usos ambos custam R$ 70; com 21, A custa 72 e B custa 71, tornando B mais barato.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-9', 'B', 'A partir de 10 usos.', false, 'Nesse ponto A custa 50 e B, 60; A ainda é mais barato.', 'testar ponto insuficiente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-9', 'C', 'Exatamente em 20 usos.', false, 'Em 20 há igualdade, não vantagem para B.', 'confundir igualdade com menor preço');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-9', 'D', 'A partir de 30 usos.', false, 'B já se torna mais barato logo após o ponto de igualdade em 20.', 'adiar cruzamento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-9', 'E', 'O plano B nunca é mais barato.', false, 'Sua taxa por uso é menor, então compensa a taxa fixa maior depois do cruzamento.', 'ignorar inclinações');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-func-10', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'challenging', 'integration', false, 'Uma incubadora mantém a temperatura pela relação T(t) = 18 + 0,5t durante o aquecimento, com t em minutos. Um sensor de segurança interrompe o processo ao atingir 24 °C. Em quanto tempo ocorre a interrupção?', 'Resolva 18 + 0,5t = 24: a variação necessária é 6 °C e, a meio grau por minuto, t = 12.', 'Resolva 18 + 0,5t = 24: a variação necessária é 6 °C e, a meio grau por minuto, t = 12.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-10', 'A', '6 minutos.', false, 'Seis é o aumento necessário em graus, não o tempo; a taxa é meio grau por minuto.', 'confundir variação e tempo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-10', 'B', '9 minutos.', false, 'Em nove minutos a temperatura seria 22,5 °C.', 'substituição incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-10', 'C', '12 minutos.', true, 'É necessário subir de 18 para 24, uma variação de 6 °C; a 0,5 °C/min, são 12 minutos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-10', 'D', '48 minutos.', false, 'Esse resultado divide 24 por 0,5 e ignora a temperatura inicial de 18 °C.', 'omitir intercepto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-func-10', 'E', '3 minutos.', false, 'Esse tempo elevaria a temperatura apenas 1,5 °C.', 'dividir valor final pela taxa');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fun-1', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'intro', 'concept', false, 'Um estacionamento cobra R$ 8 pela primeira hora e R$ 3 por hora adicional. Chamando de h o total de horas, com h maior ou igual a 1, o valor pago é dado por:', 'Preços com parcela fixa e parcela variável viram funções afins. Aqui o fixo cobre a primeira hora, e a parte variável conta apenas as horas seguintes.', 'Preços com parcela fixa e parcela variável viram funções afins. Aqui o fixo cobre a primeira hora, e a parte variável conta apenas as horas seguintes.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-1', 'A', '11h, somando os dois preços.', false, 'Somar os preços supõe que os dois valem para todas as horas.', 'somar preços de naturezas diferentes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-1', 'B', '8 + 3h, cobrando 3 por hora além do fixo.', false, 'Essa expressão cobraria 11 reais em uma hora, pois não desconta a hora já paga.', 'não descontar a primeira hora');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-1', 'C', '3h + 8, cobrando 3 reais também na primeira hora.', false, 'Isso cobraria 11 reais em uma hora, e o enunciado diz 8.', 'somar sem descontar a primeira hora');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-1', 'D', '8h + 3, tratando 8 como preço por hora.', false, 'Oito é o preço fixo da primeira hora, não um valor por hora.', 'trocar coeficiente e constante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-1', 'E', '8 + 3(h − 1), separando a primeira hora das demais.', true, 'A primeira hora custa 8 e as h − 1 horas restantes custam 3 cada uma.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fun-2', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'intro', 'applied', false, 'A temperatura de um forno sobe segundo T = 25 + 12t, com T em graus Celsius e t em minutos. Para atingir 145 °C, o tempo necessário é de:', 'Em T = 25 + 12t, o 25 é a temperatura de partida. O tempo se obtém isolando t: (145 − 25) ÷ 12 = 10.', 'Em T = 25 + 12t, o 25 é a temperatura de partida. O tempo se obtém isolando t: (145 − 25) ÷ 12 = 10.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-2', 'A', '145 minutos, porque a temperatura é o próprio tempo.', false, 'A relação entre as duas grandezas não é de igualdade.', 'confundir grandezas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-2', 'B', '10 minutos.', true, 'De 145 subtrai-se a temperatura inicial: 120 graus a ganhar, a 12 por minuto, dão 10 minutos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-2', 'C', '12 minutos.', false, 'Doze é a taxa de aquecimento por minuto, não o tempo.', 'confundir taxa com resultado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-2', 'D', 'Cerca de 12,1 minutos.', false, 'Esse valor vem de dividir 145 por 12, sem descontar os 25 graus iniciais.', 'ignorar a constante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-2', 'E', '5 minutos.', false, 'Em cinco minutos a temperatura chegaria a 85 graus.', 'cálculo incorreto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fun-3', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'intermediate', 'interpretation', false, 'O gráfico do consumo de combustível de um carro em função da velocidade tem forma de U, com o ponto mais baixo por volta de 80 km/h. A leitura correta desse gráfico é que:', 'Um ponto de mínimo é o fundo da curva: consumir menos ali significa que tanto correr mais quanto andar mais devagar aumentam o gasto.', 'Um ponto de mínimo é o fundo da curva: consumir menos ali significa que tanto correr mais quanto andar mais devagar aumentam o gasto.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-3', 'A', 'velocidades abaixo de 80 km/h não têm consumo definido.', false, 'A curva existe dos dois lados do mínimo; ela apenas assume valores maiores.', 'inventar restrição de domínio');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-3', 'B', 'quanto maior a velocidade, menor o consumo.', false, 'Isso descreveria uma curva sempre descendente, e não uma curva em U.', 'ignorar o formato');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-3', 'C', 'o carro não consome combustível a 80 km/h.', false, 'O ponto mais baixo indica o menor consumo, não consumo nulo.', 'confundir mínimo com zero');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-3', 'D', 'o consumo cresce de forma constante com a velocidade.', false, 'Crescimento constante daria uma reta, não uma curva com mínimo.', 'confundir com função afim');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-3', 'E', 'existe uma velocidade de menor consumo, e afastar-se dela para mais ou para menos aumenta o gasto.', true, 'É exatamente o que um ponto de mínimo significa: os dois lados da curva sobem a partir dele.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fun-4', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'intermediate', 'comparison', false, 'Dois planos de internet: o plano fixo custa R$ 90 por mês com dados ilimitados; o plano medido custa R$ 30 mais R$ 4 por giga usado. Para quem usa 12 GB por mês, a comparação correta é:', 'Comparar planos é comparar funções. O ponto de virada é onde as duas se igualam: 30 + 4g = 90 dá g = 15 GB.', 'Comparar planos é comparar funções. O ponto de virada é onde as duas se igualam: 30 + 4g = 90 dá g = 15 GB.', 'Antes de escolher um plano, encontre o consumo em que os dois custam igual. Abaixo dele vale um; acima, o outro.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-4', 'A', 'O fixo é melhor, porque não tem surpresa na conta.', false, 'A previsibilidade é uma vantagem real, mas o enunciado pede a comparação de valores.', 'trocar o critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-4', 'B', 'Os dois custam o mesmo em 12 GB.', false, 'Em 12 GB os valores são 78 e 90, e não coincidem.', 'cálculo incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-4', 'C', 'O medido só compensa acima de 15 GB.', false, 'É o contrário: acima de 15 GB o medido passa a custar mais que o fixo.', 'inverter o ponto de virada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-4', 'D', 'O medido é melhor, porque a mensalidade é menor.', false, 'A mensalidade menor é só a parcela fixa; com 12 GB o total chega a 78 reais e ainda é preciso comparar.', 'comparar só o fixo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-4', 'E', 'O medido custa R$ 78 e é mais barato, mas a vantagem acaba a partir de 15 GB.', true, 'Com 12 GB: 30 + 48 = 78. A igualdade ocorre quando 30 + 4g = 90, isto é, g = 15.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fun-5', 'funcoes-e-relacoes', 'interpretar-relacoes-entre-grandezas', 'challenging', 'integration', false, 'Um reservatório com 600 litros perde água a 15 litros por hora por um vazamento, enquanto uma bomba repõe 9 litros por hora. Sobre o esvaziamento do reservatório:', 'Quando duas taxas atuam em sentidos opostos, o que importa é a diferença entre elas. Aqui o nível cai 6 litros por hora, e o volume inicial dura 100 horas.', 'Quando duas taxas atuam em sentidos opostos, o que importa é a diferença entre elas. Aqui o nível cai 6 litros por hora, e o volume inicial dura 100 horas.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-5', 'A', 'Ele esvazia em cerca de 67 horas, dividindo 600 por 9.', false, 'Nove é a taxa de entrada; a taxa que esvazia é a diferença entre saída e entrada.', 'usar a taxa errada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-5', 'B', 'Ele esvazia em 25 horas, somando as duas taxas.', false, 'Somar taxas opostas superestima a perda; elas se subtraem.', 'somar taxas de sentidos contrários');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-5', 'C', 'Ele esvazia em 100 horas, a uma perda líquida de 6 litros por hora.', true, 'A perda líquida é 15 − 9 = 6 litros por hora, e 600 ÷ 6 = 100 horas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-5', 'D', 'Ele esvazia em 40 horas, considerando só o vazamento.', false, 'A bomba repõe água ao mesmo tempo e precisa entrar na conta.', 'ignorar a reposição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fun-5', 'E', 'Ele nunca esvazia, porque há reposição.', false, 'A reposição é menor que a perda, então o nível cai.', 'ignorar a magnitude das taxas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-razao-1', 'razao-e-proporcao', 'comparar-grandezas-por-razao-e-proporcao', 'intro', 'concept', false, 'Em uma turma há 18 meninas e 12 meninos. A razão entre o número de meninos e o número total de estudantes é:', 'A razão pedida compara uma parte (12 meninos) com o todo (30 estudantes): 12/30 = 2/5.', NULL, 'Escreva a razão em palavras antes dos números: "meninos dividido por total".', NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-1', 'A', '2/5', true, 'O total é 18 + 12 = 30. A razão pedida é 12/30 = 2/5.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-1', 'B', '2/3', false, 'Essa é a razão entre meninos e meninas (12/18), não entre meninos e o total.', 'usar a parte no lugar do todo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-1', 'C', '5/2', false, 'É o inverso da razão pedida.', 'inverter a ordem');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-1', 'D', '3/5', false, 'Essa é a razão entre meninas e o total (18/30).', 'trocar o grupo pedido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-1', 'E', '3/2', false, 'Essa é a razão entre meninas e meninos (18/12), que não é o pedido.', 'responder outra razão');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-razao-2', 'razao-e-proporcao', 'comparar-grandezas-por-razao-e-proporcao', 'intro', 'applied', false, 'Uma receita de bolo usa 3 xícaras de farinha para 2 xícaras de leite. Para preparar uma versão maior usando 7,5 xícaras de farinha, a quantidade de leite deve ser de:', 'A farinha foi multiplicada por 2,5 (3 → 7,5). O leite acompanha: 2 × 2,5 = 5 xícaras.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-2', 'A', '6 xícaras', false, 'Usa a razão invertida (3/2 no lugar de 2/3).', 'inverter a razão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-2', 'B', '5 xícaras', true, '3/2 = 7,5/x, então 3x = 15 e x = 5. A proporção entre farinha e leite se mantém.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-2', 'C', '3,5 xícaras', false, 'Não mantém a razão: com 3,5 de leite, a proporção seria bem diferente de 3 para 2.', 'estimar sem calcular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-2', 'D', '11,25 xícaras', false, 'Multiplica farinha por leite em vez de aplicar a proporção.', 'operação trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-2', 'E', '4,5 xícaras', false, 'Corresponde a somar 2,5 às duas xícaras originais, e não a manter a proporção.', 'raciocinar por soma');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-razao-3', 'razao-e-proporcao', 'comparar-grandezas-por-razao-e-proporcao', 'intermediate', 'interpretation', false, 'A tabela mostra dados de três cidades:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-3', 'A', 'Não é possível comparar, pois as áreas são diferentes.', false, 'É justamente a divisão pela área que torna a comparação possível.', 'não reconhecer a função da taxa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-3', 'B', 'Alfa tem a maior densidade demográfica, com 800 habitantes por km².', true, 'Alfa: 240.000/300 = 800 hab/km². Beta: 150.000/250 = 600. Gama: 420.000/600 = 700. Alfa lidera, embora não seja a mais populosa.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-3', 'C', 'Gama tem a maior densidade, por ter a maior população.', false, 'População maior não implica densidade maior: Gama tem 700 hab/km², abaixo de Alfa.', 'confundir população com densidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-3', 'D', 'Beta tem a maior densidade, por ter a menor área.', false, 'Beta tem a menor densidade das três: 600 hab/km².', 'confundir área pequena com concentração');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-3', 'E', 'As três têm a mesma densidade, pois as razões são equivalentes.', false, 'As razões resultam em 800, 600 e 700 — valores diferentes.', 'supor equivalência sem calcular');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-razao-4', 'razao-e-proporcao', 'comparar-grandezas-por-razao-e-proporcao', 'intermediate', 'comparison', false, 'Considere duas situações:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-4', 'A', 'I é inversa e II é direta.', true, 'Em I o produto é constante (1×6 = 2×3 = 6): inversa. Em II o quociente é constante (100/8 = 200/16 = 12,5): direta.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-4', 'B', 'Nenhuma das duas é proporcional.', false, 'As duas mantêm uma constante — de produto em I, de quociente em II.', 'negar a regularidade dos dados');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-4', 'C', 'Ambas são diretamente proporcionais.', false, 'Em I, aumentar o número de torneiras diminui o tempo: é inversa.', 'ignorar o sentido da variação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-4', 'D', 'Ambas são inversamente proporcionais.', false, 'Em II, mais distância exige mais combustível: é direta.', 'generalizar a inversa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-4', 'E', 'I é direta e II é inversa.', false, 'A classificação está trocada em relação ao comportamento descrito.', 'inverter os casos');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-razao-5', 'razao-e-proporcao', 'comparar-grandezas-por-razao-e-proporcao', 'challenging', 'integration', false, 'Uma cooperativa vai dividir R$ 6.300,00 entre três famílias, proporcionalmente ao número de dias trabalhados: 5, 7 e 9 dias. Uma quarta família alega que a divisão deveria ser igual, pois todas participaram do projeto.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-5', 'A', 'A divisão proporcional resulta em R$ 2.100,00 para cada família, que é o mesmo valor da divisão igualitária.', false, 'R$ 2.100 é o resultado da divisão igual entre três, não da proporcional.', 'confundir os dois critérios');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-5', 'B', 'A divisão proporcional resulta em R$ 1.500,00, R$ 2.100,00 e R$ 2.700,00, e o critério é matematicamente inválido.', false, 'Os valores estão corretos, mas divisão proporcional é um critério matematicamente válido — o que se pode discutir é sua justiça.', 'confundir validade matemática com escolha de critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-5', 'C', 'A divisão proporcional resulta em R$ 1.500,00, R$ 2.100,00 e R$ 2.700,00; escolher entre esse critério e a divisão igual é uma decisão do grupo, não uma questão de cálculo.', true, 'Somando 5 + 7 + 9 = 21 e dividindo 6.300 por 21, cada dia vale R$ 300: 1.500, 2.100 e 2.700, que somam 6.300. Qual critério adotar é decisão coletiva; a matemática apenas executa o critério escolhido.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-5', 'D', 'A divisão proporcional é impossível, pois os dias trabalhados não formam uma proporção.', false, 'Qualquer conjunto de números positivos permite divisão proporcional.', 'supor exigência inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-5', 'E', 'A divisão deve ser sempre igual, pois proporcionalidade não se aplica a pessoas.', false, 'Divisão proporcional ao trabalho é amplamente usada; o debate é sobre justiça, não sobre aplicabilidade.', 'transformar juízo em regra matemática');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-razao-rec-1', 'razao-e-proporcao', 'comparar-grandezas-por-razao-e-proporcao', 'intro', 'concept', true, 'Um mapa está na escala 1:50.000. Dois pontos separados por 4 cm no mapa correspondem, na realidade, a uma distância de:', 'Do mapa para o real, multiplica-se pela escala: 4 cm × 50.000 = 200.000 cm = 2 km.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-rec-1', 'A', '500 m', false, 'Não corresponde a nenhuma etapa correta do cálculo.', 'estimar sem calcular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-rec-1', 'B', '200 km', false, 'Multiplica por 5.000.000, cem vezes mais que o correto.', 'errar a potência de dez');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-rec-1', 'C', '200 m', false, 'Corresponde a usar 1:5.000 em vez de 1:50.000.', 'errar a ordem de grandeza');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-rec-1', 'D', '20 km', false, 'Corresponde a multiplicar por 500.000.', 'errar a conversão de cm para km');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-razao-rec-1', 'E', '2 km', true, '4 × 50.000 = 200.000 cm. Como 100.000 cm = 1 km, o resultado é 2 km.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-raz-1', 'razao-e-proporcao', 'comparar-grandezas-por-razao-e-proporcao', 'intro', 'concept', false, 'Uma receita de suco pede 2 partes de água para cada 3 partes de polpa. Sobre a razão entre polpa e o total da mistura, é correto dizer que ela é de:', 'Razão parte-parte compara ingredientes entre si; parte-todo compara um ingrediente com a soma. Aqui as duas são 3 para 2 e 3 para 5.', 'Razão parte-parte compara ingredientes entre si; parte-todo compara um ingrediente com a soma. Aqui as duas são 3 para 2 e 3 para 5.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-1', 'A', '3 para 2, como no enunciado.', false, 'Essa é a razão entre polpa e água, e não entre polpa e total.', 'confundir parte-parte com parte-todo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-1', 'B', '2 para 5, contando a água no total.', false, 'Essa é a fração de água na mistura, não a de polpa.', 'trocar as partes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-1', 'C', '3 para 2 mais 3, sem simplificar as unidades.', false, 'A expressão está incompleta e não define uma razão.', 'expressão malformada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-1', 'D', '3 para 5, porque a mistura tem 5 partes ao todo.', true, 'Somando 2 de água e 3 de polpa, o total é 5 partes, das quais 3 são polpa.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-1', 'E', '1 para 1, porque a mistura fica homogênea.', false, 'Homogeneidade descreve a aparência, não a proporção dos ingredientes.', 'confundir aparência com proporção');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-raz-2', 'razao-e-proporcao', 'comparar-grandezas-por-razao-e-proporcao', 'intro', 'applied', false, 'Um mapa está na escala 1:25.000. Dois pontos aparecem separados por 8 cm no papel. A distância real entre eles é de:', 'Escala é uma razão entre papel e realidade. Cada centímetro no mapa vale 25.000 cm reais, e a conversão para quilômetros divide por 100.000.', 'Escala é uma razão entre papel e realidade. Cada centímetro no mapa vale 25.000 cm reais, e a conversão para quilômetros divide por 100.000.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-2', 'A', '20 quilômetros.', false, 'Esse valor supõe uma escala dez vezes maior.', 'erro de ordem de grandeza');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-2', 'B', '3.125 metros.', false, 'Esse valor vem de dividir a escala pela medida, invertendo a proporção.', 'inverter a razão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-2', 'C', '200 metros.', false, 'A conta de 8 × 25.000 dá 200.000 cm, que são 2.000 metros, e não 200.', 'erro de conversão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-2', 'D', '2 quilômetros.', true, '8 × 25.000 = 200.000 cm; dividindo por 100 dão 2.000 m, isto é, 2 km.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-2', 'E', '25 quilômetros.', false, 'Vinte e cinco mil é o fator da escala, não a distância.', 'confundir fator com resultado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-raz-3', 'razao-e-proporcao', 'comparar-grandezas-por-razao-e-proporcao', 'intermediate', 'interpretation', false, 'Uma embalagem informa "densidade energética: 250 kcal por 100 g". Um consumidor lê isso como o total de calorias do pacote de 400 g. Sobre essa leitura:', 'Valores "por 100 g" são razões e precisam ser multiplicados pela quantidade real. O pacote de 400 g contém quatro porções de referência.', 'Valores "por 100 g" são razões e precisam ser multiplicados pela quantidade real. O pacote de 400 g contém quatro porções de referência.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-3', 'A', 'Está errada: o pacote tem 62,5 kcal.', false, 'Esse valor vem de dividir quando o correto é multiplicar.', 'inverter a operação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-3', 'B', 'Não dá para saber sem a tabela nutricional completa.', false, 'A densidade energética e a massa do pacote já bastam para a conta.', 'exigir dado desnecessário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-3', 'C', 'Está correta: 250 kcal é o valor do pacote.', false, 'O rótulo declara calorias por 100 g, não do pacote inteiro.', 'confundir razão com total');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-3', 'D', 'Está correta se o pacote for consumido de uma vez.', false, 'A forma de consumir não altera o que o rótulo informa.', 'condição irrelevante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-3', 'E', 'Está errada: o pacote tem 1.000 kcal, porque contém quatro porções de 100 g.', true, '400 g equivalem a quatro vezes 100 g, então 4 × 250 = 1.000 kcal.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-raz-4', 'razao-e-proporcao', 'comparar-grandezas-por-razao-e-proporcao', 'intermediate', 'comparison', false, 'Duas tintas verdes são preparadas: a primeira com 4 medidas de azul e 6 de amarelo; a segunda com 6 de azul e 9 de amarelo. Comparando os tons obtidos:', 'Proporções equivalentes produzem o mesmo resultado em escalas diferentes. Simplificar as duas razões mostra que se trata da mesma mistura.', 'Proporções equivalentes produzem o mesmo resultado em escalas diferentes. Simplificar as duas razões mostra que se trata da mesma mistura.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-4', 'A', 'A segunda é mais amarelada, porque 9 é o maior número da lista.', false, 'O maior número isolado não descreve a mistura.', 'leitura de número solto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-4', 'B', 'Não é possível comparar sem saber o volume de cada medida.', false, 'Se a medida é a mesma nas duas receitas, a razão já responde.', 'exigir dado desnecessário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-4', 'C', 'Os tons são iguais, porque as duas razões se reduzem a 2 para 3.', true, '4 para 6 e 6 para 9 simplificam ambas para 2 para 3: a proporção é a mesma, muda só o volume.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-4', 'D', 'A segunda é mais azulada, porque tem mais azul.', false, 'Ela tem mais azul e também proporcionalmente mais amarelo.', 'comparar valores absolutos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-4', 'E', 'A primeira é mais azulada, porque a diferença entre as medidas é menor.', false, 'Diferença absoluta não define tom; a razão define.', 'usar diferença em vez de razão');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-raz-5', 'razao-e-proporcao', 'comparar-grandezas-por-razao-e-proporcao', 'challenging', 'integration', false, 'Um prêmio de R$ 4.200 será dividido entre três pessoas na proporção 2 : 3 : 5, conforme as horas trabalhadas. A pessoa com a maior parte receberá:', 'Divisão proporcional soma as partes para achar o valor unitário: 4.200 ÷ 10 = 420 por parte. A maior fatia tem cinco partes.', 'Divisão proporcional soma as partes para achar o valor unitário: 4.200 ÷ 10 = 420 por parte. A maior fatia tem cinco partes.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-5', 'A', 'R$ 1.400, dividindo o prêmio em três partes iguais.', false, 'A divisão é proporcional, e não igualitária.', 'ignorar a proporção');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-5', 'B', 'R$ 840, que corresponde a uma parte.', false, 'Uma parte vale 420, e a maior fatia tem cinco partes.', 'valor de parte incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-5', 'C', 'R$ 1.260, que é a fatia intermediária.', false, 'Essa é a parte de quem tem três partes, não cinco.', 'escolher a fatia errada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-5', 'D', 'R$ 2.100, correspondente a cinco das dez partes.', true, 'O total é 2 + 3 + 5 = 10 partes; cada parte vale 420, e cinco partes somam 2.100.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-raz-5', 'E', 'R$ 2.520, correspondente a 60% do prêmio.', false, 'Cinco de dez partes correspondem a 50%, não a 60%.', 'percentual incorreto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rt-1', 'regra-de-tres', 'resolver-situacoes-com-regra-de-tres', 'intro', 'concept', false, 'Se 8 metros de tecido custam R$ 96,00, então 14 metros do mesmo tecido custam:', 'Encontre o valor unitário (R$ 12,00 por metro) e multiplique pela quantidade pedida.', NULL, 'Reduzir à unidade costuma ser mais seguro que cruzar direto.', NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-1', 'A', 'R$ 154,00', false, 'Corresponde a somar R$ 58,00 ao valor original, sem manter a proporção.', 'raciocinar por soma');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-1', 'B', 'R$ 120,00', false, 'Corresponde a 10 metros, não a 14.', 'errar o valor da incógnita');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-1', 'C', 'R$ 196,00', false, 'Usa R$ 14,00 por metro, valor que não vem dos dados.', 'inventar o preço unitário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-1', 'D', 'R$ 168,00', true, 'O metro custa 96 ÷ 8 = R$ 12,00. Logo, 14 × 12 = R$ 168,00.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-1', 'E', 'R$ 112,00', false, 'Corresponde a somar 2 metros ao preço de 8, ignorando a proporção.', 'raciocinar por soma');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rt-2', 'regra-de-tres', 'resolver-situacoes-com-regra-de-tres', 'intro', 'applied', false, 'Uma obra seria concluída por 12 operários em 20 dias. Se apenas 8 operários trabalharem, no mesmo ritmo, o prazo passa a ser de:', 'Em relação inversa, o produto se conserva: 12 × 20 = 8 × 30 = 240 operário-dia.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-2', 'A', '13 dias', false, 'Menos operários não podem reduzir o prazo.', 'inverter o sentido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-2', 'B', '16 dias', false, 'Corresponde a montar a proporção como direta.', 'tratar como direta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-2', 'C', '24 dias', false, 'Não corresponde ao produto constante 12 × 20 = 240.', 'errar a conta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-2', 'D', '32 dias', false, 'Corresponde a usar a razão 8/12 invertida duas vezes.', 'aplicar a inversa duas vezes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-2', 'E', '30 dias', true, 'Mais operários, menos dias: é inversa. 12 × 20 = 8 × x → 240 = 8x → x = 30 dias.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rt-3', 'regra-de-tres', 'resolver-situacoes-com-regra-de-tres', 'intermediate', 'interpretation', false, 'Uma padaria registrou o consumo de farinha em três semanas:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-3', 'A', '125 kg', false, 'Corresponde a 24 pães por kg, acima da relação observada.', 'errar a razão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-3', 'B', '135 kg', false, 'Não corresponde à razão constante de 20 pães por kg.', 'errar a conta final');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-3', 'C', '150 kg', true, 'A razão é constante: 1.200/60 = 20 pães por kg. Logo, 3.000 ÷ 20 = 150 kg.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-3', 'D', '160 kg', false, 'Corresponde a usar 18,75 pães por kg, valor que não aparece nos dados.', 'usar razão inventada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-3', 'E', '180 kg', false, 'Corresponde a somar as três semanas, o que não responde à pergunta.', 'somar os dados em vez de aplicar a razão');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rt-4', 'regra-de-tres', 'resolver-situacoes-com-regra-de-tres', 'challenging', 'comparison', false, 'Analise duas situações:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-4', 'A', 'As duas estão corretas e usam proporcionalidade inversa.', false, 'A relação entre lado e área não é inversa nem proporcional.', 'generalizar a inversa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-4', 'B', 'I está incorreta, pois maior velocidade não reduz o tempo proporcionalmente.', false, 'Com distância fixa, velocidade e tempo são inversamente proporcionais.', 'negar uma relação válida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-4', 'C', 'II está correta, pois basta multiplicar a área pelo mesmo fator do lado.', false, 'Esse é exatamente o erro: a área varia com o quadrado do fator.', 'aplicar fator linear à área');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-4', 'D', 'I está correta e usa proporcionalidade inversa; II está incorreta, pois a área não é proporcional ao lado.', true, 'Em I, 80 × 3 = 120 × 2 = 240: inversa correta. Em II, dobrar o lado quadruplica a área — 8 cm de lado dá 64 cm², não 32.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-4', 'E', 'As duas estão corretas e usam proporcionalidade direta.', false, 'I é inversa e II está numericamente errada.', 'classificar tudo como direta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rt-5', 'regra-de-tres', 'resolver-situacoes-com-regra-de-tres', 'challenging', 'integration', false, 'Uma cozinha comunitária serve 240 refeições por dia com 6 voluntários trabalhando 5 horas cada. Para o mês seguinte, a meta é 320 refeições diárias, e o grupo conseguiu 8 voluntários.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-5', 'A', '6,67 horas', false, 'Aplica só o aumento da meta e ignora os voluntários a mais.', 'considerar só uma grandeza');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-5', 'B', '3 horas', false, 'Aplica apenas o aumento de voluntários e ignora o aumento da meta.', 'considerar só uma grandeza');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-5', 'C', '4 horas', false, 'Corresponde a manter 240 refeições com 8 voluntários, e não à nova meta.', 'usar a meta antiga');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-5', 'D', '5 horas', true, 'Voluntários × horas é inversa (5 × 6/8 = 3,75); refeições × horas é direta (× 320/240 = 4/3). Assim, 5 × 6/8 × 320/240 = 5 horas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-5', 'E', '6 horas', false, 'Corresponde a tratar a relação com voluntários como direta.', 'errar o sentido da inversa');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rt-rec-1', 'regra-de-tres', 'resolver-situacoes-com-regra-de-tres', 'intro', 'concept', true, 'Se 3 impressoras iguais imprimem um lote em 40 minutos, 5 impressoras iguais imprimem o mesmo lote em:', 'Mais máquinas, menos tempo: relação inversa, com produto constante.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-rec-1', 'A', '24 minutos', true, '3 × 40 = 5 × x → 120 = 5x → x = 24 minutos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-rec-1', 'B', '30 minutos', false, 'Não corresponde ao produto constante de 120 impressora-minuto.', 'errar a conta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-rec-1', 'C', '20 minutos', false, 'Corresponde a 6 impressoras, não a 5.', 'errar o divisor');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-rec-1', 'D', '40 minutos', false, 'O tempo não permaneceria igual com mais máquinas.', 'ignorar a mudança');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rt-rec-1', 'E', '66,7 minutos', false, 'Mais impressoras não podem aumentar o tempo.', 'inverter o sentido');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rt-1', 'regra-de-tres', 'resolver-situacoes-com-regra-de-tres', 'intro', 'concept', false, 'Antes de aplicar regra de três, é preciso decidir se as grandezas são direta ou inversamente proporcionais. Essa decisão depende de:', 'O teste é sempre o mesmo: imagine aumentar uma grandeza e pergunte o que ocorre com a outra. A resposta define direta ou inversa.', 'O teste é sempre o mesmo: imagine aumentar uma grandeza e pergunte o que ocorre com a outra. A resposta define direta ou inversa.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-1', 'A', 'a posição das grandezas na tabela montada.', false, 'A montagem é consequência da decisão, não a causa dela.', 'inverter a ordem do raciocínio');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-1', 'B', 'a unidade em que cada grandeza está medida.', false, 'Unidades importam para converter, mas não definem o tipo de proporção.', 'confundir unidade com relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-1', 'C', 'o número de grandezas envolvidas na situação.', false, 'A quantidade de grandezas define se a regra é simples ou composta, não o sentido.', 'confundir com regra composta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-1', 'D', 'o que acontece com uma grandeza quando a outra aumenta.', true, 'Se as duas crescem juntas, a relação é direta; se uma cresce e a outra diminui, é inversa.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-1', 'E', 'qual dos números é maior no enunciado.', false, 'O tamanho dos números não diz nada sobre o tipo de relação.', 'critério numérico');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rt-2', 'regra-de-tres', 'resolver-situacoes-com-regra-de-tres', 'intro', 'applied', false, 'Se 6 impressoras iguais imprimem um lote em 10 horas, o tempo que 4 dessas impressoras levariam para o mesmo lote é de:', 'Máquinas e tempo são inversamente proporcionais: o produto entre eles é constante e mede o trabalho total.', 'Máquinas e tempo são inversamente proporcionais: o produto entre eles é constante e mede o trabalho total.', 'Em regra de três inversa, multiplique os valores de uma linha para achar a constante e depois divida pelo novo valor.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-2', 'A', '6 horas e 40 minutos.', false, 'Esse resultado sai de tratar a relação como direta, o que faria menos impressoras trabalharem mais rápido.', 'usar proporção direta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-2', 'B', '12 horas.', false, 'Esse valor não fecha a conta: 4 × 12 = 48, e o trabalho vale 60 impressoras-hora.', 'cálculo incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-2', 'C', '15 horas.', true, 'O trabalho vale 6 × 10 = 60 impressoras-hora; com 4 impressoras, 60 ÷ 4 = 15 horas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-2', 'D', '20 horas.', false, 'Vinte horas corresponderia a 3 impressoras, não a 4.', 'divisão incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-2', 'E', '10 horas, porque o lote não muda.', false, 'O lote não muda, mas menos máquinas levam mais tempo.', 'ignorar a variação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rt-3', 'regra-de-tres', 'resolver-situacoes-com-regra-de-tres', 'intermediate', 'interpretation', false, 'Um enunciado diz: "3 pedreiros levantam um muro em 8 dias; em quantos dias 6 pedreiros levantam o mesmo muro?". A resposta "4 dias" pressupõe uma condição que o enunciado não afirma, a saber:', 'Regra de três com pessoas supõe produtividade igual e independente. Onde há espaço limitado ou coordenação difícil, dobrar a equipe não corta o prazo pela metade.', 'Regra de três com pessoas supõe produtividade igual e independente. Onde há espaço limitado ou coordenação difícil, dobrar a equipe não corta o prazo pela metade.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-3', 'A', 'que o material chega antes do início da obra.', false, 'Logística importa na prática, mas não é a hipótese que sustenta o cálculo.', 'condição periférica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-3', 'B', 'que todos trabalham no mesmo ritmo e não atrapalham uns aos outros.', true, 'A proporcionalidade exige ritmo igual e ausência de interferência entre os trabalhadores.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-3', 'C', 'que o muro tem altura padronizada.', false, 'A altura já está fixada pelo fato de ser o mesmo muro.', 'condição já dada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-3', 'D', 'que os dias têm oito horas de trabalho.', false, 'A duração da jornada se cancela por ser a mesma nos dois casos.', 'condição irrelevante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-3', 'E', 'que o número de pedreiros é sempre par.', false, 'A paridade não tem papel algum no raciocínio.', 'condição inventada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rt-4', 'regra-de-tres', 'resolver-situacoes-com-regra-de-tres', 'intermediate', 'comparison', false, 'Duas situações: em uma, 5 torneiras iguais enchem um tanque em 12 minutos; em outra, 5 operários pintam 12 portas em um dia. Ao dobrar o número de torneiras e o número de operários, o que acontece em cada caso é que:', 'O sentido da proporção depende do que se mede. Mais agentes reduzem o tempo de uma tarefa fixa e aumentam a produção em um tempo fixo.', 'O sentido da proporção depende do que se mede. Mais agentes reduzem o tempo de uma tarefa fixa e aumentam a produção em um tempo fixo.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-4', 'A', 'nos dois casos o resultado cai pela metade.', false, 'No segundo caso a produção aumenta, não diminui.', 'aplicar o mesmo sentido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-4', 'B', 'o tempo do tanque dobra e a produção de portas cai pela metade.', false, 'Os dois sentidos estão invertidos.', 'inverter os dois');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-4', 'C', 'nada muda, porque o trabalho total é o mesmo.', false, 'O trabalho total é o mesmo no tanque, mas o tempo muda; nas portas, o total produzido muda.', 'confundir trabalho e resultado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-4', 'D', 'nos dois casos o resultado dobra.', false, 'No primeiro caso a grandeza medida é o tempo, que cai pela metade.', 'aplicar o mesmo sentido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-4', 'E', 'o tempo do tanque cai para 6 minutos e a produção de portas sobe para 24.', true, 'Torneiras e tempo são inversos; operários e portas produzidas são diretos.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rt-5', 'regra-de-tres', 'resolver-situacoes-com-regra-de-tres', 'challenging', 'integration', false, 'Se 4 máquinas trabalhando 6 horas por dia produzem 720 peças em 5 dias, o número de peças que 6 máquinas iguais produzem trabalhando 8 horas por dia durante 3 dias é de:', 'Regra de três composta fica mais segura quando se reduz tudo a uma unidade comum: aqui, peças por máquina-hora. Depois basta multiplicar pela nova disponibilidade.', 'Regra de três composta fica mais segura quando se reduz tudo a uma unidade comum: aqui, peças por máquina-hora. Depois basta multiplicar pela nova disponibilidade.', 'Em problemas com três ou mais grandezas, calcule primeiro a produção unitária. Isso evita errar o sentido de cada proporção.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-5', 'A', '960 peças.', false, 'Esse resultado usa fatores incompatíveis com os dados.', 'combinação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-5', 'B', '864 peças.', true, 'A produção por máquina-hora é 720 ÷ (4 × 6 × 5) = 6. Com 6 × 8 × 3 = 144 máquinas-hora: 144 × 6 = 864.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-5', 'C', '720 peças, porque a quantidade de trabalho se compensa.', false, 'As máquinas-hora passam de 120 para 144, então a produção não fica igual.', 'supor compensação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-5', 'D', '540 peças.', false, 'Esse valor considera a mudança de dias, mas ignora máquinas e horas.', 'ajustar uma grandeza só');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rt-5', 'E', '1.080 peças.', false, 'Esse valor duplica a produção sem descontar a redução de dias.', 'ajuste incompleto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-geo-1', 'geometria-plana', 'calcular-e-aplicar-medidas-em-figuras-planas', 'intro', 'concept', false, 'Uma sala retangular mede 6 m por 4,5 m. A área do piso dessa sala é:', 'Área de retângulo é o produto das dimensões: 6 × 4,5 = 27 m².', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-1', 'A', '21 m²', false, 'Corresponde ao perímetro (2 × 6 + 2 × 4,5), não à área.', 'confundir perímetro com área');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-1', 'B', '27 m²', true, '6 × 4,5 = 27 m². Área de retângulo é base vezes altura.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-1', 'C', '13,5 m²', false, 'Corresponde à metade do produto — fórmula de triângulo.', 'usar fórmula de outra figura');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-1', 'D', '54 m²', false, 'Corresponde ao dobro do produto.', 'multiplicar por dois sem motivo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-1', 'E', '10,5 m²', false, 'Corresponde à soma dos lados, não ao produto.', 'somar em vez de multiplicar');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-geo-2', 'geometria-plana', 'calcular-e-aplicar-medidas-em-figuras-planas', 'intermediate', 'applied', false, 'Uma pessoa vai cercar um terreno retangular de 25 m por 18 m com três voltas de arame. O arame é vendido em rolos de 50 metros.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-2', 'A', '5 rolos', false, 'Cobriria 250 m, insuficiente para 258 m.', 'arredondar para baixo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-2', 'B', '9 rolos', false, 'Corresponde a calcular a área em vez do perímetro.', 'trocar a grandeza');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-2', 'C', '6 rolos', true, 'Perímetro: 2 × (25 + 18) = 86 m. Três voltas: 258 m. Como 5 rolos dão 250 m, são necessários 6 rolos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-2', 'D', '4 rolos', false, 'Cobriria 200 m, abaixo do necessário.', 'errar a multiplicação por três');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-2', 'E', '3 rolos', false, 'Corresponde a uma volta apenas (86 m).', 'ignorar as três voltas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-geo-3', 'geometria-plana', 'calcular-e-aplicar-medidas-em-figuras-planas', 'intermediate', 'interpretation', false, 'A planta de um jardim mostra um retângulo de 12 m por 8 m, com um canteiro triangular no canto cuja base mede 6 m e cuja altura mede 4 m. O restante será coberto com grama.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-3', 'A', '84 m²', true, 'Retângulo: 12 × 8 = 96 m². Triângulo: (6 × 4)/2 = 12 m². Grama: 96 − 12 = 84 m².', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-3', 'B', '72 m²', false, 'Corresponde a subtrair 24 m², ou seja, a esquecer de dividir a área do triângulo por dois.', 'esquecer a divisão por 2');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-3', 'C', '96 m²', false, 'É a área total do jardim, sem descontar o canteiro.', 'ignorar a subtração');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-3', 'D', '108 m²', false, 'Corresponde a somar o canteiro em vez de subtraí-lo.', 'somar em vez de subtrair');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-3', 'E', '12 m²', false, 'É apenas a área do canteiro triangular.', 'responder a parte em vez do resto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-geo-4', 'geometria-plana', 'calcular-e-aplicar-medidas-em-figuras-planas', 'challenging', 'comparison', false, 'Duas pizzarias vendem pizzas circulares pelo mesmo preço:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-4', 'A', 'A Pizzaria da Esquina entrega o dobro, por serem duas pizzas.', false, 'Duas pizzas pequenas somam menos área que uma grande de diâmetro dobrado.', 'contar unidades em vez de área');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-4', 'B', 'A Pizzaria da Esquina entrega mais, pois há mais bordas e mais superfície.', false, 'Mais bordas não significam mais área total.', 'raciocinar por impressão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-4', 'C', 'Não é possível comparar sem saber a espessura das pizzas.', false, 'Mantida a mesma espessura, a comparação por área é suficiente e é o que a questão pede.', 'introduzir variável desnecessária');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-4', 'D', 'A Pizzaria do Centro entrega o dobro, pois sua pizza tem área quatro vezes maior que a de cada pizza pequena.', true, 'Área da pizza grande: π × 20² = 400π. Cada pizza pequena: π × 10² = 100π, e as duas somam 200π. A pizza grande entrega o dobro.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-4', 'E', 'As duas ofertas entregam a mesma quantidade, pois 20 + 20 = 40.', false, 'Somar diâmetros não soma áreas: a relação é quadrática.', 'somar medidas lineares');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-geo-5', 'geometria-plana', 'calcular-e-aplicar-medidas-em-figuras-planas', 'challenging', 'integration', false, 'Um ciclista precisa ir do ponto A ao ponto C. Pelo caminho das ruas, ele percorre 800 m para o norte e depois 600 m para o leste. Uma ciclovia em construção ligará A e C em linha reta.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-5', 'A', '1.000 m, o que representa 71% de economia.', false, '1.000 m é o comprimento da ciclovia, não a economia.', 'confundir medida com diferença');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-5', 'B', '400 m, o que representa 25% de economia.', false, 'O percentual foi calculado sobre 1.600 m, valor que não corresponde ao percurso.', 'errar o denominador');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-5', 'C', '400 m, o que representa 40% de economia.', false, 'A diferença é de 400 m, mas o percentual está calculado sobre a base errada.', 'usar base incorreta no percentual');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-5', 'D', '400 m, o que representa cerca de 29% de economia.', true, 'Ciclovia: √(800² + 600²) = √1.000.000 = 1.000 m. Percurso atual: 1.400 m. Economia: 400 m, que sobre 1.400 m equivale a ≈ 28,6%.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-5', 'E', '200 m, o que representa cerca de 14% de economia.', false, 'A hipotenusa mede 1.000 m, e não 1.200 m.', 'errar Pitágoras');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-geo-rec-1', 'geometria-plana', 'calcular-e-aplicar-medidas-em-figuras-planas', 'intro', 'concept', true, 'Um triângulo retângulo tem catetos de 9 cm e 12 cm. A hipotenusa mede:', 'A hipotenusa é sempre maior que qualquer cateto e menor que a soma dos dois — 15 cm cumpre as duas condições.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-rec-1', 'A', '16 cm', false, 'Não satisfaz a relação: 16² = 256 ≠ 225.', 'errar a raiz');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-rec-1', 'B', '21 cm', false, 'Corresponde a somar os catetos, e não a aplicar Pitágoras.', 'somar em vez de usar o teorema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-rec-1', 'C', '10,5 cm', false, 'É a média dos catetos, valor menor que o maior cateto — impossível para a hipotenusa.', 'calcular média');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-rec-1', 'D', '15 cm', true, '9² + 12² = 81 + 144 = 225, e √225 = 15 cm. É o trio 3-4-5 multiplicado por 3.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-geo-rec-1', 'E', '13 cm', false, 'Corresponde ao trio 5-12-13, que não é o caso aqui.', 'trocar de trio pitagórico');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-geo-1', 'geometria-plana', 'calcular-e-aplicar-medidas-em-figuras-planas', 'intro', 'concept', false, 'Um terreno retangular tem 12 m de frente e 30 m de fundo. Sobre perímetro e área desse terreno, é correto afirmar que:', 'Perímetro mede o contorno e sai em metros; área mede a superfície e sai em metros quadrados. Uma soma, a outra multiplica.', 'Perímetro mede o contorno e sai em metros; área mede a superfície e sai em metros quadrados. Uma soma, a outra multiplica.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-1', 'A', 'a área é 84 m², porque a área é a soma dos lados.', false, 'A soma dos lados dá contorno; área é produto de duas dimensões.', 'somar em vez de multiplicar');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-1', 'B', 'o perímetro é 360 m e a área é 84 m².', false, 'Os dois valores estão trocados e as unidades também.', 'trocar as duas medidas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-1', 'C', 'o perímetro é 84 m e a área é 360 m².', true, 'Perímetro: 2 × (12 + 30) = 84 m. Área: 12 × 30 = 360 m².', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-1', 'D', 'o perímetro é 42 m e a área é 360 m².', false, 'Quarenta e dois é a soma de um lado com o outro, e o contorno tem quatro lados.', 'somar apenas dois lados');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-1', 'E', 'perímetro e área são iguais, pois dependem dos mesmos lados.', false, 'Elas usam os mesmos lados em operações diferentes e têm unidades diferentes.', 'igualar grandezas distintas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-geo-2', 'geometria-plana', 'calcular-e-aplicar-medidas-em-figuras-planas', 'intermediate', 'applied', false, 'Uma sala de 5 m por 4 m será revestida com placas quadradas de 50 cm de lado. Desprezando recortes e perdas, o número de placas necessárias é de:', 'Reduzir o lado pela metade reduz a área a um quarto. Por isso a placa de 50 cm cobre 0,25 m², e não 0,5 m².', 'Reduzir o lado pela metade reduz a área a um quarto. Por isso a placa de 50 cm cobre 0,25 m², e não 0,5 m².', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-2', 'A', '200 placas.', false, 'Esse valor não corresponde à razão entre as áreas.', 'divisão incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-2', 'B', '80 placas.', true, 'A sala tem 20 m². Cada placa tem 0,5 × 0,5 = 0,25 m². Então 20 ÷ 0,25 = 80.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-2', 'C', '20 placas.', false, 'Esse número sairia se cada placa cobrisse 1 m².', 'ignorar o tamanho da placa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-2', 'D', '40 placas.', false, 'Esse número supõe que a placa cobre meio metro quadrado.', 'converter só uma dimensão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-2', 'E', '160 placas.', false, 'Esse valor dobra a conta correta.', 'fator duplicado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-geo-3', 'geometria-plana', 'calcular-e-aplicar-medidas-em-figuras-planas', 'intermediate', 'interpretation', false, 'Um projeto mostra a planta de um jardim em forma de L, obtida retirando um retângulo menor do canto de um retângulo maior. Para calcular a área do jardim, o caminho mais seguro é:', 'Toda figura em L se decompõe em retângulos. Somar dois retângulos ou subtrair um do outro dá o mesmo resultado exato.', 'Toda figura em L se decompõe em retângulos. Somar dois retângulos ou subtrair um do outro dá o mesmo resultado exato.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-3', 'A', 'somar todos os lados e dividir por quatro.', false, 'Isso mistura contorno com superfície.', 'confundir perímetro com área');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-3', 'B', 'calcular a área do retângulo maior e subtrair a do pedaço retirado.', true, 'Figuras compostas se resolvem por soma ou subtração de figuras simples cujas fórmulas se conhece.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-3', 'C', 'aproximar a figura por um quadrado de lado médio.', false, 'A aproximação introduz um erro que não é necessário, já que a decomposição é exata.', 'aproximação desnecessária');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-3', 'D', 'multiplicar as duas maiores medidas do desenho.', false, 'Isso dá a área do retângulo maior, ignorando a parte retirada.', 'ignorar o recorte');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-3', 'E', 'medir a maior diagonal e elevá-la ao quadrado.', false, 'A diagonal não determina a área de uma figura em L.', 'fórmula inventada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-geo-4', 'geometria-plana', 'calcular-e-aplicar-medidas-em-figuras-planas', 'challenging', 'comparison', false, 'Um pedreiro precisa cercar um canteiro de 36 m² e quer gastar o mínimo de tela. Comparando um canteiro quadrado com um retangular de 4 m por 9 m:', 'Entre retângulos de mesma área, o quadrado é o de menor perímetro. Quanto mais alongada a forma, mais contorno para a mesma superfície.', 'Entre retângulos de mesma área, o quadrado é o de menor perímetro. Quanto mais alongada a forma, mais contorno para a mesma superfície.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-4', 'A', 'Não é possível decidir sem saber a altura da tela.', false, 'A altura multiplicaria os dois casos igualmente e não muda a comparação.', 'exigir dado desnecessário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-4', 'B', 'O quadrado gasta menos: 24 m de tela contra 26 m.', true, 'Quadrado de 6 m de lado: 4 × 6 = 24 m. Retângulo 4 × 9: 2 × (4 + 9) = 26 m.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-4', 'C', 'Os dois gastam o mesmo, porque a área é igual.', false, 'Área igual não implica contorno igual; formas mais alongadas gastam mais.', 'igualar área e perímetro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-4', 'D', 'O retângulo gasta menos, porque tem lados menores.', false, 'Ele tem um lado menor e outro bem maior, e a soma resulta em mais tela.', 'olhar só um lado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-4', 'E', 'O quadrado gasta menos: 18 m contra 26 m.', false, 'O valor do quadrado está incorreto; o contorno tem quatro lados de 6 m.', 'cálculo incorreto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-geo-5', 'geometria-plana', 'calcular-e-aplicar-medidas-em-figuras-planas', 'challenging', 'integration', false, 'Uma praça circular de 20 m de raio terá uma calçada de 2 m de largura em toda a sua borda externa. Usando 3,14 para π, a área da calçada é de aproximadamente:', 'A calçada é uma coroa circular: a área do círculo maior menos a do menor. A aproximação por perímetro vezes largura subestima porque despreza a curvatura.', 'A calçada é uma coroa circular: a área do círculo maior menos a do menor. A aproximação por perímetro vezes largura subestima porque despreza a curvatura.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-5', 'A', '12,56 m², usando apenas a largura da calçada.', false, 'A largura sozinha não define área.', 'ignorar o raio');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-5', 'B', '125,6 m², multiplicando o perímetro pela largura.', false, 'Essa aproximação ignora que a borda externa é maior que a interna.', 'aproximação por perímetro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-5', 'C', '251,2 m², usando o diâmetro no lugar do raio.', false, 'Trocar raio por diâmetro dobra indevidamente o resultado.', 'confundir raio e diâmetro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-5', 'D', '1.256 m², que é a área da praça inteira.', false, 'Essa é a área interna, e não a da faixa acrescentada.', 'calcular a figura errada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-geo-5', 'E', '263,8 m².', true, 'Círculo externo: 3,14 × 22² = 1.519,76. Praça: 3,14 × 20² = 1.256. A diferença é 263,76 m².', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-est-1', 'estatistica', 'interpretar-medidas-estatisticas-em-contexto', 'intro', 'concept', false, 'Considere o conjunto de valores: 4, 7, 7, 9, 13. A média, a mediana e a moda são, respectivamente:', 'Média é soma dividida pela quantidade; mediana é o valor central da lista ordenada; moda é o mais frequente.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-1', 'A', '8, 7 e 13', false, 'Moda é o valor mais frequente, não o maior.', 'confundir moda com máximo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-1', 'B', '9, 7 e 7', false, 'A soma é 40, e não 45: a média é 8.', 'errar a soma');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-1', 'C', '8, 7 e 7', true, 'Média: 40 ÷ 5 = 8. Mediana: o terceiro valor da lista ordenada é 7. Moda: 7 aparece duas vezes.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-1', 'D', '7, 8 e 7', false, 'Inverte média e mediana.', 'trocar as duas medidas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-1', 'E', '8, 9 e 7', false, 'A mediana de cinco valores é o terceiro, que é 7, não 9.', 'errar a posição central');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-est-2', 'estatistica', 'interpretar-medidas-estatisticas-em-contexto', 'intermediate', 'applied', false, 'Um estudante tem notas 7,0; 5,0 e 8,0 em três avaliações com pesos 2, 3 e 5, respectivamente. A média ponderada é:', 'Na média ponderada, o divisor é a soma dos pesos — aqui, 10.', NULL, 'Escreva a soma dos pesos antes de começar: é o erro mais comum do tópico.', NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-2', 'A', '6,7', false, 'Corresponde à média simples das três notas.', 'ignorar os pesos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-2', 'B', '7,3', false, 'Corresponde a somar os produtos e dividir por 3.', 'dividir pela quantidade de notas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-2', 'C', '20,0', false, 'É a soma total dos produtos, sem a divisão.', 'esquecer de dividir');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-2', 'D', '6,9', true, '(7×2 + 5×3 + 8×5) ÷ (2+3+5) = (14 + 15 + 40) ÷ 10 = 69 ÷ 10 = 6,9.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-2', 'E', '8,0', false, 'Considera apenas a nota de maior peso.', 'ignorar as demais notas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-est-3', 'estatistica', 'interpretar-medidas-estatisticas-em-contexto', 'intermediate', 'interpretation', false, 'A tabela mostra o número de livros lidos em um ano por sete pessoas de um grupo de leitura:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-3', 'A', 'A média de 10,6 livros descreve bem o comportamento do grupo.', false, 'Seis das sete pessoas leram menos que a média: ela não descreve o grupo.', 'aceitar a média sem análise');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-3', 'B', 'A mediana de 5 livros representa melhor o grupo, pois a média é puxada por um valor extremo.', true, 'A soma é 74, e a média ≈ 10,6 — acima de seis dos sete valores. A mediana (4º valor ordenado, igual a 5) representa o leitor típico.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-3', 'C', 'A moda de 4 livros é a única medida válida neste conjunto.', false, 'A moda é informativa, mas não invalida as demais medidas.', 'excluir medidas sem justificativa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-3', 'D', 'Os dados são inválidos porque uma das pessoas leu muito mais que as outras.', false, 'Um valor extremo é um dado legítimo; ele exige cuidado na escolha da medida, não descarte.', 'descartar dado incômodo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-3', 'E', 'A média e a mediana são iguais, pois o conjunto tem sete valores.', false, 'A média é ≈ 10,6 e a mediana é 5.', 'supor igualdade sem calcular');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-est-4', 'estatistica', 'interpretar-medidas-estatisticas-em-contexto', 'challenging', 'comparison', false, 'Duas turmas fizeram a mesma prova:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-4', 'A', 'A comparação é impossível porque as turmas têm notas diferentes.', false, 'É exatamente para isso que servem as medidas estatísticas.', 'recusar a comparação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-4', 'B', 'A turma X tem maior mediana, o que compensa a média igual.', false, 'As duas têm mediana 6.', 'supor diferença inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-4', 'C', 'A turma X teve desempenho superior, pois suas notas são mais altas.', false, 'As duas turmas têm a mesma soma (42) e a mesma média (6).', 'comparar sem calcular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-4', 'D', 'A turma Y teve desempenho superior, pois alcançou as maiores notas.', false, 'Notas máximas mais altas convivem com notas mínimas mais baixas; a média é a mesma.', 'olhar apenas os extremos superiores');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-4', 'E', 'As duas turmas têm a mesma média, mas a turma Y apresenta dispersão muito maior, o que indica desempenhos mais desiguais.', true, 'Ambas somam 42 e têm média 6. A amplitude de X é 2 (de 5 a 7) e a de Y é 7 (de 2 a 9): a turma Y é bem mais heterogênea.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-est-5', 'estatistica', 'interpretar-medidas-estatisticas-em-contexto', 'challenging', 'integration', false, 'Uma reportagem afirma: "O salário médio na empresa subiu 18% no último ano." O sindicato responde: "A mediana salarial ficou praticamente estável."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-5', 'A', 'Os aumentos se concentraram em poucos salários altos, o que eleva a média sem deslocar o valor central da distribuição.', true, 'A média responde ao total pago; a mediana, à posição central. Aumentos grandes em poucos cargos elevam a soma sem mover quem está no meio da lista.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-5', 'B', 'Uma das duas informações é necessariamente falsa, pois média e mediana devem variar juntas.', false, 'As duas medidas medem coisas diferentes e podem divergir sem contradição.', 'supor que as medidas são equivalentes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-5', 'C', 'A empresa contratou muitos funcionários novos, o que sempre aumenta a média.', false, 'Contratações podem puxar a média em qualquer direção, conforme os salários de entrada.', 'generalizar um efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-5', 'D', 'A mediana só não subiu porque foi calculada sobre um número par de funcionários.', false, 'A paridade do total afeta apenas o modo de cálculo, não a estabilidade do valor.', 'atribuir o efeito a um detalhe de cálculo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-5', 'E', 'O aumento de 18% na média garante que todos receberam pelo menos algum reajuste.', false, 'A média pode subir com a maioria dos salários congelados.', 'inferir efeito individual a partir da média');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-est-rec-1', 'estatistica', 'interpretar-medidas-estatisticas-em-contexto', 'intro', 'concept', true, 'A média de quatro números é 12. Se três deles são 10, 11 e 14, o quarto número é:', 'Volte da média para a soma total (12 × 4 = 48) e subtraia o que já é conhecido.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-rec-1', 'A', '12', false, 'Só seria correto se os outros três somassem 36, o que não é o caso.', 'supor que o valor coincide com a média');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-rec-1', 'B', '15', false, 'Levaria a uma soma de 50, e a média seria 12,5.', 'errar a soma');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-rec-1', 'C', '11', false, 'Levaria a uma soma de 46, e a média seria 11,5.', 'errar a soma');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-rec-1', 'D', '13', true, 'Média 12 em quatro números significa soma 48. Como 10 + 11 + 14 = 35, o quarto é 48 − 35 = 13.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-est-rec-1', 'E', '14', false, 'Levaria a uma soma de 49, acima do necessário.', 'errar a subtração');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-est-1', 'estatistica', 'interpretar-medidas-estatisticas-em-contexto', 'intro', 'concept', false, 'Em uma equipe de 9 pessoas, oito ganham cerca de R$ 3.000 e uma ganha R$ 60.000. Para descrever o salário típico dessa equipe, a medida mais adequada é:', 'Distribuições com valores muito distantes puxam a média. A mediana descreve melhor o que a maior parte do grupo recebe.', 'Distribuições com valores muito distantes puxam a média. A mediana descreve melhor o que a maior parte do grupo recebe.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-1', 'A', 'a média, porque usa todos os dados.', false, 'Usar todos os dados é justamente o que faz a média ser puxada pelo salário atípico.', 'usar média com extremo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-1', 'B', 'a mediana, porque não se desloca com o valor extremo.', true, 'A mediana é o valor central da lista ordenada e permanece perto dos 3.000, que é o caso típico.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-1', 'C', 'a amplitude, porque mostra a diferença entre extremos.', false, 'Amplitude descreve dispersão, não valor típico.', 'confundir dispersão com centro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-1', 'D', 'o maior salário, porque define o teto da equipe.', false, 'O teto descreve um caso, não o conjunto.', 'usar valor isolado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-1', 'E', 'a soma dos salários, porque representa o custo real.', false, 'A soma é um total, não uma medida de valor típico.', 'confundir total com centro');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-est-2', 'estatistica', 'interpretar-medidas-estatisticas-em-contexto', 'intro', 'applied', false, 'Sete alunos tiraram as notas 4, 6, 6, 7, 8, 9 e 10. A média e a mediana dessa turma são, respectivamente:', 'Média é a soma dividida pela quantidade. Mediana é o valor central da lista ordenada — com sete valores, é o quarto.', 'Média é a soma dividida pela quantidade. Mediana é o valor central da lista ordenada — com sete valores, é o quarto.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-2', 'A', '7,14 e 8, tomando o valor do meio da lista original.', false, 'A lista já está ordenada, e o quarto valor é 7.', 'contar posição errada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-2', 'B', '7,14 e 6, porque 6 é a nota que mais se repete.', false, 'A nota mais repetida é a moda, não a mediana.', 'confundir moda com mediana');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-2', 'C', '7 e 7,14, invertendo as duas medidas.', false, 'Os valores estão trocados de lugar.', 'trocar as medidas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-2', 'D', '7,14 e 7.', true, 'A soma é 50 e 50 ÷ 7 ≈ 7,14. Com sete valores ordenados, o central é o quarto, que é 7.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-2', 'E', '7,5 e 7, arredondando a soma.', false, 'A soma das notas é 50, e não 52,5.', 'soma incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-est-3', 'estatistica', 'interpretar-medidas-estatisticas-em-contexto', 'intermediate', 'interpretation', false, 'Duas escolas têm a mesma média de 6,0 em uma prova, mas a primeira tem desvio padrão 0,5 e a segunda, 2,5. Sobre o desempenho das duas, conclui-se que:', 'Média informa o centro; desvio padrão informa o espalhamento. Sem os dois, duas realidades diferentes parecem iguais.', 'Média informa o centro; desvio padrão informa o espalhamento. Sem os dois, duas realidades diferentes parecem iguais.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-3', 'A', 'na primeira as notas se concentram perto de 6; na segunda há muitas notas bem altas e bem baixas.', true, 'O desvio padrão mede o quanto os valores se afastam da média, e é justamente isso que separa as duas escolas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-3', 'B', 'as duas têm o mesmo desempenho, pois a média é igual.', false, 'Médias iguais podem esconder distribuições muito diferentes.', 'ignorar a dispersão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-3', 'C', 'a segunda é melhor, porque tem mais variedade.', false, 'Variedade não é sinônimo de qualidade do desempenho.', 'confundir dispersão com mérito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-3', 'D', 'a primeira é melhor, porque desvio menor significa nota maior.', false, 'Desvio menor significa notas mais próximas entre si, não mais altas.', 'confundir dispersão com nível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-3', 'E', 'a segunda tem mais alunos, por isso o desvio é maior.', false, 'O desvio padrão não mede tamanho de amostra.', 'confundir dispersão com tamanho');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-est-4', 'estatistica', 'interpretar-medidas-estatisticas-em-contexto', 'intermediate', 'comparison', false, 'Uma pesquisa ouviu 500 pessoas na fila de um estádio e outra ouviu 500 pessoas sorteadas do cadastro de eleitores do município. Sobre a comparação entre as duas amostras:', 'O que permite generalizar não é o tamanho da amostra, e sim como ela foi escolhida. Uma amostra grande e enviesada erra com confiança.', 'O que permite generalizar não é o tamanho da amostra, e sim como ela foi escolhida. Uma amostra grande e enviesada erra com confiança.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-4', 'A', 'A primeira é melhor, porque as pessoas estavam disponíveis para conversar.', false, 'Facilidade de acesso é exatamente o que produz viés de conveniência.', 'confundir conveniência com qualidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-4', 'B', 'As duas são equivalentes, porque ouviram o mesmo número de pessoas.', false, 'Tamanho igual não corrige um método de seleção enviesado.', 'julgar pelo tamanho');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-4', 'C', 'A segunda é melhor apenas se ouvir mais de mil pessoas.', false, 'O limiar citado é arbitrário; o que muda a qualidade é o sorteio.', 'critério inventado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-4', 'D', 'Nenhuma serve, porque toda pesquisa por amostra é imprecisa.', false, 'Amostras têm margem de erro, e isso não as invalida quando bem construídas.', 'recusa sem critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-4', 'E', 'O tamanho é o mesmo, mas só a segunda permite generalizar para o município.', true, 'Amostragem aleatória do cadastro dá a cada eleitor chance conhecida de ser sorteado; a fila do estádio já seleciona um perfil.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-est-5', 'estatistica', 'interpretar-medidas-estatisticas-em-contexto', 'challenging', 'integration', false, 'Uma turma de 20 alunos tem média 6,0. Chegam dois alunos transferidos, com notas 9,0 e 10,0. A nova média da turma passa a ser de aproximadamente:', 'Para recompor uma média, volte à soma total. Novos valores mudam soma e quantidade, e o efeito de poucos casos sobre muitos é pequeno.', 'Para recompor uma média, volte à soma total. Novos valores mudam soma e quantidade, e o efeito de poucos casos sobre muitos é pequeno.', 'Nunca faça média de médias sem verificar o tamanho de cada grupo. Reconstruir a soma evita o erro.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-5', 'A', '8,3, tirando a média entre 6,0, 9,0 e 10,0.', false, 'Média de médias só vale quando os grupos têm o mesmo tamanho, e aqui são 20 contra 2.', 'média das médias');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-5', 'B', '6,0, porque dois alunos não mudam a turma.', false, 'Dois alunos acima da média puxam o resultado, ainda que pouco.', 'supor invariância');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-5', 'C', '6,3.', true, 'A soma antiga é 20 × 6 = 120. Com 9 e 10, a soma passa a 139, e 139 ÷ 22 ≈ 6,32.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-5', 'D', '7,0, arredondando a favor dos novos alunos.', false, 'Esse valor superestima o efeito de dois alunos entre 22.', 'peso incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est-5', 'E', '6,9, considerando os novos alunos com peso maior.', false, 'Não há peso extra: cada aluno conta uma vez.', 'atribuir peso indevido');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-prob-1', 'probabilidade', 'calcular-e-interpretar-probabilidades', 'intro', 'concept', false, 'Uma urna contém 3 bolas verdes, 5 azuis e 2 brancas. Retirando uma bola ao acaso, a probabilidade de ela ser azul é:', 'Probabilidade simples é casos favoráveis sobre o total de casos possíveis: 5 em 10.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-1', 'A', '1/2', true, 'Total de bolas: 3 + 5 + 2 = 10. Favoráveis: 5 azuis. P = 5/10 = 1/2.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-1', 'B', '5/7', false, 'Usa 7 como total, esquecendo duas bolas.', 'errar o espaço amostral');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-1', 'C', '2/10', false, 'Corresponde às bolas brancas.', 'responder outra cor');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-1', 'D', '5/8', false, 'Usa 8 como total, esquecendo as bolas brancas.', 'errar o espaço amostral');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-1', 'E', '3/10', false, 'Corresponde às bolas verdes.', 'responder outra cor');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-prob-2', 'probabilidade', 'calcular-e-interpretar-probabilidades', 'intermediate', 'applied', false, 'Uma moeda honesta é lançada três vezes. A probabilidade de sair pelo menos uma coroa é:', 'Para "pelo menos um", calcule o complementar: 1 menos a probabilidade de nenhum.', NULL, 'Se a resposta passar de 1, há erro de método — provavelmente soma indevida.', NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-2', 'A', '7/8', true, 'O complementar de "pelo menos uma coroa" é "nenhuma coroa", isto é, três caras: (1/2)³ = 1/8. Logo, 1 − 1/8 = 7/8.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-2', 'B', '1/8', false, 'É a probabilidade de sair coroa nas três jogadas.', 'responder o caso extremo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-2', 'C', '3/8', false, 'Corresponde a exatamente uma coroa.', 'confundir "pelo menos uma" com "exatamente uma"');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-2', 'D', '1/2', false, 'É a probabilidade de coroa em um único lançamento.', 'ignorar as três jogadas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-2', 'E', '3/2', false, 'Probabilidade não pode ser maior que 1.', 'somar probabilidades indevidamente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-prob-3', 'probabilidade', 'calcular-e-interpretar-probabilidades', 'intermediate', 'interpretation', false, 'Uma pesquisa com 200 pessoas registrou o meio de transporte usado para ir ao trabalho:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-3', 'A', '15%', false, 'Considera apenas quem usa bicicleta.', 'responder só uma categoria');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-3', 'B', '25%', true, 'Não motorizado reúne bicicleta (30) e a pé (20): 50 pessoas em 200, ou 25%.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-3', 'C', '10%', false, 'Considera apenas quem vai a pé.', 'responder só uma categoria');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-3', 'D', '75%', false, 'É a probabilidade de usar transporte motorizado.', 'responder o complementar do pedido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-3', 'E', '45%', false, 'Corresponde à proporção de quem usa ônibus.', 'responder outra categoria');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-prob-4', 'probabilidade', 'calcular-e-interpretar-probabilidades', 'challenging', 'comparison', false, 'Considere duas situações com uma urna que contém 4 fichas vermelhas e 6 azuis:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-4', 'A', 'A probabilidade em I é maior, pois em II a segunda retirada tem menos fichas vermelhas disponíveis.', true, 'I: (4/10) × (4/10) = 16%. II: (4/10) × (3/9) ≈ 13,3%. Sem reposição, tanto o numerador quanto o denominador diminuem.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-4', 'B', 'As duas probabilidades são iguais, pois a composição inicial é a mesma.', false, 'A composição muda depois da primeira retirada no caso II.', 'ignorar a mudança do espaço amostral');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-4', 'C', 'A probabilidade em II é maior, pois há menos fichas na urna.', false, 'Menos fichas no total não compensa a perda de uma ficha vermelha.', 'raciocinar apenas pelo denominador');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-4', 'D', 'Não é possível comparar sem saber a ordem das retiradas.', false, 'A ordem não altera o resultado neste caso.', 'introduzir variável desnecessária');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-4', 'E', 'A probabilidade em I é o dobro da probabilidade em II.', false, 'A diferença é de 16% para 13,3%, e não do dobro.', 'exagerar a diferença');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-prob-5', 'probabilidade', 'calcular-e-interpretar-probabilidades', 'challenging', 'integration', false, 'Um teste rápido para uma doença acerta 95% dos casos positivos. Em uma cidade em que 1 em cada 1.000 pessoas tem a doença, uma pessoa sem sintomas recebe resultado positivo.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-5', 'A', 'A pessoa certamente está doente, pois o teste é confiável.', false, 'Nenhum teste torna um resultado isolado uma certeza.', 'tratar probabilidade como certeza');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-5', 'B', 'O resultado não traz nenhuma informação, pois a doença é rara.', false, 'O resultado aumenta bastante a probabilidade em relação à população geral; ele apenas não a torna alta em termos absolutos.', 'descartar informação relevante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-5', 'C', 'Como a doença é rara, boa parte dos positivos pode vir de falsos positivos, e um segundo exame é necessário.', true, 'Com prevalência de 1 em 1.000, mesmo uma pequena taxa de falso positivo gera mais positivos falsos que verdadeiros. Por isso um resultado isolado, sem sintomas, pede confirmação.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-5', 'D', 'A raridade da doença torna o teste inútil para qualquer finalidade.', false, 'O teste é útil como triagem; o que muda é a interpretação do resultado isolado.', 'generalizar a limitação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-5', 'E', 'A pessoa tem 95% de chance de estar doente, que é a taxa de acerto do teste.', false, 'A taxa de acerto responde a outra pergunta: dado que a pessoa está doente, qual a chance de o teste dar positivo.', 'inverter a condicional');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-prob-rec-1', 'probabilidade', 'calcular-e-interpretar-probabilidades', 'intro', 'concept', true, 'Um dado comum de seis faces é lançado uma vez. A probabilidade de sair um número maior que 4 é:', '"Maior que 4" inclui apenas 5 e 6 — o próprio 4 fica de fora.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-rec-1', 'A', '2/3', false, 'Corresponde aos números menores ou iguais a 4.', 'responder o complementar');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-rec-1', 'B', '5/6', false, 'Corresponde a excluir apenas um resultado.', 'errar a contagem');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-rec-1', 'C', '1/2', false, 'Corresponde a incluir 4, 5 e 6 — mas "maior que 4" exclui o próprio 4.', 'incluir o limite');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-rec-1', 'D', '1/6', false, 'Corresponde a um único resultado favorável.', 'contar de menos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prob-rec-1', 'E', '1/3', true, 'Maiores que 4 são 5 e 6: dois casos em seis, ou seja, 2/6 = 1/3.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-prob-1', 'probabilidade', 'calcular-e-interpretar-probabilidades', 'intro', 'concept', false, 'Uma moeda honesta foi lançada quatro vezes e deu cara nas quatro. Sobre o quinto lançamento, é correto afirmar que a probabilidade de sair cara é de:', 'Lançamentos de moeda são independentes: o resultado anterior não muda a chance do próximo. A sequência ser improvável não muda o passo seguinte.', 'Lançamentos de moeda são independentes: o resultado anterior não muda a chance do próximo. A sequência ser improvável não muda o passo seguinte.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-1', 'A', '1 em 32, que é a chance de cinco caras seguidas.', false, 'Essa é a probabilidade da sequência inteira antes de começar, não a do próximo lançamento.', 'confundir sequência com evento isolado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-1', 'B', '50%, porque cada lançamento é independente dos anteriores.', true, 'Em eventos independentes, o histórico não altera a chance do próximo resultado.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-1', 'C', '100%, porque a tendência se mantém.', false, 'Não existe tendência em lançamentos independentes.', 'inventar tendência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-1', 'D', 'menos de 50%, porque coroa está atrasada.', false, 'A moeda não guarda memória dos lançamentos anteriores.', 'falácia do jogador');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-1', 'E', 'mais de 50%, porque a moeda parece viciada.', false, 'Quatro caras seguidas acontecem com frequência razoável em moedas honestas.', 'conclusão precipitada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-prob-2', 'probabilidade', 'calcular-e-interpretar-probabilidades', 'intermediate', 'applied', false, 'Uma urna tem 5 bolas verdes e 3 azuis. Duas bolas são retiradas sem reposição. A probabilidade de as duas serem verdes é de:', 'Sem reposição, cada retirada muda a urna. A chance conjunta multiplica a primeira pela segunda já ajustada.', 'Sem reposição, cada retirada muda a urna. A chance conjunta multiplica a primeira pela segunda já ajustada.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-2', 'A', '5/8, considerando apenas a primeira retirada.', false, 'Essa é a chance de a primeira ser verde, não de as duas serem.', 'parar na primeira etapa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-2', 'B', '9/14, que é o complemento do resultado correto.', false, 'Esse é o valor de "não sair duas verdes".', 'usar o complemento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-2', 'C', '20/56 é impossível, pois probabilidade não é fração.', false, 'Probabilidade é justamente uma razão entre casos favoráveis e possíveis.', 'negar a forma de fração');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-2', 'D', '25/64, mantendo a urna cheia nas duas retiradas.', false, 'Sem reposição, a segunda retirada acontece com uma bola a menos na urna.', 'ignorar a retirada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-2', 'E', '5/14.', true, 'Primeira: 5/8. Segunda: 4/7. O produto é 20/56, que simplifica para 5/14.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-prob-3', 'probabilidade', 'calcular-e-interpretar-probabilidades', 'challenging', 'interpretation', false, 'Um exame para uma doença rara acerta 99% dos casos. Um jornal conclui que quem teve resultado positivo tem 99% de chance de estar doente. Sobre essa conclusão:', 'A chance de estar doente dado um teste positivo depende da prevalência. Em doenças raras, mesmo exames muito bons produzem maioria de falsos positivos.', 'A chance de estar doente dado um teste positivo depende da prevalência. Em doenças raras, mesmo exames muito bons produzem maioria de falsos positivos.', 'Ao ler uma probabilidade condicional, pergunte sempre: condicional a quê? Trocar a condição inverte o sentido do resultado.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-3', 'A', 'Está correta, porque o exame é confiável.', false, 'Confiabilidade alta não basta: o resultado depende também de quantas pessoas têm a doença.', 'ignorar a prevalência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-3', 'B', 'Está correta apenas se o exame for repetido.', false, 'A repetição melhora a estimativa, mas o erro do raciocínio não é esse.', 'condição periférica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-3', 'C', 'Está errada porque nenhum exame é confiável.', false, 'O problema não é a existência de erro, e sim como as chances se combinam.', 'recusa sem critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-3', 'D', 'Está errada porque 99% se refere a quem não tem a doença.', false, 'O índice citado descreve o acerto do exame, não um grupo específico.', 'leitura incorreta do dado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-3', 'E', 'Está errada: em doença rara, a maior parte dos positivos vem de falsos positivos na população saudável.', true, 'Se poucos têm a doença, 1% de erro sobre um grupo enorme de saudáveis produz mais positivos que os doentes verdadeiros.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-prob-4', 'probabilidade', 'calcular-e-interpretar-probabilidades', 'intermediate', 'comparison', false, 'Comparando o lançamento de dois dados honestos, a chance de a soma ser 7 e a chance de a soma ser 12 estão na relação:', 'Com dois dados há 36 resultados igualmente prováveis. A soma 7 aparece em seis deles; a soma 12, em apenas um.', 'Com dois dados há 36 resultados igualmente prováveis. A soma 7 aparece em seis deles; a soma 12, em apenas um.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-4', 'A', 'a soma 7 é duas vezes mais provável.', false, 'A razão entre os casos favoráveis é de seis para um, não de dois para um.', 'contagem incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-4', 'B', 'não é possível comparar sem saber a ordem dos dados.', false, 'A contagem já considera os pares ordenados no espaço de 36 resultados.', 'exigir dado desnecessário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-4', 'C', 'a soma 7 é seis vezes mais provável, porque tem seis combinações contra uma.', true, 'A soma 7 sai de seis pares distintos e a soma 12 só de um: 6/36 contra 1/36.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-4', 'D', 'as duas têm a mesma chance, pois há 11 somas possíveis.', false, 'As somas possíveis não são equiprováveis: elas vêm de números diferentes de pares.', 'supor equiprobabilidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-4', 'E', 'a soma 12 é mais provável, porque exige o valor máximo.', false, 'Exigir o valor máximo nos dois dados torna o evento mais raro, não mais comum.', 'inverter o raciocínio');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-prob-5', 'probabilidade', 'calcular-e-interpretar-probabilidades', 'challenging', 'integration', false, 'Em uma turma, 60% praticam esporte, 30% tocam um instrumento e 20% fazem as duas coisas. Sorteando um aluno ao acaso, a probabilidade de ele praticar esporte ou tocar instrumento é de:', 'Para eventos que podem ocorrer juntos, a união soma os dois e desconta a interseção, que foi contada duas vezes.', 'Para eventos que podem ocorrer juntos, a união soma os dois e desconta a interseção, que foi contada duas vezes.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-5', 'A', '110%, somando tudo o que aparece no enunciado.', false, 'Probabilidade não pode passar de 100%, o que já sinaliza o erro de soma.', 'resultado impossível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-5', 'B', '90%, somando os dois percentuais.', false, 'Somar sem descontar conta duas vezes quem faz as duas coisas.', 'contagem dupla');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-5', 'C', '50%, subtraindo a interseção do maior grupo.', false, 'A interseção deve ser descontada uma vez da soma, não do grupo maior.', 'subtração no lugar errado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-5', 'D', '70%.', true, 'A união é 60% + 30% − 20% = 70%, descontando uma vez quem foi contado duas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prob-5', 'E', '20%, considerando apenas quem faz as duas coisas.', false, 'Esse é o valor da interseção, não da união.', 'confundir união com interseção');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-fin-1', 'matematica-financeira', 'avaliar-situacoes-financeiras-com-juros-e-descontos', 'intro', 'concept', false, 'Um capital de R$ 2.000,00 é aplicado a juros simples de 2% ao mês durante 5 meses. O montante final é:', 'Em juros simples, os juros incidem sempre sobre o capital inicial: 2% × 5 = 10% de R$ 2.000.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-1', 'A', 'R$ 2.040,00', false, 'Corresponde a apenas um mês de juros.', 'ignorar o prazo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-1', 'B', 'R$ 2.200,00', true, 'Juros: 2.000 × 0,02 × 5 = R$ 200. Montante: 2.000 + 200 = R$ 2.200,00.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-1', 'C', 'R$ 2.208,16', false, 'É o montante a juros compostos, e não simples.', 'trocar o regime de capitalização');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-1', 'D', 'R$ 2.100,00', false, 'Corresponde a 5% no período, e não a 2% ao mês por 5 meses.', 'errar a taxa acumulada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-1', 'E', 'R$ 2.400,00', false, 'Corresponde a 4% ao mês.', 'dobrar a taxa');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-fin-2', 'matematica-financeira', 'avaliar-situacoes-financeiras-com-juros-e-descontos', 'intermediate', 'applied', false, 'Uma loja anuncia um sofá por R$ 1.800,00 à vista ou em 12 parcelas de R$ 175,00 "sem juros".
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-2', 'A', 'O parcelamento é sempre a melhor opção, pois preserva o dinheiro em caixa.', false, 'Preservar caixa pode ser desejável, mas isso é uma decisão de orçamento, não uma vantagem financeira automática.', 'generalizar uma decisão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-2', 'B', 'Realmente não há juros, pois o anúncio informa "sem juros".', false, 'O total parcelado supera o preço à vista, o que caracteriza acréscimo.', 'aceitar o rótulo sem verificar');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-2', 'C', 'A parcela de R$ 175,00 é menor que R$ 1.800,00, o que já comprova vantagem do parcelamento.', false, 'Comparar parcela com preço total não é uma comparação válida.', 'comparar grandezas diferentes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-2', 'D', 'Há um acréscimo de R$ 300,00, o que corresponde a cerca de 16,7% sobre o preço à vista.', true, 'Total parcelado: 12 × 175 = R$ 2.100. Diferença: R$ 300 sobre R$ 1.800, ou seja, ≈ 16,7% de acréscimo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-2', 'E', 'Há um acréscimo de R$ 300,00, o que corresponde a 30% sobre o preço à vista.', false, 'O valor absoluto está certo, mas 300 sobre 1.800 é ≈ 16,7%, não 30%.', 'errar a base do percentual');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-fin-3', 'matematica-financeira', 'avaliar-situacoes-financeiras-com-juros-e-descontos', 'intermediate', 'interpretation', false, 'A tabela mostra a evolução de uma dívida de R$ 1.000,00 em dois regimes, com taxa de 10% ao mês:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-3', 'A', 'Os dois regimes produzem o mesmo resultado em qualquer prazo.', false, 'Só coincidem no primeiro período.', 'ignorar os dados da tabela');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-3', 'B', 'O regime composto só é desvantajoso a partir de um ano.', false, 'A desvantagem começa já no segundo mês, e apenas se amplia.', 'errar o momento da divergência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-3', 'C', 'A diferença entre os dois regimes cresce com o tempo, porque no regime composto os juros passam a incidir também sobre juros anteriores.', true, 'No mês 1 os valores coincidem; no mês 3 diferem em R$ 31; no mês 6, em R$ 172. A base de cálculo do regime composto aumenta a cada período.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-3', 'D', 'A diferença entre os regimes é constante e igual a R$ 100,00 por mês.', false, 'A tabela mostra diferenças de R$ 0, R$ 10, R$ 31 e R$ 172 — crescentes.', 'supor crescimento linear');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-3', 'E', 'O regime simples é sempre mais caro para quem deve.', false, 'É o contrário: o composto acumula mais.', 'inverter a comparação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-fin-4', 'matematica-financeira', 'avaliar-situacoes-financeiras-com-juros-e-descontos', 'challenging', 'comparison', false, 'Duas lojas anunciam o mesmo produto de R$ 500,00:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-4', 'A', 'Não é possível comparar sem saber a ordem dos descontos na loja B.', false, 'A ordem dos descontos sucessivos não altera o resultado final.', 'introduzir variável irrelevante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-4', 'B', 'Os preços finais são iguais, pois 15% + 10% = 25%.', false, 'Descontos sucessivos não se somam: incidem sobre bases diferentes.', 'somar percentuais sucessivos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-4', 'C', 'A loja B é mais barata, pois oferece dois descontos.', false, 'Dois descontos não garantem desconto maior.', 'contar descontos em vez de calcular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-4', 'D', 'A loja B é mais barata em R$ 12,50.', false, 'O valor está certo em módulo, mas favorece a loja errada.', 'inverter o sinal da diferença');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-4', 'E', 'A loja A é mais barata em R$ 7,50.', true, 'Loja A: 500 × 0,75 = R$ 375,00. Loja B: 500 × 0,85 × 0,90 = R$ 382,50. A diferença é de R$ 7,50 a favor da loja A.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-fin-5', 'matematica-financeira', 'avaliar-situacoes-financeiras-com-juros-e-descontos', 'challenging', 'integration', false, 'Uma pessoa tem R$ 3.000,00 guardados rendendo 0,8% ao mês. Ela quer comprar um equipamento que custa R$ 3.000,00 à vista ou 10 parcelas de R$ 330,00.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-5', 'A', 'Pagar à vista é melhor apenas se a pessoa não tiver outra reserva de emergência.', false, 'Ter reserva é um critério relevante, mas a comparação de custo já favorece o pagamento à vista.', 'trocar o critério financeiro por outro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-5', 'B', 'A decisão depende exclusivamente do valor da parcela caber no orçamento mensal.', false, 'Caber no orçamento é condição necessária, não suficiente: o custo total também pesa.', 'reduzir a decisão a um só critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-5', 'C', 'Parcelar é sempre melhor, pois o dinheiro continua rendendo na aplicação.', false, 'O rendimento precisa superar o acréscimo do parcelamento — e aqui não supera.', 'generalizar sem comparar taxas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-5', 'D', 'O parcelamento custa 10% a mais no total, acréscimo superior ao que os R$ 3.000,00 renderiam no período, o que favorece a compra à vista.', true, 'Total parcelado: 10 × 330 = R$ 3.300, ou 10% de acréscimo. A aplicação renderia cerca de 8,3% em 10 meses (1,008¹⁰ ≈ 1,083), abaixo do custo do parcelamento.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-5', 'E', 'As duas opções são equivalentes, pois o valor à vista é igual ao total das parcelas.', false, 'O total parcelado é R$ 3.300, e não R$ 3.000.', 'errar a soma das parcelas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-fin-rec-1', 'matematica-financeira', 'avaliar-situacoes-financeiras-com-juros-e-descontos', 'intro', 'concept', true, 'Um produto de R$ 200,00 recebe um desconto de 10% e, sobre o valor já reduzido, mais 10%. O preço final é:', 'O segundo desconto incide sobre o valor já reduzido: 0,90 × 0,90 = 0,81, isto é, 19% de desconto total.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-rec-1', 'A', 'R$ 160,00', false, 'Corresponde a somar os descontos e aplicar 20% de uma vez.', 'somar descontos sucessivos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-rec-1', 'B', 'R$ 180,00', false, 'Corresponde a aplicar apenas um dos descontos.', 'esquecer o segundo desconto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-rec-1', 'C', 'R$ 162,00', true, '200 × 0,90 = 180; 180 × 0,90 = R$ 162,00. O desconto total é de 19%, não de 20%.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-rec-1', 'D', 'R$ 170,00', false, 'Não corresponde a nenhuma etapa do cálculo.', 'estimar sem calcular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-fin-rec-1', 'E', 'R$ 164,00', false, 'Não corresponde ao produto dos fatores de desconto.', 'errar a multiplicação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fin-1', 'matematica-financeira', 'avaliar-situacoes-financeiras-com-juros-e-descontos', 'intro', 'concept', false, 'Sobre a diferença entre juros simples e juros compostos aplicados ao mesmo capital, prazo e taxa, é correto afirmar que:', 'No regime simples a base dos juros não muda; no composto ela cresce a cada período. Daí a diferença aumentar com o prazo.', 'No regime simples a base dos juros não muda; no composto ela cresce a cada período. Daí a diferença aumentar com o prazo.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-1', 'A', 'o composto só existe em aplicações bancárias.', false, 'Ele aparece também em dívidas, cartões e financiamentos.', 'restrição inventada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-1', 'B', 'a diferença aparece só quando a taxa passa de 10%.', false, 'A diferença aparece a partir do segundo período, com qualquer taxa positiva.', 'limiar inventado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-1', 'C', 'os dois dão sempre o mesmo montante.', false, 'Eles coincidem apenas no primeiro período; depois o composto cresce mais.', 'igualar regimes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-1', 'D', 'o simples rende mais no longo prazo.', false, 'É o contrário: o composto incorpora os juros anteriores à base.', 'inverter os regimes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-1', 'E', 'no simples os juros incidem sempre sobre o capital inicial; no composto, sobre o saldo acumulado.', true, 'Essa é exatamente a diferença entre os dois regimes, e o que faz o composto crescer mais rápido.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fin-2', 'matematica-financeira', 'avaliar-situacoes-financeiras-com-juros-e-descontos', 'intro', 'applied', false, 'Um capital de R$ 2.000 é aplicado a juros compostos de 10% ao mês. Após dois meses, o montante é de:', 'Juros compostos multiplicam o fator (1 + i) uma vez por período. Dois meses a 10% dão fator 1,21.', 'Juros compostos multiplicam o fator (1 + i) uma vez por período. Dois meses a 10% dão fator 1,21.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-2', 'A', 'R$ 2.420 é impossível, pois excede 20% do capital.', false, 'O montante de fato passa de 20% do capital, e é isso que caracteriza o regime composto.', 'negar o resultado correto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-2', 'B', 'R$ 2.442, capitalizando três meses.', false, 'Esse valor corresponde a um período a mais.', 'período extra');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-2', 'C', 'R$ 2.420.', true, '2.000 × 1,10 × 1,10 = 2.420. O segundo mês rende sobre 2.200, e não sobre 2.000.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-2', 'D', 'R$ 2.400, somando 10% duas vezes sobre o capital.', false, 'Essa é a conta de juros simples; no composto o segundo mês incide sobre 2.200.', 'usar regime simples');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-2', 'E', 'R$ 2.200, considerando apenas um mês.', false, 'O enunciado pede dois meses.', 'parar no primeiro período');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fin-3', 'matematica-financeira', 'avaliar-situacoes-financeiras-com-juros-e-descontos', 'intermediate', 'interpretation', false, 'Um anúncio oferece "12 vezes sem juros de R$ 250" para um produto que custa R$ 2.400 à vista. Sobre esse anúncio, a leitura mais correta é que:', '"Sem juros" costuma significar que o juro está no preço, não na parcela. A comparação honesta é sempre com o preço à vista.', '"Sem juros" costuma significar que o juro está no preço, não na parcela. A comparação honesta é sempre com o preço à vista.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-3', 'A', 'há um custo embutido de R$ 600, ou 25% sobre o preço à vista.', true, '12 × 250 = 3.000, contra 2.400 à vista: a diferença é 600, isto é, 25% do preço à vista.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-3', 'B', 'o preço à vista é que está inflacionado.', false, 'O enunciado dá o preço à vista como referência da compra.', 'inverter a referência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-3', 'C', 'não há juros, como diz o anúncio.', false, 'O parcelado soma 3.000 contra 2.400 à vista, então há custo embutido.', 'aceitar o rótulo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-3', 'D', 'há juros de 25% ao mês.', false, 'Vinte e cinco por cento é a diferença total do período, não a taxa mensal.', 'confundir total com taxa mensal');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-3', 'E', 'o parcelamento é sempre pior que pagar à vista.', false, 'Depende do que a pessoa faria com o dinheiro; o ponto aqui é que o custo existe e está escondido.', 'conclusão absoluta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fin-4', 'matematica-financeira', 'avaliar-situacoes-financeiras-com-juros-e-descontos', 'challenging', 'comparison', false, 'Duas formas de pagar uma compra de R$ 1.000: à vista com 8% de desconto, ou em duas parcelas iguais de R$ 500, a primeira hoje. Considerando que o dinheiro guardado renderia 1% ao mês, a comparação correta é:', 'Fluxos em datas diferentes só se comparam trazendo tudo à mesma data. Aqui o desconto à vista supera com folga o ganho de adiar metade do pagamento.', 'Fluxos em datas diferentes só se comparam trazendo tudo à mesma data. Aqui o desconto à vista supera com folga o ganho de adiar metade do pagamento.', 'Traga todos os pagamentos para a data de hoje antes de comparar. Somar valores de meses diferentes é comparar coisas distintas.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-4', 'A', 'As duas opções custam R$ 1.000 e se equivalem.', false, 'A opção à vista custa 920, e a parcelada tem valor presente próximo de 995.', 'ignorar desconto e tempo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-4', 'B', 'A opção à vista é melhor: custa R$ 920 contra cerca de R$ 995 em valor de hoje.', true, 'À vista: 1.000 × 0,92 = 920. Parcelado: 500 hoje mais 500 daqui a um mês, que hoje valem 500 ÷ 1,01 ≈ 495.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-4', 'C', 'A parcelada é melhor, porque adia metade do valor.', false, 'Adiar tem valor, mas 1% ao mês sobre 500 não compensa um desconto de 80 reais.', 'superestimar o rendimento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-4', 'D', 'A parcelada é melhor apenas se o rendimento passar de 8% ao mês.', false, 'O limiar citado compara grandezas de períodos diferentes.', 'limiar incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-4', 'E', 'Não é possível comparar porque os prazos são diferentes.', false, 'É justamente para prazos diferentes que se traz tudo a valor presente.', 'recusa sem critério');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-fin-5', 'matematica-financeira', 'avaliar-situacoes-financeiras-com-juros-e-descontos', 'challenging', 'integration', false, 'Uma fatura de cartão de R$ 800 não foi paga e sofre juros de 12% ao mês, em regime composto. Se nada for pago por três meses, a dívida chega a aproximadamente:', 'Doze por cento ao mês em regime composto multiplica a dívida por 1,12 a cada mês. Em três meses o fator chega a 1,40, e não a 1,36 do regime simples.', 'Doze por cento ao mês em regime composto multiplica a dívida por 1,12 a cada mês. Em três meses o fator chega a 1,40, e não a 1,36 do regime simples.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-5', 'A', 'R$ 800, porque juros só valem após seis meses.', false, 'Não existe carência desse tipo no enunciado.', 'regra inventada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-5', 'B', 'R$ 1.124, um acréscimo de cerca de 40% sobre a dívida original.', true, '800 × 1,12³ = 800 × 1,404928 ≈ 1.123,94, isto é, cerca de 40% acima do valor inicial.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-5', 'C', 'R$ 1.088, somando 12% três vezes sobre os 800 iniciais.', false, 'Essa é a conta de juros simples; no composto a base cresce a cada mês.', 'usar regime simples');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-5', 'D', 'R$ 896, considerando apenas o primeiro mês.', false, 'O enunciado pede três meses.', 'parar no primeiro período');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-fin-5', 'E', 'R$ 2.240, aplicando 12% ao dia.', false, 'A taxa informada é mensal.', 'trocar a unidade de tempo');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cid-1', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'intro', 'concept', false, 'Um município cria um conselho municipal de saúde com participação de usuários, trabalhadores e gestores, com poder de aprovar o plano municipal de saúde.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-1', 'A', 'Direito social, pois o conselho trata de saúde.', false, 'O tema é social, mas o direito exercido é o de participar. Classificar pelo assunto é o erro mais comum aqui.', 'classificar pelo tema em vez do exercício');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-1', 'B', 'Direito civil, pois garante liberdade individual.', false, 'Direitos civis protegem a liberdade individual; conselho é ação coletiva de decisão.', 'confundir individual com coletivo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-1', 'C', 'Não configura direito, apenas prática administrativa.', false, 'A participação social em conselhos é prevista como diretriz do sistema de saúde brasileiro.', 'reduzir participação a formalidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-1', 'D', 'Direito trabalhista, pois inclui trabalhadores em sua composição.', false, 'A presença de trabalhadores é parte da composição, não a natureza do direito exercido.', 'classificar pela composição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-1', 'E', 'Direito político, pois trata de participação nas decisões públicas.', true, 'O conselho é um canal de participação na decisão coletiva. Embora o tema seja saúde, o direito exercido no ato é o de participar do poder.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cid-2', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'intermediate', 'applied', false, 'Uma escola pública instala rampas, contrata intérprete de Libras e adapta materiais para estudantes com deficiência. Um morador critica a medida dizendo que "isso é privilégio, porque nem todos recebem esse tratamento".
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-2', 'A', 'A crítica só faria sentido se a escola fosse privada.', false, 'A obrigação de acessibilidade não depende da natureza da instituição.', 'condicionar o direito à natureza da instituição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-2', 'B', 'Tratamentos diferenciados podem ser o meio necessário para garantir acesso igual ao mesmo direito.', true, 'Sem rampa ou intérprete, o direito à educação existe no papel mas não se realiza. A diferenciação corrige a barreira, não cria vantagem.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-2', 'C', 'Direitos educacionais são facultativos e dependem da disponibilidade orçamentária.', false, 'Educação é direito, não medida facultativa sujeita a conveniência.', 'tratar direito como benefício');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-2', 'D', 'A escola deveria oferecer o mesmo recurso a todos os estudantes indistintamente.', false, 'Intérprete de Libras para quem ouve não amplia acesso nenhum; recursos de acessibilidade respondem a barreiras específicas.', 'confundir igualdade com uniformidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-2', 'E', 'Estudantes com deficiência deveriam ser atendidos em instituições separadas.', false, 'A perspectiva inclusiva prevê acesso à escola comum com os apoios necessários.', 'propor segregação como solução');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cid-3', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'intermediate', 'interpretation', false, 'Leia o trecho de um relatório fictício de ouvidoria:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-3', 'A', 'O excesso de recursos orçamentários destinados a acessibilidade.', false, 'Só 31% preveem orçamento específico — o oposto de excesso.', 'inverter a leitura do dado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-3', 'B', 'A distância entre a previsão legal e a efetivação, evidenciada pela queda entre lei, orçamento e execução.', true, 'A sequência 78% → 31% → 12% mostra que a norma existe na maioria, mas orçamento e obra acompanham em proporção muito menor. Esse é o retrato de um direito garantido e não efetivado.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-3', 'C', 'A ausência de legislação sobre acessibilidade na maior parte dos municípios.', false, 'A legislação existe em 78% — é justamente o item com maior cobertura.', 'ler o dado ao contrário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-3', 'D', 'A desnecessidade de novas leis, já que o tema está totalmente resolvido.', false, 'Apenas 12% executaram obras: o tema está longe de resolvido.', 'confundir existência de lei com solução');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-3', 'E', 'A prioridade dada por gestores municipais ao tema da acessibilidade.', false, 'Prioridade se mede em orçamento e execução, e ambos são baixos.', 'inferir intenção a partir da norma');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cid-4', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'challenging', 'comparison', false, 'Considere duas afirmações sobre o conceito de cidadania regulada:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-4', 'A', 'Nenhuma das duas.', false, 'I descreve o conceito com precisão.', 'excesso de cautela');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-4', 'B', 'I e II, desde que consideradas apenas as décadas recentes.', false, 'Nenhum recorte temporal torna II compatível com o conceito.', 'salvar a afirmação com condição artificial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-4', 'C', 'I, apenas.', true, 'A cidadania regulada define direitos a partir da inserção em ocupação formalmente reconhecida — o que, por definição, deixava de fora trabalhadores rurais, domésticos e informais. II afirma o contrário disso.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-4', 'D', 'II, apenas.', false, 'II é justamente o que o conceito nega: a cobertura era desigual e condicionada.', 'inverter o sentido do conceito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-4', 'E', 'I e II.', false, 'I está correta, mas II a contradiz: se os direitos são vinculados à ocupação reconhecida, não são universais.', 'não perceber a contradição entre as afirmações');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cid-5', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'challenging', 'integration', false, 'Uma comunidade rural sem transporte escolar regular tem 40% de seus adolescentes fora da escola. A prefeitura responde criando uma campanha de conscientização sobre a importância dos estudos.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-5', 'A', 'A medida trata como problema de informação uma barreira que é material, deixando a causa apontada pelos dados sem resposta.', true, 'O dado apresentado aponta ausência de transporte. Campanha informativa não move ninguém até a escola: a política precisa remover a barreira concreta identificada.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-5', 'B', 'Campanhas de conscientização são sempre ineficazes em qualquer contexto.', false, 'Campanhas funcionam quando o obstáculo é de fato informacional. O problema é a inadequação ao caso, não a ferramenta em si.', 'generalizar a crítica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-5', 'C', 'A responsabilidade pela frequência escolar é exclusiva das famílias.', false, 'A garantia de acesso à educação básica envolve o poder público, inclusive quanto ao transporte escolar.', 'transferir responsabilidade ao indivíduo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-5', 'D', 'O percentual de 40% é baixo demais para justificar qualquer política pública.', false, 'Quatro em cada dez adolescentes fora da escola é indicador grave por qualquer critério.', 'minimizar o dado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-5', 'E', 'A solução correta seria transferir os estudantes para escolas particulares.', false, 'A solução não enfrenta a barreira de deslocamento e desloca a obrigação do poder público.', 'propor solução que ignora a causa');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cid-rec-1', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'intro', 'concept', true, 'O direito de votar e ser votado pertence a qual categoria de direitos?', 'Votar e ser votado são a expressão central dos direitos políticos.', NULL, NULL, NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-rec-1', 'A', 'Direitos políticos.', true, 'Direitos políticos tratam da participação no poder, e votar é a forma mais direta dessa participação.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-rec-1', 'B', 'Direitos civis.', false, 'Direitos civis protegem liberdades individuais como ir e vir, expressão e propriedade.', 'confundir liberdade individual com participação política');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-rec-1', 'C', 'Direitos sociais.', false, 'Direitos sociais garantem condições materiais como saúde e educação.', 'confundir categorias');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-rec-1', 'D', 'Direitos trabalhistas.', false, 'Direitos trabalhistas são um subconjunto dos sociais e não tratam de participação eleitoral.', 'usar categoria específica demais');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-rec-1', 'E', 'Não é um direito, mas um dever obrigatório.', false, 'No Brasil o voto é obrigatório para parte da população, mas isso não retira sua natureza de direito.', 'confundir obrigatoriedade com ausência de direito');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cid-rec-2', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'intermediate', 'applied', true, 'Uma lei garante o direito a atendimento prioritário, mas a unidade não possui sinalização nem organização de fila que o viabilize.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-rec-2', 'A', 'A necessidade de revogar a lei por ser inaplicável.', false, 'A lei não é inaplicável: faltam condições de aplicação, que podem ser criadas.', 'confundir falta de meio com impossibilidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-rec-2', 'B', 'O excesso de direitos garantidos à população.', false, 'O problema apontado é de implementação, não de quantidade de direitos.', 'deslocar o problema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-rec-2', 'C', 'Uma escolha legítima da unidade quanto ao seu funcionamento.', false, 'Descumprir norma de prioridade não é escolha administrativa legítima.', 'legitimar descumprimento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-rec-2', 'D', 'A diferença entre direito previsto em lei e direito efetivado na prática.', true, 'A norma existe; faltam os meios de implementação. Essa distância é exatamente o que o conceito descreve.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-rec-2', 'E', 'A inexistência de legislação sobre o tema.', false, 'O enunciado afirma que a lei existe.', 'contrariar o enunciado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cid-6', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'intro', 'concept', false, 'Uma lei garante acesso gratuito a determinado serviço público, mas o prédio não possui rampa, elevador ou atendimento alternativo. A situação evidencia que:', 'Direitos não se realizam apenas pela declaração legal; condições materiais e adaptações podem ser necessárias para acesso efetivo.', 'Direitos não se realizam apenas pela declaração legal; condições materiais e adaptações podem ser necessárias para acesso efetivo.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-6', 'A', 'A igualdade prevista formalmente precisa de condições materiais para se tornar efetiva.', true, 'A norma existe, mas a infraestrutura impede que todos usufruam dela.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-6', 'B', 'Somente serviços pagos precisam de adaptação.', false, 'Dever de acessibilidade não depende da cobrança.', 'associação indevida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-6', 'C', 'A gratuidade elimina qualquer barreira ao serviço.', false, 'Barreiras físicas continuam impedindo parte da população de exercer o direito.', 'reduzir acesso a preço');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-6', 'D', 'A acessibilidade é uma preferência individual sem relação com cidadania.', false, 'Acessibilidade é condição para exercício de direitos em igualdade.', 'individualizar barreira estrutural');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-6', 'E', 'O serviço deve deixar de ser público.', false, 'O problema exige adequação, não retirada do caráter público.', 'solução incompatível');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cid-7', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'intro', 'applied', false, 'Moradores participam de uma audiência sobre orçamento municipal, apresentam dados do bairro e propõem prioridades. Essa prática exemplifica:', 'Cidadania política inclui voto, debate público, proposição, controle social e acompanhamento de decisões coletivas.', 'Cidadania política inclui voto, debate público, proposição, controle social e acompanhamento de decisões coletivas.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-7', 'A', 'Decisão judicial sobre o orçamento.', false, 'A cena é de participação pública, não de julgamento.', 'confundir poderes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-7', 'B', 'Substituição definitiva dos representantes eleitos.', false, 'A participação social complementa instituições representativas; não as elimina.', 'falsa substituição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-7', 'C', 'Participação cidadã na deliberação e fiscalização de políticas públicas.', true, 'Os moradores intervêm no debate sobre prioridades e acompanham a alocação de recursos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-7', 'D', 'Privatização da administração municipal.', false, 'Não há transferência do serviço ao setor privado.', 'conceito sem relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-7', 'E', 'Suspensão do direito ao voto.', false, 'A audiência não retira direitos eleitorais.', 'oposição inventada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cid-8', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'intermediate', 'interpretation', false, 'Um município publica dados de contratos em formato aberto, com busca por fornecedor, valor e etapa de execução. O principal efeito democrático dessa medida é:', 'Transparência qualificada reduz assimetria de informação e fortalece fiscalização por cidadãos, imprensa e instituições.', 'Transparência qualificada reduz assimetria de informação e fortalece fiscalização por cidadãos, imprensa e instituições.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-8', 'A', 'Garantir que todo contrato esteja livre de irregularidades.', false, 'Transparência facilita controle, mas não garante ausência de problemas.', 'promessa absoluta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-8', 'B', 'Eliminar a necessidade de órgãos de fiscalização.', false, 'Controle social complementa, não substitui, controles institucionais.', 'substituição indevida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-8', 'C', 'Transferir ao cidadão a obrigação exclusiva de administrar.', false, 'A responsabilidade administrativa permanece com o poder público.', 'inverter responsabilidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-8', 'D', 'Impedir qualquer divergência sobre prioridades orçamentárias.', false, 'Dados podem ampliar o debate, não eliminar divergências legítimas.', 'confundir informação com consenso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-8', 'E', 'Ampliar condições para controle social e responsabilização sobre o uso de recursos.', true, 'Dados acessíveis permitem acompanhar decisões e cobrar justificativas.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cid-9', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'intermediate', 'comparison', false, 'Compare duas políticas: I. distribuir o mesmo material impresso a todos; II. oferecer material impresso, digital acessível e apoio de leitura conforme a necessidade. A segunda se aproxima do princípio de equidade porque:', 'Equidade não nega igualdade; ela considera obstáculos distintos para tornar o acesso ao direito mais próximo do universal.', 'Equidade não nega igualdade; ela considera obstáculos distintos para tornar o acesso ao direito mais próximo do universal.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-9', 'A', 'Substitui políticas públicas por caridade.', false, 'Trata-se de desenho de política pública, não de favor voluntário.', 'despolitizar direito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-9', 'B', 'Reconhece barreiras diferentes e ajusta meios para aproximar as condições de acesso.', true, 'Equidade trata necessidades desiguais com respostas adequadas para viabilizar o mesmo direito.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-9', 'C', 'Garante resultados idênticos para todas as pessoas.', false, 'A política amplia acesso, mas não controla todos os resultados individuais.', 'confundir condição e resultado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-9', 'D', 'Abandona o direito universal ao conteúdo.', false, 'O direito permanece universal; variam os meios de acesso.', 'confundir meio e direito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-9', 'E', 'Restringe o material digital a quem não sabe ler.', false, 'A formulação não estabelece essa restrição.', 'inventar critério');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cid-10', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'challenging', 'integration', false, 'Uma plataforma pública só permite solicitar benefício por aplicativo, embora parte do público não tenha internet estável nem aparelho compatível. A análise que integra cidadania e tecnologia é:', 'Tecnologia pode ampliar acesso, mas um canal único também exclui. Cidadania digital exige infraestrutura, acessibilidade e alternativas.', 'Tecnologia pode ampliar acesso, mas um canal único também exclui. Cidadania digital exige infraestrutura, acessibilidade e alternativas.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-10', 'A', 'O benefício deixa de ser uma política pública quando usa aplicativo.', false, 'O canal não altera a natureza da política.', 'confundir suporte e instituição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-10', 'B', 'A solução é eliminar todo atendimento digital.', false, 'O problema pode ser resolvido por múltiplos canais, não pela rejeição completa da tecnologia.', 'falsa escolha');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-10', 'C', 'A digitalização torna o serviço universal por definição.', false, 'Disponibilidade online não garante acesso material ou competência digital.', 'determinismo tecnológico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-10', 'D', 'Quem não usa o aplicativo abre mão voluntariamente do direito.', false, 'A falta de infraestrutura pode ser uma barreira involuntária.', 'culpabilização individual');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cid-10', 'E', 'Sem canais alternativos e apoio, a inovação pode produzir nova barreira ao exercício de um direito.', true, 'A eficiência tecnológica precisa ser combinada com inclusão e atendimento acessível.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cid-1', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'intro', 'concept', false, 'A classificação dos direitos em civis, políticos e sociais é útil porque:', 'A tipologia organiza a análise: liberdade exige que o Estado não interfira, participação exige que ele organize, e direitos sociais exigem que ele provenha.', 'A tipologia organiza a análise: liberdade exige que o Estado não interfira, participação exige que ele organize, e direitos sociais exigem que ele provenha.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-1', 'A', 'mostra que apenas os direitos civis são universais.', false, 'Todos os três são reivindicados como universais em documentos internacionais.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-1', 'B', 'estabelece uma hierarquia entre eles, dos mais aos menos importantes.', false, 'A tipologia não ordena por importância.', 'ler como hierarquia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-1', 'C', 'indica a ordem em que devem ser concedidos em qualquer país.', false, 'A sequência histórica variou entre países e não é uma regra.', 'confundir descrição com norma');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-1', 'D', 'separa os direitos garantidos por lei dos que dependem de costume.', false, 'Todos os tipos podem estar previstos em lei.', 'critério trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-1', 'E', 'distingue tipos de garantia com exigências diferentes: liberdades, participação política e acesso a bens sociais.', true, 'Cada grupo demanda do Estado uma ação distinta, e por isso a distinção ajuda a analisar sua efetivação.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cid-2', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'intro', 'applied', false, 'Um município cria um conselho com participação de moradores para decidir parte do orçamento local. Essa iniciativa é um exemplo de:', 'Orçamento participativo é canal de deliberação direta sobre parte dos recursos, somando-se ao voto em vez de substituí-lo.', 'Orçamento participativo é canal de deliberação direta sobre parte dos recursos, somando-se ao voto em vez de substituí-lo.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-2', 'A', 'democracia representativa, pois há eleição de conselheiros.', false, 'Ainda que haja escolha de representantes, o traço definidor aqui é a deliberação direta sobre o orçamento.', 'classificar pelo procedimento acessório');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-2', 'B', 'substituição do poder legislativo municipal.', false, 'O conselho complementa as instituições, sem substituí-las.', 'consequência incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-2', 'C', 'democracia participativa, que amplia a decisão para além do voto periódico.', true, 'Mecanismos participativos criam canais de deliberação entre eleições, sobre políticas específicas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-2', 'D', 'centralização administrativa, pois concentra decisões no município.', false, 'Descentralizar a decisão para os moradores é o oposto de centralizar.', 'conceito invertido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-2', 'E', 'medida inconstitucional, por retirar competência do prefeito.', false, 'A participação social em orçamento é prevista e praticada legalmente.', 'afirmação incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cid-3', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'intermediate', 'interpretation', false, 'Uma lei garante atendimento prioritário a pessoas com deficiência, mas o prédio público não tem rampa nem elevador. Essa situação ilustra que:', 'Direito efetivo exige condição material. Rampa, elevador e sinalização são parte do direito, não acessórios dele.', 'Direito efetivo exige condição material. Rampa, elevador e sinalização são parte do direito, não acessórios dele.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-3', 'A', 'o problema é da pessoa, que deveria buscar outro local de atendimento.', false, 'A obrigação de acessibilidade é do serviço público, não do usuário.', 'transferir a responsabilidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-3', 'B', 'a acessibilidade só se aplica a prédios novos.', false, 'A adequação de prédios existentes também é exigida.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-3', 'C', 'a lei é desnecessária, já que não é cumprida.', false, 'A lei é o instrumento que torna a falta exigível.', 'inverter a conclusão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-3', 'D', 'a previsão legal de um direito não basta: sem condições materiais, o acesso não se realiza.', true, 'Direito garantido no papel e barreira física no prédio mostram que efetivação depende de investimento e fiscalização.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-3', 'E', 'a prioridade no atendimento é um privilégio indevido.', false, 'Tratamento diferenciado para equalizar acesso não é privilégio.', 'confundir equidade com privilégio');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cid-4', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'intermediate', 'comparison', false, 'Comparando igualdade formal e igualdade material como princípios de política pública, é correto afirmar que:', 'Tratar igualmente os desiguais pode aprofundar a desigualdade. A igualdade material é o princípio que autoriza diferenciar para equalizar.', 'Tratar igualmente os desiguais pode aprofundar a desigualdade. A igualdade material é o princípio que autoriza diferenciar para equalizar.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-4', 'A', 'a igualdade material é incompatível com a Constituição.', false, 'A Constituição prevê instrumentos voltados à redução de desigualdades.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-4', 'B', 'a igualdade formal é suficiente quando há desigualdade histórica.', false, 'Tratamento idêntico sobre pontos de partida desiguais tende a manter a distância.', 'ignorar o ponto de partida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-4', 'C', 'a igualdade material só se aplica a questões econômicas.', false, 'Ela é invocada também em acesso à educação, saúde e representação.', 'restrição indevida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-4', 'D', 'a formal garante as mesmas regras para todos, e a material admite tratamento diferenciado para corrigir desigualdades de partida.', true, 'Uma assegura a mesma regra; a outra considera as condições concretas em que a regra é aplicada.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-4', 'E', 'as duas exigem tratamento idêntico a todos, em qualquer situação.', false, 'A igualdade material admite tratamento diferenciado para corrigir desigualdades de partida.', 'igualar os princípios');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cid-5', 'cidadania-e-direitos', 'relacionar-conceitos-a-situacoes-concretas', 'challenging', 'integration', false, 'Um estudante afirma que "direitos humanos servem para proteger bandidos". Uma resposta consistente com o conceito jurídico e histórico desses direitos observa que eles:', 'Direitos humanos existem sobretudo para limitar o que o poder pode fazer com qualquer pessoa. Punir com processo justo é compatível com eles; punir com tortura, não.', 'Direitos humanos existem sobretudo para limitar o que o poder pode fazer com qualquer pessoa. Punir com processo justo é compatível com eles; punir com tortura, não.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-5', 'A', 'valem para todas as pessoas justamente porque limitam o poder do Estado, o que não impede punição prevista em lei e com devido processo.', true, 'A universalidade protege qualquer um contra tortura e arbítrio; ela não retira do Estado o poder de julgar e punir conforme a lei.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-5', 'B', 'aplicam-se apenas a quem nunca cometeu crime.', false, 'Condicionar direitos à conduta anula a ideia de universalidade.', 'condicionar a universalidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-5', 'C', 'impedem que qualquer pessoa seja presa.', false, 'Prisão legal, com processo, é compatível com esses direitos.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-5', 'D', 'são um conceito recente, sem relação com a história.', false, 'Eles resultam de séculos de disputa e se consolidam no pós-guerra.', 'datação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cid-5', 'E', 'valem somente em tratados internacionais, sem efeito interno.', false, 'Eles integram o ordenamento jurídico brasileiro.', 'afirmação incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-urb-1', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'intro', 'concept', false, 'A urbanização brasileira, entre 1950 e 1990, caracterizou-se por ser acelerada e não acompanhada, na mesma proporção, por oferta de moradia adequada e infraestrutura.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-1', 'A', 'A concentração exclusiva do crescimento em cidades de pequeno porte.', false, 'O crescimento concentrou-se sobretudo em grandes cidades e regiões metropolitanas.', 'errar a escala do fenômeno');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-1', 'B', 'A expansão de assentamentos precários e a ocupação de áreas periféricas e de risco.', true, 'Sem oferta de moradia acessível na velocidade da chegada, a ocupação se deu onde o solo era barato ou desprezado pelo mercado: periferias distantes e áreas de risco.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-1', 'C', 'A redução da população urbana em favor do retorno ao campo.', false, 'O movimento foi o oposto: a população urbana cresceu de forma acentuada no período.', 'inverter o sentido do processo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-1', 'D', 'A equalização das condições de moradia entre as regiões das cidades.', false, 'O período aprofundou, e não reduziu, as diferenças internas das cidades.', 'assumir efeito equalizador');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-1', 'E', 'A eliminação da especulação imobiliária nas áreas centrais.', false, 'A valorização das áreas centrais é justamente um dos motores do processo descrito.', 'inverter o papel do mercado de terras');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-urb-2', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'intermediate', 'applied', false, 'Em uma região metropolitana, um município concentra os empregos e outro concentra a moradia dos trabalhadores. O município-dormitório arrecada pouco e precisa manter escolas e postos de saúde para uma população que trabalha fora.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-2', 'A', 'A desnecessidade de políticas integradas entre municípios vizinhos.', false, 'O quadro demonstra exatamente a necessidade dessas políticas.', 'inverter a conclusão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-2', 'B', 'A superioridade do modelo de cidades isoladas sobre regiões metropolitanas.', false, 'O texto descreve um desafio de gestão, não uma comparação entre modelos.', 'extrapolar juízo de valor');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-2', 'C', 'O descompasso entre a cidade real, que é metropolitana, e a gestão administrativa, que é municipal.', true, 'As pessoas vivem uma cidade única que atravessa fronteiras municipais, enquanto orçamento e responsabilidade seguem divididos por município. Daí o desequilíbrio entre onde se arrecada e onde se gasta.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-2', 'D', 'A má administração exclusiva do município-dormitório.', false, 'O problema é estrutural: mesmo uma gestão eficiente enfrenta o descompasso entre base tributária e demanda por serviços.', 'reduzir problema estrutural a gestão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-2', 'E', 'A ausência de população economicamente ativa no município-dormitório.', false, 'A população é ativa: ela apenas trabalha em outro município.', 'confundir local de trabalho com inatividade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-urb-3', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'intermediate', 'interpretation', false, 'Observe os dados de uma cidade fictícia:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-3', 'A', 'A desigualdade de renda se manifesta também em acesso desigual a tempo e a espaço público, caracterizando segregação socioespacial.', true, 'Os três indicadores se alinham: menor renda coincide com maior tempo de deslocamento e menos área verde. A desigualdade social aparece inscrita no território.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-3', 'B', 'A renda mais baixa da Zona B é causada pela menor quantidade de áreas verdes.', false, 'Área verde não determina renda. Os indicadores estão associados, não em relação causal direta nessa direção.', 'inverter causa e efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-3', 'C', 'Os dados não permitem qualquer comparação, pois medem coisas diferentes.', false, 'Justamente por medirem dimensões diferentes é que revelam o alinhamento entre elas.', 'recusar leitura possível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-3', 'D', 'A Zona A é mais populosa, o que explica seu melhor desempenho nos indicadores.', false, 'Os dados não informam população, e dois dos três indicadores são médias ou razões per capita.', 'inventar dado ausente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-3', 'E', 'O tempo de deslocamento é uma escolha individual dos moradores da Zona B.', false, 'Morar longe do trabalho decorre do preço do solo, não de preferência por deslocamento longo.', 'individualizar causa estrutural');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-urb-4', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'challenging', 'comparison', false, 'Dois programas urbanos foram propostos para um bairro periférico:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-4', 'A', 'A primeira beneficia mais moradores, por concentrar recursos no transporte.', false, 'Beneficia enquanto os moradores permanecerem; sem política de permanência, parte deles não permanece.', 'medir benefício sem considerar o deslocamento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-4', 'B', 'A segunda impede a valorização do bairro, o que prejudica o investimento.', false, 'Limitar a valorização por período não impede o investimento nem a melhoria: apenas modera a captura do ganho.', 'confundir moderação com impedimento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-4', 'C', 'Não há diferença prática: transporte é o fator determinante nos dois casos.', false, 'Os efeitos sobre quem permanece no bairro são substancialmente diferentes.', 'ignorar efeitos distributivos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-4', 'D', 'A primeira é preferível por não interferir no mercado imobiliário.', false, 'Investimento público em transporte já interfere fortemente no mercado imobiliário — a questão é se essa interferência será regulada ou não.', 'supor neutralidade do investimento público');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-4', 'E', 'A segunda prevê mecanismos de permanência, reduzindo o risco de que a valorização desloque a população que se pretende beneficiar.', true, 'Melhoria urbana valoriza o solo. Sem instrumentos de permanência, o ganho é capturado por quem chega depois e a população original é deslocada por preço.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-urb-5', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'challenging', 'integration', false, 'Uma cidade registra ocupações recorrentes em encostas com risco de deslizamento. Ao mesmo tempo, 18% dos lotes com infraestrutura completa em áreas centrais estão vazios há mais de dez anos.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-5', 'A', 'Os lotes vazios devem permanecer assim para preservar o valor do solo urbano.', false, 'Preservar o valor do solo é justamente o interesse que sustenta a retenção — e o que a política urbana busca moderar em nome da função social da propriedade.', 'confundir interesse privado com interesse público');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-5', 'B', 'Os dois fatos são faces do mesmo processo: a retenção especulativa de terra bem localizada eleva o preço e empurra a ocupação para áreas de risco.', true, 'Lotes vazios com infraestrutura são mantidos à espera de valorização. Isso reduz a oferta efetiva de solo urbanizado, eleva o preço e desloca quem não pode pagar para áreas desprezadas pelo mercado — exatamente as de risco.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-5', 'C', 'São fenômenos independentes: um decorre da geografia e o outro do mercado.', false, 'A geografia define onde há encosta; o mercado define quem acaba morando lá. Os dois se articulam.', 'separar fatos conectados');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-5', 'D', 'A ocupação de encostas decorre da preferência dos moradores por áreas com vista e menor movimento.', false, 'Risco de deslizamento não é atributo desejado; a ocupação decorre de ausência de alternativa acessível.', 'individualizar causa estrutural');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-5', 'E', 'A solução adequada seria remover as ocupações sem qualquer contrapartida habitacional.', false, 'Remoção sem alternativa transfere o problema de lugar e costuma gerar nova ocupação de risco.', 'propor solução que reproduz a causa');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-urb-rec-1', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'intro', 'concept', true, 'O termo "periferização" descreve principalmente:', 'Periferização liga renda baixa a localização distante e mal servida.', NULL, NULL, NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-rec-1', 'A', 'A construção de novos centros comerciais fora do centro histórico.', false, 'Isso descreve descentralização de atividades, não a distribuição da moradia por renda.', 'confundir com descentralização econômica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-rec-1', 'B', 'A migração de moradores urbanos para o campo.', false, 'É o movimento inverso ao descrito pelo conceito.', 'inverter o sentido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-rec-1', 'C', 'A valorização dos imóveis das áreas mais afastadas.', false, 'A periferização decorre justamente do preço mais baixo dessas áreas.', 'inverter a lógica de preço');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-rec-1', 'D', 'O deslocamento da população de menor renda para áreas distantes e menos servidas de infraestrutura.', true, 'O conceito descreve a relação entre renda e localização: quem tem menos renda ocupa a terra mais barata, que é a mais distante e menos equipada.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-rec-1', 'E', 'O crescimento populacional das cidades em geral.', false, 'Crescimento populacional é urbanização; periferização é a distribuição desigual dentro da cidade.', 'confundir volume com distribuição');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-urb-rec-2', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'intermediate', 'applied', true, 'Após a instalação de equipamentos públicos em um bairro popular, o aluguel médio sobe fortemente e parte dos moradores antigos precisa se mudar.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-rec-2', 'A', 'Conurbação.', false, 'Conurbação é a junção física de manchas urbanas de municípios diferentes.', 'confundir com fenômeno físico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-rec-2', 'B', 'Êxodo rural.', false, 'Êxodo rural é a saída da população do campo para a cidade.', 'trocar de fenômeno');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-rec-2', 'C', 'Gentrificação.', true, 'Gentrificação é a valorização de uma área que resulta na substituição da população original por moradores de renda mais alta.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-rec-2', 'D', 'Periferização.', false, 'Periferização descreve o deslocamento para áreas distantes; aqui o foco é a valorização de uma área já ocupada.', 'confundir dois processos relacionados');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-rec-2', 'E', 'Metropolização.', false, 'Metropolização é a integração funcional entre municípios vizinhos.', 'trocar de escala');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-urb-6', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'intro', 'concept', false, 'Em uma metrópole, empregos se concentram no centro, enquanto moradias de menor custo se expandem em áreas periféricas. Uma consequência provável é:', 'A segregação entre locais de morar e trabalhar transforma desigualdade territorial em desigualdade de tempo e acesso.', 'A segregação entre locais de morar e trabalhar transforma desigualdade territorial em desigualdade de tempo e acesso.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-6', 'A', 'Desaparecimento do preço da terra como fator urbano.', false, 'O custo da moradia é parte central do padrão descrito.', 'ignorar causa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-6', 'B', 'Aumento do tempo e do custo de deslocamento para parte da população.', true, 'A distância entre residência periférica e emprego central amplia viagens cotidianas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-6', 'C', 'Redução automática das distâncias diárias.', false, 'A separação entre moradia e emprego tende a aumentar deslocamentos.', 'inverter relação espacial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-6', 'D', 'Fim da dependência de transporte coletivo.', false, 'Longas distâncias costumam aumentar a importância de redes de transporte.', 'consequência oposta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-6', 'E', 'Distribuição igual de infraestrutura pelo território.', false, 'A descrição já indica concentração e expansão desigual.', 'negar premissa');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-urb-7', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'intermediate', 'applied', false, 'Uma linha de transporte de alta capacidade é inaugurada em área periférica, mas a tarifa permanece elevada e faltam conexões locais até as estações. Para ampliar efetivamente a mobilidade, seria prioritário:', 'Mobilidade é uma cadeia: origem, acesso à estação, tarifa, deslocamento principal e destino. A infraestrutura isolada não garante acesso.', 'Mobilidade é uma cadeia: origem, acesso à estação, tarifa, deslocamento principal e destino. A infraestrutura isolada não garante acesso.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-7', 'A', 'Retirar informação sobre horários.', false, 'Menos informação reduz previsibilidade e não corrige as barreiras.', 'ação sem relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-7', 'B', 'Concentrar ainda mais empregos no centro.', false, 'Isso reforça a necessidade de longos deslocamentos.', 'aprofundar causa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-7', 'C', 'Proibir deslocamentos a pé até as estações.', false, 'A medida elimina uma forma de acesso e não resolve segurança ou conexão.', 'solução absurda');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-7', 'D', 'Integrar tarifas e linhas alimentadoras, considerando o percurso completo do usuário.', true, 'Acesso depende de chegar à estação e conseguir pagar pela viagem total.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-7', 'E', 'Aumentar a distância entre as estações.', false, 'Isso pode piorar o acesso local e não enfrenta a tarifa.', 'medida contrária');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-urb-8', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'intermediate', 'interpretation', false, 'Após a valorização de um bairro, aluguéis sobem, comércios populares fecham e moradores antigos se deslocam para áreas mais distantes. O processo descrito é associado a:', 'Gentrificação combina revalorização do espaço com pressão econômica que altera quem consegue permanecer nele.', 'Gentrificação combina revalorização do espaço com pressão econômica que altera quem consegue permanecer nele.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-8', 'A', 'Gentrificação, com valorização acompanhada de substituição social.', true, 'A alta de custos e o deslocamento de moradores caracterizam substituição socioespacial.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-8', 'B', 'Desmetropolização total.', false, 'A mudança em um bairro não significa fim da metrópole.', 'generalização de escala');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-8', 'C', 'Reforma agrária.', false, 'O conceito se refere à estrutura fundiária rural.', 'trocar contexto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-8', 'D', 'Conurbação.', false, 'Conurbação é a união física de áreas urbanizadas de municípios próximos.', 'confundir processos urbanos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-8', 'E', 'Ruralização.', false, 'O processo ocorre no espaço urbano e não envolve predomínio de atividades rurais.', 'conceito incompatível');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-urb-9', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'challenging', 'comparison', false, 'Compare: I. construir conjuntos habitacionais distantes, sem serviços próximos; II. combinar moradia acessível, transporte, escolas, saúde e comércio em áreas integradas. A segunda estratégia tende a:', 'Habitação adequada depende da inserção urbana, não apenas da unidade construída. Serviços e mobilidade reduzem isolamento territorial.', 'Habitação adequada depende da inserção urbana, não apenas da unidade construída. Serviços e mobilidade reduzem isolamento territorial.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-9', 'A', 'Impedir qualquer deslocamento entre bairros.', false, 'Integração reduz viagens compulsórias, mas não elimina circulação.', 'exagero');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-9', 'B', 'Aumentar necessariamente o preço de toda moradia.', false, 'O desenho integrado não implica uma única trajetória de preços.', 'consequência absoluta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-9', 'C', 'Eliminar a necessidade de planejamento urbano.', false, 'A integração exige mais coordenação entre políticas.', 'inverter exigência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-9', 'D', 'Separar ainda mais residência e serviços.', false, 'A proposta busca justamente aproximá-los.', 'contradição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-9', 'E', 'Reduzir a segregação funcional e parte dos deslocamentos obrigatórios.', true, 'Mistura de usos e serviços próximos amplia acesso cotidiano.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-urb-10', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'challenging', 'integration', false, 'Uma cidade mapeia tempo de viagem, renda, localização de hospitais e frequência do transporte. A combinação desses dados permite analisar principalmente:', 'Cruzar indicadores revela acesso real, que depende tanto da oferta de serviços quanto das condições de deslocamento e renda.', 'Cruzar indicadores revela acesso real, que depende tanto da oferta de serviços quanto das condições de deslocamento e renda.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-10', 'A', 'Somente a quantidade física de hospitais.', false, 'Os dados incluem acesso, renda e transporte, indo além da contagem.', 'redução do conjunto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-10', 'B', 'A preferência estética dos moradores.', false, 'Os indicadores não medem gosto ou estética.', 'variável ausente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-10', 'C', 'Desigualdades de acesso à saúde produzidas pela localização e pela mobilidade.', true, 'Tempo, renda, oferta e transporte mostram quem consegue alcançar serviços e em quais condições.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-10', 'D', 'A idade exata de cada edifício hospitalar.', false, 'Nenhum dado de idade foi mencionado.', 'inventar variável');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-urb-10', 'E', 'A inexistência de diferenças entre bairros.', false, 'A análise foi montada justamente para identificar diferenças territoriais.', 'negar objetivo');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-urb-1', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'intro', 'concept', false, 'O termo "segregação socioespacial" descreve, nos estudos urbanos, a situação em que:', 'Segregação socioespacial é desigualdade escrita no mapa: quem mora onde, e o que existe perto de cada lugar.', 'Segregação socioespacial é desigualdade escrita no mapa: quem mora onde, e o que existe perto de cada lugar.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-1', 'A', 'há muros e cercas separando bairros.', false, 'Muros são uma forma visível, mas a segregação opera principalmente por preço da terra e localização.', 'reduzir à forma visível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-1', 'B', 'pessoas de renda diferente convivem no mesmo bairro.', false, 'Isso descreve o oposto: mistura social no espaço.', 'inverter o conceito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-1', 'C', 'há diferença de renda entre habitantes de uma cidade.', false, 'A diferença de renda é condição, mas a segregação é a sua tradução no espaço.', 'parar na renda');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-1', 'D', 'grupos sociais distintos ocupam áreas distintas da cidade, com acesso desigual a serviços e oportunidades.', true, 'A desigualdade se inscreve no território e se reproduz por transporte, infraestrutura e preço da terra.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-1', 'E', 'a cidade cresce além dos limites do município.', false, 'Esse processo é a conurbação, e não a segregação.', 'conceito trocado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-urb-2', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'intermediate', 'applied', false, 'Uma prefeitura instala uma linha de metrô que liga a periferia ao centro. Sem política habitacional acompanhando a obra, um efeito frequentemente observado é:', 'Investimento em infraestrutura vira preço da terra. Sem instrumentos de permanência, a melhoria pode expulsar quem ela deveria beneficiar.', 'Investimento em infraestrutura vira preço da terra. Sem instrumentos de permanência, a melhoria pode expulsar quem ela deveria beneficiar.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-2', 'A', 'queda do preço dos imóveis próximos às estações.', false, 'Acesso a transporte de qualidade costuma valorizar, não desvalorizar.', 'prever efeito inverso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-2', 'B', 'valorização dos imóveis no entorno e deslocamento de moradores de menor renda para áreas mais distantes.', true, 'A melhoria se converte em preço, e quem paga aluguel tende a ser empurrado para onde o preço ainda cabe.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-2', 'C', 'redução do número de viagens diárias na cidade.', false, 'Melhor transporte costuma aumentar a mobilidade.', 'prever efeito inverso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-2', 'D', 'fim da informalidade habitacional na região atendida.', false, 'A informalidade responde a preço e renda, e pode até se agravar com a valorização.', 'consequência exagerada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-2', 'E', 'isolamento do centro em relação à periferia.', false, 'A obra faz exatamente o contrário: conecta as duas áreas.', 'contradizer o enunciado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-urb-3', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'intermediate', 'interpretation', false, 'Um mapa mostra que os bairros com menor cobertura de arborização coincidem com os de menor renda e maiores temperaturas registradas. A leitura mais adequada desse conjunto de dados é que:', 'Injustiça ambiental é o nome dessa sobreposição: os efeitos ambientais negativos se concentram onde vive a população com menos recursos para se proteger.', 'Injustiça ambiental é o nome dessa sobreposição: os efeitos ambientais negativos se concentram onde vive a população com menos recursos para se proteger.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-3', 'A', 'a temperatura mais alta reduz a renda dos moradores.', false, 'A inversão da ordem causal não se sustenta com esses dados.', 'inverter a causalidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-3', 'B', 'a falta de árvores é escolha dos moradores desses bairros.', false, 'Arborização depende de investimento público e de desenho urbano, não de escolha individual.', 'atribuição individual');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-3', 'C', 'a coincidência entre as três camadas é casual e não sustenta conclusão.', false, 'Padrões espaciais sistemáticos raramente são casuais e pedem investigação.', 'descartar o padrão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-3', 'D', 'os dados provam que arborizar resolveria a desigualdade de renda.', false, 'Arborizar melhora o conforto térmico, mas não é política de renda.', 'conclusão exagerada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-3', 'E', 'a desigualdade social também se expressa na exposição a riscos ambientais, como o calor urbano.', true, 'A sobreposição das camadas mostra que quem tem menos renda vive nas áreas menos protegidas do calor.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-urb-4', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'intermediate', 'comparison', false, 'Comparando duas cidades com o mesmo número de habitantes, uma compacta e outra espalhada por grande área, é correto esperar que a segunda apresente:', 'Densidade não é sinônimo de qualidade nem de problema: ela define o custo de conectar pessoas a redes e serviços.', 'Densidade não é sinônimo de qualidade nem de problema: ela define o custo de conectar pessoas a redes e serviços.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-4', 'A', 'maior custo por habitante em redes de infraestrutura e maior distância média de deslocamento.', true, 'Espalhar a mesma população por mais área alonga redes e trajetos, encarecendo os dois.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-4', 'B', 'ausência de periferias, por não haver concentração central.', false, 'Cidades espalhadas costumam ter periferias extensas e mal servidas.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-4', 'C', 'menor custo por habitante para levar água e esgoto.', false, 'Redes mais longas para a mesma população encarecem o custo por pessoa.', 'inverter a relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-4', 'D', 'menor dependência do transporte motorizado.', false, 'Distâncias maiores aumentam a dependência do transporte motorizado.', 'inverter a relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-4', 'E', 'maior facilidade para viabilizar transporte coletivo de alta capacidade.', false, 'Alta capacidade exige densidade de demanda ao longo do trajeto.', 'inverter a relação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-urb-5', 'urbanizacao-e-desigualdade', 'interpretar-fenomenos-espaciais-sociais-economicos', 'challenging', 'integration', false, 'Um plano municipal propõe combater a ocupação de encostas apenas com remoção das famílias, sem oferta de moradia alternativa próxima. Analisando essa proposta:', 'Ocupação de área de risco é sintoma de um problema de moradia e localização. Tratar só o sintoma reproduz o problema em outro lugar.', 'Ocupação de área de risco é sintoma de um problema de moradia e localização. Tratar só o sintoma reproduz o problema em outro lugar.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-5', 'A', 'ela resolve o problema se as famílias forem indenizadas em dinheiro.', false, 'Indenização sem oferta de moradia acessível não garante alternativa no mesmo território.', 'solução parcial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-5', 'B', 'ela é a única política possível diante de risco iminente.', false, 'Diante de risco iminente a remoção pode ser necessária, mas ela não substitui a política habitacional.', 'confundir emergência com política');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-5', 'C', 'ela tende a falhar, porque a ocupação de área de risco decorre da falta de moradia acessível perto do trabalho.', true, 'Removida de um ponto, a família tende a ocupar outro semelhante, já que a causa — preço e localização — permanece.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-5', 'D', 'ela é suficiente, pois elimina o risco de deslizamento.', false, 'Ela desloca o risco em vez de resolvê-lo.', 'confundir remoção com solução');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-urb-5', 'E', 'ela é desnecessária, pois encostas não oferecem risco real.', false, 'Encostas ocupadas sem contenção apresentam risco documentado.', 'negar o risco');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-amb-1', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'intro', 'concept', false, 'Uma fábrica lança efluentes não tratados em um córrego. Moradores a jusante relatam perda da pesca e aumento de problemas de saúde.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-1', 'A', 'Subsídio ambiental.', false, 'Subsídio é transferência deliberada de recursos públicos, o que não descreve a situação.', 'trocar de conceito econômico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-1', 'B', 'Compensação ambiental.', false, 'Compensação é a medida que repara ou contrabalança o dano — aqui ela está ausente.', 'confundir dano com reparação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-1', 'C', 'Depreciação de capital.', false, 'Depreciação refere-se à perda de valor de bens da própria empresa.', 'usar termo contábil não relacionado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-1', 'D', 'Externalidade negativa.', true, 'É um custo real gerado pela atividade produtiva, mas suportado por terceiros que não participam da decisão nem do lucro.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-1', 'E', 'Custo de produção.', false, 'Custo de produção é o que a empresa efetivamente paga. Aqui, o custo foi transferido para fora da empresa.', 'confundir custo interno com externo');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-amb-2', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'intermediate', 'applied', false, 'Um estudo mapeia a localização de aterros, indústrias poluentes e áreas com maior exposição a enchentes em uma região metropolitana. Verifica-se forte coincidência com as áreas de menor renda.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-2', 'A', 'Desenvolvimento sustentável, que equilibra crescimento e preservação.', false, 'Esse conceito trata da relação entre gerações e dimensões do desenvolvimento, não da distribuição do dano entre grupos no presente.', 'usar conceito mais genérico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-2', 'B', 'Determinismo geográfico, segundo o qual o meio define as condições sociais.', false, 'A coincidência decorre de decisões de localização e do mercado de terras, não de determinação natural.', 'naturalizar padrão socialmente produzido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-2', 'C', 'Transição energética, que trata da mudança da matriz de energia.', false, 'Não há relação com matriz energética no caso descrito.', 'trocar de tema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-2', 'D', 'Capacidade de suporte, que define o limite populacional de um ecossistema.', false, 'Capacidade de suporte é conceito ecológico sobre limites, não sobre distribuição social de danos.', 'usar conceito ecológico em questão social');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-2', 'E', 'Justiça ambiental, que trata da distribuição desigual dos riscos e danos ambientais entre grupos sociais.', true, 'O conceito nomeia exatamente esse padrão: os custos ambientais recaem desproporcionalmente sobre populações de menor renda e grupos vulnerabilizados.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-amb-3', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'intermediate', 'interpretation', false, 'Leia o trecho de um parecer técnico fictício:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-3', 'A', 'O empreendimento deve ser aprovado sem restrições, pois gera empregos.', false, 'O parecer aponta risco concreto à principal fonte de renda de comunidades, o que exige tratamento e não omissão.', 'considerar apenas um lado da conta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-3', 'B', 'O empreendimento deve ser rejeitado, pois todo impacto ambiental é inaceitável.', false, 'A análise ambiental trabalha com mitigação, compensação e condicionantes; rejeição automática não decorre do parecer.', 'adotar posição absoluta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-3', 'C', 'A pesca das comunidades é atividade econômica irrelevante frente à arrecadação municipal.', false, 'É a principal fonte de renda local — hierarquizar assim ignora a distribuição do impacto.', 'desconsiderar quem sofre o custo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-3', 'D', 'O estudo técnico é desnecessário quando há geração de emprego.', false, 'O estudo é justamente o instrumento que revela a assimetria e permite decidir com informação.', 'dispensar instrumento de análise');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-3', 'E', 'Os benefícios se distribuem de forma ampla enquanto os custos se concentram em um grupo específico, o que exige medidas de compensação e mitigação.', true, 'Emprego e arrecadação beneficiam o município como um todo; o risco recai sobre três comunidades cuja renda depende do rio. Essa assimetria é o núcleo do problema e o que justifica condicionantes.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-amb-4', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'challenging', 'comparison', false, 'Duas propostas para reduzir resíduos plásticos em uma cidade:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-4', 'A', 'A segunda é ineficaz, pois interfere na liberdade do consumidor.', false, 'Regulação de oferta amplia opções em vez de restringi-las, e a responsabilidade pela destinação é instrumento consolidado de política ambiental.', 'confundir regulação com restrição de escolha');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-4', 'B', 'As duas propostas produzem exatamente o mesmo efeito.', false, 'Elas atuam em pontos diferentes da cadeia: comportamento individual e estrutura de oferta.', 'igualar intervenções de escalas distintas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-4', 'C', 'Nenhuma das duas trata do problema, que é exclusivamente global.', false, 'Resíduo sólido urbano tem gestão local e regional bem definidas.', 'deslocar tudo para a escala global');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-4', 'D', 'A segunda atua sobre a estrutura da oferta e a responsabilidade do produtor, tendendo a efeito mais amplo; a primeira é complementar e depende da existência de alternativas viáveis.', true, 'Campanha muda escolhas dentro das opções existentes. Regulação muda quais opções existem e onde recai o custo da destinação. As duas se somam, mas não são equivalentes em alcance.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-4', 'E', 'A primeira é suficiente, pois o consumo é a origem do problema.', false, 'Sem alternativa disponível, a orientação não se converte em prática — e a destinação segue sem responsável definido.', 'atribuir solução estrutural ao indivíduo');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-amb-5', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'challenging', 'integration', false, 'Um município aprova a expansão urbana sobre área de proteção de manancial, alegando déficit habitacional. A companhia de saneamento alerta para risco de contaminação do reservatório que abastece 300 mil pessoas.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-5', 'A', 'A área de manancial deve ser preservada mesmo que nenhuma alternativa habitacional seja oferecida.', false, 'Preservar sem oferecer alternativa tende a produzir ocupação irregular na mesma área, agravando o risco.', 'ignorar a demanda social que gera a pressão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-5', 'B', 'A decisão é exclusivamente técnica e não comporta participação social.', false, 'Decisões sobre uso do território afetam direitos e envolvem participação prevista nos instrumentos urbanísticos.', 'excluir a dimensão política do problema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-5', 'C', 'Há conflito entre dois direitos legítimos — moradia e segurança hídrica — que exige instrumentos de planejamento territorial capazes de atender à demanda habitacional fora da área sensível.', true, 'Os dois lados representam direitos reais de populações reais. A saída não é escolher um, e sim usar zoneamento e produção de habitação de interesse social para atender à moradia em área adequada.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-5', 'D', 'Trata-se de conflito entre desenvolvimento e meio ambiente, no qual o desenvolvimento deve prevalecer.', false, 'A oposição é falsa: 300 mil pessoas abastecidas também estão do lado social da equação.', 'opor meio ambiente a pessoas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-5', 'E', 'O déficit habitacional justifica qualquer ocupação, independentemente do risco de abastecimento.', false, 'Comprometer o abastecimento de 300 mil pessoas criaria um problema social maior que o resolvido.', 'considerar apenas um dos direitos');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-amb-rec-1', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'intro', 'concept', true, 'O princípio das "responsabilidades comuns porém diferenciadas" estabelece que:', 'Comum a todos, proporcional a cada um.', NULL, NULL, NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-rec-1', 'A', 'Apenas os países mais ricos têm qualquer responsabilidade ambiental.', false, 'A responsabilidade é comum a todos: o que varia é a proporção.', 'ler "diferenciadas" como "exclusivas"');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-rec-1', 'B', 'Todos os países devem adotar exatamente as mesmas metas.', false, 'Metas idênticas contrariam a parte "diferenciadas" do princípio.', 'ignorar a diferenciação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-rec-1', 'C', 'Países em desenvolvimento estão dispensados de qualquer compromisso.', false, 'Dispensa total contraria a parte "comuns" do princípio.', 'confundir proporcionalidade com isenção');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-rec-1', 'D', 'A responsabilidade recai exclusivamente sobre empresas, não sobre Estados.', false, 'O princípio organiza compromissos entre Estados em acordos internacionais.', 'trocar o sujeito do princípio');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-rec-1', 'E', 'Todos os países têm responsabilidade sobre problemas ambientais globais, em medidas proporcionais à sua contribuição histórica e capacidade de resposta.', true, 'O princípio reconhece a responsabilidade compartilhada e, ao mesmo tempo, a desigualdade de contribuição para o problema e de capacidade de agir.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-amb-rec-2', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'intermediate', 'applied', true, 'Uma cidade cria um programa de coleta seletiva doméstica e o apresenta como solução para o descarte irregular de resíduos industriais perigosos.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-rec-2', 'A', 'A responsabilidade pelo descarte industrial é dos moradores da cidade.', false, 'A responsabilidade pelo resíduo perigoso é do gerador.', 'transferir responsabilidade ao indivíduo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-rec-2', 'B', 'Resíduos industriais não causam impacto ambiental relevante.', false, 'Resíduos perigosos estão entre os de maior potencial de dano.', 'minimizar o problema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-rec-2', 'C', 'Programas municipais não podem tratar de resíduos.', false, 'Municípios têm competência sobre gestão de resíduos sólidos urbanos.', 'negar competência existente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-rec-2', 'D', 'A solução atua em uma escala e um tipo de resíduo diferentes do problema apontado, que exige fiscalização e responsabilização do gerador industrial.', true, 'Resíduo industrial perigoso tem cadeia, regulação e responsável distintos do resíduo doméstico. A coleta seletiva é útil, mas não endereça esse problema.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-rec-2', 'E', 'A coleta seletiva é uma política ineficaz em qualquer situação.', false, 'Ela é eficaz para resíduo domiciliar reciclável — o problema é o descompasso com o caso apresentado.', 'generalizar a crítica');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-amb-6', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'intro', 'concept', false, 'Uma indústria reduz seu custo ao lançar resíduos em um rio, enquanto comunidades a jusante pagam por água tratada e perdem pesca. A situação exemplifica:', 'Externalidade ocorre quando parte do custo de uma atividade não é assumida por quem a produz e recai sobre terceiros.', 'Externalidade ocorre quando parte do custo de uma atividade não é assumida por quem a produz e recai sobre terceiros.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-6', 'A', 'Recuperação natural imediata do rio.', false, 'O enunciado relata perda de qualidade e de pesca.', 'contradição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-6', 'B', 'Ausência de relação entre economia e ambiente.', false, 'A redução de custo depende diretamente da destinação dos resíduos.', 'separação artificial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-6', 'C', 'Conflito exclusivamente cultural.', false, 'Há dimensões econômicas, ambientais e territoriais concretas.', 'redução indevida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-6', 'D', 'Externalização de custos ambientais para outros grupos e territórios.', true, 'O custo evitado pela indústria reaparece como prejuízo coletivo a jusante.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-6', 'E', 'Distribuição igual dos benefícios da produção.', false, 'Os benefícios e prejuízos estão distribuídos de forma desigual.', 'ignorar assimetria');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-amb-7', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'intermediate', 'applied', false, 'Para reduzir enchentes em uma bacia urbana, qual conjunto de medidas atua tanto na causa quanto na adaptação?', 'Gestão de bacia combina prevenção estrutural, ordenamento do território, soluções baseadas na natureza e preparação para eventos extremos.', 'Gestão de bacia combina prevenção estrutural, ordenamento do território, soluções baseadas na natureza e preparação para eventos extremos.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-7', 'A', 'Canalizar todos os rios e ocupar várzeas.', false, 'A ocupação de várzeas aumenta exposição e a canalização pode transferir picos a jusante.', 'solução que desloca risco');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-7', 'B', 'Impermeabilizar praças para acelerar o escoamento.', false, 'Impermeabilização aumenta volume e velocidade da água superficial.', 'inverter processo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-7', 'C', 'Retirar alertas e concentrar recursos após o desastre.', false, 'Prevenção e aviso reduzem perdas antes do evento.', 'atuação apenas reativa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-7', 'D', 'Construir apenas uma obra, sem manutenção nem controle do solo.', false, 'Uma obra isolada não enfrenta ocupação, drenagem e manutenção da bacia.', 'solução única');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-7', 'E', 'Ampliar áreas permeáveis, proteger várzeas, manter drenagem e criar sistemas de alerta.', true, 'O conjunto reduz escoamento, preserva áreas de inundação e prepara a população.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-amb-8', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'intermediate', 'interpretation', false, 'Um mapa mostra depósitos de resíduos perigosos concentrados perto de bairros de baixa renda e longe das áreas que mais geram esses resíduos. O padrão sugere:', 'Justiça ambiental pergunta quem recebe benefícios e quem suporta danos. O mapa indica concentração do risco em grupos socialmente vulneráveis.', 'Justiça ambiental pergunta quem recebe benefícios e quem suporta danos. O mapa indica concentração do risco em grupos socialmente vulneráveis.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-8', 'A', 'Equilíbrio entre locais de produção e descarte.', false, 'O enunciado informa distância entre quem gera e quem recebe o risco.', 'contradição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-8', 'B', 'Distribuição aleatória comprovada.', false, 'A concentração espacial associada à renda contraria a ideia de aleatoriedade comprovada.', 'ignorar padrão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-8', 'C', 'Desigualdade ambiental na distribuição de riscos e capacidade de influência.', true, 'Grupos menos beneficiados pela geração recebem maior carga de risco.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-8', 'D', 'Ausência de conflito sobre uso do território.', false, 'A distribuição desigual é fonte potencial de conflito e injustiça.', 'negar dimensão política');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-8', 'E', 'Proteção prioritária dos bairros mais vulneráveis.', false, 'A proximidade dos depósitos indica maior exposição, não proteção.', 'inverter leitura');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-amb-9', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'challenging', 'comparison', false, 'Compare duas respostas à escassez de água: I. ampliar captação sem revisar perdas; II. reduzir vazamentos, proteger mananciais, reutilizar água e só então avaliar nova captação. A segunda é mais sustentável porque:', 'A gestão integrada evita tratar aumento de oferta como única resposta e reduz desperdício e degradação da fonte.', 'A gestão integrada evita tratar aumento de oferta como única resposta e reduz desperdício e degradação da fonte.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-9', 'A', 'Prioriza eficiência e conservação antes de criar nova pressão sobre a bacia.', true, 'A estratégia atua na demanda, na qualidade e na oferta com menor impacto.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-9', 'B', 'Proíbe qualquer uso econômico da água.', false, 'Não há proibição, e sim gestão integrada.', 'radicalização');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-9', 'C', 'Impede para sempre qualquer crise hídrica.', false, 'Nenhuma política elimina toda incerteza climática e social.', 'promessa absoluta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-9', 'D', 'Dispensa monitoramento de consumo.', false, 'Gestão eficiente depende de acompanhamento contínuo.', 'retirar instrumento necessário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-9', 'E', 'Aumenta perdas antes de ampliar a oferta.', false, 'A proposta reduz perdas e demanda antes de nova captação.', 'inverter sequência');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-amb-10', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'challenging', 'integration', false, 'Uma proposta de corredor ecológico atravessa propriedades rurais e prevê restauração de margens de rios, passagens de fauna e compensação aos produtores. O objetivo integrado é:', 'Conectividade ecológica depende do território usado por pessoas; compensação e planejamento tornam a conservação praticável e menos desigual.', 'Conectividade ecológica depende do território usado por pessoas; compensação e planejamento tornam a conservação praticável e menos desigual.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-10', 'A', 'Concentrar animais em uma única área isolada.', false, 'Corredores conectam habitats, não os isolam.', 'inverter conectividade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-10', 'B', 'Reconectar habitats e cursos d’água, negociando custos da conservação com quem usa o território.', true, 'A proposta combina função ecológica e instrumento social/econômico de implementação.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-10', 'C', 'Substituir rios por canais artificiais.', false, 'O projeto restaura margens e protege cursos existentes.', 'contradição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-10', 'D', 'Garantir que nenhuma espécie se desloque.', false, 'Passagens de fauna existem justamente para permitir deslocamento seguro.', 'inverter função');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-amb-10', 'E', 'Eliminar toda atividade rural da região.', false, 'A compensação e o desenho de passagens indicam convivência, não expulsão total.', 'falsa oposição');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-amb-1', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'intro', 'concept', false, 'A expressão "serviços ecossistêmicos" designa:', 'Serviços ecossistêmicos são funções da natureza das quais dependemos: clima regulado, água filtrada, solo fértil, polinização.', 'Serviços ecossistêmicos são funções da natureza das quais dependemos: clima regulado, água filtrada, solo fértil, polinização.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-1', 'A', 'a fiscalização ambiental exercida por órgãos do Estado.', false, 'Fiscalização é atividade administrativa, não função do ecossistema.', 'confundir com fiscalização');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-1', 'B', 'os benefícios que os ecossistemas prestam à sociedade, como regulação do clima, polinização e água limpa.', true, 'São funções ecológicas das quais a vida econômica e social depende, ainda que raramente tenham preço.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-1', 'C', 'a venda de créditos de carbono no mercado internacional.', false, 'Créditos são um instrumento econômico que tenta precificar parte desses serviços.', 'confundir instrumento com conceito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-1', 'D', 'as áreas protegidas por lei em cada bioma.', false, 'Áreas protegidas são um instrumento de conservação, não o benefício em si.', 'confundir instrumento com conceito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-1', 'E', 'os serviços de limpeza urbana prestados pelas prefeituras.', false, 'Coleta e varrição são serviços públicos, não processos ecológicos.', 'confundir com serviço público');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-amb-2', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'intermediate', 'applied', false, 'Uma hidrelétrica será construída em um rio, alagando terras de comunidades ribeirinhas. Do ponto de vista da análise de conflitos pelo uso do território, o ponto central a examinar é:', 'Conflito ambiental não é natureza contra desenvolvimento: é disputa entre grupos sobre quem usa o território, quem perde e quem decide.', 'Conflito ambiental não é natureza contra desenvolvimento: é disputa entre grupos sobre quem usa o território, quem perde e quem decide.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-2', 'A', 'quem arca com os custos e quem recebe os benefícios da obra, e como as comunidades participam da decisão.', true, 'Conflitos territoriais se analisam pela distribuição desigual de perdas e ganhos e pelo grau de participação dos afetados.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-2', 'B', 'o custo total do empreendimento em reais.', false, 'O custo financeiro é um dado, mas não descreve o conflito.', 'reduzir ao custo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-2', 'C', 'a distância entre a barragem e a capital do estado.', false, 'A distância não define o conflito.', 'critério irrelevante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-2', 'D', 'se existe alternativa tecnológica mais barata.', false, 'A comparação técnica é relevante, mas não substitui a análise da distribuição de impactos.', 'deslocar a questão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-2', 'E', 'se a energia gerada é renovável ou não.', false, 'A classificação da fonte não resolve a questão de quem ganha e quem perde com a obra.', 'deslocar a questão');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-amb-3', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'intermediate', 'interpretation', false, 'Uma campanha atribui a responsabilidade pela crise climática às escolhas individuais de consumo. Sobre esse enquadramento, a análise mais consistente é que:', 'Individualizar a responsabilidade climática desloca o foco das decisões que definem a maior parte das emissões e que se tomam em outro nível.', 'Individualizar a responsabilidade climática desloca o foco das decisões que definem a maior parte das emissões e que se tomam em outro nível.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-3', 'A', 'ele está errado, pois o consumo individual não tem impacto algum.', false, 'O consumo tem impacto; o problema é apresentá-lo como a causa principal.', 'negar o impacto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-3', 'B', 'ele é irrelevante, já que o clima varia naturalmente.', false, 'A variação natural não explica a alteração observada no período recente.', 'negacionismo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-3', 'C', 'ele desloca para o indivíduo uma responsabilidade que é majoritariamente de decisões produtivas e de políticas públicas.', true, 'Matriz energética, regulação e modelo de transporte pesam mais que a escolha de um consumidor isolado, e não estão ao alcance dele.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-3', 'D', 'ele é adequado porque políticas públicas não influenciam emissões.', false, 'Políticas públicas são justamente um dos principais determinantes das emissões.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-3', 'E', 'ele está correto, pois a soma das escolhas individuais forma o total das emissões.', false, 'A soma existe, mas a maior parte das emissões decorre de decisões de produção, energia e transporte fora do alcance individual.', 'somar sem hierarquizar');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-amb-4', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'intermediate', 'comparison', false, 'Comparando a preservação integral e o uso sustentável como modelos de proteção ambiental, é correto afirmar que:', 'Modelos de conservação são ferramentas, não doutrinas. O critério é o objetivo pretendido e a realidade da área, incluindo quem vive nela.', 'Modelos de conservação são ferramentas, não doutrinas. O critério é o objetivo pretendido e a realidade da área, incluindo quem vive nela.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-4', 'A', 'apenas o uso sustentável admite pesquisa científica.', false, 'A pesquisa é admitida também em unidades de proteção integral.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-4', 'B', 'cada modelo responde a objetivos diferentes, e a escolha depende do bioma, do estado de conservação e das populações que vivem na área.', true, 'Proteger processos ecológicos raros e conciliar conservação com modo de vida local são objetivos distintos que pedem instrumentos distintos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-4', 'C', 'a preservação integral é sempre superior, pois exclui a presença humana.', false, 'Não há superioridade automática: o modelo adequado depende do bioma, do estado de conservação e das populações envolvidas.', 'hierarquia automática');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-4', 'D', 'o uso sustentável é sempre superior, pois gera renda.', false, 'Gerar renda não garante conservação em qualquer contexto.', 'hierarquia automática');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-4', 'E', 'os dois modelos são idênticos na prática.', false, 'Eles definem regras distintas de acesso e uso do território.', 'igualar modelos');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-amb-5', 'meio-ambiente-e-sociedade', 'analisar-impactos-conflitos-e-uso-do-territorio', 'challenging', 'integration', false, 'Um município enfrenta enchentes recorrentes. O plano proposto prevê apenas alargar o canal do rio no trecho urbano. Considerando o funcionamento de uma bacia hidrográfica:', 'Bacia hidrográfica é a unidade de análise: o que acontece a montante chega a jusante. Intervir só onde a água transborda costuma deslocar o problema.', 'Bacia hidrográfica é a unidade de análise: o que acontece a montante chega a jusante. Intervir só onde a água transborda costuma deslocar o problema.', 'Em questões ambientais, verifique se a escala da solução proposta corresponde à escala do processo que gera o problema.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-5', 'A', 'a intervenção pode acelerar a água e transferir a enchente para jusante, pois a causa está no uso do solo em toda a bacia.', true, 'Impermeabilização e desmatamento a montante aumentam o volume e a velocidade; alargar só o trecho urbano empurra o problema rio abaixo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-5', 'B', 'a obra resolve o problema, pois aumenta a capacidade do canal.', false, 'Aumentar a capacidade local não reduz o volume que chega.', 'solução local para causa distribuída');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-5', 'C', 'a enchente é fenômeno natural e não admite intervenção.', false, 'A cheia é natural; a enchente urbana depende fortemente do uso do solo.', 'confundir cheia com enchente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-5', 'D', 'o problema seria resolvido apenas com limpeza de bueiros.', false, 'Limpeza ajuda, mas não responde ao volume gerado na bacia.', 'solução parcial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-amb-5', 'E', 'a solução exige mudar o curso do rio para fora da cidade.', false, 'Desviar o rio transfere o problema e cria outros, sem tratar a causa.', 'solução desproporcional');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rep-1', 'brasil-republica', 'analisar-processos-da-republica-brasileira', 'intro', 'concept', false, 'Durante a República Velha (1889-1930), a chamada "política dos governadores" consistia em:', 'A política dos governadores era o acordo que dava sustentação mútua entre presidente e oligarquias estaduais.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-1', 'A', 'Um programa de investimento federal em infraestrutura estadual.', false, 'O acordo era político-eleitoral, não um programa de obras.', 'trocar política por economia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-1', 'B', 'A criação de partidos nacionais que substituíram as oligarquias regionais.', false, 'Partidos de alcance nacional só se estruturam depois de 1945.', 'antecipar um processo posterior');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-1', 'C', 'Um sistema de eleições diretas para governador com participação popular ampla.', false, 'O eleitorado era restrito e o voto, aberto; não havia participação ampla.', 'projetar o presente sobre o passado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-1', 'D', 'Um acordo de apoio mútuo entre o governo federal e as oligarquias estaduais, que garantia estabilidade ao arranjo de poder.', true, 'O presidente apoiava os grupos dominantes nos estados e recebia deles apoio no Congresso, o que reduzia disputas e mantinha o sistema oligárquico.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-1', 'E', 'Uma política de descentralização administrativa que ampliou a autonomia dos municípios.', false, 'O efeito principal foi consolidar o poder das oligarquias estaduais, não a autonomia municipal.', 'confundir com descentralização');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rep-2', 'brasil-republica', 'analisar-processos-da-republica-brasileira', 'intermediate', 'applied', false, 'Um trabalhador urbano dos anos 1940 comenta: "Passei a ter carteira assinada e férias, mas o sindicato só funciona do jeito que o Ministério aprova."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-2', 'A', 'A ausência total de direitos trabalhistas no período.', false, 'O próprio relato menciona carteira assinada e férias.', 'contrariar o documento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-2', 'B', 'A plena autonomia sindical conquistada pelos trabalhadores.', false, 'O relato afirma o oposto sobre o funcionamento sindical.', 'contrariar o documento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-2', 'C', 'A substituição do Estado pelos sindicatos na regulação do trabalho.', false, 'O Estado assumiu papel central na regulação, não o contrário.', 'inverter a relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-2', 'D', 'A extensão de direitos trabalhistas acompanhada do controle estatal sobre a organização sindical.', true, 'A CLT ampliou direitos ao mesmo tempo em que os sindicatos foram atrelados ao Ministério do Trabalho: as duas coisas fazem parte do mesmo arranjo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-2', 'E', 'A recusa do Estado em intervir nas relações entre patrões e empregados.', false, 'A marca do período é justamente a forte intervenção estatal.', 'inverter a característica');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rep-3', 'brasil-republica', 'analisar-processos-da-republica-brasileira', 'intermediate', 'interpretation', false, 'Leia o trecho de um comunicado autoral, no espírito dos atos institucionais do regime iniciado em 1964:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-3', 'A', 'Trata-se de norma de rotina administrativa, sem impacto sobre direitos.', false, 'Suspensão de habeas corpus atinge diretamente a liberdade individual.', 'minimizar o alcance do documento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-3', 'B', 'Descreve um estado de sítio aprovado por plebiscito popular.', false, 'Não há menção a consulta popular, e os atos institucionais não passavam por ela.', 'inventar procedimento inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-3', 'C', 'Concentra poder no Executivo e retira garantias jurídicas, usando a linguagem da ordem pública para legitimar a exceção.', true, 'Suspender habeas corpus e permitir intervenção no Legislativo desmonta os freios ao Executivo. A expressão "interesse superior da ordem pública" cumpre a função de legitimar a medida.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-3', 'D', 'Amplia as garantias individuais em situações de crise institucional.', false, 'O texto faz o oposto: suspende garantias.', 'inverter o conteúdo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-3', 'E', 'Fortalece o Poder Legislativo diante do Executivo.', false, 'A autorização de intervenção enfraquece o Legislativo.', 'inverter a relação entre poderes');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rep-4', 'brasil-republica', 'analisar-processos-da-republica-brasileira', 'challenging', 'comparison', false, 'Compare duas afirmações sobre a Constituição de 1988:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-4', 'A', 'Nenhuma das duas.', false, 'I descreve corretamente as mudanças de 1988.', 'excesso de recusa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-4', 'B', 'I e II, desde que se considere o período posterior a 2000.', false, 'Nenhum recorte temporal torna II verdadeira.', 'relativizar um erro factual');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-4', 'C', 'I e II.', false, 'II não se sustenta: garantir direitos em lei não elimina desigualdade estrutural.', 'confundir norma com realidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-4', 'D', 'II, apenas.', false, 'II é justamente a afirmação incorreta.', 'inverter a avaliação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-4', 'E', 'I, apenas.', true, 'A Constituição de 1988 ampliou de fato direitos sociais e políticos. Já a desigualdade persistiu: reconhecer isso é parte da análise histórica.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rep-5', 'brasil-republica', 'analisar-processos-da-republica-brasileira', 'challenging', 'integration', false, 'Um professor pede que a turma investigue por que, mesmo após sucessivas mudanças de regime político, a concentração fundiária permaneceu alta no Brasil ao longo de todo o período republicano.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-5', 'A', 'Atribuir a permanência exclusivamente ao período da ditadura militar, quando a modernização agrícola se intensificou.', false, 'A concentração antecede 1964 e persiste depois de 1985; um período só não explica o processo.', 'reduzir a um recorte');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-5', 'B', 'Concluir que a concentração decorre de características geográficas do território brasileiro.', false, 'A distribuição da terra é resultado de decisões políticas e jurídicas, não de geografia.', 'naturalizar processo social');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-5', 'C', 'Analisar apenas os textos constitucionais, já que a lei define a estrutura agrária.', false, 'A distância entre norma e prática é justamente o que a investigação precisa explicar.', 'ficar só na norma');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-5', 'D', 'Considerar que a permanência é impossível de explicar, dada a variedade de regimes políticos no período.', false, 'A variedade de regimes com resultado semelhante é exatamente o que sugere causas estruturais.', 'desistir da explicação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-5', 'E', 'Relacionar a herança colonial da grande propriedade, o peso político dos proprietários rurais em diferentes regimes e a limitação das reformas efetivamente implementadas.', true, 'A permanência se explica pela combinação de herança estrutural, capacidade de influência política dos grandes proprietários em regimes distintos e reformas que ou não saíram do papel ou tiveram alcance restrito.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-rep-rec-1', 'brasil-republica', 'analisar-processos-da-republica-brasileira', 'intro', 'concept', true, 'O voto secreto e o direito de voto feminino foram estabelecidos no Brasil pelo Código Eleitoral de:', 'O Código Eleitoral de 1932 trouxe o voto secreto e o voto feminino, ainda antes do Estado Novo.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-rec-1', 'A', '1889, com a proclamação da República.', false, 'O voto permaneceu aberto e restrito após 1889.', 'associar mudança à proclamação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-rec-1', 'B', '1932, durante o governo provisório de Vargas.', true, 'O Código Eleitoral de 1932 instituiu o voto secreto e estendeu o direito de voto às mulheres.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-rec-1', 'C', '1946, com a redemocratização do pós-guerra.', false, 'A Constituição de 1946 consolidou avanços, mas o marco citado é anterior.', 'atrasar o marco');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-rec-1', 'D', '1964, com o início do regime militar.', false, 'O período restringiu, e não ampliou, direitos políticos.', 'inverter o sentido do período');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-rep-rec-1', 'E', '1988, com a nova Constituição.', false, '1988 ampliou o eleitorado, mas o voto secreto e o voto feminino são bem anteriores.', 'concentrar tudo em 1988');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-br-1', 'brasil-republica', 'analisar-processos-da-republica-brasileira', 'intro', 'concept', false, 'Na República Velha, o voto era aberto e o eleitorado, restrito. A expressão "voto de cabresto" designa a prática de:', 'O voto de cabresto depende de duas condições do período: ausência de voto secreto e relação de dependência econômica no campo.', 'O voto de cabresto depende de duas condições do período: ausência de voto secreto e relação de dependência econômica no campo.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-1', 'A', 'comprar votos exclusivamente com dinheiro em espécie.', false, 'A troca material existia, mas o traço definidor é a relação de dependência e a ausência de sigilo.', 'reduzir a compra de votos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-1', 'B', 'adulterar as atas depois da votação.', false, 'Essa prática existiu e era chamada de "eleição a bico de pena", que é fenômeno distinto.', 'trocar por outra prática');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-1', 'C', 'proibir a candidatura de opositores nas eleições estaduais.', false, 'A exclusão de opositores se dava por outros mecanismos, como a degola.', 'trocar por outra prática');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-1', 'D', 'impedir legalmente que trabalhadores rurais se alistassem.', false, 'A restrição legal existia por outros critérios; o cabresto opera sobre quem já podia votar.', 'confundir restrição legal com coerção');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-1', 'E', 'controlar o voto do eleitor dependente por pressão econômica e vigilância, já que o voto era aberto.', true, 'Sem sigilo, o coronel podia verificar em quem seu dependente havia votado, e a dependência fazia o resto.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-br-2', 'brasil-republica', 'analisar-processos-da-republica-brasileira', 'intermediate', 'applied', false, 'A Consolidação das Leis do Trabalho, de 1943, reuniu direitos trabalhistas e ao mesmo tempo submeteu os sindicatos ao controle do Estado. Essa combinação é característica de um governo que:', 'A legislação social do período não é só conquista nem só controle: ela reconhece direitos ao mesmo tempo em que enquadra a organização operária.', 'A legislação social do período não é só conquista nem só controle: ela reconhece direitos ao mesmo tempo em que enquadra a organização operária.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-2', 'A', 'ampliou a liberdade de organização sindical.', false, 'A estrutura sindical passou a depender de reconhecimento estatal e de imposto obrigatório.', 'inverter o traço');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-2', 'B', 'transferiu aos empregadores a definição dos direitos.', false, 'Os direitos foram definidos em lei, e não deixados à negociação privada.', 'inverter o traço');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-2', 'C', 'atendeu demandas históricas dos trabalhadores e, ao mesmo tempo, retirou dos sindicatos a autonomia para pressionar.', true, 'Direitos garantidos por lei e sindicatos tutelados pelo Estado são as duas faces do mesmo arranjo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-2', 'D', 'aboliu a legislação trabalhista anterior sem substituí-la.', false, 'A consolidação organizou e ampliou a legislação existente.', 'afirmação factualmente incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-2', 'E', 'abriu mão de intervir na economia, deixando a regulação ao mercado.', false, 'O período foi de forte intervenção estatal na economia e nas relações de trabalho.', 'inverter o traço');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-br-3', 'brasil-republica', 'analisar-processos-da-republica-brasileira', 'intermediate', 'interpretation', false, 'Um livro didático afirma que a Proclamação da República foi "um movimento popular que derrubou a monarquia". Confrontada com o que se sabe do episódio, essa formulação:', 'Narrativas de fundação tendem a atribuir ao povo o que foi feito por grupos restritos. Avaliar a formulação exige confrontá-la com a participação efetiva.', 'Narrativas de fundação tendem a atribuir ao povo o que foi feito por grupos restritos. Avaliar a formulação exige confrontá-la com a participação efetiva.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-3', 'A', 'é imprecisa: tratou-se de um golpe militar com apoio de setores civis, sem participação popular ampla.', true, 'A mudança de regime foi conduzida por militares e por elites descontentes, com a população em grande medida à margem.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-3', 'B', 'está correta, pois houve grandes manifestações de rua pedindo a República.', false, 'Não houve mobilização popular ampla no episódio.', 'afirmação factualmente incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-3', 'C', 'está correta, pois o povo elegeu o primeiro presidente logo em seguida.', false, 'O primeiro governo republicano foi provisório, e não eleito por voto popular.', 'afirmação factualmente incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-3', 'D', 'é imprecisa porque a monarquia não foi de fato derrubada.', false, 'A monarquia foi de fato encerrada e a família imperial exilada.', 'negar o fato');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-3', 'E', 'não pode ser avaliada, pois o episódio é objeto de disputa entre historiadores.', false, 'Há debate sobre causas e alcance, mas o caráter não popular do ato é ponto assentado.', 'recusa sem critério');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-br-4', 'brasil-republica', 'analisar-processos-da-republica-brasileira', 'challenging', 'comparison', false, 'Comparando o Estado Novo (1937-1945) e o regime militar (1964-1985) quanto ao controle da informação, é correto afirmar que:', 'Regimes autoritários costumam operar nas duas pontas: bloqueiam o que contradiz e produzem a narrativa que os legitima. Comparar exige ver semelhança de mecanismo e diferença de contexto.', 'Regimes autoritários costumam operar nas duas pontas: bloqueiam o que contradiz e produzem a narrativa que os legitima. Comparar exige ver semelhança de mecanismo e diferença de contexto.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-4', 'A', 'nenhum dos dois interferiu na produção cultural.', false, 'Houve interferência sistemática em música, teatro, cinema e imprensa.', 'afirmação factualmente incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-4', 'B', 'apenas o Estado Novo praticou censura à imprensa.', false, 'Os dois regimes censuraram, com instrumentos e intensidades diferentes ao longo do tempo.', 'atribuir a um só');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-4', 'C', 'apenas o regime militar manteve órgão oficial de propaganda.', false, 'O Estado Novo teve o Departamento de Imprensa e Propaganda, com papel central.', 'atribuir a um só');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-4', 'D', 'ambos combinaram censura com produção de propaganda oficial, embora com estruturas e contextos distintos.', true, 'Silenciar a crítica e produzir a própria versão são movimentos complementares nos dois casos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-4', 'E', 'ambos permitiram imprensa livre, censurando apenas o rádio e a televisão.', false, 'A imprensa escrita foi alvo direto de censura nos dois períodos.', 'afirmação factualmente incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-br-5', 'brasil-republica', 'analisar-processos-da-republica-brasileira', 'challenging', 'integration', false, 'A Constituição de 1988 ficou conhecida como "Constituição Cidadã" por ampliar direitos sociais e mecanismos de participação. Avaliar hoje o alcance desse texto exige considerar que:', 'Analisar uma constituição exige separar o que ela promete do que se realiza. A diferença entre os dois planos é onde a política acontece.', 'Analisar uma constituição exige separar o que ela promete do que se realiza. A diferença entre os dois planos é onde a política acontece.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-5', 'A', 'há distância entre o direito escrito e o acesso real, e essa distância é objeto permanente de disputa política e judicial.', true, 'Reconhecer o avanço formal e medir o acesso efetivo são duas operações distintas, e a segunda é a que revela desigualdades.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-5', 'B', 'a previsão constitucional de um direito garante sua efetivação imediata.', false, 'A efetivação depende de orçamento, política pública e disputa institucional.', 'confundir previsão com efetivação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-5', 'C', 'direitos sociais não constam do texto, que trata apenas de direitos individuais.', false, 'Saúde, educação, trabalho e previdência estão expressamente previstos.', 'afirmação factualmente incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-5', 'D', 'a Constituição não previu instrumentos de participação além do voto.', false, 'Ela prevê plebiscito, referendo, iniciativa popular e conselhos com participação social.', 'afirmação factualmente incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-br-5', 'E', 'o texto de 1988 permanece inalterado desde a promulgação.', false, 'Ele já recebeu dezenas de emendas.', 'afirmação factualmente incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ind-1', 'industrializacao', 'relacionar-industrializacao-trabalho-e-territorio', 'intro', 'concept', false, 'A introdução da linha de montagem na produção industrial do início do século XX teve como efeito direto:', 'Produtividade alta e fragmentação do trabalho são as duas faces da mesma reorganização produtiva.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-1', 'A', 'O aumento expressivo da produtividade acompanhado da fragmentação das tarefas.', true, 'Dividir a produção em tarefas simples e repetitivas multiplicou a produtividade e, ao mesmo tempo, reduziu o controle do trabalhador sobre o conjunto do processo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-1', 'B', 'A eliminação da necessidade de trabalhadores nas fábricas.', false, 'A produção em massa exigiu grande contingente de trabalhadores.', 'antecipar automação total');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-1', 'C', 'A descentralização da produção em pequenas oficinas familiares.', false, 'O movimento foi de concentração em grandes plantas industriais.', 'inverter o movimento produtivo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-1', 'D', 'A valorização do trabalho artesanal e do domínio de todo o processo produtivo.', false, 'A linha de montagem fragmenta a produção e reduz o domínio do processo completo.', 'inverter o efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-1', 'E', 'A redução imediata das jornadas de trabalho nas fábricas.', false, 'A redução de jornada resultou de conflito e legislação, não da tecnologia em si.', 'atribuir à técnica o que veio da luta social');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ind-2', 'industrializacao', 'relacionar-industrializacao-trabalho-e-territorio', 'intermediate', 'applied', false, 'Uma cidade do interior recebe uma grande fábrica. Em cinco anos, sua população dobra, os aluguéis sobem, formam-se bairros sem saneamento na periferia e o comércio local se expande.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-2', 'A', 'Um caso de êxodo urbano em direção ao campo.', false, 'O movimento descrito é de chegada à cidade.', 'inverter o sentido da migração');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-2', 'B', 'A ausência de relação entre atividade econômica e ocupação do espaço urbano.', false, 'A descrição mostra justamente essa relação.', 'negar a relação evidente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-2', 'C', 'A relação entre industrialização e urbanização acelerada, em que a chegada de empregos atrai população em ritmo superior à ampliação da infraestrutura urbana.', true, 'A fábrica atrai migrantes; a cidade cresce mais rápido do que a capacidade de oferecer moradia, saneamento e transporte. Daí a combinação de expansão econômica e precariedade urbana.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-2', 'D', 'Um processo de desindustrialização regional.', false, 'O caso descreve a chegada de indústria, não sua saída.', 'inverter o processo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-2', 'E', 'O efeito exclusivamente positivo da industrialização sobre a qualidade de vida local.', false, 'Bairros sem saneamento e alta de aluguéis são custos concretos que a descrição inclui.', 'ignorar os custos');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ind-3', 'industrializacao', 'relacionar-industrializacao-trabalho-e-territorio', 'intermediate', 'interpretation', false, 'A tabela mostra a participação da indústria de transformação no PIB de um país hipotético:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-3', 'A', 'O setor de serviços necessariamente encolheu no mesmo período.', false, 'A queda da participação industrial sugere o contrário quanto aos demais setores.', 'inverter a leitura');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-3', 'B', 'Houve queda contínua da participação relativa da indústria na economia, o que caracteriza um processo de desindustrialização relativa.', true, 'A série mostra redução constante do peso da indústria no PIB. Isso caracteriza desindustrialização relativa, sem afirmar nada sobre o volume absoluto produzido.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-3', 'C', 'Os dados são inconclusivos, pois participações percentuais não permitem análise.', false, 'Séries de participação são amplamente usadas para analisar mudança estrutural.', 'descartar dado válido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-3', 'D', 'A produção industrial do país foi reduzida a um terço no período.', false, 'A tabela mostra participação relativa no PIB; a produção absoluta pode ter crescido enquanto outros setores cresciam mais.', 'confundir participação com volume');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-3', 'E', 'O país deixou de produzir bens industriais.', false, '11% do PIB ainda representa atividade industrial significativa.', 'exagerar a conclusão');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ind-4', 'industrializacao', 'relacionar-industrializacao-trabalho-e-territorio', 'challenging', 'comparison', false, 'Compare dois modelos de organização do trabalho:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-4', 'A', 'A ausência de vínculo no segundo modelo aumenta necessariamente a renda do trabalhador.', false, 'A remuneração por tarefa produz renda variável, sem garantia de ganho maior.', 'supor efeito não demonstrado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-4', 'B', 'O controle sobre o trabalho permaneceu, mudando de forma: da supervisão presencial e da esteira para a mediação algorítmica, com perda de proteções vinculadas ao emprego formal.', true, 'O que muda é o mecanismo de controle e o tipo de vínculo — não a existência de controle. A perda de proteções ligadas ao contrato formal é o efeito social mais relevante.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-4', 'C', 'O segundo modelo eliminou o controle sobre o trabalhador, que passou a definir livremente seu ritmo.', false, 'A flexibilidade de horário convive com metas, avaliações e distribuição de tarefas definidas por sistema.', 'confundir flexibilidade com ausência de controle');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-4', 'D', 'Os dois modelos são equivalentes do ponto de vista da proteção social.', false, 'A diferença de vínculo produz diferenças significativas de proteção.', 'ignorar a diferença de vínculo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-4', 'E', 'O primeiro modelo é mais recente que o segundo.', false, 'A ordem histórica é a inversa.', 'inverter a cronologia');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ind-5', 'industrializacao', 'relacionar-industrializacao-trabalho-e-territorio', 'challenging', 'integration', false, 'Um município discute atrair uma indústria de grande porte oferecendo isenção fiscal por 15 anos. A empresa promete 800 empregos diretos.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-5', 'A', 'Somente os impactos ambientais, pois são os únicos irreversíveis.', false, 'Impactos fiscais e sociais também produzem efeitos duradouros sobre o município.', 'considerar uma dimensão só');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-5', 'B', 'Que isenções fiscais nunca se justificam, por reduzirem a arrecadação municipal.', false, 'Isenções podem se justificar em certos arranjos; a análise é que precisa ser feita caso a caso.', 'transformar análise em regra fixa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-5', 'C', 'Que a decisão cabe exclusivamente à empresa, por ser ela quem investe.', false, 'A decisão sobre renúncia fiscal e uso do território é do poder público.', 'transferir a decisão pública ao investidor');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-5', 'D', 'Apenas o número de empregos prometidos, já que emprego é o principal indicador de desenvolvimento.', false, 'Emprego é indicador central, mas não é o único custo-benefício em jogo.', 'reduzir a decisão a um indicador');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-5', 'E', 'O saldo entre a renúncia fiscal e a arrecadação futura, a pressão sobre infraestrutura e serviços públicos, os impactos ambientais e a dependência econômica de uma única empresa.', true, 'A decisão envolve custo fiscal presente contra retorno futuro incerto, demanda adicional por moradia, transporte, saúde e educação, licenciamento ambiental e o risco de a economia local ficar dependente de um só empregador.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ind-rec-1', 'industrializacao', 'relacionar-industrializacao-trabalho-e-territorio', 'intro', 'concept', true, 'Durante o governo de Juscelino Kubitschek (1956-1961), o Plano de Metas teve como um de seus eixos centrais:', 'O Plano de Metas apostou em indústria de bens duráveis, energia e transportes, com forte presença de capital estrangeiro.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-rec-1', 'A', 'A priorização exclusiva da agricultura de exportação.', false, 'O foco foi a indústria e a infraestrutura.', 'trocar o setor');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-rec-1', 'B', 'A implantação da indústria automobilística com atração de capital estrangeiro.', true, 'O Plano de Metas atraiu montadoras estrangeiras e investiu em energia e transportes, com o lema de "cinquenta anos em cinco".', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-rec-1', 'C', 'O fechamento da economia ao capital externo.', false, 'O plano dependeu justamente da entrada de capital externo.', 'inverter a política');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-rec-1', 'D', 'A criação da Petrobras e da Companhia Siderúrgica Nacional.', false, 'Essas empresas são do período Vargas, anterior ao Plano de Metas.', 'trocar o período');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ind-rec-1', 'E', 'A estatização completa da indústria brasileira.', false, 'O plano combinou capital estatal, privado nacional e estrangeiro.', 'exagerar o papel estatal');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ind-1', 'industrializacao', 'relacionar-industrializacao-trabalho-e-territorio', 'intro', 'concept', false, 'A expressão "divisão internacional do trabalho" designa, na análise da industrialização, a:', 'A divisão internacional do trabalho descreve quem faz o quê no sistema produtivo mundial, e não a organização interna de uma fábrica.', 'A divisão internacional do trabalho descreve quem faz o quê no sistema produtivo mundial, e não a organização interna de uma fábrica.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-1', 'A', 'distribuição de turnos entre fábricas de um mesmo grupo.', false, 'Organização de turnos é gestão interna, não divisão internacional.', 'escala trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-1', 'B', 'jornada máxima de trabalho acordada entre países.', false, 'Acordos de jornada são regulação trabalhista, não divisão produtiva.', 'conceito trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-1', 'C', 'especialização de diferentes países ou regiões em etapas distintas da produção mundial.', true, 'Alguns territórios concentram matéria-prima, outros manufatura e outros pesquisa e serviços de alto valor.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-1', 'D', 'migração de trabalhadores entre países em busca de emprego industrial.', false, 'A migração é consequência possível, não a definição do conceito.', 'confundir efeito com conceito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-1', 'E', 'separação entre operários especializados e não especializados na linha de montagem.', false, 'Essa é a divisão técnica do trabalho, interna à unidade produtiva.', 'confundir com divisão técnica');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ind-2', 'industrializacao', 'relacionar-industrializacao-trabalho-e-territorio', 'intermediate', 'applied', false, 'Uma montadora anuncia a instalação de fábrica em um município do interior, atraída por isenção fiscal e terreno cedido. Um efeito habitualmente observado em casos assim é:', 'Guerra fiscal e atração industrial trazem emprego e renda, mas também demanda por moradia, transporte, saúde e escola que o município nem sempre consegue absorver.', 'Guerra fiscal e atração industrial trazem emprego e renda, mas também demanda por moradia, transporte, saúde e escola que o município nem sempre consegue absorver.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-2', 'A', 'fim da atividade agrícola na região.', false, 'A atividade agrícola pode se manter ou se transformar, mas não desaparece por esse motivo.', 'consequência exagerada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-2', 'B', 'redução imediata do custo de vida no município.', false, 'A chegada de renda e de população costuma pressionar preços, sobretudo de aluguel.', 'prever efeito inverso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-2', 'C', 'queda da arrecadação estadual pela isenção concedida a todos os setores.', false, 'A isenção é dirigida à empresa atraída, e não a todos os setores.', 'generalização indevida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-2', 'D', 'crescimento populacional e pressão sobre moradia e serviços públicos locais.', true, 'A oferta de emprego atrai trabalhadores, e a infraestrutura do município costuma demorar a acompanhar.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-2', 'E', 'isolamento do município em relação às rodovias existentes.', false, 'A escolha do local costuma privilegiar acesso logístico, e não isolamento.', 'inverter o critério locacional');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ind-3', 'industrializacao', 'relacionar-industrializacao-trabalho-e-territorio', 'intermediate', 'interpretation', false, 'Uma reportagem descreve um galpão em que trabalhadores cumprem metas cronometradas por aplicativo, com trajetos definidos por algoritmo. Em relação à organização fabril do século XX, esse arranjo indica:', 'O controle algorítmico não inaugura a disciplina do tempo: ele aprofunda um princípio antigo com instrumentos novos, individualizando a medição.', 'O controle algorítmico não inaugura a disciplina do tempo: ele aprofunda um princípio antigo com instrumentos novos, individualizando a medição.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-3', 'A', 'continuidade do controle do tempo e do movimento, agora exercido por meios digitais e em tempo real.', true, 'A cronometragem e a padronização de gestos vêm do taylorismo; o algoritmo torna o monitoramento contínuo e individualizado.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-3', 'B', 'retorno ao trabalho artesanal, pela autonomia do trabalhador.', false, 'Não há autonomia sobre método nem sobre ritmo nesse arranjo.', 'inverter a leitura');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-3', 'C', 'fim da divisão de tarefas, já que o aplicativo faz tudo.', false, 'O aplicativo coordena; as tarefas continuam divididas entre pessoas.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-3', 'D', 'ausência de relação com a organização industrial, por se tratar de logística.', false, 'Logística de armazém aplica princípios de organização industrial ao fluxo de mercadorias.', 'separar indevidamente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-3', 'E', 'ruptura completa, pois o controle do tempo deixou de existir.', false, 'O controle do tempo se intensificou; o que mudou foi o instrumento.', 'negar a continuidade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ind-4', 'industrializacao', 'relacionar-industrializacao-trabalho-e-territorio', 'intermediate', 'comparison', false, 'Comparando o fordismo e a produção flexível (toyotismo), uma diferença central quanto ao estoque e à demanda é que:', 'A diferença não está apenas na máquina, e sim na relação com a demanda: produzir antes e estocar, ou produzir conforme o pedido chega.', 'A diferença não está apenas na máquina, e sim na relação com a demanda: produzir antes e estocar, ou produzir conforme o pedido chega.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-4', 'A', 'os dois trabalham com grandes estoques, mudando só a velocidade.', false, 'A produção flexível procura reduzir estoques ao mínimo.', 'igualar os modelos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-4', 'B', 'o toyotismo elimina a padronização de peças.', false, 'A padronização permanece; o que muda é o volume e o momento da produção.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-4', 'C', 'o fordismo depende de trabalho terceirizado e o toyotismo, de emprego estável.', false, 'A terceirização se expande justamente com a produção flexível.', 'inverter o traço');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-4', 'D', 'o fordismo produz em grande escala para estoque, enquanto a produção flexível ajusta o volume à demanda, reduzindo estoques.', true, 'Produzir para estoque e produzir sob demanda organizam de modo distinto fornecedores, fábrica e emprego.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-4', 'E', 'o fordismo não usava linha de montagem e o toyotismo, sim.', false, 'A linha de montagem é justamente uma marca do fordismo.', 'inverter o traço');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ind-5', 'industrializacao', 'relacionar-industrializacao-trabalho-e-territorio', 'challenging', 'integration', false, 'Um país exporta minério bruto e importa equipamentos fabricados com esse mesmo minério. Analisando essa situação do ponto de vista do desenvolvimento industrial, conclui-se que:', 'Posição na cadeia produtiva define quanto de valor e de emprego qualificado fica no território. Exportar bruto e importar manufaturado deixa a parte mais rentável fora.', 'Posição na cadeia produtiva define quanto de valor e de emprego qualificado fica no território. Exportar bruto e importar manufaturado deixa a parte mais rentável fora.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-5', 'A', 'o saldo comercial positivo garante desenvolvimento industrial.', false, 'Saldo positivo pode conviver com baixa industrialização.', 'reduzir ao saldo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-5', 'B', 'o país deve interromper a exportação de minério para se industrializar.', false, 'A interrupção não cria por si a capacidade industrial ausente.', 'solução simplista');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-5', 'C', 'a análise não se aplica, pois preços de commodities variam muito.', false, 'A variação de preços é um fator adicional, e não um impedimento à análise.', 'recusa sem critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-5', 'D', 'o país capta pouco do valor gerado na cadeia, pois as etapas de maior agregação ocorrem fora do seu território.', true, 'Transformação e engenharia concentram valor e emprego qualificado; exportar bruto deixa essa parte com terceiros.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ind-5', 'E', 'a situação é vantajosa, pois exportar matéria-prima exige menos investimento.', false, 'Exigir menos investimento não equivale a captar mais valor.', 'confundir custo com ganho');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cart-1', 'cartografia', 'ler-e-interpretar-representacoes-cartograficas', 'intro', 'concept', false, 'Um mapa está na escala 1:25.000. Uma estrada representada por um segmento de 8 cm tem, na realidade, a extensão de:', 'Do mapa para a realidade, multiplica-se pelo denominador da escala; depois converte-se a unidade.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-1', 'A', '20 km', false, 'Erra a conversão de cm para km por um fator de dez.', 'errar a potência de dez');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-1', 'B', '25 km', false, 'Usa o denominador da escala como resultado.', 'confundir escala com distância');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-1', 'C', '800 m', false, 'Não corresponde a nenhuma etapa correta do cálculo.', 'estimar sem calcular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-1', 'D', '200 m', false, 'Corresponde a dividir em vez de multiplicar pela escala.', 'inverter a operação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-1', 'E', '2 km', true, '8 × 25.000 = 200.000 cm. Como 100.000 cm equivalem a 1 km, o resultado é 2 km.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cart-2', 'cartografia', 'ler-e-interpretar-representacoes-cartograficas', 'intermediate', 'applied', false, 'Uma prefeitura precisa de um mapa para planejar a rede de esgoto de um bairro, indicando ruas, lotes e desníveis do terreno.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-2', 'A', '1:500.000, por ser a escala mais usada em mapas oficiais.', false, 'Escala usual não é escala adequada: essa não mostra lotes.', 'apelar ao costume');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-2', 'B', '1:100.000, por equilibrar detalhe e abrangência regional.', false, 'Ainda é pequena demais para representar lotes e desníveis.', 'errar a ordem de grandeza');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-2', 'C', 'A escala é irrelevante, desde que a legenda esteja completa.', false, 'Legenda não substitui a resolução espacial que a escala define.', 'ignorar o papel da escala');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-2', 'D', '1:2.000, por ser uma escala grande, que representa área pequena com muito detalhe.', true, 'Planejar lotes e desníveis exige detalhe, o que só uma escala grande oferece.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-2', 'E', '1:1.000.000, por permitir enxergar toda a região de uma vez.', false, 'Nessa escala, um bairro inteiro caberia em poucos milímetros.', 'confundir abrangência com utilidade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cart-3', 'cartografia', 'ler-e-interpretar-representacoes-cartograficas', 'intermediate', 'interpretation', false, 'Dois mapas do mundo usam projeções diferentes. No primeiro, a Groenlândia aparece com tamanho semelhante ao da África. No segundo, a África aparece cerca de catorze vezes maior que a Groenlândia.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-3', 'A', 'As duas representações são igualmente precisas em todos os aspectos.', false, 'Cada uma preserva uma propriedade diferente e sacrifica outra.', 'ignorar as limitações de cada projeção');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-3', 'B', 'A diferença decorre apenas da escala usada em cada mapa.', false, 'A diferença é de projeção, não de escala.', 'trocar os conceitos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-3', 'C', 'As duas são válidas: a primeira preserva ângulos e distorce áreas; a segunda preserva áreas e distorce formas.', true, 'Nenhuma projeção plana preserva todas as propriedades de uma superfície esférica. A escolha depende do uso — navegação pede ângulos; comparação de territórios pede áreas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-3', 'D', 'O primeiro mapa está errado e deve ser descartado.', false, 'Ele não está errado: preserva ângulos e distorce áreas, o que é adequado para navegação.', 'confundir escolha de projeção com erro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-3', 'E', 'O segundo mapa está errado, pois exagera o tamanho da África.', false, 'A proporção de catorze vezes corresponde à realidade das áreas.', 'inverter a avaliação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cart-4', 'cartografia', 'ler-e-interpretar-representacoes-cartograficas', 'challenging', 'comparison', false, 'Compare dois mapas temáticos do mesmo país, feitos com os mesmos dados de acesso à internet por município:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-4', 'A', 'Apenas mapas com escala definida podem usar cores temáticas.', false, 'Escala e simbologia temática são elementos independentes.', 'misturar conceitos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-4', 'B', 'O mapa II falsifica os dados ao reduzir a informação a duas cores.', false, 'Reduzir faixas simplifica a leitura, mas não altera os dados: não há falsificação.', 'confundir simplificação com fraude');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-4', 'C', 'O mapa I é sempre superior, pois usa mais cores.', false, 'Mais faixas nem sempre comunicam melhor; depende da pergunta que o mapa responde.', 'hierarquizar por quantidade de cores');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-4', 'D', 'Os dois mapas produzem exatamente a mesma impressão visual.', false, 'A escolha das faixas altera bastante o contraste percebido.', 'ignorar o efeito da legenda');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-4', 'E', 'Os dois são legítimos, mas produzem leituras diferentes: I mostra gradação e II enfatiza a divisão entre acima e abaixo da média.', true, 'Os dados são idênticos; o recorte da legenda decide se o leitor vê um gradiente contínuo ou uma clivagem entre dois blocos. Por isso a legenda precisa ser lida antes das cores.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cart-5', 'cartografia', 'ler-e-interpretar-representacoes-cartograficas', 'challenging', 'integration', false, 'Uma organização publica um cartograma em que o tamanho de cada país é proporcional às suas emissões históricas de gases de efeito estufa, e não à sua área territorial.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-5', 'A', 'O cartograma substitui a necessidade de dados numéricos sobre emissões.', false, 'A representação visual complementa os dados, não os dispensa.', 'supor substituição entre visual e numérico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-5', 'B', 'Trata-se de um erro cartográfico, pois mapas devem sempre respeitar as proporções territoriais.', false, 'Cartogramas são uma técnica reconhecida, cuja finalidade é justamente representar um dado no lugar da área.', 'confundir técnica com erro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-5', 'C', 'A escolha é neutra do ponto de vista político, pois apenas apresenta dados.', false, 'Toda escolha de representação destaca uma dimensão e apaga outras — inclusive esta.', 'supor neutralidade da representação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-5', 'D', 'A representação é tecnicamente válida e carrega um argumento: ao deformar o território segundo as emissões, torna visível a desproporção entre responsabilidade histórica e tamanho dos países.', true, 'O cartograma é uma técnica legítima. Ao substituir área por dado, ele evidencia que países pequenos podem ter emissões históricas enormes — o que sustenta o debate sobre responsabilidades diferenciadas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-5', 'E', 'A representação é inválida porque dificulta a localização geográfica dos países.', false, 'A perda de precisão locacional é um custo assumido pela técnica, não um defeito que a invalide.', 'exigir de uma técnica o que ela não propõe');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cart-rec-1', 'cartografia', 'ler-e-interpretar-representacoes-cartograficas', 'intro', 'concept', true, 'Em relação à escala cartográfica, é correto afirmar que:', 'Escala grande = denominador pequeno = pouca área com muito detalhe.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-rec-1', 'A', 'Escala 1:1.000.000 é maior que escala 1:1.000.', false, 'Como fração, 1/1.000 é maior que 1/1.000.000.', 'comparar denominadores como se fossem o valor');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-rec-1', 'B', 'Todo mapa deve usar a mesma escala, independentemente da finalidade.', false, 'A escala é escolhida conforme o objetivo do mapa.', 'ignorar a finalidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-rec-1', 'C', 'Escalas pequenas representam áreas pequenas com muitos detalhes.', false, 'A relação está invertida.', 'inverter a definição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-rec-1', 'D', 'Escalas grandes representam áreas pequenas com muitos detalhes.', true, 'Escala grande significa denominador pequeno (1:1.000), o que permite representar pouca área com muito detalhe.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cart-rec-1', 'E', 'A escala não influencia a quantidade de detalhes de um mapa.', false, 'A escala define diretamente o nível de detalhe possível.', 'negar a relação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cart-1', 'cartografia', 'ler-e-interpretar-representacoes-cartograficas', 'intro', 'concept', false, 'Toda projeção cartográfica distorce alguma propriedade da superfície terrestre. Essa limitação decorre de:', 'Nenhum mapa é fiel em tudo. Cada projeção escolhe o que preservar, e essa escolha depende do uso pretendido.', 'Nenhum mapa é fiel em tudo. Cada projeção escolhe o que preservar, e essa escolha depende do uso pretendido.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-1', 'A', 'variação do campo magnético terrestre.', false, 'O magnetismo afeta a bússola, não a geometria da projeção.', 'causa trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-1', 'B', 'falta de precisão dos instrumentos de medição.', false, 'Mesmo com medição perfeita a distorção permanece.', 'atribuir a instrumento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-1', 'C', 'erros acumulados na impressão dos mapas.', false, 'A distorção é anterior à impressão, e existe também em mapas digitais.', 'atribuir a impressão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-1', 'D', 'escolhas ideológicas dos cartógrafos.', false, 'Escolhas existem, mas a impossibilidade é geométrica antes de ser política.', 'confundir escolha com causa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-1', 'E', 'ser impossível representar uma superfície curva em um plano sem deformar ângulos, áreas ou distâncias.', true, 'A esfera não é planificável sem deformação, e cada projeção decide qual propriedade preservar.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cart-2', 'cartografia', 'ler-e-interpretar-representacoes-cartograficas', 'intermediate', 'applied', false, 'Um mapa temático precisa mostrar a taxa de mortalidade infantil por estado brasileiro. A forma de representação mais adequada é:', 'A forma segue o dado: valores relativos por unidade territorial pedem coropletas; totais absolutos pedem símbolos proporcionais.', 'A forma segue o dado: valores relativos por unidade territorial pedem coropletas; totais absolutos pedem símbolos proporcionais.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-2', 'A', 'curvas de nível ligando pontos de mesma taxa.', false, 'Isóbatas e curvas de nível servem a fenômenos contínuos, não a dados por unidade administrativa.', 'representação incompatível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-2', 'B', 'pontos distribuídos aleatoriamente dentro de cada estado.', false, 'A distribuição aleatória sugere localização que o dado não tem.', 'sugerir precisão inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-2', 'C', 'mapa coroplético, com faixas de cor por classe de taxa.', true, 'Dados relativos por unidade territorial se representam por preenchimento de cor em classes.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-2', 'D', 'círculos proporcionais ao número absoluto de óbitos.', false, 'Isso representaria o total, e não a taxa pedida.', 'trocar dado absoluto por relativo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-2', 'E', 'setas indicando o fluxo entre estados.', false, 'Setas representam movimento, e taxa não é fluxo.', 'representação incompatível');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cart-3', 'cartografia', 'ler-e-interpretar-representacoes-cartograficas', 'intermediate', 'interpretation', false, 'Dois mapas do mesmo fenômeno usam classes diferentes: o primeiro divide os dados em cinco faixas iguais; o segundo, em faixas que isolam os valores extremos. A comparação entre eles mostra que:', 'Mapa não é espelho do dado: entre o número e a cor há decisões. Explicitá-las é condição para uma leitura honesta.', 'Mapa não é espelho do dado: entre o número e a cor há decisões. Explicitá-las é condição para uma leitura honesta.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-3', 'A', 'a escolha das classes é uma decisão que muda o padrão percebido, e por isso precisa ser explicitada na legenda.', true, 'Agrupar valores de modos diferentes faz surgir ou desaparecer contrastes, e o leitor precisa saber qual critério foi usado.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-3', 'B', 'um dos mapas está necessariamente errado.', false, 'Ambas as classificações podem ser tecnicamente corretas.', 'supor erro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-3', 'C', 'a diferença é apenas estética e não afeta a leitura.', false, 'A classificação altera quais contrastes aparecem e quais desaparecem.', 'minimizar o efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-3', 'D', 'o segundo mapa é sempre preferível, por destacar extremos.', false, 'Destacar extremos pode ser útil ou enganoso, conforme o objetivo.', 'preferência automática');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-3', 'E', 'a diferença indica que os dados de origem não são os mesmos.', false, 'Os dados são os mesmos; o que muda é como foram agrupados.', 'atribuir à fonte');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cart-4', 'cartografia', 'ler-e-interpretar-representacoes-cartograficas', 'intermediate', 'comparison', false, 'Comparando um mapa em escala 1:10.000 e outro em escala 1:1.000.000 da mesma região, é correto afirmar que:', 'Escala grande, área pequena e muito detalhe; escala pequena, área grande e forte generalização. O denominador indica quanto a realidade foi reduzida.', 'Escala grande, área pequena e muito detalhe; escala pequena, área grande e forte generalização. O denominador indica quanto a realidade foi reduzida.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-4', 'A', 'os dois têm o mesmo nível de detalhe, mudando só o tamanho do papel.', false, 'O detalhe representável muda com a escala.', 'igualar níveis de detalhe');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-4', 'B', 'o de 1:10.000 tem escala maior, mostra área menor e mais detalhe.', true, 'Denominador menor significa menos redução, portanto mais detalhe em menos área.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-4', 'C', 'o de 1:10.000 serve para mapear um país inteiro.', false, 'Nessa escala o país exigiria milhares de folhas.', 'uso incompatível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-4', 'D', 'escala não tem relação com o detalhe representado.', false, 'A escala define o que cabe e o que precisa ser generalizado.', 'negar a relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-4', 'E', 'o de 1:1.000.000 tem escala maior e mais detalhe.', false, 'Quanto maior o denominador, menor a escala e menor o detalhe.', 'inverter a relação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cart-5', 'cartografia', 'ler-e-interpretar-representacoes-cartograficas', 'challenging', 'integration', false, 'Um mapa-múndi em projeção de Mercator é usado para comparar a extensão territorial da Groenlândia e da África. Sobre essa comparação:', 'Escolher a projeção é escolher o que se pode afirmar com o mapa. Para comparar áreas, é preciso uma projeção equivalente, não uma conforme.', 'Escolher a projeção é escolher o que se pode afirmar com o mapa. Para comparar áreas, é preciso uma projeção equivalente, não uma conforme.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-5', 'A', 'ela é inadequada porque a Groenlândia não é um continente.', false, 'A categoria da unidade não tem relação com a distorção da projeção.', 'critério irrelevante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-5', 'B', 'ela é inadequada, porque Mercator preserva ângulos e distorce áreas fortemente perto dos polos.', true, 'A projeção foi feita para navegação, mantendo direções corretas; comparar áreas nela exagera enormemente as regiões de alta latitude.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-5', 'C', 'ela é adequada, pois todo mapa-múndi preserva proporções de área.', false, 'Nem todo mapa preserva área; projeções equivalentes é que o fazem.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-5', 'D', 'ela é adequada, desde que o mapa esteja atualizado.', false, 'Atualização não corrige a distorção da projeção.', 'deslocar o problema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cart-5', 'E', 'ela é inadequada porque Mercator distorce ângulos.', false, 'Mercator preserva ângulos; é justamente essa a sua propriedade.', 'trocar a propriedade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-glob-1', 'globalizacao', 'analisar-processos-e-efeitos-da-globalizacao', 'intro', 'concept', false, 'A fragmentação da produção industrial entre vários países, com cada etapa realizada onde as condições são mais vantajosas para a empresa, é característica das:', 'Cadeias globais de valor são a forma predominante de organização da produção industrial contemporânea.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-1', 'A', 'Políticas protecionistas de substituição de importações.', false, 'Essas políticas concentram etapas dentro do país, em vez de distribuí-las.', 'trocar por outro modelo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-1', 'B', 'Corporações de capital exclusivamente nacional.', false, 'A fragmentação internacional pressupõe atuação além das fronteiras nacionais.', 'restringir indevidamente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-1', 'C', 'Cadeias globais de valor, em que etapas produtivas se distribuem entre países conforme custos e vantagens de cada lugar.', true, 'Projeto, componentes, montagem e distribuição podem ocorrer em países distintos, cada um agregando uma parcela diferente do valor final.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-1', 'D', 'Zonas de livre-comércio regionais restritas a um único continente.', false, 'A fragmentação descrita atravessa continentes.', 'restringir a escala');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-1', 'E', 'Economias autárquicas, voltadas para o mercado interno.', false, 'Autarquia é justamente o oposto: produção fechada e independente.', 'inverter o conceito');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-glob-2', 'globalizacao', 'analisar-processos-e-efeitos-da-globalizacao', 'intermediate', 'applied', false, 'Um país exporta minério de ferro a baixo preço e importa máquinas e equipamentos de alto valor produzidos com esse mesmo insumo.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-2', 'A', 'A superioridade tecnológica natural de alguns países.', false, '"Natural" não explica nada: trata-se de trajetória histórica de investimento e política industrial.', 'naturalizar a desigualdade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-2', 'B', 'A ausência de globalização, já que há dependência de importações.', false, 'Interdependência comercial é exatamente uma marca da globalização.', 'inverter o conceito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-2', 'C', 'Uma relação comercial equilibrada, pois há exportação e importação.', false, 'O equilíbrio não se mede pela existência dos dois fluxos, e sim pelo valor de cada um.', 'confundir existência de fluxo com equilíbrio');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-2', 'D', 'O fim da divisão internacional do trabalho.', false, 'A situação descreve justamente a permanência dessa divisão.', 'inverter a conclusão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-2', 'E', 'A permanência de uma divisão internacional do trabalho em que alguns países concentram etapas de maior valor agregado.', true, 'Exportar matéria-prima barata e importar bens industrializados caros reproduz uma assimetria histórica: o valor se concentra nas etapas de transformação e tecnologia.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-glob-3', 'globalizacao', 'analisar-processos-e-efeitos-da-globalizacao', 'intermediate', 'interpretation', false, 'Leia o dado autoral: "Em uma metrópole latino-americana, 96% dos domicílios do distrito central têm internet de banda larga fixa; em três distritos periféricos, o índice fica abaixo de 40%."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-3', 'A', 'O dado indica apenas diferenças de interesse dos moradores pela internet.', false, 'Acesso depende de infraestrutura, renda e oferta de serviço, não de preferência individual.', 'individualizar um problema estrutural');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-3', 'B', 'A globalização não afeta a escala urbana, apenas as relações entre países.', false, 'Seus efeitos aparecem inclusive dentro de um mesmo bairro.', 'restringir a escala do fenômeno');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-3', 'C', 'O dado prova que a globalização reduziu as desigualdades urbanas.', false, 'A diferença apresentada indica o contrário.', 'inverter a conclusão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-3', 'D', 'Trata-se de um problema técnico sem relação com desigualdade social.', false, 'Acesso à rede está diretamente associado a renda e localização.', 'despolitizar o dado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-3', 'E', 'A globalização conecta o território de forma seletiva, e a desigualdade de acesso reproduz, dentro da cidade, a divisão entre áreas integradas e áreas à margem dos fluxos.', true, 'A diferença entre 96% e menos de 40% na mesma cidade mostra que a integração aos fluxos globais é desigual em escala intraurbana, com efeitos sobre trabalho, estudo e acesso a serviços.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-glob-4', 'globalizacao', 'analisar-processos-e-efeitos-da-globalizacao', 'challenging', 'comparison', false, 'Analise duas leituras sobre os efeitos culturais da globalização:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-4', 'A', 'I é correta e II descreve apenas exceções irrelevantes.', false, 'Casos de projeção global de manifestações locais são numerosos e estruturais, não exceções.', 'minimizar um efeito real');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-4', 'B', 'As duas são corretas e descrevem efeitos simultâneos do mesmo processo, que combina homogeneização e hibridação cultural.', true, 'Homogeneização e hibridação coexistem: os mesmos fluxos que espalham produtos dominantes também permitem circulação e recombinação de expressões locais. Uma análise consistente reconhece as duas direções.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-4', 'C', 'Apenas I é correta, pois a globalização destrói culturas locais.', false, 'A destruição não é o único efeito observado; há também projeção e recombinação.', 'reduzir o processo a um efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-4', 'D', 'Apenas II é correta, pois a cultura local sempre se fortalece com a exposição global.', false, 'A exposição não garante fortalecimento; pode haver perda de práticas e de línguas.', 'otimismo sem evidência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-4', 'E', 'As duas são incorretas, pois cultura e economia são esferas independentes.', false, 'Circulação cultural depende diretamente de infraestrutura econômica e técnica.', 'separar esferas interdependentes');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-glob-5', 'globalizacao', 'analisar-processos-e-efeitos-da-globalizacao', 'challenging', 'integration', false, 'Uma empresa transfere sua produção de um país com legislação ambiental rigorosa para outro com regras mais frouxas, mantendo a venda nos mercados de origem.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-5', 'A', 'A decisão é irrelevante do ponto de vista ambiental, pois a produção total permanece a mesma.', false, 'A mudança de regulação pode aumentar o impacto por unidade produzida.', 'ignorar o efeito da regulação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-5', 'B', 'A decisão beneficia igualmente os dois países envolvidos.', false, 'Os ganhos e custos se distribuem de forma desigual entre eles.', 'supor simetria inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-5', 'C', 'A empresa perde competitividade, pois a distância aumenta os custos logísticos.', false, 'A logística é apenas um dos fatores, e a decisão pressupõe ganho líquido para a empresa.', 'reduzir a análise a um custo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-5', 'D', 'A transferência resolve o problema ambiental do país de origem, que passa a ter emissões menores.', false, 'As emissões apenas mudam de lugar; a atmosfera é um sistema único.', 'confundir contabilidade nacional com efeito real');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-5', 'E', 'A transferência desloca custos ambientais para o país receptor sem eliminá-los, gera empregos ali em condições regulatórias mais frágeis e mantém o consumo nos mercados de origem, o que evidencia a dimensão global do problema ambiental.', true, 'A decisão reduz o custo da empresa transferindo o passivo ambiental para outro território. As emissões continuam existindo, o país receptor ganha empregos com menor proteção e o consumo permanece onde estava — o que mostra por que regulação ambiental puramente nacional tem limites.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-glob-rec-1', 'globalizacao', 'analisar-processos-e-efeitos-da-globalizacao', 'intro', 'concept', true, 'Uma característica marcante da globalização contemporânea é a assimetria entre a circulação de capitais e a de pessoas. Essa assimetria significa que:', 'Capital circula quase sem barreiras; a mobilidade humana é seletiva e regulada — uma das assimetrias estruturais da globalização.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-rec-1', 'A', 'Tanto capitais quanto pessoas circulam livremente entre países.', false, 'A circulação de pessoas é fortemente regulada e desigual conforme a nacionalidade.', 'igualar os fluxos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-rec-1', 'B', 'Pessoas circulam com mais facilidade que capitais.', false, 'A relação é inversa.', 'inverter a assimetria');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-rec-1', 'C', 'Capitais atravessam fronteiras com muito menos restrição do que pessoas.', true, 'Transferências financeiras ocorrem em segundos e com poucas barreiras, enquanto a mobilidade humana enfrenta vistos, muros e seleção por origem.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-rec-1', 'D', 'Ambos os fluxos foram interrompidos pela globalização.', false, 'A globalização intensificou os fluxos, não os interrompeu.', 'inverter o processo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-glob-rec-1', 'E', 'A assimetria existe apenas entre países vizinhos.', false, 'Ela se manifesta em escala global.', 'restringir o alcance');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-glob-1', 'globalizacao', 'analisar-processos-e-efeitos-da-globalizacao', 'intro', 'concept', false, 'A afirmação de que a globalização "encurtou distâncias" refere-se, em termos geográficos, à:', 'A distância que encolhe é a distância-tempo e a distância-custo, não a quilometragem. E ela encolhe de forma desigual pelo planeta.', 'A distância que encolhe é a distância-tempo e a distância-custo, não a quilometragem. E ela encolhe de forma desigual pelo planeta.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-1', 'A', 'redução do tempo e do custo necessários para deslocar pessoas, mercadorias e informações.', true, 'Transporte e telecomunicações reduziram o tempo de conexão, o que se chama compressão espaço-tempo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-1', 'B', 'padronização dos fusos horários no mundo.', false, 'A padronização de fusos é anterior e não é o que a expressão designa.', 'conceito trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-1', 'C', 'ampliação do território dos blocos econômicos.', false, 'Blocos são acordos, e não expansão territorial.', 'conceito trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-1', 'D', 'redução física da distância entre os continentes.', false, 'A distância física não mudou.', 'leitura literal');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-1', 'E', 'diminuição do número de fronteiras entre países.', false, 'O número de países aumentou nas últimas décadas.', 'afirmação incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-glob-2', 'globalizacao', 'analisar-processos-e-efeitos-da-globalizacao', 'intro', 'applied', false, 'Uma empresa projeta um aparelho em um país, fabrica componentes em outros três e monta em um quinto. Esse arranjo é um exemplo de:', 'Cadeias globais fragmentam a produção. Cada etapa se instala onde encontra a combinação desejada de custo, qualificação e logística.', 'Cadeias globais fragmentam a produção. Cada etapa se instala onde encontra a combinação desejada de custo, qualificação e logística.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-2', 'A', 'autossuficiência produtiva nacional.', false, 'A produção depende de vários países, e não de um só.', 'conceito oposto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-2', 'B', 'comércio bilateral simples entre dois países.', false, 'Há pelo menos cinco territórios envolvidos em etapas diferentes.', 'reduzir a escala');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-2', 'C', 'integração vertical em um único território.', false, 'A integração ocorre entre países, e não dentro de um só.', 'escala trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-2', 'D', 'cadeia global de valor, com etapas distribuídas entre territórios segundo custo e competência.', true, 'Projetar, fabricar componentes e montar em lugares diferentes é a definição operacional de cadeia global de valor.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-2', 'E', 'protecionismo comercial.', false, 'Protecionismo restringe o comércio; aqui ele é intenso e distribuído.', 'conceito oposto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-glob-3', 'globalizacao', 'analisar-processos-e-efeitos-da-globalizacao', 'intermediate', 'interpretation', false, 'Um estudo mostra que, em uma mesma cidade, parte da população tem internet de alta velocidade e trabalha remotamente para empresas de outros países, enquanto outra parte não tem conexão estável. Esse quadro ilustra que a globalização:', 'Globalização não é maré que sobe igual para todos. Ela conecta pontos e deixa vazios, inclusive entre bairros vizinhos.', 'Globalização não é maré que sobe igual para todos. Ela conecta pontos e deixa vazios, inclusive entre bairros vizinhos.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-3', 'A', 'é seletiva: integra intensamente alguns lugares e pessoas e deixa outros à margem, inclusive dentro da mesma cidade.', true, 'A conexão às redes globais se distribui de forma desigual, e a desigualdade não é apenas entre países.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-3', 'B', 'eliminou a importância do lugar onde as pessoas vivem.', false, 'O exemplo mostra que o lugar e a infraestrutura disponível continuam decisivos.', 'afirmação contrária');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-3', 'C', 'depende exclusivamente de políticas nacionais de comércio.', false, 'Infraestrutura urbana e renda também determinam quem se conecta.', 'reduzir a um fator');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-3', 'D', 'é um processo recente, iniciado com a internet.', false, 'A integração mundial é anterior; a internet intensificou um processo já em curso.', 'datação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-3', 'E', 'atinge todos os lugares e pessoas de maneira uniforme.', false, 'O próprio exemplo mostra o contrário dentro de uma mesma cidade.', 'contradizer o enunciado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-glob-4', 'globalizacao', 'analisar-processos-e-efeitos-da-globalizacao', 'intermediate', 'comparison', false, 'Comparando os argumentos favoráveis e contrários à abertura comercial de um país, uma análise equilibrada reconhece que:', 'Efeito médio positivo e perdas concentradas coexistem. Analisar abertura comercial exige perguntar quem ganha, quem perde e o que se faz por quem perde.', 'Efeito médio positivo e perdas concentradas coexistem. Analisar abertura comercial exige perguntar quem ganha, quem perde e o que se faz por quem perde.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-4', 'A', 'há ganhos para consumidores e para setores competitivos, e perdas concentradas em setores e regiões expostos, o que torna decisivas as políticas de transição.', true, 'O saldo agregado convive com perdas concentradas, e é essa concentração que define o custo social do processo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-4', 'B', 'a discussão é apenas ideológica e não admite análise técnica.', false, 'Há evidência empírica considerável sobre efeitos setoriais e regionais.', 'recusa sem critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-4', 'C', 'a abertura só produz ganhos, distribuídos igualmente pela sociedade.', false, 'Mesmo quando há ganho agregado, ele não se distribui igualmente.', 'ignorar a distribuição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-4', 'D', 'a abertura só produz perdas, pois destrói a indústria nacional.', false, 'Setores competitivos podem se expandir com a abertura.', 'generalização negativa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-4', 'E', 'os efeitos dependem apenas do tamanho do país.', false, 'Tamanho influencia, mas estrutura produtiva e políticas de transição pesam mais.', 'reduzir a um fator');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-glob-5', 'globalizacao', 'analisar-processos-e-efeitos-da-globalizacao', 'challenging', 'integration', false, 'Um país reduz tarifas de importação de alimentos e, anos depois, enfrenta desabastecimento quando uma crise internacional interrompe o fornecimento externo. Esse episódio evidencia que:', 'Eficiência e resiliência são objetivos que competem entre si. Depender do mercado externo barateia em tempos normais e cobra caro em choques.', 'Eficiência e resiliência são objetivos que competem entre si. Depender do mercado externo barateia em tempos normais e cobra caro em choques.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-5', 'A', 'o desabastecimento decorre apenas de falhas logísticas internas.', false, 'A causa apontada é a interrupção do fornecimento externo.', 'deslocar a causa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-5', 'B', 'a autossuficiência total é a única política viável.', false, 'Autossuficiência total costuma ser cara e ineficiente; o ponto é gerenciar risco, não eliminá-lo.', 'solução extrema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-5', 'C', 'integração comercial reduz custos e ao mesmo tempo cria dependência, o que exige política de segurança alimentar.', true, 'Ganhos de eficiência e exposição a choques externos vêm juntos, e é por isso que estoques e produção interna entram na conta.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-5', 'D', 'a abertura comercial é sempre prejudicial e deve ser revertida.', false, 'A conclusão ignora os ganhos obtidos no período anterior à crise.', 'generalização');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-glob-5', 'E', 'crises internacionais não afetam países integrados ao comércio.', false, 'O episódio mostra exatamente o contrário.', 'contradizer o enunciado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-etica-1', 'etica', 'aplicar-teorias-eticas-a-situacoes-concretas', 'intro', 'concept', false, 'Uma pessoa afirma: "Devo devolver a carteira que encontrei porque, se todos ficassem com o que acham, ninguém poderia confiar em ninguém — e eu não posso querer um mundo assim."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-1', 'A', 'Ética deontológica, pela aplicação do teste de universalização da conduta.', true, 'Perguntar se a máxima poderia valer para todos é exatamente o procedimento kantiano de universalização, que julga a ação pelo princípio e não pelo resultado.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-1', 'B', 'Ética das virtudes, por descrever o caráter da pessoa honesta.', false, 'O argumento não fala do caráter que se cultiva, e sim da regra que se poderia universalizar.', 'confundir com foco no agente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-1', 'C', 'Ética relativista, por depender do contexto cultural.', false, 'O argumento pretende justamente valer independentemente do contexto.', 'inverter a pretensão do argumento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-1', 'D', 'Ética hedonista, por buscar o prazer individual.', false, 'Não há apelo a prazer ou satisfação pessoal.', 'atribuir critério ausente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-1', 'E', 'Ética utilitarista, pois calcula o benefício coletivo da devolução.', false, 'A justificativa não pesa benefícios: ela testa se a conduta poderia valer para todos.', 'confundir universalização com utilidade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-etica-2', 'etica', 'aplicar-teorias-eticas-a-situacoes-concretas', 'intermediate', 'applied', false, 'Uma cidade precisa decidir se destina uma verba limitada à vacinação em massa, que beneficiaria milhares, ou a um tratamento caro para poucos pacientes com doença rara. Um gestor defende a vacinação, argumentando que ela produz o maior benefício para o maior número de pessoas.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-2', 'A', 'Deontológica, pois cumpre o dever do Estado de proteger a saúde.', false, 'A justificativa apresentada é o cálculo de benefício agregado, não o cumprimento de um dever independentemente do resultado.', 'trocar o critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-2', 'B', 'Da ética das virtudes, pois demonstra prudência administrativa.', false, 'A prudência aparece como consequência, mas o argumento explícito é de maximização.', 'confundir efeito com critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-2', 'C', 'Relativista, pois a decisão depende dos valores da cidade.', false, 'O argumento apresentado não apela a valores culturais locais.', 'atribuir critério ausente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-2', 'D', 'Consequencialista, pois avalia a ação pelo resultado agregado que produz.', true, 'Escolher a alternativa que maximiza o benefício para o maior número é a formulação clássica do utilitarismo, uma forma de consequencialismo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-2', 'E', 'Contratualista, pois pressupõe um acordo prévio entre os cidadãos.', false, 'Não há apelo a acordo ou contrato social no argumento.', 'atribuir teoria não mobilizada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-etica-3', 'etica', 'aplicar-teorias-eticas-a-situacoes-concretas', 'intermediate', 'interpretation', false, 'Leia o comentário autoral: "Não vejo problema em uma empresa usar dados de navegação dos usuários sem aviso claro. Está na cláusula que todo mundo aceita, então é legal — e se é legal, está certo."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-3', 'A', 'Não contém nenhum problema, pois legalidade e ética são sinônimos.', false, 'São conceitos distintos, e a história oferece muitos exemplos de leis eticamente contestadas.', 'aceitar a premissa do comentário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-3', 'B', 'Reduz a questão ética à legalidade, ignorando que uma prática pode ser prevista em lei e ainda assim não respeitar a autonomia de quem consente sem informação adequada.', true, 'A lei estabelece o mínimo exigível; a análise ética pergunta se o consentimento foi real. Uma cláusula genérica, não lida e não recusável sem perda do serviço, cumpre a norma sem produzir autonomia.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-3', 'C', 'Apresenta um argumento deontológico consistente, baseado no cumprimento de deveres legais.', false, 'Deontologia não se confunde com legalismo: o dever moral não se esgota na norma jurídica vigente.', 'confundir dever moral com norma legal');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-3', 'D', 'Defende a ética das virtudes ao valorizar o cumprimento de contratos.', false, 'Não há discussão sobre caráter ou virtude no comentário.', 'atribuir teoria ausente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-3', 'E', 'É um argumento utilitarista, pois pesa benefícios e custos do uso de dados.', false, 'Nenhum cálculo de benefícios é apresentado.', 'atribuir critério ausente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-etica-4', 'etica', 'aplicar-teorias-eticas-a-situacoes-concretas', 'challenging', 'comparison', false, 'Considere duas justificativas para não mentir:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-4', 'A', 'Utilitarismo e deontologia.', false, 'Nenhuma das duas calcula benefícios agregados.', 'atribuir critério ausente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-4', 'B', 'Ética das virtudes e utilitarismo.', false, 'A ordem está trocada e o utilitarismo não aparece em nenhuma delas.', 'trocar as correntes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-4', 'C', 'Deontologia e ética das virtudes.', true, 'I aplica o teste de universalização, próprio da deontologia. II se preocupa com o caráter que a prática constrói, que é o foco da ética das virtudes.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-4', 'D', 'Relativismo e contratualismo.', false, 'Nenhuma das duas apela a variação cultural ou a acordo social.', 'atribuir teorias não mobilizadas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-4', 'E', 'Consequencialismo e deontologia.', false, 'I não avalia consequências e II não formula um dever universal.', 'inverter os critérios');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-etica-5', 'etica', 'aplicar-teorias-eticas-a-situacoes-concretas', 'challenging', 'integration', false, 'Um hospital com um único leito de UTI disponível recebe simultaneamente dois pacientes graves. A equipe precisa decidir com transparência e critério.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-5', 'A', 'Aplicar protocolos previamente definidos, que combinam critérios clínicos de benefício esperado com regras que impedem discriminação por condição social, e registrar publicamente a justificativa da decisão.', true, 'Protocolos anteriores ao caso reduzem a arbitrariedade, combinam o cálculo de benefício com salvaguardas deontológicas contra discriminação e tornam a decisão auditável — o que responde às três tradições éticas ao mesmo tempo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-5', 'B', 'Escolher aleatoriamente, já que qualquer critério é arbitrário.', false, 'Sorteio pode integrar um protocolo, mas afirmar que todo critério é arbitrário abandona a deliberação clínica e ética.', 'confundir dificuldade com impossibilidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-5', 'C', 'Aplicar exclusivamente o critério de quem chegou primeiro, por ser o mais simples.', false, 'Simplicidade não é justificativa suficiente diante de prognósticos diferentes.', 'escolher pela facilidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-5', 'D', 'Decidir pela capacidade de pagamento, já que os recursos são limitados.', false, 'Critério econômico em atendimento de urgência viola princípios básicos de equidade em saúde.', 'introduzir critério injusto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-5', 'E', 'Adiar a decisão até que haja consenso entre todos os envolvidos, incluindo as famílias.', false, 'Em emergência, adiar equivale a decidir por omissão, com risco para ambos os pacientes.', 'transformar indecisão em método');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-etica-rec-1', 'etica', 'aplicar-teorias-eticas-a-situacoes-concretas', 'intro', 'concept', true, 'A distinção entre ética e moral pode ser assim resumida:', 'Moral é o vivido e prescrito por um grupo; ética é a reflexão crítica sobre esse conjunto de normas.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-rec-1', 'A', 'Ética é o conjunto de leis do Estado; moral é o comportamento privado.', false, 'Leis pertencem ao campo do direito, distinto dos dois conceitos.', 'confundir com direito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-rec-1', 'B', 'Moral se aplica a instituições; ética, apenas a indivíduos.', false, 'As duas noções operam nos dois níveis.', 'restringir o alcance');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-rec-1', 'C', 'Ética é imutável; moral muda conforme a época.', false, 'A reflexão ética também se transforma historicamente.', 'atribuir imutabilidade indevida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-rec-1', 'D', 'São sinônimos perfeitos, sem qualquer diferença conceitual.', false, 'A filosofia distingue as duas noções de modo produtivo.', 'igualar os conceitos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-etica-rec-1', 'E', 'Moral é o conjunto de normas e valores vigentes em um grupo; ética é a reflexão crítica sobre esses valores.', true, 'A moral é o que um grupo pratica e prescreve; a ética examina, questiona e busca justificar ou revisar essas normas.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-eti-1', 'etica', 'aplicar-teorias-eticas-a-situacoes-concretas', 'intro', 'concept', false, 'A distinção entre moral e ética, tal como usada na filosofia, pode ser formulada assim:', 'Moral é o conjunto de normas vividas; ética é a investigação sobre elas. Sem essa distinção, criticar uma norma vira apenas desobedecê-la.', 'Moral é o conjunto de normas vividas; ética é a investigação sobre elas. Sem essa distinção, criticar uma norma vira apenas desobedecê-la.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-1', 'A', 'moral trata de leis e ética trata de costumes.', false, 'Leis são o campo do direito, distinto dos dois.', 'confundir com direito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-1', 'B', 'moral é o conjunto de normas efetivamente vigentes em um grupo; ética é a reflexão crítica sobre essas normas e seus fundamentos.', true, 'Uma descreve o que vigora; a outra examina se e por que aquilo se justifica.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-1', 'C', 'moral é religiosa e ética é laica.', false, 'Existem morais laicas e reflexões éticas de origem religiosa.', 'divisão incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-1', 'D', 'os termos são sinônimos e a distinção é apenas de estilo.', false, 'A distinção é operativa e organiza boa parte da discussão filosófica.', 'negar a distinção');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-1', 'E', 'moral é individual e ética é coletiva.', false, 'A moral é justamente o conjunto compartilhado de normas de um grupo.', 'inverter os termos');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-eti-2', 'etica', 'aplicar-teorias-eticas-a-situacoes-concretas', 'intermediate', 'applied', false, 'Um gestor decide demitir cinco funcionários para evitar a falência da empresa e a perda de cinquenta empregos. Uma justificativa utilitarista dessa decisão apoia-se em:', 'O utilitarismo julga pelas consequências agregadas. É diferente de agir por interesse próprio e diferente de agir por dever.', 'O utilitarismo julga pelas consequências agregadas. É diferente de agir por interesse próprio e diferente de agir por dever.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-2', 'A', 'no interesse pessoal do gestor em manter o cargo.', false, 'Interesse próprio é egoísmo, não utilitarismo.', 'confundir com egoísmo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-2', 'B', 'na tradição da empresa em manter seus funcionários.', false, 'Apelo à tradição não é critério utilitarista.', 'teoria trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-2', 'C', 'no dever de cumprir contratos, independentemente das consequências.', false, 'Esse é um argumento deontológico, centrado no dever.', 'teoria trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-2', 'D', 'no cálculo do maior bem para o maior número de afetados.', true, 'O utilitarismo avalia a ação pelos resultados agregados sobre todos os envolvidos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-2', 'E', 'na virtude da coragem demonstrada pelo gestor.', false, 'Esse é um argumento da ética das virtudes, centrado no caráter.', 'teoria trocada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-eti-3', 'etica', 'aplicar-teorias-eticas-a-situacoes-concretas', 'challenging', 'interpretation', false, 'Alguém afirma: "cada cultura tem seus valores, então não se pode criticar prática alguma de outra sociedade". Sobre essa formulação, a análise filosófica mais consistente é que:', 'O relativismo forte se enreda: para valer, precisa de um princípio universal, que é justamente o que ele diz não existir. Reconhecer diversidade não impede avaliar razões.', 'O relativismo forte se enreda: para valer, precisa de um princípio universal, que é justamente o que ele diz não existir. Reconhecer diversidade não impede avaliar razões.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-3', 'A', 'ela está correta, pois criticar outra cultura é sempre imperialismo.', false, 'A crítica pode ser imperialista, mas não é isso necessariamente.', 'generalização');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-3', 'B', 'ela está errada porque todas as culturas têm exatamente os mesmos valores.', false, 'A diversidade de valores é um fato observável.', 'negar a diversidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-3', 'C', 'ela confunde constatar a diversidade de valores com concluir que nenhum juízo é possível, o que a própria formulação contradiz ao afirmar um princípio universal.', true, 'A frase enuncia uma regra válida para todos — não criticar — e assim usa aquilo que nega.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-3', 'D', 'ela está correta, pois valores são sempre subjetivos.', false, 'Do fato de valores variarem não se segue que qualquer prática esteja além de avaliação.', 'salto do descritivo ao normativo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-3', 'E', 'ela está errada, pois existe uma cultura superior às demais.', false, 'Afirmar superioridade cultural é etnocentrismo, o extremo oposto e igualmente frágil.', 'etnocentrismo');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-eti-4', 'etica', 'aplicar-teorias-eticas-a-situacoes-concretas', 'intermediate', 'comparison', false, 'Comparando a ética kantiana e o utilitarismo diante da pergunta "é permitido mentir para evitar um dano?", a diferença central é que:', 'A divergência não está na conclusão, e sim no critério: universalizabilidade da máxima contra saldo de consequências.', 'A divergência não está na conclusão, e sim no critério: universalizabilidade da máxima contra saldo de consequências.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-4', 'A', 'a kantiana julga pelas consequências e o utilitarismo, pelo dever.', false, 'Os critérios estão trocados entre as duas.', 'inverter as teorias');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-4', 'B', 'a kantiana avalia se a máxima da ação poderia valer como regra universal, enquanto o utilitarismo avalia o saldo de consequências.', true, 'Uma pergunta o que aconteceria se todos agissem assim; a outra, quanto bem e quanto mal a ação produz.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-4', 'C', 'nenhuma das duas oferece resposta a esse tipo de caso.', false, 'Ambas oferecem respostas, e é a divergência entre elas que torna o caso instrutivo.', 'negar a aplicabilidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-4', 'D', 'as duas proíbem a mentira pelos mesmos motivos.', false, 'O utilitarismo pode admiti-la conforme as consequências.', 'igualar as teorias');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-4', 'E', 'as duas permitem a mentira quando o dano é grave.', false, 'A perspectiva deontológica avalia a máxima da ação, e não a gravidade do dano.', 'igualar as teorias');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-eti-5', 'etica', 'aplicar-teorias-eticas-a-situacoes-concretas', 'challenging', 'integration', false, 'Um hospital com um único respirador disponível precisa escolher entre dois pacientes. A equipe adota critérios clínicos previamente definidos e públicos. Do ponto de vista ético, o principal ganho desse procedimento é:', 'Diante de dilemas trágicos, a justiça possível é procedimental: critérios definidos antes, públicos e aplicáveis a todos, com responsabilidade preservada.', 'Diante de dilemas trágicos, a justiça possível é procedimental: critérios definidos antes, públicos e aplicáveis a todos, com responsabilidade preservada.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-5', 'A', 'transferir a responsabilidade da equipe para o protocolo.', false, 'A equipe continua responsável por aplicar e revisar o critério.', 'evasão de responsabilidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-5', 'B', 'tornar a decisão puramente técnica, sem dimensão moral.', false, 'A escolha permanece moral; o critério apenas organiza como se decide.', 'negar a dimensão moral');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-5', 'C', 'assegurar que a decisão agrade aos familiares dos pacientes.', false, 'Aceitação não é o critério ético em jogo.', 'critério trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-5', 'D', 'submeter a decisão a critérios impessoais e verificáveis, reduzindo arbítrio e permitindo prestação de contas, sem eliminar a tragédia da escolha.', true, 'Nenhum procedimento torna a decisão indolor, mas critérios públicos evitam que ela dependa de preferência pessoal ou de pressão.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eti-5', 'E', 'garantir que ninguém morra em consequência da escolha.', false, 'A escassez não é resolvida pelo procedimento.', 'consequência impossível');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cult-1', 'cultura-e-identidade', 'analisar-cultura-identidade-e-diversidade', 'intro', 'concept', false, 'Em ciências humanas, o conceito de cultura designa:', 'Cultura, no sentido antropológico, é todo modo de vida aprendido e compartilhado — bem mais amplo que "cultura erudita".', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-1', 'A', 'O conjunto de práticas, valores, saberes e formas de organização aprendidos e compartilhados socialmente.', true, 'Língua, alimentação, técnicas, rituais e valores compõem a cultura de um grupo, e todos são aprendidos na convivência.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-1', 'B', 'O grau de desenvolvimento econômico alcançado por uma sociedade.', false, 'Desenvolvimento econômico é outra dimensão, que não define cultura.', 'trocar cultura por economia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-1', 'C', 'O conjunto de leis formais que organizam a vida em sociedade.', false, 'Leis são parte da vida social, mas não esgotam o conceito de cultura.', 'reduzir cultura a norma jurídica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-1', 'D', 'O conjunto de conhecimentos artísticos e literários de uma elite instruída.', false, 'Essa é a acepção corrente de "cultura erudita", mais restrita que o conceito antropológico.', 'confundir com erudição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-1', 'E', 'As características biológicas herdadas que distinguem os povos.', false, 'Cultura é aprendida socialmente, não transmitida por herança biológica.', 'naturalizar a diferença cultural');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cult-2', 'cultura-e-identidade', 'analisar-cultura-identidade-e-diversidade', 'intermediate', 'applied', false, 'Um turista comenta, ao visitar outro país: "Aqui as pessoas almoçam às quatro da tarde. É um povo desorganizado, deviam almoçar na hora certa."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-2', 'A', 'Apropriação cultural, por interferir nos costumes locais.', false, 'Não há uso de elementos culturais alheios pelo turista.', 'aplicar conceito inadequado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-2', 'B', 'Identidade cultural, pois o turista afirma sua origem.', false, 'A afirmação de origem não é, por si, um conceito explicativo aqui.', 'trocar o conceito central');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-2', 'C', 'Etnocentrismo, pois toma os próprios hábitos como padrão universal para julgar os do outro.', true, '"Hora certa" é a hora do país do turista. Transformar um hábito próprio em critério universal é a definição de etnocentrismo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-2', 'D', 'Relativismo cultural, pois reconhece a existência de outro costume.', false, 'Reconhecer a diferença e em seguida hierarquizá-la é o oposto do relativismo como método.', 'confundir constatação com relativismo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-2', 'E', 'Uma observação neutra sobre horários de refeição.', false, 'A palavra "desorganizado" carrega um juízo de valor explícito.', 'ignorar o juízo embutido');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cult-3', 'cultura-e-identidade', 'analisar-cultura-identidade-e-diversidade', 'intermediate', 'interpretation', false, 'Leia o relato autoral: "Cresci falando duas línguas em casa. Na escola, eu era ‘o estrangeiro’; nas férias, no país da minha mãe, eu era ‘o de fora’. Levei anos para entender que não precisava escolher um lado."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-3', 'A', 'É um dado fixo, que só se altera por decisão formal de nacionalidade.', false, 'Nacionalidade jurídica e identidade cultural são coisas distintas.', 'confundir identidade com documento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-3', 'B', 'É determinada pelo local de nascimento e não muda ao longo da vida.', false, 'O relato descreve exatamente uma identidade que não se resolve pelo local de nascimento.', 'contrariar o relato');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-3', 'C', 'Deve ser escolhida entre as origens disponíveis, para evitar conflito.', false, 'A conclusão do relato é justamente que não era preciso escolher.', 'contrariar a conclusão do texto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-3', 'D', 'Depende exclusivamente da língua que a pessoa fala com mais fluência.', false, 'A língua é um elemento entre vários, e o relato mostra pertencimento múltiplo.', 'reduzir identidade a um marcador');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-3', 'E', 'É relacional e múltipla, construindo-se de forma diferente conforme o contexto e o olhar dos outros.', true, 'A pessoa é "estrangeira" em um contexto e "de fora" no outro: a identidade se define na relação, e pode acomodar pertencimentos simultâneos.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cult-4', 'cultura-e-identidade', 'analisar-cultura-identidade-e-diversidade', 'challenging', 'comparison', false, 'Analise duas situações:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-4', 'A', 'Apenas II configura apropriação problemática, pela combinação de assimetria de poder, ausência de reconhecimento e concentração dos ganhos.', true, 'Em I há reciprocidade, autoria compartilhada e crédito. Em II, um agente economicamente dominante utiliza a criação de uma comunidade sem consulta, sem crédito e sem contrapartida.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-4', 'B', 'Apenas I configura apropriação, pois mistura estilos de origens diferentes.', false, 'Mistura com reciprocidade e crédito é troca cultural, não apropriação.', 'inverter a avaliação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-4', 'C', 'Nenhuma configura apropriação, pois culturas sempre circularam.', false, 'A circulação histórica não anula a assimetria concreta descrita em II.', 'usar a história para neutralizar o caso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-4', 'D', 'A distinção entre as situações depende apenas do gosto pessoal de quem avalia.', false, 'Existem critérios objetivos: consulta, crédito, poder relativo e repartição de benefícios.', 'reduzir análise a preferência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-4', 'E', 'Ambas configuram apropriação cultural, pois envolvem uso de elementos de outra cultura.', false, 'Circulação cultural não é, por si, apropriação problemática: o que pesa é a assimetria, o crédito e a repartição dos ganhos.', 'condenar toda circulação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cult-5', 'cultura-e-identidade', 'analisar-cultura-identidade-e-diversidade', 'challenging', 'integration', false, 'Uma escola recebe estudantes de várias origens culturais e discute como organizar suas atividades e calendário.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-5', 'A', 'Criar turmas separadas por origem cultural, para que cada grupo preserve seus costumes.', false, 'Separação institucional produz segregação, e não convivência.', 'confundir preservação com separação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-5', 'B', 'Realizar uma feira cultural anual com comidas e danças típicas, mantendo o restante do calendário inalterado.', false, 'Eventos pontuais podem virar folclorização se não houver mudança nas práticas cotidianas da escola.', 'reduzir diversidade a evento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-5', 'C', 'Deixar que cada estudante decida individualmente quais regras seguir, sem critérios comuns.', false, 'A convivência exige regras compartilhadas construídas coletivamente.', 'confundir respeito com ausência de regras');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-5', 'D', 'Manter regras comuns construídas com participação da comunidade escolar, prever flexibilizações justificadas — como datas religiosas e restrições alimentares — e incorporar as diferentes referências culturais ao currículo ao longo do ano.', true, 'A proposta trata a diversidade como parte do cotidiano, e não como evento; distingue igualdade de uniformidade ao prever flexibilizações justificadas; e sustenta regras comuns construídas coletivamente, o que evita tanto a imposição de um padrão único quanto a ausência de critérios.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-5', 'E', 'Adotar um único padrão cultural para todos, garantindo que ninguém seja tratado de forma diferente.', false, 'Padrão único costuma ser o padrão do grupo majoritário, o que não é neutralidade.', 'confundir uniformidade com igualdade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-cult-rec-1', 'cultura-e-identidade', 'analisar-cultura-identidade-e-diversidade', 'intro', 'concept', true, 'A afirmação "as diferenças culturais entre grupos não implicam hierarquia entre eles" corresponde ao reconhecimento de que:', 'Diferença cultural é horizontal; desigualdade é vertical. Usar a primeira para justificar a segunda é o mecanismo do preconceito.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-rec-1', 'A', 'Todas as culturas produzem exatamente os mesmos resultados materiais.', false, 'A afirmação não trata de resultados materiais, e sim de hierarquia de valor.', 'trocar o objeto da afirmação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-rec-1', 'B', 'Diversidade cultural é diferença horizontal, enquanto desigualdade é distribuição desigual de recursos e poder.', true, 'Modos de vida distintos não formam uma escala de superioridade. Desigualdade é outro fenômeno: refere-se ao acesso desigual a bens, direitos e poder.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-rec-1', 'C', 'As culturas devem ser preservadas sem qualquer contato entre si.', false, 'Isolamento não decorre do reconhecimento da diversidade.', 'confundir respeito com isolamento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-rec-1', 'D', 'Nenhuma prática cultural pode ser objeto de debate público.', false, 'Reconhecer diversidade não encerra o debate sobre práticas.', 'exagerar a consequência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-cult-rec-1', 'E', 'A desigualdade social é uma consequência natural da diversidade cultural.', false, 'Desigualdade tem causas econômicas e políticas, não decorre da diferença cultural.', 'naturalizar a desigualdade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cult-1', 'cultura-e-identidade', 'analisar-cultura-identidade-e-diversidade', 'intro', 'concept', false, 'O conceito antropológico de cultura, tal como usado nas ciências sociais, refere-se a:', 'No sentido antropológico, todo grupo humano tem cultura. Ela não se mede em graus e não se herda pelo corpo: aprende-se.', 'No sentido antropológico, todo grupo humano tem cultura. Ela não se mede em graus e não se herda pelo corpo: aprende-se.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-1', 'A', 'as manifestações artísticas de um povo.', false, 'A arte é parte da cultura, não a sua totalidade.', 'reduzir à arte');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-1', 'B', 'o estágio de desenvolvimento técnico de uma sociedade.', false, 'Essa formulação supõe uma escala evolutiva entre povos, hoje rejeitada.', 'evolucionismo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-1', 'C', 'o conjunto de significados, práticas e modos de vida compartilhados e transmitidos socialmente.', true, 'Cultura abrange linguagem, técnicas, valores, rituais e hábitos, aprendidos na convivência.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-1', 'D', 'a herança genética que distingue grupos humanos.', false, 'Cultura é aprendida, não transmitida biologicamente.', 'confundir com biologia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-1', 'E', 'o conjunto de conhecimentos eruditos de uma pessoa.', false, 'Esse é o sentido corrente de "pessoa culta", distinto do conceito antropológico.', 'confundir com erudição');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cult-2', 'cultura-e-identidade', 'analisar-cultura-identidade-e-diversidade', 'intermediate', 'applied', false, 'Uma marca lança uma coleção com grafismos de um povo indígena, sem consulta, sem crédito e sem repartição de benefícios. Do ponto de vista da análise cultural, o caso é lido como:', 'O que caracteriza apropriação não é o uso de elementos alheios, e sim a assimetria: quem decide, quem é creditado e quem se beneficia.', 'O que caracteriza apropriação não é o uso de elementos alheios, e sim a assimetria: quem decide, quem é creditado e quem se beneficia.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-2', 'A', 'apropriação cultural, porque há uso comercial sem consentimento, crédito ou repartição de benefícios, em relação assimétrica.', true, 'Os três elementos ausentes — consulta, reconhecimento e retorno — são o que distingue apropriação de diálogo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-2', 'B', 'valorização automática da cultura indígena, pela visibilidade obtida.', false, 'Visibilidade sem controle sobre o uso não equivale a valorização.', 'confundir exposição com reconhecimento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-2', 'C', 'questão exclusivamente jurídica, sem dimensão cultural.', false, 'Há dimensão jurídica, mas a questão é também de reconhecimento e autonomia.', 'reduzir ao direito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-2', 'D', 'impossibilidade de qualquer uso de elementos de outra cultura.', false, 'Trocas culturais são possíveis e comuns; o critério é como elas se dão.', 'proibição absoluta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-2', 'E', 'intercâmbio cultural legítimo, pois culturas sempre se influenciam.', false, 'A influência mútua é real, mas aqui falta reciprocidade: uma parte usa e lucra, a outra não decide nem recebe.', 'ignorar a assimetria');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cult-3', 'cultura-e-identidade', 'analisar-cultura-identidade-e-diversidade', 'intermediate', 'interpretation', false, 'Um jovem filho de migrantes se diz "das duas terras", combinando referências do lugar onde nasceu e daquele de onde veio a família. Essa formulação ilustra a ideia de identidade como:', 'Identidade não é dado de nascimento nem escolha única. Ela se constrói na relação e comporta pertencimentos simultâneos.', 'Identidade não é dado de nascimento nem escolha única. Ela se constrói na relação e comporta pertencimentos simultâneos.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-3', 'A', 'essência fixa, herdada e imutável.', false, 'A fala do jovem contradiz a ideia de pertencimento único e dado de antemão.', 'essencialismo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-3', 'B', 'confusão a ser resolvida pela escolha de um único pertencimento.', false, 'Não há exigência de escolha exclusiva; a combinação é a própria identidade.', 'exigir exclusividade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-3', 'C', 'perda cultural provocada pela migração.', false, 'O relato descreve acúmulo de referências, não perda.', 'inverter a leitura');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-3', 'D', 'adesão superficial a duas culturas, sem pertencimento real.', false, 'Nada no relato indica superficialidade.', 'julgamento sem base');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-3', 'E', 'construção relacional e múltipla, que combina referências e se reelabora ao longo da vida.', true, 'Identidades se formam na relação com os outros e podem articular mais de um pertencimento sem contradição.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cult-4', 'cultura-e-identidade', 'analisar-cultura-identidade-e-diversidade', 'intermediate', 'comparison', false, 'Comparando etnocentrismo e relativismo cultural como posturas diante da diferença, é correto afirmar que:', 'Relativismo metodológico é ferramenta de compreensão: entender antes de julgar. Isso não obriga a aprovar tudo o que se compreende.', 'Relativismo metodológico é ferramenta de compreensão: entender antes de julgar. Isso não obriga a aprovar tudo o que se compreende.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-4', 'A', 'o etnocentrismo é uma postura científica e o relativismo, uma opinião.', false, 'A relação é inversa: o relativismo metodológico é ferramenta de pesquisa.', 'inverter os termos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-4', 'B', 'o etnocentrismo toma a própria cultura como medida de todas; o relativismo metodológico busca compreender cada prática em seu próprio contexto.', true, 'Uma postura avalia de fora com régua própria; a outra suspende a régua para entender o sentido interno da prática.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-4', 'C', 'o relativismo cultural impede qualquer descrição de práticas sociais.', false, 'Ele orienta a descrição, em vez de impedi-la.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-4', 'D', 'as duas posturas foram abandonadas pela antropologia.', false, 'O relativismo metodológico segue central na disciplina.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-4', 'E', 'ambos julgam o outro a partir dos próprios valores.', false, 'O relativismo procura justamente suspender esse julgamento imediato.', 'igualar as posturas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-cult-5', 'cultura-e-identidade', 'analisar-cultura-identidade-e-diversidade', 'challenging', 'integration', false, 'Uma escola decide incluir no currículo a história e a cultura africana e indígena. Um grupo alega que isso "divide os alunos". Analisando a proposta:', 'Currículo é escolha sobre o que merece ser conhecido por todos. Incluir matrizes formadoras amplia o comum em vez de fragmentá-lo.', 'Currículo é escolha sobre o que merece ser conhecido por todos. Incluir matrizes formadoras amplia o comum em vez de fragmentá-lo.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-5', 'A', 'a proposta é indiferente, pois currículo não afeta identidade.', false, 'O que a escola ensina participa da formação da identidade dos estudantes.', 'negar o efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-5', 'B', 'a proposta deveria ser facultativa para cada família.', false, 'Conteúdo curricular obrigatório não se define por adesão individual.', 'solução incompatível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-5', 'C', 'a alegação procede, pois reconhecer diferenças enfraquece a unidade nacional.', false, 'Unidade construída pelo apagamento de parte da população é frágil e excludente.', 'opor reconhecimento e unidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-5', 'D', 'a inclusão amplia o repertório comum ao reconhecer matrizes que já formam a sociedade brasileira, e é exigida por lei.', true, 'Reconhecer as matrizes constitutivas do país integra em vez de dividir, e a inclusão desses conteúdos é obrigação legal.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-cult-5', 'E', 'a alegação procede, pois currículos devem tratar apenas de história europeia.', false, 'A formação brasileira não se explica sem essas matrizes.', 'recorte incorreto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-trab-1', 'trabalho-e-sociedade', 'analisar-transformacoes-do-mundo-do-trabalho', 'intro', 'concept', false, 'O modelo de organização do trabalho baseado na cronometragem de tempos e movimentos e na separação entre planejamento e execução é conhecido como:', 'Taylorismo é a administração científica: medir, padronizar e separar concepção de execução.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-1', 'A', 'Corporativismo.', false, 'Corporativismo se refere à relação entre Estado e categorias profissionais.', 'confundir com arranjo político');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-1', 'B', 'Mercantilismo.', false, 'Mercantilismo é uma política econômica dos séculos XVI a XVIII.', 'trocar o campo conceitual');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-1', 'C', 'Taylorismo.', true, 'A administração científica de Taylor cronometrava tarefas e separava quem concebe de quem executa.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-1', 'D', 'Toyotismo.', false, 'O toyotismo enfatiza produção sob demanda, estoque mínimo e trabalhador multifuncional.', 'trocar de modelo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-1', 'E', 'Cooperativismo.', false, 'Cooperativismo é forma de propriedade e gestão coletiva, não método de organização fabril.', 'confundir com modelo de propriedade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-trab-2', 'trabalho-e-sociedade', 'analisar-transformacoes-do-mundo-do-trabalho', 'intermediate', 'applied', false, 'Uma pessoa trabalha diariamente como entregadora por aplicativo, cumpre longas jornadas, arca com combustível e manutenção da moto e não possui contrato de trabalho.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-2', 'A', 'Trabalho informal em condições de precarização, com transferência de custos e riscos ao trabalhador.', true, 'Há trabalho contínuo e renda, sem contrato, sem proteção previdenciária automática e com os custos operacionais deslocados para quem executa a tarefa.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-2', 'B', 'Trabalho voluntário, por não haver subordinação formal.', false, 'Há remuneração por tarefa, o que descarta voluntariado.', 'confundir com trabalho não remunerado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-2', 'C', 'Emprego formal atípico, com direitos equivalentes aos da CLT.', false, 'A ausência de contrato afasta os direitos previstos na legislação trabalhista.', 'igualar situações distintas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-2', 'D', 'Desemprego, pois não há vínculo formal com uma empresa.', false, 'A pessoa trabalha e obtém renda: não está desempregada.', 'confundir informalidade com desemprego');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-2', 'E', 'Trabalho autônomo plenamente protegido pela legislação.', false, 'Sem contrato e sem contribuição, a proteção social é frágil.', 'supor proteção inexistente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-trab-3', 'trabalho-e-sociedade', 'analisar-transformacoes-do-mundo-do-trabalho', 'intermediate', 'interpretation', false, 'Uma pesquisa registrou, em determinado país, a média semanal de horas dedicadas a afazeres domésticos e cuidados:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-3', 'A', 'Os dados mostram que o trabalho doméstico é irrelevante para a economia.', false, 'Trata-se de trabalho que produz valor e sustenta a economia remunerada.', 'desconsiderar o valor do trabalho reprodutivo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-3', 'B', 'A diferença desaparece quando as mulheres trabalham fora de casa.', false, 'Pesquisas indicam acúmulo de jornadas, não substituição.', 'supor efeito não observado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-3', 'C', 'O dado só teria sentido se incluísse a renda de cada grupo.', false, 'O dado de tempo já sustenta a análise sobre divisão do trabalho.', 'exigir informação desnecessária');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-3', 'D', 'Há uma divisão sexual do trabalho que concentra o trabalho de cuidado nas mulheres, reduzindo seu tempo disponível para trabalho remunerado, estudo e descanso.', true, 'A diferença de mais de dez horas semanais é sistemática e compete diretamente com atividades que geram renda e qualificação, o que ajuda a explicar desigualdades de carreira e de aposentadoria.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-3', 'E', 'A diferença resulta de preferências individuais e não tem efeitos sociais relevantes.', false, 'A diferença é estrutural e afeta renda, carreira e aposentadoria.', 'individualizar padrão estrutural');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-trab-4', 'trabalho-e-sociedade', 'analisar-transformacoes-do-mundo-do-trabalho', 'challenging', 'comparison', false, 'Considere duas leituras sobre automação e emprego:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-4', 'A', 'I está correta, pois a tecnologia substitui trabalhadores de forma definitiva.', false, 'Historicamente, funções desaparecem e outras surgem; o desaparecimento total do emprego não se verificou.', 'aceitar previsão catastrófica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-4', 'B', 'II está correta, pois a história mostra que o emprego sempre se recupera.', false, 'A recuperação agregada convive com perdas concretas para grupos específicos.', 'aceitar otimismo agregado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-4', 'C', 'As duas estão corretas em contextos diferentes e se aplicam a países distintos.', false, 'A limitação das duas leituras não é geográfica: ambas simplificam o mesmo processo.', 'relativizar sem critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-4', 'D', 'Ambas simplificam o processo: a automação elimina e cria ocupações simultaneamente, com efeitos desiguais entre grupos, o que torna a transição um problema de política pública.', true, 'A questão relevante não é o saldo agregado, e sim quem perde, quem ganha e o que se faz com quem é deslocado — o que envolve qualificação, proteção de renda e regulação.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-4', 'E', 'Nenhuma das duas tem relação com o debate sociológico sobre trabalho.', false, 'As duas são posições recorrentes no debate público sobre o tema.', 'negar a pertinência do debate');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-trab-5', 'trabalho-e-sociedade', 'analisar-transformacoes-do-mundo-do-trabalho', 'challenging', 'integration', false, 'Um município quer reduzir a informalidade entre trabalhadores de serviços e entregas. A equipe técnica avalia diferentes caminhos.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-5', 'A', 'Proibir a atuação de plataformas digitais no município.', false, 'A proibição elimina renda imediata sem oferecer alternativa, e desloca o problema.', 'trocar política por interdição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-5', 'B', 'Realizar campanhas de conscientização sobre a importância da formalização, sem outras medidas.', false, 'Informação é insuficiente quando o obstáculo é econômico e estrutural.', 'reduzir política a comunicação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-5', 'C', 'Fiscalizar e multar os trabalhadores que atuam sem registro, o que os incentivaria a formalizar a atividade.', false, 'Punir quem já está em situação frágil tende a aprofundar a precariedade, sem alterar as causas.', 'punir o elo mais frágil');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-5', 'D', 'Combinar simplificação do registro e da contribuição, negociação com as empresas que intermediam o serviço, ampliação do acesso à proteção social e monitoramento dos resultados ao longo do tempo.', true, 'A informalidade tem causas múltiplas — custo e complexidade da formalização, modelo de negócio das plataformas e lacunas de proteção. Uma política eficaz atua nesses três pontos e verifica se os resultados aparecem.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-5', 'E', 'Aguardar que o crescimento econômico reduza espontaneamente a informalidade.', false, 'Períodos de crescimento no Brasil já conviveram com informalidade elevada.', 'esperar solução automática');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-trab-rec-1', 'trabalho-e-sociedade', 'analisar-transformacoes-do-mundo-do-trabalho', 'intro', 'concept', true, 'A conquista da jornada de trabalho de oito horas diárias, no século XX, resultou principalmente:', 'Direitos trabalhistas são resultado de conflito social organizado — o que ajuda a entender por que continuam em disputa.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-rec-1', 'A', 'De uma concessão espontânea dos empregadores diante do avanço tecnológico.', false, 'A redução de jornada foi objeto de disputa, não de concessão espontânea.', 'atribuir a iniciativa ao empregador');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-rec-1', 'B', 'De uma exigência técnica das máquinas, que não podiam operar por mais tempo.', false, 'A limitação não era técnica, e sim social e política.', 'naturalizar uma conquista social');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-rec-1', 'C', 'Da organização e da mobilização dos trabalhadores, com greves e pressão política ao longo de décadas.', true, 'Sindicatos, greves e disputa parlamentar sustentaram a redução progressiva da jornada, que depois foi incorporada à legislação.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-rec-1', 'D', 'De acordos internacionais firmados antes da industrialização.', false, 'Os acordos internacionais sobre jornada são posteriores à industrialização.', 'inverter a cronologia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-trab-rec-1', 'E', 'Da automação, que reduziu a necessidade de trabalho humano.', false, 'A automação em larga escala é posterior às primeiras conquistas de jornada.', 'antecipar processo posterior');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-trab-1', 'trabalho-e-sociedade', 'analisar-transformacoes-do-mundo-do-trabalho', 'intro', 'concept', false, 'A diferença entre emprego formal e trabalho informal, no Brasil, está principalmente em:', 'O que separa formal de informal é o vínculo registrado e a proteção que ele aciona, não o tipo, o valor ou o lugar do trabalho.', 'O que separa formal de informal é o vínculo registrado e a proteção que ele aciona, não o tipo, o valor ou o lugar do trabalho.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-1', 'A', 'no valor da remuneração recebida.', false, 'Há informalidade com renda alta e formalidade com renda baixa.', 'critério de renda');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-1', 'B', 'no registro da relação de trabalho e no acesso a direitos e proteção previdenciária.', true, 'A formalização é o que vincula a pessoa a férias, décimo terceiro, seguro-desemprego e contribuição previdenciária.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-1', 'C', 'no local em que o trabalho é realizado.', false, 'Trabalho em casa pode ser formal, e trabalho em empresa pode ser informal.', 'critério de local');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-1', 'D', 'na carga horária cumprida por semana.', false, 'Jornadas variadas existem nas duas condições.', 'critério de jornada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-1', 'E', 'no tipo de atividade exercida pelo trabalhador.', false, 'A mesma atividade pode ser exercida nas duas condições.', 'critério de atividade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-trab-2', 'trabalho-e-sociedade', 'analisar-transformacoes-do-mundo-do-trabalho', 'intermediate', 'applied', false, 'Um entregador de aplicativo define seus horários, mas o preço da corrida, a rota sugerida e o acesso à plataforma são determinados pela empresa. Esse arranjo é analisado nas ciências sociais como:', 'Escolher quando trabalhar não é o mesmo que decidir como e por quanto. É essa diferença que a análise do trabalho por plataformas procura tornar visível.', 'Escolher quando trabalhar não é o mesmo que decidir como e por quanto. É essa diferença que a análise do trabalho por plataformas procura tornar visível.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-2', 'A', 'trabalho voluntário, por não haver contrato.', false, 'Há remuneração e finalidade econômica.', 'classificação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-2', 'B', 'autonomia parcial combinada com controle exercido pela plataforma sobre remuneração e condições de trabalho.', true, 'A escolha do horário não altera quem define o preço, a rota e o acesso à atividade.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-2', 'C', 'forma de trabalho sem qualquer subordinação.', false, 'Há subordinação exercida por meios digitais, ainda que não pela figura de um chefe presente.', 'negar a subordinação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-2', 'D', 'trabalho autônomo pleno, pois há liberdade de horário.', false, 'A liberdade de horário convive com controle sobre preço, rota e permanência.', 'reduzir autonomia a horário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-2', 'E', 'emprego formal com jornada flexível.', false, 'Não há registro do vínculo nem os direitos que dele decorrem.', 'classificação incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-trab-3', 'trabalho-e-sociedade', 'analisar-transformacoes-do-mundo-do-trabalho', 'intermediate', 'interpretation', false, 'Uma empresa anuncia que a automação de um setor "libera os trabalhadores para tarefas mais criativas". Sobre esse anúncio, a leitura mais atenta observa que:', 'Discursos sobre automação costumam falar do processo e não das pessoas. A pergunta que decide o efeito social é o que acontece com quem ocupava o posto.', 'Discursos sobre automação costumam falar do processo e não das pessoas. A pergunta que decide o efeito social é o que acontece com quem ocupava o posto.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-3', 'A', 'a frase é neutra, pois descreve um fato técnico.', false, 'Ela é uma formulação escolhida, que enquadra o processo de um modo favorável.', 'supor neutralidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-3', 'B', 'a formulação apaga a pergunta central: quem de fato é realocado, com que qualificação e em que condições.', true, '"Liberar" pressupõe realocação, que depende de política de requalificação e nem sempre acontece.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-3', 'C', 'a automação sempre aumenta o número de postos de trabalho.', false, 'O efeito líquido varia por setor e período, e não é automático.', 'generalização otimista');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-3', 'D', 'a automação sempre reduz o número de postos de trabalho.', false, 'O efeito também não é automaticamente negativo.', 'generalização pessimista');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-3', 'E', 'tarefas criativas não podem ser automatizadas em nenhuma hipótese.', false, 'A fronteira do que se automatiza vem se deslocando.', 'afirmação absoluta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-trab-4', 'trabalho-e-sociedade', 'analisar-transformacoes-do-mundo-do-trabalho', 'intermediate', 'comparison', false, 'Comparando a jornada de trabalho no século XIX europeu e a jornada regulada no Brasil atual, a diferença central decorre de:', 'A jornada de oito horas não é resultado natural do progresso: é conquista disputada e depois inscrita em lei.', 'A jornada de oito horas não é resultado natural do progresso: é conquista disputada e depois inscrita em lei.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-4', 'A', 'redução da população disponível para o trabalho.', false, 'A população trabalhadora cresceu no período.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-4', 'B', 'mudança no clima e nas condições de saúde das cidades.', false, 'Condições sanitárias influenciaram o debate, mas não são a causa central.', 'causa periférica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-4', 'C', 'iniciativa espontânea dos empregadores em busca de produtividade.', false, 'Ganhos de produtividade foram argumentos posteriores, e não a origem da mudança.', 'inverter a causa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-4', 'D', 'avanço tecnológico, que tornou desnecessárias jornadas longas.', false, 'A tecnologia criou a possibilidade, mas não determinou a redução da jornada por si.', 'determinismo tecnológico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-4', 'E', 'organização dos trabalhadores e regulação estatal, que transformaram a jornada em objeto de lei.', true, 'Limites de jornada resultam de conflito social convertido em legislação, e não de concessão espontânea.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-trab-5', 'trabalho-e-sociedade', 'analisar-transformacoes-do-mundo-do-trabalho', 'challenging', 'integration', false, 'Um país registra queda no desemprego acompanhada de aumento do trabalho por conta própria sem contribuição previdenciária. Avaliando esse quadro:', 'Indicadores agregados escondem a qualidade da inserção. Ocupação sem proteção transfere para o futuro um custo que hoje não aparece na estatística.', 'Indicadores agregados escondem a qualidade da inserção. Ocupação sem proteção transfere para o futuro um custo que hoje não aparece na estatística.', 'Ao ler dados de mercado de trabalho, olhe sempre dois indicadores juntos: quantos estão ocupados e em que condição estão.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-5', 'A', 'os dois dados são contraditórios e um deles deve estar incorreto.', false, 'Eles são perfeitamente compatíveis e ocorrem juntos com frequência.', 'supor erro nos dados');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-5', 'B', 'a ausência de contribuição previdenciária não tem efeito relevante.', false, 'Ela afeta aposentadoria, auxílio-doença e proteção em caso de acidente.', 'minimizar o efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-5', 'C', 'a queda do desemprego não basta como avaliação: é preciso examinar a qualidade das ocupações e a proteção social associada a elas.', true, 'Menos desemprego com mais informalidade indica um mercado que absorve pessoas sem lhes garantir direitos, e o efeito da falta de contribuição aparece anos depois.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-5', 'D', 'o quadro é inequivocamente positivo, pois menos pessoas estão desempregadas.', false, 'A taxa isolada não informa em que condições as pessoas estão trabalhando.', 'reduzir ao indicador');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-trab-5', 'E', 'o quadro é inequivocamente negativo, pois todo trabalho por conta própria é precário.', false, 'Há trabalho por conta própria qualificado e bem remunerado.', 'generalização');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-eco-1', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'intro', 'concept', false, 'Em um ecossistema, os produtores fixam 15.000 kcal/m²/ano. Considerando uma transferência média de 10% entre níveis tróficos, a energia disponível para os consumidores secundários é de aproximadamente:', 'Produtores → primários → secundários são duas etapas de 10%: 15.000 × 0,1 × 0,1 = 150.', NULL, 'Escreva a cadeia com setas e conte quantas setas separam o nível pedido dos produtores.', NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-1', 'A', '15 kcal/m²/ano', false, 'Corresponde aos consumidores terciários, uma transferência além do pedido.', 'contar uma transferência a mais');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-1', 'B', '7.500 kcal/m²/ano', false, 'Corresponde a 50% de transferência, e não aos 10% informados.', 'usar percentual incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-1', 'C', '15.000 kcal/m²/ano', false, 'É o valor fixado pelos produtores, antes de qualquer transferência.', 'não aplicar a perda');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-1', 'D', '1.500 kcal/m²/ano', false, 'Esse é o valor dos consumidores primários — apenas uma transferência a partir dos produtores.', 'contar uma transferência a menos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-1', 'E', '150 kcal/m²/ano', true, 'São duas transferências: 15.000 → 1.500 (primários) → 150 (secundários).', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-eco-2', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'intermediate', 'applied', false, 'Um lago próximo a área agrícola recebe grande quantidade de fertilizantes por escoamento. Semanas depois, observa-se intensa proliferação de algas e, em seguida, mortandade de peixes.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-2', 'A', 'A liberação de gás carbônico pelas algas durante a fotossíntese.', false, 'Na fotossíntese as algas consomem CO₂ e liberam O₂; o processo descrito está invertido.', 'inverter reagentes e produtos da fotossíntese');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-2', 'B', 'O consumo direto das algas pelos peixes, que causa intoxicação em todos os casos.', false, 'Algumas florações produzem toxinas, mas o mecanismo geral e mais frequente da mortandade é a queda do oxigênio.', 'generalizar um caso particular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-2', 'C', 'O aumento da luminosidade na superfície do lago.', false, 'A proliferação de algas reduz a penetração de luz, não a aumenta.', 'inverter o efeito sobre a luz');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-2', 'D', 'A elevação do pH provocada pelos fertilizantes ao entrar em contato com a água.', false, 'Alterações de pH podem ocorrer, mas não são o mecanismo central descrito no processo de eutrofização.', 'escolher um efeito secundário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-2', 'E', 'A redução do oxigênio dissolvido durante a decomposição da matéria orgânica acumulada.', true, 'As algas morrem em massa e sua decomposição consome oxigênio dissolvido. Os peixes morrem por asfixia — a causa é indireta.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-eco-3', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'intermediate', 'interpretation', false, 'A tabela apresenta a concentração de um poluente persistente em organismos de um mesmo ambiente aquático:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-3', 'A', 'Decomposição progressiva do poluente ao longo da cadeia.', false, 'Se houvesse decomposição, a concentração cairia ao subir a cadeia.', 'ler o dado ao contrário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-3', 'B', 'Equilíbrio da concentração entre todos os níveis tróficos.', false, 'A variação é de mais de mil vezes entre o primeiro e o último nível.', 'ignorar a magnitude da variação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-3', 'C', 'Biomagnificação, com aumento da concentração a cada nível trófico.', true, 'A concentração multiplica-se cerca de dez vezes a cada nível. Isso caracteriza biomagnificação: o predador concentra o que estava disperso em muitas presas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-3', 'D', 'Bioacumulação exclusivamente individual, sem relação com a cadeia.', false, 'Bioacumulação ocorre dentro do indivíduo. Os dados mostram progressão **entre níveis**, o que caracteriza biomagnificação.', 'confundir os dois conceitos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-3', 'E', 'Produção crescente do poluente pelos organismos de níveis superiores.', false, 'Os organismos não produzem o poluente: eles o acumulam a partir do alimento.', 'inverter origem do poluente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-eco-4', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'challenging', 'comparison', false, 'Considere duas afirmações sobre ecossistemas:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-4', 'A', 'I e II.', true, 'As duas afirmações descrevem os dois princípios complementares: energia flui em sentido único e se dissipa; matéria cicla e é reutilizada.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-4', 'B', 'Nenhuma das duas.', false, 'Ambas correspondem a princípios básicos da ecologia.', 'excesso de cautela');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-4', 'C', 'I e II, mas apenas em ecossistemas aquáticos.', false, 'Os dois princípios valem para qualquer ecossistema.', 'restringir indevidamente o alcance');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-4', 'D', 'I, apenas.', false, 'I está correta, mas II também: a matéria cicla, então os mesmos átomos são reutilizados indefinidamente.', 'não reconhecer a ciclagem da matéria');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-4', 'E', 'II, apenas.', false, 'II está correta, mas I também descreve corretamente o fluxo unidirecional da energia.', 'não reconhecer o fluxo da energia');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-eco-5', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'challenging', 'integration', false, 'Uma proposta de recuperação de uma área degradada prevê o plantio exclusivo de uma única espécie de crescimento rápido, com corte previsto em sete anos.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-5', 'A', 'A cobertura vegetal por uma única espécie não reconstitui as interações e a diversidade necessárias para restabelecer as funções do ecossistema.', true, 'Restauração ecológica exige diversidade de espécies, presença de polinizadores e dispersores e retomada da sucessão. Uma monocultura cobre o solo, mas não recompõe a teia de interações nem os ciclos associados.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-5', 'B', 'Espécies de crescimento rápido não realizam fotossíntese de forma eficiente.', false, 'Crescimento rápido normalmente indica alta eficiência fotossintética, não o contrário.', 'inverter relação fisiológica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-5', 'C', 'O plantio de árvores nunca contribui para a recuperação de áreas degradadas.', false, 'O plantio contribui — a limitação está na baixa diversidade e no manejo previsto, não no ato de plantar.', 'generalizar a crítica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-5', 'D', 'A área deveria permanecer sem intervenção para que se recupere sozinha.', false, 'Em áreas muito degradadas, a regeneração natural pode não ocorrer sem intervenção. A crítica é ao desenho da intervenção.', 'trocar uma solução simplista por outra');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-5', 'E', 'Sete anos é tempo suficiente para a plena recuperação de qualquer ecossistema.', false, 'A restauração de funções ecossistêmicas costuma levar décadas, o que reforça a limitação da proposta.', 'subestimar o tempo da sucessão');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-eco-rec-1', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'intro', 'concept', true, 'Em uma cadeia alimentar, os organismos capazes de produzir seu próprio alimento a partir da energia solar são chamados de:', 'Produtores são a porta de entrada da energia no ecossistema.', NULL, NULL, NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-rec-1', 'A', 'Produtores.', true, 'Produtores (autótrofos) convertem energia luminosa em matéria orgânica pela fotossíntese, sustentando os demais níveis.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-rec-1', 'B', 'Consumidores primários.', false, 'Consumidores primários se alimentam dos produtores; não produzem o próprio alimento.', 'confundir níveis adjacentes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-rec-1', 'C', 'Decompositores.', false, 'Decompositores obtêm energia da matéria orgânica morta.', 'confundir com o papel de reciclagem');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-rec-1', 'D', 'Consumidores terciários.', false, 'Estão no topo da cadeia e dependem de outros consumidores.', 'inverter a posição na cadeia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-rec-1', 'E', 'Detritívoros.', false, 'Detritívoros consomem restos orgânicos, sem produzir o próprio alimento.', 'confundir com decomposição');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-eco-rec-2', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'intermediate', 'applied', true, 'A remoção de um predador de topo de um ecossistema tende a provocar, inicialmente:', 'O efeito se propaga em cascata pela cadeia, começando pelo aumento das presas.', NULL, NULL, NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-rec-2', 'A', 'Aumento imediato da população de produtores.', false, 'Com mais herbívoros, os produtores tendem a sofrer maior consumo.', 'pular níveis na cadeia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-rec-2', 'B', 'Nenhuma alteração, pois predadores de topo são pouco numerosos.', false, 'Predadores de topo exercem controle desproporcional à sua abundância.', 'confundir número com importância ecológica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-rec-2', 'C', 'Extinção imediata de todos os níveis inferiores.', false, 'O efeito é de desequilíbrio e oscilação, não de extinção instantânea generalizada.', 'exagerar a magnitude do efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-rec-2', 'D', 'Aumento da população de suas presas, com pressão crescente sobre os níveis inferiores.', true, 'Sem controle predatório, as presas crescem em número e passam a consumir mais dos níveis abaixo, o que se propaga pela cadeia.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-rec-2', 'E', 'Redução imediata da população de suas presas.', false, 'Sem o predador, a pressão sobre as presas diminui, o que tende a aumentar sua população.', 'inverter o efeito');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-eco-6', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'intro', 'concept', false, 'Em uma cadeia alimentar capim → gafanhoto → sapo → serpente, a quantidade de energia disponível tende a:', 'A energia entra principalmente pelos produtores e diminui a cada nível por respiração, calor e matéria não consumida.', 'A energia entra principalmente pelos produtores e diminui a cada nível por respiração, calor e matéria não consumida.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-6', 'A', 'Aumentar em cada nível porque os consumidores acumulam alimento.', false, 'Parte da energia é dissipada em metabolismo e calor a cada transferência.', 'inverter pirâmide energética');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-6', 'B', 'Permanecer igual porque a matéria é conservada.', false, 'Conservação da matéria não implica transferência integral de energia útil.', 'confundir matéria e energia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-6', 'C', 'Diminuir nos níveis superiores devido às perdas metabólicas em cada transferência.', true, 'Somente uma fração da energia incorporada passa ao nível seguinte.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-6', 'D', 'Ser maior na serpente por ela ocupar o último nível.', false, 'A posição superior indica menor, não maior, energia disponível.', 'associar topo a maior quantidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-6', 'E', 'Circular integralmente e retornar ao capim.', false, 'Energia flui e se dissipa; nutrientes é que participam de ciclos.', 'tratar energia como ciclo fechado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-eco-7', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'intermediate', 'applied', false, 'Um lago recebe excesso de esgoto rico em nitrogênio e fósforo. Após intensa proliferação de algas, ocorre mortandade de peixes. O mecanismo mais provável é:', 'Na eutrofização, nutrientes estimulam algas; a decomposição posterior eleva a demanda de oxigênio e pode sufocar organismos aquáticos.', 'Na eutrofização, nutrientes estimulam algas; a decomposição posterior eleva a demanda de oxigênio e pode sufocar organismos aquáticos.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-7', 'A', 'O nitrogênio transforma diretamente peixes em decompositores.', false, 'Nutrientes não alteram o papel biológico dessa forma.', 'mecanismo inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-7', 'B', 'As algas removem todo o fósforo e tornam a água destilada.', false, 'A água não se torna destilada, e o problema central é oxigênio dissolvido.', 'conclusão absurda');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-7', 'C', 'A luz aumenta no fundo e interrompe a fotossíntese.', false, 'A proliferação tende a reduzir luz em profundidade.', 'inverter efeito óptico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-7', 'D', 'Os peixes passam a produzir menos matéria orgânica.', false, 'A mortandade decorre de alteração ambiental, não dessa mudança produtiva.', 'causalidade sem base');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-7', 'E', 'A decomposição da biomassa aumenta o consumo de oxigênio dissolvido, causando hipóxia.', true, 'Microrganismos decompositores consomem oxigênio ao degradar o excesso de matéria orgânica.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-eco-8', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'intermediate', 'interpretation', false, 'Após desmatamento seguido de queimada, medições indicam aumento de CO₂ atmosférico e redução de carbono na biomassa local. Esses dados se explicam porque:', 'Queimada transfere rapidamente carbono da biomassa para a atmosfera, e a perda de vegetação enfraquece o sumidouro de carbono.', 'Queimada transfere rapidamente carbono da biomassa para a atmosfera, e a perda de vegetação enfraquece o sumidouro de carbono.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-8', 'A', 'O CO₂ atmosférico se converte integralmente em oxigênio sem plantas.', false, 'A conversão fotossintética depende de organismos produtores.', 'mecanismo invertido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-8', 'B', 'A queima libera carbono armazenado e a retirada da vegetação reduz a captura futura por fotossíntese.', true, 'A mudança atua simultaneamente na emissão e na remoção de CO₂.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-8', 'C', 'O desmatamento cria carbono novo a partir do nada.', false, 'O carbono é transferido entre reservatórios; não é criado.', 'violar conservação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-8', 'D', 'A fotossíntese passa a liberar mais CO₂ que a combustão.', false, 'Fotossíntese retira CO₂ da atmosfera; sua redução é parte do problema.', 'inverter processo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-8', 'E', 'O solo deixa de conter qualquer elemento químico.', false, 'O solo continua contendo matéria; a afirmação é absoluta e falsa.', 'generalização');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-eco-9', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'challenging', 'comparison', false, 'Compare duas áreas agrícolas: I. monocultura extensa com solo exposto entre safras; II. rotação de culturas, cobertura do solo e faixas de vegetação nativa. A área II tende a apresentar:', 'Diversificação e cobertura conectam produção a processos ecológicos como controle de erosão, ciclagem e manutenção de habitat.', 'Diversificação e cobertura conectam produção a processos ecológicos como controle de erosão, ciclagem e manutenção de habitat.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-9', 'A', 'Ausência completa de pragas.', false, 'Manejo diverso pode reduzir riscos, mas não elimina todas as pragas.', 'promessa absoluta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-9', 'B', 'Maior proteção do solo e diversidade de funções ecológicas.', true, 'Cobertura, rotação e vegetação nativa favorecem ciclagem, infiltração e habitat.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-9', 'C', 'Interrupção total do ciclo de nutrientes.', false, 'Rotação e matéria orgânica podem fortalecer a ciclagem.', 'contradição ecológica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-9', 'D', 'Menor diversidade por ter mais tipos de cobertura.', false, 'Diversidade de culturas e vegetação tende a ampliar habitats.', 'inverter relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-9', 'E', 'Maior erosão porque o solo permanece coberto.', false, 'Cobertura reduz impacto da chuva e perda de partículas.', 'inverter efeito');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-eco-10', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'challenging', 'integration', false, 'A redução de polinizadores pode afetar plantas silvestres, produção de frutos e animais que dependem desses frutos. Essa sequência mostra:', 'Redes ecológicas conectam espécies e economia: impactos sobre uma interação podem gerar efeitos em cascata diretos e indiretos.', 'Redes ecológicas conectam espécies e economia: impactos sobre uma interação podem gerar efeitos em cascata diretos e indiretos.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-10', 'A', 'Que polinizadores influenciam apenas a agricultura comercial.', false, 'Plantas silvestres também dependem de polinização.', 'reduzir alcance');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-10', 'B', 'Uma alteração em uma interação ecológica pode se propagar pela rede e por atividades humanas.', true, 'Menos polinização afeta reprodução vegetal, alimento e produção.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-10', 'C', 'Que frutos são produtores de polinizadores.', false, 'Frutos são estruturas vegetais; não produzem animais.', 'trocar relações');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-10', 'D', 'Que todos os animais dependem diretamente de néctar.', false, 'A cadeia descrita inclui dependências indiretas por frutos.', 'generalização');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-eco-10', 'E', 'Que a produção agrícola não possui relação com biodiversidade.', false, 'O exemplo demonstra exatamente a relação.', 'negação da premissa');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-eco-1', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'intro', 'concept', false, 'Em uma cadeia alimentar, a quantidade de energia disponível diminui a cada nível trófico. A principal razão para essa perda é que:', 'Energia flui em sentido único e se dissipa como calor a cada transferência. Matéria, ao contrário, circula em ciclos.', 'Energia flui em sentido único e se dissipa como calor a cada transferência. Matéria, ao contrário, circula em ciclos.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-1', 'A', 'os predadores comem menos do que precisam.', false, 'A perda ocorre mesmo com alimentação adequada.', 'causa incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-1', 'B', 'os decompositores retiram a energia dos organismos vivos.', false, 'Os decompositores atuam sobre matéria orgânica morta.', 'papel trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-1', 'C', 'parte da energia é usada nos processos vitais e liberada como calor, não sendo transferida adiante.', true, 'Respiração, movimento e manutenção corporal consomem energia que sai do sistema como calor.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-1', 'D', 'a fotossíntese ocorre apenas no primeiro nível.', false, 'A fotossíntese de fato ocorre nos produtores, mas isso não explica a perda entre os níveis seguintes.', 'explicação insuficiente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-1', 'E', 'a matéria desaparece ao passar de um nível para outro.', false, 'A matéria é conservada e reciclada; o que se dissipa é energia.', 'confundir matéria com energia');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-eco-2', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'intermediate', 'applied', false, 'Um lago recebe esgoto rico em nitrogênio e fósforo. Semanas depois, ocorre proliferação intensa de algas e morte de peixes. A explicação para a morte dos peixes é:', 'Eutrofização é uma cadeia: excesso de nutrientes, explosão de algas, morte delas, decomposição intensa e queda do oxigênio dissolvido.', 'Eutrofização é uma cadeia: excesso de nutrientes, explosão de algas, morte delas, decomposição intensa e queda do oxigênio dissolvido.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-2', 'A', 'a água esquenta e evapora, reduzindo o volume do lago.', false, 'Não há relação necessária entre eutrofização e evaporação.', 'mecanismo trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-2', 'B', 'as algas bloqueiam a alimentação dos peixes por competição direta.', false, 'Peixes e algas não competem pelo mesmo alimento.', 'relação ecológica incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-2', 'C', 'as algas consomem diretamente os peixes.', false, 'Algas são produtoras e não predam peixes.', 'papel trófico incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-2', 'D', 'a decomposição da grande massa de algas consome o oxigênio dissolvido, e os peixes morrem por asfixia.', true, 'O excesso de nutrientes gera muita alga; quando elas morrem, a decomposição bacteriana consome o oxigênio da água.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-2', 'E', 'o nitrogênio é tóxico para peixes em qualquer concentração.', false, 'O problema decorre do excesso de nutrientes e seus efeitos, não de toxicidade direta em qualquer nível.', 'simplificação incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-eco-3', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'intermediate', 'interpretation', false, 'Um gráfico mostra a concentração de um poluente persistente ao longo de uma cadeia alimentar aquática, com valores crescentes do plâncton até o peixe predador de topo. Esse padrão é explicado por:', 'Magnificação trófica combina duas coisas: o composto não é eliminado e cada nível consome muitos indivíduos do nível anterior.', 'Magnificação trófica combina duas coisas: o composto não é eliminado e cada nível consome muitos indivíduos do nível anterior.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-3', 'A', 'transformação química do poluente no interior dos peixes.', false, 'A persistência significa justamente que o composto resiste à degradação.', 'contradizer a persistência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-3', 'B', 'maior exposição direta dos predadores à água contaminada.', false, 'A via principal é o alimento, e não o contato direto.', 'via de exposição incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-3', 'C', 'maior massa corporal dos predadores, que acumula mais substância.', false, 'A concentração é medida por unidade de massa, o que já desconta o tamanho.', 'confundir total com concentração');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-3', 'D', 'acúmulo do poluente ao longo da vida de cada organismo, somado ao consumo de muitas presas contaminadas.', true, 'Substâncias persistentes não são eliminadas e se somam a cada refeição, elevando a concentração nos níveis superiores.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-3', 'E', 'maior taxa metabólica dos organismos de topo.', false, 'Metabolismo mais alto tenderia a acelerar a eliminação, não o acúmulo.', 'mecanismo invertido');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-eco-4', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'intermediate', 'comparison', false, 'Comparando o ciclo do carbono e o ciclo da água quanto ao papel dos seres vivos, é correto afirmar que:', 'Comparar ciclos exige olhar quem move a matéria. No carbono, os organismos ocupam etapas centrais; na água, contribuem sem serem o motor principal.', 'Comparar ciclos exige olhar quem move a matéria. No carbono, os organismos ocupam etapas centrais; na água, contribuem sem serem o motor principal.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-4', 'A', 'apenas o ciclo da água envolve mudança de estado físico.', false, 'A afirmação é correta em si, mas não responde ao que se compara: o papel dos seres vivos.', 'resposta fora do pedido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-4', 'B', 'no ciclo do carbono os seres vivos apenas liberam carbono, sem fixá-lo.', false, 'A fotossíntese fixa carbono, e é etapa central do ciclo.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-4', 'C', 'no ciclo da água os seres vivos não participam de nenhuma etapa.', false, 'A transpiração vegetal é uma via importante de retorno de água à atmosfera.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-4', 'D', 'nos dois há participação biológica, mas no carbono ela é determinante, com fotossíntese e respiração como etapas centrais.', true, 'A água circula sobretudo por processos físicos, enquanto o carbono depende de reações realizadas por organismos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-4', 'E', 'em ambos os ciclos, os seres vivos são irrelevantes.', false, 'Eles participam dos dois, com pesos diferentes.', 'negar a participação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-eco-5', 'ecologia-e-ciclos', 'relacionar-seres-vivos-energia-materia-impactos', 'challenging', 'integration', false, 'Um projeto propõe restaurar a mata ciliar de um rio degradado. Além de recompor a vegetação, espera-se dessa ação:', 'Mata ciliar não é ornamento: ela segura o solo, filtra o escoamento superficial, sombreia a água e conecta habitats.', 'Mata ciliar não é ornamento: ela segura o solo, filtra o escoamento superficial, sombreia a água e conecta habitats.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-5', 'A', 'redução do assoreamento, filtragem de parte dos poluentes que chegam pelo escoamento e formação de corredor para a fauna.', true, 'A vegetação segura o solo, retém nutrientes antes que cheguem ao curso d’água e conecta fragmentos florestais.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-5', 'B', 'aumento imediato da vazão do rio em todas as estações.', false, 'A mata ciliar regula o fluxo; não há aumento imediato garantido da vazão.', 'efeito exagerado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-5', 'C', 'eliminação completa da necessidade de tratamento de esgoto.', false, 'A vegetação retém parte da carga difusa, mas não substitui tratamento de esgoto.', 'substituição indevida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-5', 'D', 'redução da biodiversidade local, pela competição entre espécies plantadas.', false, 'A restauração com espécies nativas tende a aumentar a diversidade.', 'efeito invertido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-eco-5', 'E', 'aquecimento da água pela redução do sombreamento.', false, 'A mata ciliar aumenta o sombreamento, não o contrário.', 'efeito invertido');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ene-1', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'intro', 'concept', false, 'Um ferro de passar de 1.200 W é utilizado durante 30 minutos por dia, ao longo de 30 dias.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-1', 'A', '18 kWh', true, '1,2 kW × 0,5 h = 0,6 kWh por dia; × 30 dias = 18 kWh.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-1', 'B', '36 kWh', false, 'Corresponde a usar 1 hora por dia em vez de 30 minutos.', 'não converter minutos em horas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-1', 'C', '1.200 kWh', false, 'Confunde a potência em watts com o consumo em quilowatt-hora.', 'confundir potência com energia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-1', 'D', '600 kWh', false, 'Corresponde a esquecer a conversão de watts para quilowatts.', 'esquecer a divisão por 1.000');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-1', 'E', '0,6 kWh', false, 'É o consumo de um único dia, não do mês.', 'parar antes de multiplicar pelos dias');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ene-2', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'intermediate', 'applied', false, 'Uma família troca 10 lâmpadas incandescentes de 60 W por lâmpadas de LED de 9 W, que produzem a mesma iluminação. O uso médio é de 5 horas por dia.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-2', 'A', '13,5 kWh', false, 'Corresponde ao consumo total das lâmpadas de LED.', 'responder o consumo novo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-2', 'B', '51 kWh', false, 'Usa a diferença de potência (51) diretamente como resultado, sem multiplicar pelo tempo e pela quantidade.', 'não completar o cálculo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-2', 'C', '76,5 kWh', true, 'Diferença por lâmpada: 60 − 9 = 51 W = 0,051 kW. Total: 0,051 × 10 × 5 h × 30 dias = 76,5 kWh.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-2', 'D', '7,65 kWh', false, 'Resultado de considerar apenas uma lâmpada em vez de dez.', 'esquecer a quantidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-2', 'E', '90 kWh', false, 'Corresponde ao consumo total das incandescentes, não à economia.', 'calcular consumo em vez de diferença');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ene-3', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'intermediate', 'interpretation', false, 'Uma usina termelétrica recebe 1.000 MJ de energia na forma de combustível e entrega 380 MJ na forma de energia elétrica.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-3', 'A', 'Foram convertidos integralmente em energia química no combustível restante.', false, 'A energia química é a entrada do processo, não o destino das perdas.', 'inverter entrada e saída');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-3', 'B', 'Foram transferidos ao ambiente, sobretudo como calor, permanecendo conservados mas em forma de menor aproveitamento.', true, 'A energia se conserva. O que se perde é a capacidade de realizar trabalho: os 620 MJ se dispersam como calor de baixa temperatura, difícil de reaproveitar.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-3', 'C', 'Foram destruídos durante o processo de conversão.', false, 'Energia não é destruída — esse é o princípio da conservação.', 'violar a conservação da energia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-3', 'D', 'Foram armazenados na usina para uso posterior.', false, 'Calor dissipado no ambiente não fica armazenado de forma utilizável.', 'confundir dissipação com armazenamento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-3', 'E', 'Correspondem a erro de medição, pois a eficiência deveria ser de 100%.', false, 'Eficiência de 100% é fisicamente impossível em conversões térmicas.', 'esperar eficiência total');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ene-4', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'challenging', 'comparison', false, 'Dois aparelhos são comparados:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-4', 'A', 'Y consome o dobro de X, pois 2 kWh/dia contra 1 kWh/dia.', true, 'X: 2 kW × 0,5 h = 1 kWh/dia. Y: 0,25 kW × 8 h = 2 kWh/dia. O aparelho de menor potência consome mais por ficar ligado oito vezes mais tempo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-4', 'B', 'X consome mais, pois tem potência oito vezes maior.', false, 'Potência maior não implica consumo maior quando o tempo de uso é muito menor.', 'comparar só pela potência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-4', 'C', 'Os dois consomem exatamente o mesmo.', false, 'Os valores são 1 kWh/dia e 2 kWh/dia — diferentes.', 'supor equivalência sem calcular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-4', 'D', 'X consome mais, pois potência elevada gera mais perdas por calor.', false, 'Perdas dependem do projeto do equipamento; o consumo faturado é potência × tempo.', 'introduzir fator não informado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-4', 'E', 'Não é possível comparar sem conhecer a tarifa de energia.', false, 'A tarifa converte kWh em reais, mas a comparação de consumo em kWh já é possível.', 'exigir dado desnecessário');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ene-5', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'challenging', 'integration', false, 'Um município pretende reduzir emissões substituindo parte da energia de origem térmica por solar fotovoltaica. Um técnico observa que a geração solar cai à noite e em dias nublados, e que os painéis exigem mineração de materiais específicos.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-5', 'A', 'A fonte solar reduz emissões na operação, mas exige planejamento para a intermitência e avaliação dos impactos de todo o ciclo de vida.', true, 'Reconhece o benefício real (baixa emissão na geração) sem ignorar dois pontos concretos: a necessidade de armazenamento ou complementação para a intermitência e os impactos de extração e descarte.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-5', 'B', 'A fonte solar não deve ser adotada, pois sua geração é intermitente.', false, 'Intermitência é um desafio de planejamento — resolvido com armazenamento e complementaridade entre fontes —, não um impedimento.', 'rejeitar por limitação gerenciável');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-5', 'C', 'A fonte solar é totalmente limpa e não apresenta impacto ambiental algum.', false, 'Extração de materiais, fabricação e descarte geram impacto. Nenhuma fonte é isenta.', 'confundir renovável com sem impacto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-5', 'D', 'A geração térmica deve ser mantida integralmente, pois é mais estável.', false, 'Estabilidade não anula o custo ambiental das emissões; a solução usual é combinar fontes.', 'escolher um lado ignorando o outro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-5', 'E', 'A intermitência prova que a energia solar viola a conservação da energia.', false, 'Intermitência decorre da variação da radiação disponível, sem qualquer relação com a conservação da energia.', 'misturar conceitos sem relação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ene-rec-1', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'intro', 'concept', true, 'Em uma lâmpada incandescente, a maior parte da energia elétrica é convertida em:', 'A incandescente é, na prática, um aquecedor que também ilumina.', NULL, NULL, NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-rec-1', 'A', 'Energia mecânica.', false, 'Não há movimento macroscópico associado ao funcionamento.', 'trocar de forma de energia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-rec-1', 'B', 'Energia térmica.', true, 'Cerca de 95% da energia elétrica vira calor no filamento; apenas uma pequena parcela sai como luz visível. Por isso a lâmpada esquenta tanto.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-rec-1', 'C', 'Energia luminosa.', false, 'A parcela convertida em luz é pequena — é justamente por isso que a tecnologia foi substituída.', 'assumir a função como destino principal da energia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-rec-1', 'D', 'Energia química.', false, 'Não há reação química envolvida no funcionamento da lâmpada incandescente.', 'trocar de forma de energia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-rec-1', 'E', 'Energia sonora.', false, 'A conversão em som é desprezível.', 'escolher forma irrelevante');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ene-rec-2', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'intermediate', 'applied', true, 'Um aparelho de 800 W permanece ligado 3 horas por dia. Qual é o consumo em 30 dias?', '0,8 × 3 × 30 = 72 kWh.', NULL, NULL, NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-rec-2', 'A', '24 kWh', false, 'Corresponde a 1 hora por dia em vez de 3.', 'usar tempo incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-rec-2', 'B', '800 kWh', false, 'Confunde a potência com o consumo mensal.', 'confundir potência com energia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-rec-2', 'C', '72 kWh', true, '0,8 kW × 3 h = 2,4 kWh/dia; × 30 = 72 kWh.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-rec-2', 'D', '2,4 kWh', false, 'É o consumo de um dia.', 'não multiplicar pelos dias');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-rec-2', 'E', '720 kWh', false, 'Corresponde a esquecer a conversão de watts para quilowatts em uma das etapas.', 'erro de ordem de grandeza');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ene-6', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'intro', 'concept', false, 'Uma lâmpada de 10 W fica ligada por 5 horas. A grandeza 10 W indica:', 'Watt é joule por segundo: uma taxa. A energia consumida depende da potência multiplicada pelo tempo de uso.', 'Watt é joule por segundo: uma taxa. A energia consumida depende da potência multiplicada pelo tempo de uso.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-6', 'A', 'O tempo máximo de funcionamento.', false, 'Watt não mede duração.', 'confundir unidades');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-6', 'B', 'A tensão elétrica obrigatória da lâmpada.', false, 'Potência e tensão são grandezas distintas.', 'trocar grandezas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-6', 'C', 'A eficiência de conversão em luz.', false, 'A potência nominal não informa sozinha a fração convertida em luz.', 'inferir eficiência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-6', 'D', 'A taxa de transformação/consumo de energia por unidade de tempo.', true, 'Potência mede quão rapidamente a energia é transformada.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-6', 'E', 'A energia total de 10 kWh.', false, 'Potência não é energia total, e o valor em kWh exigiria multiplicar pelo tempo.', 'unidade e grandeza');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ene-7', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'intermediate', 'applied', false, 'Um chuveiro de 5.500 W é usado por 12 minutos por dia durante 30 dias. O consumo mensal aproximado é:', 'Converta 12 minutos para 0,2 hora e 5.500 W para 5,5 kW antes de multiplicar pelo número de dias.', 'Converta 12 minutos para 0,2 hora e 5.500 W para 5,5 kW antes de multiplicar pelo número de dias.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-7', 'A', '11 kWh.', false, 'Esse valor corresponde ao consumo em dez dias, não trinta.', 'ignorar período');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-7', 'B', '66 kWh.', false, 'O tempo diário foi dobrado para 24 minutos.', 'conversão temporal incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-7', 'C', '990 kWh.', false, 'Minutos foram usados como se fossem horas.', 'não converter unidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-7', 'D', '2.750 kWh.', false, 'O valor mistura potência em watts com tempo sem conversão coerente.', 'mistura de unidades');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-7', 'E', '33 kWh.', true, '5,5 kW × 0,2 h/dia × 30 dias = 33 kWh.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ene-8', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'intermediate', 'interpretation', false, 'Um diagrama de uma usina mostra 1.000 unidades de energia entrando, 350 unidades de energia elétrica útil e 650 unidades dissipadas como calor. A eficiência indicada é:', 'Conserva-se a energia total, mas eficiência considera somente a parcela útil: 35%. Os outros 65% foram transformados em calor não aproveitado.', 'Conserva-se a energia total, mas eficiência considera somente a parcela útil: 35%. Os outros 65% foram transformados em calor não aproveitado.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-8', 'A', '15%.', false, 'Esse percentual não corresponde a nenhuma razão informada.', 'razão arbitrária');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-8', 'B', '30%.', false, 'A energia útil é 350 de 1.000, não 300.', 'ler valor incorretamente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-8', 'C', '35%.', true, 'Eficiência = energia útil/energia de entrada = 350/1.000.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-8', 'D', '65%.', false, 'Esse é o percentual dissipado como calor.', 'usar perda como eficiência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-8', 'E', '100%.', false, 'A conservação da energia não significa que toda entrada vira forma útil desejada.', 'confundir conservação e eficiência');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ene-9', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'challenging', 'comparison', false, 'Para transportar a mesma quantidade de pessoas pelo mesmo trajeto, o sistema I usa 20 veículos com 1 ocupante; o sistema II usa um ônibus com 20 ocupantes. Sem afirmar valores exatos, a comparação energética mais adequada é:', 'Comparações ambientais e energéticas precisam usar a mesma unidade de serviço, como passageiro-quilômetro, e explicitar condições.', 'Comparações ambientais e energéticas precisam usar a mesma unidade de serviço, como passageiro-quilômetro, e explicitar condições.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-9', 'A', 'Veículos individuais sempre consomem zero quando estão em movimento uniforme.', false, 'Manter movimento real envolve resistências e consumo.', 'idealização indevida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-9', 'B', 'O ônibus necessariamente usa menos energia total em qualquer condição.', false, 'Rota, tecnologia, ocupação e operação influenciam; “necessariamente” é forte demais.', 'regra absoluta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-9', 'C', 'Basta comparar a potência máxima dos motores.', false, 'O serviço depende de tempo, distância, ocupação e eficiência, não só potência máxima.', 'indicador insuficiente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-9', 'D', 'É relevante comparar energia por passageiro transportado, considerando ocupação e operação.', true, 'A unidade funcional torna comparáveis sistemas que prestam o mesmo serviço.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-9', 'E', 'O número de passageiros não interfere na análise.', false, 'Ocupação altera fortemente o consumo por pessoa.', 'ignorar denominador');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-ene-10', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'challenging', 'integration', false, 'Em horários de excesso de energia solar, uma usina bombeia água para um reservatório elevado. À noite, a água desce por turbinas. O sistema armazena energia principalmente por transformação entre:', 'O reservatório elevado funciona como bateria gravitacional: há conversões com perdas, mas a energia não é criada.', 'O reservatório elevado funciona como bateria gravitacional: há conversões com perdas, mas a energia não é criada.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-10', 'A', 'Energia criada durante a descida.', false, 'A descida converte energia previamente armazenada; não cria energia.', 'violar conservação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-10', 'B', 'Energia química e nuclear.', false, 'Não há reação química nem nuclear descrita.', 'formas ausentes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-10', 'C', 'Energia elétrica, potencial gravitacional e novamente elétrica.', true, 'A eletricidade move bombas, a água ganha altura e depois aciona geradores.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-10', 'D', 'Energia sonora e luminosa.', false, 'Som e luz não são etapas principais do armazenamento.', 'focar efeitos secundários');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-ene-10', 'E', 'Massa e temperatura, sem perdas.', false, 'Massa não é forma de energia, e o processo real possui perdas.', 'conceitos inadequados');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ener-1', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'intro', 'concept', false, 'A afirmação de que "a energia não é criada nem destruída, apenas transformada" implica que, ao acender uma lâmpada incandescente:', 'Conservação não significa que tudo continua útil. A energia se mantém, mas parte dela se degrada em calor difuso.', 'Conservação não significa que tudo continua útil. A energia se mantém, mas parte dela se degrada em calor difuso.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-1', 'A', 'a lâmpada cria energia luminosa a partir do filamento.', false, 'O filamento converte energia, não a cria.', 'negar a conservação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-1', 'B', 'a conservação só vale em sistemas fechados sem lâmpadas.', false, 'O princípio vale de modo geral, contabilizando todas as formas envolvidas.', 'restrição inventada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-1', 'C', 'parte da energia elétrica desaparece no processo.', false, 'Nada desaparece; parte apenas assume forma menos útil.', 'negar a conservação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-1', 'D', 'toda a energia elétrica vira luz.', false, 'Boa parte se converte em calor, o que caracteriza a baixa eficiência dessa lâmpada.', 'ignorar as perdas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-1', 'E', 'a energia elétrica se converte em luz e em calor, somando o total consumido.', true, 'A soma das formas de saída equivale à energia recebida; a lâmpada incandescente converte a maior parte em calor.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ener-2', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'intermediate', 'applied', false, 'Um chuveiro de 5.400 W é usado 20 minutos por dia. Considerando 30 dias e tarifa de R$ 0,80 por quilowatt-hora, o custo mensal aproximado é de:', 'Consumo em quilowatt-hora é potência em quilowatts vezes tempo em horas. Vinte minutos equivalem a um terço de hora.', 'Consumo em quilowatt-hora é potência em quilowatts vezes tempo em horas. Vinte minutos equivalem a um terço de hora.', 'Converta sempre potência para quilowatts e tempo para horas antes de multiplicar. A maioria dos erros nasce na unidade, não na conta.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-2', 'A', 'R$ 8,64.', false, 'Esse valor sai de considerar apenas um terço do tempo total.', 'tempo incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-2', 'B', 'R$ 129,60.', false, 'Esse valor supõe uma hora de banho por dia.', 'tempo incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-2', 'C', 'R$ 2,16.', false, 'Esse é o custo aproximado de um único dia.', 'esquecer os 30 dias');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-2', 'D', 'R$ 43,20.', true, 'Potência: 5,4 kW. Tempo: 1/3 de hora por dia, 10 h no mês. Energia: 54 kWh. Custo: 54 × 0,80 = 43,20.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-2', 'E', 'R$ 4.320,00.', false, 'Esse valor confunde watts com quilowatts na conta final.', 'erro de unidade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ener-3', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'intermediate', 'interpretation', false, 'Uma usina termelétrica converte cerca de 40% da energia do combustível em eletricidade. O restante é liberado principalmente como calor. Essa informação indica que:', 'Eficiência trata da qualidade da energia disponível, não da sua quantidade. Calor disperso a baixa temperatura é energia que existe e serve pouco.', 'Eficiência trata da qualidade da energia disponível, não da sua quantidade. Calor disperso a baixa temperatura é energia que existe e serve pouco.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-3', 'A', 'a usina viola o princípio de conservação da energia.', false, 'A conservação é respeitada: entrada e saída se equivalem quando se contabiliza o calor.', 'confundir eficiência com conservação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-3', 'B', 'com melhorias técnicas é possível chegar a 100% de eficiência.', false, 'Há limite físico para a conversão de calor em trabalho.', 'ignorar o limite térmico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-3', 'C', 'a eficiência independe da temperatura de operação.', false, 'A eficiência de máquinas térmicas depende das temperaturas envolvidas.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-3', 'D', 'a energia se conserva, mas parte dela se degrada em calor de baixa temperatura, difícil de reaproveitar.', true, 'Quantidade e qualidade são coisas distintas: o total permanece, mas a fração útil diminui.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-3', 'E', '60% da energia é destruída no processo.', false, 'Nenhuma energia é destruída; ela muda de forma.', 'negar a conservação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ener-4', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'intermediate', 'comparison', false, 'Comparando um aquecedor solar e um chuveiro elétrico para aquecer a mesma quantidade de água, é correto afirmar que:', 'Comparar sistemas energéticos exige olhar fonte, conversão, custo de operação e disponibilidade — não apenas o preço do equipamento.', 'Comparar sistemas energéticos exige olhar fonte, conversão, custo de operação e disponibilidade — não apenas o preço do equipamento.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-4', 'A', 'os dois consomem a mesma energia elétrica por litro aquecido.', false, 'O solar usa radiação, não eletricidade, para o aquecimento principal.', 'igualar as fontes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-4', 'B', 'o chuveiro elétrico é mais eficiente na conversão e por isso mais barato.', false, 'A conversão elétrica em calor é eficiente, mas a eletricidade é uma forma cara de energia para essa finalidade.', 'confundir eficiência com custo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-4', 'C', 'o solar não funciona em regiões de clima frio.', false, 'Ele funciona em climas frios, com desempenho reduzido e apoio auxiliar.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-4', 'D', 'o chuveiro elétrico não gera impacto ambiental, por não queimar combustível no local.', false, 'O impacto ocorre na geração da eletricidade, ainda que fora da residência.', 'deslocar o impacto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-4', 'E', 'o solar tem custo de operação muito menor, mas depende da radiação disponível e costuma exigir sistema de apoio.', true, 'A fonte é gratuita e limpa, porém intermitente, o que torna comum a combinação com aquecimento elétrico auxiliar.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ener-5', 'energia-e-transformacoes', 'interpretar-conservacao-consumo-transformacao-energia', 'challenging', 'integration', false, 'Uma residência instala painéis solares e reduz a conta de luz, mas passa a consumir mais eletricidade porque deixa aparelhos ligados por mais tempo. Esse comportamento é analisado como:', 'Ganho técnico e ganho efetivo não coincidem. Quando o custo marginal cai, o uso cresce e parte da economia prevista se dissolve.', 'Ganho técnico e ganho efetivo não coincidem. Quando o custo marginal cai, o uso cresce e parte da economia prevista se dissolve.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-5', 'A', 'indício de defeito nos painéis instalados.', false, 'Não há indício de defeito no relato.', 'hipótese sem base');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-5', 'B', 'prova de que painéis solares não reduzem consumo.', false, 'Eles reduzem o consumo da rede; o efeito descrito é comportamental.', 'atribuir ao equipamento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-5', 'C', 'efeito rebote: parte do ganho de eficiência é absorvida por aumento no uso.', true, 'Quando o custo por unidade cai, o uso tende a subir, consumindo parte do ganho esperado.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-5', 'D', 'erro de medição do relógio de energia.', false, 'O aumento é real, e decorre de mudança de comportamento.', 'atribuir a erro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ener-5', 'E', 'violação do princípio de conservação da energia.', false, 'Nada aqui contraria a conservação.', 'confundir conceitos');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qui-1', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'intro', 'concept', false, 'Considere os processos:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-1', 'A', 'II.', true, 'A ferrugem é um óxido de ferro — substância nova, com propriedades diferentes do ferro metálico. É a única transformação química da lista.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-1', 'B', 'III.', false, 'A dissolução é física: o açúcar pode ser recuperado por evaporação da água.', 'confundir dissolução com reação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-1', 'C', 'I e III.', false, 'Ambas são transformações físicas.', 'inverter a classificação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-1', 'D', 'II e III.', false, 'II está correta, mas III é transformação física.', 'incluir a dissolução indevidamente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-1', 'E', 'I.', false, 'O derretimento muda o estado físico; a água continua sendo água.', 'confundir mudança de estado com reação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qui-2', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'intermediate', 'applied', false, 'Em um experimento, palha de aço é queimada ao ar livre sobre uma balança. Ao final, a massa registrada é maior que a inicial.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-2', 'A', 'A balança apresentou defeito, pois toda combustão reduz a massa.', false, 'Combustões que liberam gases reduzem a massa medida; combustões de metais que incorporam oxigênio a aumentam.', 'generalizar a partir de um caso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-2', 'B', 'A palha de aço absorveu umidade do ar, o que explica todo o ganho.', false, 'A umidade pode ter efeito marginal, mas o ganho característico do experimento decorre da incorporação de oxigênio.', 'escolher causa secundária');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-2', 'C', 'O ferro combinou-se com o oxigênio do ar, e a massa desse oxigênio incorporado explica o aumento.', true, 'A oxidação incorpora oxigênio atmosférico ao sólido. Como o oxigênio veio de fora da balança e passou a fazer parte do produto, a massa registrada aumenta.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-2', 'D', 'Houve criação de matéria durante a combustão.', false, 'Matéria não é criada — isso violaria a conservação da massa.', 'violar a lei de Lavoisier');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-2', 'E', 'O calor liberado tem massa e foi somado ao produto.', false, 'A energia liberada não contribui de forma mensurável para a massa em uma reação química comum.', 'atribuir massa mensurável ao calor');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qui-3', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'intermediate', 'interpretation', false, 'A combustão completa do metano é representada por:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-3', 'A', 'A reação produz mais moléculas do que consome.', false, 'São 3 moléculas de reagentes (1 + 2) e 3 de produtos (1 + 2): o total é igual.', 'não somar os coeficientes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-3', 'B', 'Cada 1 mol de metano consome 2 mol de gás oxigênio e produz 1 mol de gás carbônico.', true, 'Os coeficientes indicam proporção em quantidade de matéria: 1 CH₄ : 2 O₂ : 1 CO₂ : 2 H₂O.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-3', 'C', 'Cada 1 grama de metano consome 2 gramas de oxigênio.', false, 'Coeficientes expressam mol, não massa. A conversão exige as massas molares de cada substância.', 'ler coeficiente como massa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-3', 'D', 'A equação não está balanceada, pois há mais átomos à direita.', false, 'Está balanceada: 1 C, 4 H e 4 O de cada lado.', 'contar átomos incorretamente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-3', 'E', 'A água formada é reagente da reação.', false, 'A água aparece à direita da seta: é produto.', 'inverter reagente e produto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qui-4', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'challenging', 'comparison', false, 'Na reação 2 H₂ + O₂ → 2 H₂O, um estudante dispõe de 6 mol de H₂ e 2 mol de O₂.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-4', 'A', '6 mol de água, com O₂ em excesso.', false, 'Formar 6 mol de água exigiria 3 mol de O₂, mas só há 2 mol. Além disso, o O₂ é o limitante, não o excesso.', 'usar o reagente mais abundante como base');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-4', 'B', '4 mol de água, com H₂ em excesso.', true, 'Os 2 mol de O₂ reagem com 4 mol de H₂ e formam 4 mol de H₂O. Sobram 2 mol de H₂, que não têm com o que reagir.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-4', 'C', '2 mol de água, com H₂ em excesso.', false, 'A proporção 2:1 indica que 2 mol de O₂ formam 4 mol de água, não 2.', 'ignorar o coeficiente da água');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-4', 'D', '4 mol de água, com O₂ em excesso.', false, 'A quantidade está correta, mas o O₂ foi totalmente consumido: é o limitante.', 'confundir limitante com excesso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-4', 'E', '8 mol de água, sem excesso.', false, 'Não há reagente suficiente para essa quantidade, e sobra H₂.', 'somar reagentes sem respeitar a proporção');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qui-5', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'challenging', 'integration', false, 'Uma indústria libera efluente ácido em um curso d''água. Um técnico propõe adicionar carbonato de cálcio ao efluente antes do descarte, monitorando o pH até a faixa neutra.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-5', 'A', 'A proposta é inadequada, pois carbonatos não reagem com ácidos.', false, 'Carbonatos reagem com ácidos produzindo sal, água e gás carbônico — é uma neutralização clássica.', 'negar reação existente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-5', 'B', 'A proposta resolve integralmente o problema ambiental do efluente.', false, 'Corrigir o pH não remove metais, matéria orgânica ou outros contaminantes eventualmente presentes.', 'confundir um parâmetro com o todo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-5', 'C', 'A efervescência observada indicaria falha do processo.', false, 'A efervescência é justamente a evidência de que a reação está ocorrendo, com liberação de CO₂.', 'interpretar evidência de reação como falha');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-5', 'D', 'O pH deveria ser elevado o máximo possível para garantir segurança.', false, 'Efluente muito alcalino também causa dano ambiental: o objetivo é a faixa adequada, não o extremo.', 'supor que mais é sempre melhor');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-5', 'E', 'A neutralização é quimicamente adequada, mas o monitoramento do pH sozinho não garante ausência de outros contaminantes nem controla o gás e os sais gerados.', true, 'Carbonato neutraliza ácido, com liberação de CO₂ e formação de sal. O pH volta à faixa neutra, mas metais dissolvidos e carga de sais permanecem — e não aparecem na medida de pH.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qui-rec-1', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'intro', 'concept', true, 'A formação de um precipitado ao misturar duas soluções transparentes é indício de:', 'Precipitado é substância nova — evidência de reação química.', NULL, NULL, NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-rec-1', 'A', 'Aumento da temperatura da mistura, sem reação.', false, 'Variação de temperatura é outra evidência possível, mas não explica a formação de sólido.', 'trocar de evidência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-rec-1', 'B', 'Transformação química, pela formação de uma substância nova insolúvel.', true, 'O sólido que se forma não estava presente antes: é substância nova, evidência de reação química.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-rec-1', 'C', 'Transformação física, semelhante à solidificação.', false, 'Na solidificação a mesma substância muda de estado; aqui surge substância diferente.', 'confundir com mudança de estado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-rec-1', 'D', 'Evaporação de um dos solventes.', false, 'Evaporação não produz sólido insolúvel de forma imediata na mistura.', 'trocar de fenômeno');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-rec-1', 'E', 'Erro de preparo das soluções.', false, 'A formação de precipitado é resultado esperado em diversas reações.', 'tratar resultado esperado como erro');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qui-rec-2', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'intermediate', 'applied', true, 'Uma reação ocorre em um frasco hermeticamente fechado, com liberação de gás. Sobre a massa total do sistema ao final:', 'Sistema fechado: nada entra, nada sai, massa constante.', NULL, NULL, NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-rec-2', 'A', 'Diminui pela metade, conforme a proporção da reação.', false, 'Proporções estequiométricas não implicam perda de massa.', 'confundir proporção com perda');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-rec-2', 'B', 'Não pode ser determinada sem conhecer os reagentes.', false, 'A conservação vale independentemente das substâncias envolvidas.', 'exigir dado desnecessário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-rec-2', 'C', 'Permanece igual à massa inicial, pois nada entrou nem saiu do sistema.', true, 'Em sistema fechado, o gás produzido continua dentro do frasco. A massa total se conserva, conforme a lei de Lavoisier.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-rec-2', 'D', 'Diminui, porque gases têm massa desprezível.', false, 'Gases têm massa, e ela continua sendo contabilizada dentro do frasco fechado.', 'supor que gás não tem massa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-rec-2', 'E', 'Aumenta, devido à pressão interna.', false, 'Pressão não altera a massa do conteúdo.', 'confundir pressão com massa');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qui-6', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'intro', 'concept', false, 'Qual observação constitui evidência mais forte de transformação química?', 'Evidências químicas incluem formação de gás, precipitado, mudança energética ou de cor quando associadas ao surgimento de novas substâncias.', 'Evidências químicas incluem formação de gás, precipitado, mudança energética ou de cor quando associadas ao surgimento de novas substâncias.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-6', 'A', 'Quebra de um vidro.', false, 'Muda forma e tamanho, não composição química.', 'confundir fragmentação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-6', 'B', 'Dissolução de açúcar em água com recuperação por evaporação.', false, 'O açúcar pode ser recuperado sem formar nova substância.', 'confundir dissolução');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-6', 'C', 'Compressão de ar em uma seringa.', false, 'Volume e pressão mudam, não a identidade das substâncias.', 'confundir propriedade física');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-6', 'D', 'Formação persistente de gás ao misturar duas soluções que não estavam em ebulição.', true, 'O aparecimento de nova substância gasosa em condições controladas indica reação.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-6', 'E', 'Derretimento de gelo.', false, 'A água muda de estado, mas continua sendo H₂O.', 'confundir mudança de estado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qui-7', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'intermediate', 'applied', false, 'Uma receita de limpeza orienta usar 20 mL de concentrado para preparar 500 mL de solução final. Para preparar 2 litros mantendo a proporção, são necessários:', 'A solução final aumenta por fator 4, portanto todos os componentes devem ser multiplicados por 4.', 'A solução final aumenta por fator 4, portanto todos os componentes devem ser multiplicados por 4.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-7', 'A', '80 mL.', true, 'Dois litros equivalem a quatro porções de 500 mL; 4 × 20 = 80 mL.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-7', 'B', '20 mL.', false, 'Esse volume prepara apenas 500 mL, não 2.000 mL.', 'não escalar');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-7', 'C', '40 mL.', false, 'Corresponde a 1 litro, metade do volume pedido.', 'fator de escala pela metade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-7', 'D', '50 mL.', false, 'O fator de escala correto é 4, não 2,5.', 'proporção incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-7', 'E', '2.000 mL.', false, 'Esse é o volume final total, não o volume de concentrado.', 'confundir parte e total');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qui-8', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'intermediate', 'interpretation', false, 'Em recipiente fechado, 12 g de carbono reagem completamente com 32 g de oxigênio. Uma tabela de resultados coerente com a conservação da massa deve registrar massa total de produtos igual a:', 'Em sistema fechado, a massa total se conserva. Gases também possuem massa e entram na soma dos reagentes.', 'Em sistema fechado, a massa total se conserva. Gases também possuem massa e entram na soma dos reagentes.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-8', 'A', '384 g.', false, 'Multiplicar massas não tem significado para a conservação.', 'operação inadequada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-8', 'B', '12 g.', false, 'Esse valor considera apenas o carbono.', 'omitir reagente gasoso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-8', 'C', '20 g.', false, 'A massa não é obtida subtraindo os reagentes.', 'usar diferença');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-8', 'D', '44 g.', true, 'Em sistema fechado, 12 + 32 = 44 g de produtos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-8', 'E', '32 g.', false, 'Esse valor considera apenas o oxigênio.', 'omitir sólido');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qui-9', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'challenging', 'comparison', false, 'Duas soluções de mesmo soluto têm: I. 10 g em 100 mL; II. 30 g em 500 mL. Comparando a concentração em g/mL:', 'Compare razões, não quantidades isoladas: 10/100 = 0,10 g/mL e 30/500 = 0,06 g/mL.', 'Compare razões, não quantidades isoladas: 10/100 = 0,10 g/mL e 30/500 = 0,06 g/mL.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-9', 'A', 'A II é mais concentrada porque tem mais soluto.', false, 'Também tem volume muito maior; é preciso calcular a razão.', 'comparar numerador isolado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-9', 'B', 'As duas têm concentração de 0,1 g/mL.', false, 'A I tem 0,1, mas a II tem 0,06 g/mL.', 'não dividir segunda razão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-9', 'C', 'A II é cinco vezes mais concentrada.', false, 'Cinco é a razão entre volumes, não entre concentrações.', 'usar fator errado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-9', 'D', 'A I é mais concentrada: 0,10 g/mL contra 0,06 g/mL.', true, 'Concentração é massa por volume; as duas razões mostram maior valor em I.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-9', 'E', 'Não é possível comparar porque os volumes diferem.', false, 'A concentração existe justamente para comparar proporções em volumes distintos.', 'negar uso da razão');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qui-10', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'challenging', 'integration', false, 'Gases ácidos emitidos por uma atividade industrial reagem com água atmosférica e contribuem para chuva ácida. Uma medida que atua na origem do problema é:', 'Controle na fonte remove ou transforma os precursores antes que participem das reações atmosféricas, reduzindo o impacto em vez de apenas remediá-lo.', 'Controle na fonte remove ou transforma os precursores antes que participem das reações atmosféricas, reduzindo o impacto em vez de apenas remediá-lo.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-10', 'A', 'Impedir a evaporação natural da água.', false, 'Evaporação é parte do ciclo da água e não é uma medida viável de controle industrial.', 'alvo inadequado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-10', 'B', 'Pintar monumentos com cores mais escuras.', false, 'Isso não reduz a formação dos ácidos nem a emissão precursora.', 'ação cosmética');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-10', 'C', 'Remover ou converter os gases precursores antes de liberá-los na atmosfera.', true, 'O tratamento reduz reagentes que formariam ácidos no ambiente.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-10', 'D', 'Aumentar a emissão para diluir os poluentes.', false, 'Mais emissão aumenta a carga total e não resolve a reação.', 'diluição falsa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qui-10', 'E', 'Adicionar sal aos rios depois de cada chuva.', false, 'A ação posterior pode gerar outros impactos e não controla a fonte.', 'atuar no efeito');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-tq-1', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'intro', 'concept', false, 'Entre os fenômenos a seguir, aquele que constitui uma transformação química é:', 'Transformação química forma substância nova. Mudanças de estado, dissolução e trituração alteram a forma, não a identidade da matéria.', 'Transformação química forma substância nova. Mudanças de estado, dissolução e trituração alteram a forma, não a identidade da matéria.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-1', 'A', 'a evaporação do álcool deixado no prato.', false, 'Mudança de estado, com a mesma substância na fase vapor.', 'fenômeno físico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-1', 'B', 'a fusão do gelo em água líquida.', false, 'Mudança de estado não altera a substância.', 'fenômeno físico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-1', 'C', 'a dissolução de açúcar em água.', false, 'A dissolução dispersa o soluto sem formar substância nova.', 'fenômeno físico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-1', 'D', 'a moagem de um comprimido até virar pó.', false, 'A trituração muda o tamanho das partículas, não a composição.', 'fenômeno físico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-1', 'E', 'a formação de ferrugem sobre uma barra de ferro exposta ao ar úmido.', true, 'Ferro, oxigênio e água reagem formando um composto novo, com propriedades distintas do metal original.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-tq-2', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'intermediate', 'applied', false, 'Ao adicionar bicarbonato de sódio a vinagre em um copo aberto, observa-se efervescência e a massa total do sistema diminui ao longo do tempo. Essa diminuição ocorre porque:', 'Lei da conservação da massa vale em sistema fechado. Em recipiente aberto, o gás que sai é matéria que deixou a balança.', 'Lei da conservação da massa vale em sistema fechado. Em recipiente aberto, o gás que sai é matéria que deixou a balança.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-2', 'A', 'o vinagre evapora completamente durante a reação.', false, 'A perda observada corresponde principalmente ao gás formado.', 'causa trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-2', 'B', 'o bicarbonato se transforma em energia.', false, 'Não há conversão de matéria em energia em reações químicas comuns.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-2', 'C', 'a balança perde precisão com a agitação da efervescência.', false, 'A diminuição persiste após o fim da efervescência.', 'atribuir a erro instrumental');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-2', 'D', 'a massa não se conserva em reações que liberam gás.', false, 'A massa se conserva; o que ocorre é a saída de matéria do recipiente.', 'negar a conservação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-2', 'E', 'parte dos produtos é um gás que escapa do copo aberto, levando massa consigo.', true, 'Em sistema fechado a massa total permaneceria constante; no copo aberto o gás sai e a balança acusa a diferença.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-tq-3', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'intermediate', 'interpretation', false, 'Um estudante observa que, ao misturar duas soluções incolores, o líquido esquenta e forma-se um sólido branco no fundo. As evidências apontam para:', 'Evidências de reação incluem formação de precipitado, liberação de gás, mudança de cor e variação de temperatura. Basta uma delas, bem observada.', 'Evidências de reação incluem formação de precipitado, liberação de gás, mudança de cor e variação de temperatura. Basta uma delas, bem observada.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-3', 'A', 'reação apenas se houvesse liberação de gás.', false, 'Liberação de gás é uma evidência entre várias.', 'exigir uma única evidência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-3', 'B', 'reação química, com formação de precipitado e liberação de energia na forma de calor.', true, 'Sólido novo e variação de temperatura são duas evidências independentes de transformação química.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-3', 'C', 'nenhuma reação, pois não houve mudança de cor.', false, 'Mudança de cor é uma evidência possível, mas não é a única nem necessária.', 'exigir uma única evidência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-3', 'D', 'apenas mudança de estado físico das substâncias.', false, 'Mudança de estado não gera sólido novo a partir de duas soluções.', 'classificação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-3', 'E', 'dissolução de um sólido previamente presente.', false, 'O sólido apareceu depois da mistura, e não estava presente antes.', 'contradizer o enunciado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-tq-4', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'intermediate', 'comparison', false, 'Comparando a combustão completa e a combustão incompleta de um mesmo combustível, é correto afirmar que a incompleta:', 'A diferença está na disponibilidade de oxigênio. Sem oxigênio suficiente, sobram produtos parcialmente oxidados, tóxicos e com menos energia liberada.', 'A diferença está na disponibilidade de oxigênio. Sem oxigênio suficiente, sobram produtos parcialmente oxidados, tóxicos e com menos energia liberada.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-4', 'A', 'não produz água entre os produtos.', false, 'A água continua entre os produtos quando o combustível contém hidrogênio.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-4', 'B', 'é preferível em ambientes fechados por gerar menos calor.', false, 'Ela é justamente mais perigosa em ambientes fechados, pelo monóxido de carbono.', 'inverter a avaliação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-4', 'C', 'libera mais energia por grama de combustível.', false, 'A combustão incompleta libera menos energia, pois a oxidação não se completa.', 'inverter a relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-4', 'D', 'ocorre apenas com combustíveis sólidos.', false, 'Ela ocorre também com gases e líquidos, quando falta oxigênio.', 'restrição incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-4', 'E', 'ocorre com oxigênio insuficiente e produz monóxido de carbono e fuligem, além de liberar menos energia.', true, 'A falta de oxigênio impede a oxidação completa, gerando produtos parcialmente oxidados e mais perigosos.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-tq-5', 'transformacoes-quimicas', 'identificar-reagentes-produtos-evidencias-proporcoes', 'challenging', 'integration', false, 'Em uma reação em que 4 g de hidrogênio reagem completamente com 32 g de oxigênio produzindo água, a massa de água formada e o que ocorreria com 6 g de hidrogênio e 32 g de oxigênio são, respectivamente:', 'Duas leis atuam juntas: a massa total se conserva e os reagentes se combinam em proporção fixa. O reagente que acaba primeiro limita a reação.', 'Duas leis atuam juntas: a massa total se conserva e os reagentes se combinam em proporção fixa. O reagente que acaba primeiro limita a reação.', 'Ao receber quantidades de dois reagentes, verifique primeiro qual deles limita a reação. O excesso do outro simplesmente sobra.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-5', 'A', '36 g de água; com 6 g de hidrogênio, a reação não ocorreria.', false, 'A reação ocorre normalmente, apenas com sobra de um dos reagentes.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-5', 'B', '32 g de água, igual à massa de oxigênio empregada.', false, 'A massa dos produtos é a soma das massas dos reagentes consumidos.', 'ignorar um reagente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-5', 'C', '36 g de água; com 6 g de hidrogênio, ainda se formariam 36 g e sobrariam 2 g de hidrogênio.', true, 'A massa se conserva na primeira reação, e a proporção fixa faz o oxigênio limitar a segunda, deixando hidrogênio em excesso.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-5', 'D', '36 g de água; com 6 g de hidrogênio, formar-se-iam 38 g de água.', false, 'A proporção entre os reagentes é fixa: o excesso de hidrogênio não encontra oxigênio para reagir.', 'ignorar o reagente limitante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tq-5', 'E', '28 g de água, pois parte da massa se perde como energia.', false, 'A massa se conserva na reação.', 'negar a conservação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-genetica-1', 'genetica-basica', 'aplicar-principios-de-heranca-genetica', 'intro', 'concept', false, 'Em uma espécie, a cor escura da pelagem (A) é dominante sobre a cor clara (a). Do cruzamento entre dois indivíduos heterozigotos, a proporção fenotípica esperada na descendência é:', 'Genótipos 1:2:1; fenótipos 3:1, porque o heterozigoto expressa o alelo dominante.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-1', 'A', '1 : 2 : 1', false, 'Essa é a proporção genotípica (AA : Aa : aa), não a fenotípica.', 'confundir genótipo com fenótipo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-1', 'B', '4 escuros : 0 claros', false, 'Isso ocorreria se um dos pais fosse homozigoto dominante.', 'trocar os genótipos parentais');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-1', 'C', '3 escuros : 1 claro', true, 'Aa × Aa gera 1 AA, 2 Aa e 1 aa. Como AA e Aa têm o mesmo fenótipo, a proporção observada é 3 escuros para 1 claro.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-1', 'D', '2 escuros : 2 claros', false, 'Não corresponde a nenhum cruzamento mendeliano simples com dominância completa.', 'estimar sem montar o quadro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-1', 'E', '1 escuro : 1 claro', false, 'Essa é a proporção de um cruzamento entre heterozigoto e homozigoto recessivo.', 'trocar o cruzamento');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-genetica-2', 'genetica-basica', 'aplicar-principios-de-heranca-genetica', 'intermediate', 'applied', false, 'Um casal sem fibrose cística tem um filho com a doença, que é recessiva e autossômica. O casal deseja saber a probabilidade de o próximo filho também nascer com a doença.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-2', 'A', '25%.', true, 'Como o filho afetado é aa, ambos os pais são portadores (Aa). Em Aa × Aa, a chance de aa é 1/4 a cada gestação.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-2', 'B', '50%.', false, 'Corresponderia a um cruzamento Aa × aa.', 'errar o genótipo de um dos pais');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-2', 'C', '100%, pois o alelo já se manifestou na família.', false, 'A manifestação anterior não torna certa a repetição.', 'confundir presença de alelo com certeza');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-2', 'D', '0%, pois o casal já teve um filho afetado.', false, 'Cada gestação é independente; o nascimento anterior não altera as chances.', 'aplicar falácia do apostador');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-2', 'E', '12,5%, metade da probabilidade original.', false, 'Não há razão para dividir a probabilidade pela metade.', 'inventar correção');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-genetica-3', 'genetica-basica', 'aplicar-principios-de-heranca-genetica', 'intermediate', 'interpretation', false, 'Um heredograma mostra: um casal não afetado (I-1 e I-2) com três filhos — dois não afetados e uma filha afetada. A filha afetada, casada com um homem não afetado sem histórico familiar da característica, tem dois filhos, ambos não afetados.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-3', 'A', 'A característica é ligada ao cromossomo Y, pois apareceu em apenas um dos filhos.', false, 'Herança ligada ao Y se manifestaria apenas em homens, e a afetada é mulher.', 'atribuir herança incompatível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-3', 'B', 'Os filhos da mulher afetada não podem ser portadores, pois não manifestam a característica.', false, 'Portador é justamente quem tem o alelo sem manifestá-lo.', 'confundir portador com afetado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-3', 'C', 'Os dados são insuficientes para qualquer conclusão sobre o tipo de herança.', false, 'O padrão descrito é suficiente para concluir que a herança é recessiva.', 'recusar conclusão possível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-3', 'D', 'A característica é recessiva, os pais I-1 e I-2 são heterozigotos e os filhos da mulher afetada são obrigatoriamente portadores.', true, 'Pais não afetados com filha afetada indicam herança recessiva e genótipo Aa para ambos. A filha é aa e transmite um "a" a todos os seus filhos, que herdam A do pai e são, portanto, Aa.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-3', 'E', 'A característica é dominante, pois se manifestou em duas gerações.', false, 'Ela se manifestou apenas na segunda geração; os netos não são afetados.', 'ler o padrão ao contrário');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-genetica-4', 'genetica-basica', 'aplicar-principios-de-heranca-genetica', 'challenging', 'comparison', false, 'Compare dois casos de herança:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-4', 'A', 'Herança dominante e herança recessiva.', true, 'Em I, todo afetado tem genitor afetado — padrão típico de dominante. Em II, o alelo atravessa gerações silenciosamente em heterozigotos — padrão típico de recessiva.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-4', 'B', 'Herança ligada ao X em ambos os casos.', false, 'Os padrões descritos não permitem essa conclusão; faltaria informação sobre o sexo dos afetados.', 'atribuir herança sem evidência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-4', 'C', 'Herança mitocondrial e herança autossômica.', false, 'Herança mitocondrial é exclusivamente materna, o que não é descrito.', 'atribuir mecanismo incompatível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-4', 'D', 'Ausência de padrão genético em ambos os casos.', false, 'Os dois padrões são clássicos e reconhecíveis.', 'negar padrões estabelecidos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-4', 'E', 'Herança recessiva e herança dominante.', false, 'A ordem está trocada em relação aos padrões descritos.', 'inverter os padrões');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-genetica-5', 'genetica-basica', 'aplicar-principios-de-heranca-genetica', 'challenging', 'integration', false, 'Um exame revela que uma pessoa possui uma variante genética associada a maior risco de determinada doença. A reportagem que divulga o caso afirma que a pessoa "certamente desenvolverá a doença".
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-5', 'A', 'A afirmação é incorreta: a variante aumenta o risco, mas o desfecho depende de outros genes, do ambiente e do estilo de vida, o que justifica acompanhamento e prevenção em vez de prognóstico definitivo.', true, 'A maioria das doenças complexas é multifatorial. O resultado do exame indica probabilidade elevada e serve para orientar decisões de prevenção, não para anunciar um destino.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-5', 'B', 'A afirmação está correta, pois a presença da variante determina o fenótipo.', false, 'Variantes de risco alteram probabilidade, não produzem certeza.', 'aceitar determinismo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-5', 'C', 'A afirmação está correta apenas se a variante for dominante.', false, 'Mesmo variantes dominantes podem ter penetrância incompleta e expressividade variável.', 'simplificar a relação genótipo-fenótipo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-5', 'D', 'O exame é inútil, já que não permite prever com certeza o futuro da pessoa.', false, 'Informação probabilística orienta prevenção e acompanhamento — é útil sem ser determinista.', 'descartar informação válida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-5', 'E', 'A afirmação está correta porque exames genéticos têm alta precisão técnica.', false, 'Precisão em detectar a variante não é o mesmo que certeza sobre o desfecho clínico.', 'confundir precisão do teste com determinismo do desfecho');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-genetica-rec-1', 'genetica-basica', 'aplicar-principios-de-heranca-genetica', 'intro', 'concept', true, 'Um indivíduo de genótipo Aa para um gene com dominância completa é chamado de:', 'Alelos diferentes para o mesmo gene definem o heterozigoto.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-rec-1', 'A', 'Homozigoto dominante.', false, 'Homozigoto dominante seria AA.', 'trocar o genótipo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-rec-1', 'B', 'Homozigoto recessivo.', false, 'Homozigoto recessivo seria aa.', 'trocar o genótipo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-rec-1', 'C', 'Heterozigoto.', true, 'Ter dois alelos diferentes para o mesmo gene (A e a) define o heterozigoto, que expressa o fenótipo dominante e transmite os dois alelos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-rec-1', 'D', 'Hemizigoto.', false, 'Hemizigoto se refere a genes presentes em dose única, como os do X em indivíduos XY.', 'usar termo de outro contexto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-genetica-rec-1', 'E', 'Mutante.', false, 'A presença de dois alelos diferentes é comum e não caracteriza mutação.', 'confundir variação normal com mutação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-gene-1', 'genetica-basica', 'aplicar-principios-de-heranca-genetica', 'intro', 'concept', false, 'Sobre a diferença entre genótipo e fenótipo, é correto afirmar que:', 'Genótipo é o que se herda; fenótipo é o que se manifesta. Entre um e outro está o ambiente, que pode alterar a expressão.', 'Genótipo é o que se herda; fenótipo é o que se manifesta. Entre um e outro está o ambiente, que pode alterar a expressão.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-1', 'A', 'o fenótipo determina o genótipo ao longo da vida.', false, 'A direção da relação é a inversa, e o ambiente não altera o genótipo herdado.', 'inverter a relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-1', 'B', 'o genótipo é a constituição genética e o fenótipo é a característica manifestada, que resulta do genótipo em interação com o ambiente.', true, 'A manifestação depende de quais genes o indivíduo carrega e das condições em que se desenvolve.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-1', 'C', 'o fenótipo se refere apenas a características visíveis a olho nu.', false, 'Tipo sanguíneo e níveis enzimáticos também são fenótipos.', 'restrição indevida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-1', 'D', 'o genótipo muda a cada geração dentro do mesmo indivíduo.', false, 'O genótipo do indivíduo permanece o mesmo ao longo da vida.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-1', 'E', 'genótipo e fenótipo são sinônimos em organismos diploides.', false, 'Indivíduos com o mesmo genótipo podem apresentar fenótipos distintos.', 'igualar os conceitos');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-gene-2', 'genetica-basica', 'aplicar-principios-de-heranca-genetica', 'intro', 'applied', false, 'Em um cruzamento entre dois indivíduos heterozigotos para um gene com dominância completa, a proporção fenotípica esperada na descendência é de:', 'A proporção 3:1 é fenotípica; a genotípica correspondente é 1:2:1. Confundir as duas é o erro mais comum nesse cruzamento.', 'A proporção 3:1 é fenotípica; a genotípica correspondente é 1:2:1. Confundir as duas é o erro mais comum nesse cruzamento.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-2', 'A', '9 para 3 para 3 para 1.', false, 'Essa proporção envolve dois genes, e o enunciado trata de um.', 'número de genes trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-2', 'B', '3 dominantes para 1 recessivo.', true, 'Dos quatro genótipos possíveis, três expressam o fenótipo dominante e um, o recessivo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-2', 'C', '1 dominante para 1 recessivo.', false, 'Essa proporção aparece no cruzamento entre heterozigoto e homozigoto recessivo.', 'cruzamento trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-2', 'D', '1 para 2 para 1.', false, 'Essa é a proporção genotípica, não a fenotípica.', 'confundir genótipo com fenótipo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-2', 'E', 'todos dominantes.', false, 'Um quarto da descendência é homozigoto recessivo e manifesta o outro fenótipo.', 'ignorar o recessivo');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-gene-3', 'genetica-basica', 'aplicar-principios-de-heranca-genetica', 'intermediate', 'interpretation', false, 'Um casal sem determinada doença tem um filho afetado. Sabendo que a doença é causada por um alelo autossômico recessivo, conclui-se que:', 'Pais não afetados com filho afetado é a assinatura clássica da herança autossômica recessiva: ambos são portadores heterozigotos.', 'Pais não afetados com filho afetado é a assinatura clássica da herança autossômica recessiva: ambos são portadores heterozigotos.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-3', 'A', 'a doença surgiu por mutação nova no filho.', false, 'A explicação mais simples e compatível com os dados é a herança de portadores.', 'hipótese desnecessária');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-3', 'B', 'a doença é dominante, e o enunciado está incorreto.', false, 'O padrão descrito é exatamente o esperado para herança recessiva.', 'negar o enunciado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-3', 'C', 'o alelo está no cromossomo X, e o filho é do sexo masculino.', false, 'O enunciado informa que o gene é autossômico.', 'contradizer o enunciado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-3', 'D', 'um dos pais é homozigoto recessivo e não manifestou a doença.', false, 'Em herança recessiva com penetrância completa, o homozigoto recessivo manifesta a característica.', 'contradizer a definição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-3', 'E', 'ambos os pais são heterozigotos, portadores do alelo sem manifestá-lo.', true, 'A criança afetada recebeu um alelo recessivo de cada progenitor, o que só é possível se ambos o carregam.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-gene-4', 'genetica-basica', 'aplicar-principios-de-heranca-genetica', 'intermediate', 'comparison', false, 'Comparando herança autossômica e herança ligada ao cromossomo X quanto à distribuição entre os sexos, espera-se que:', 'O que produz a diferença é o número de cromossomos X. Com apenas um, não há alelo alternativo para mascarar o recessivo.', 'O que produz a diferença é o número de cromossomos X. Com apenas um, não há alelo alternativo para mascarar o recessivo.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-4', 'A', 'a herança autossômica afete mais mulheres.', false, 'Características autossômicas não têm viés de sexo por esse motivo.', 'viés inventado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-4', 'B', 'a autossômica afete os dois sexos em proporções semelhantes, enquanto a recessiva ligada ao X afete mais homens, que têm um único cromossomo X.', true, 'Sem um segundo X para mascarar o alelo, basta um exemplar para que o homem manifeste a característica.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-4', 'C', 'a herança ligada ao X seja sempre dominante.', false, 'Existem características ligadas ao X tanto dominantes quanto recessivas.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-4', 'D', 'ambas afetem igualmente os dois sexos em qualquer caso.', false, 'A herança ligada ao X apresenta distribuição desigual entre os sexos.', 'igualar os padrões');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-4', 'E', 'a herança ligada ao X afete exclusivamente homens.', false, 'Mulheres homozigotas para o alelo também são afetadas.', 'exclusividade incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-gene-5', 'genetica-basica', 'aplicar-principios-de-heranca-genetica', 'challenging', 'integration', false, 'Duas plantas geneticamente idênticas são cultivadas, uma em solo pobre e outra em solo fértil, e apresentam alturas bem diferentes. Esse resultado permite concluir que:', 'Um mesmo genótipo pode produzir fenótipos diferentes conforme o ambiente. É essa faixa de resposta que os geneticistas chamam de norma de reação.', 'Um mesmo genótipo pode produzir fenótipos diferentes conforme o ambiente. É essa faixa de resposta que os geneticistas chamam de norma de reação.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-5', 'A', 'as plantas não eram, de fato, geneticamente idênticas.', false, 'O enunciado estabelece a identidade genética como premissa.', 'contradizer o enunciado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-5', 'B', 'o solo fértil provocou uma mutação favorável.', false, 'Não há indício de mutação, e a explicação ambiental já responde ao observado.', 'hipótese desnecessária');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-5', 'C', 'o fenótipo resulta da interação entre genótipo e ambiente, e um mesmo genótipo admite faixa de manifestações.', true, 'Com genótipos idênticos, a diferença observada só pode vir das condições de cultivo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-5', 'D', 'o genótipo das plantas mudou por causa do solo.', false, 'O solo não altera a constituição genética das plantas.', 'confundir expressão com alteração genética');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-gene-5', 'E', 'a altura não tem componente genético algum.', false, 'Há componente genético; o ambiente atua sobre ele, e não no lugar dele.', 'negar o componente genético');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-saude-1', 'saude-e-prevencao', 'relacionar-agente-transmissao-e-prevencao', 'intro', 'concept', false, 'A dengue, a zika e a chikungunya são transmitidas ao ser humano principalmente pela picada do mosquito Aedes aegypti. A medida de prevenção mais eficaz contra essas doenças é:', 'Contra doenças transmitidas por vetor, a prevenção mais eficaz age sobre o vetor — no caso do Aedes, sobre os criadouros.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-1', 'A', 'A eliminação de criadouros com água parada, que impede a reprodução do mosquito.', true, 'Sem locais de reprodução, a população do vetor cai e a transmissão é interrompida na origem.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-1', 'B', 'O isolamento das pessoas doentes, já que a transmissão é direta entre humanos.', false, 'A transmissão depende do mosquito, não do contato direto entre pessoas.', 'confundir a via de transmissão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-1', 'C', 'A fervura da água antes do consumo.', false, 'A transmissão não é por veiculação hídrica.', 'aplicar prevenção de outra via');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-1', 'D', 'A vacinação obrigatória contra os três vírus na infância.', false, 'A oferta de vacinas para essas arboviroses é limitada e não substitui o controle do vetor.', 'supor solução indisponível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-1', 'E', 'O uso preventivo de antibióticos durante o verão.', false, 'As três doenças são virais; antibióticos não agem sobre vírus.', 'usar antibiótico contra vírus');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-saude-2', 'saude-e-prevencao', 'relacionar-agente-transmissao-e-prevencao', 'intermediate', 'applied', false, 'Uma pessoa com sintomas de gripe procura a farmácia e pede um antibiótico, alegando que "sempre funciona".
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-2', 'A', 'O antibiótico deve ser tomado por precaução, para evitar complicações bacterianas.', false, 'Uso preventivo sem indicação médica não é recomendado e favorece a resistência.', 'generalizar profilaxia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-2', 'B', 'O antibiótico funciona porque reduz a duração da gripe.', false, 'Ele não age sobre vírus e não altera a duração da gripe.', 'aceitar a premissa incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-2', 'C', 'O antibiótico só não funciona se for tomado em dose baixa.', false, 'A dose não muda o fato de que o alvo do medicamento são bactérias.', 'atribuir o problema à dosagem');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-2', 'D', 'A gripe é causada por vírus, sobre os quais o antibiótico não age; o uso indevido ainda contribui para a resistência bacteriana.', true, 'Antibióticos atuam em estruturas bacterianas ausentes nos vírus. Usá-los sem indicação seleciona bactérias resistentes, que depois circulam na população.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-2', 'E', 'O uso é indiferente, pois antibióticos não causam efeito algum quando não há bactérias.', false, 'Há efeito: alteração da microbiota e pressão seletiva sobre bactérias resistentes.', 'supor ausência de consequência');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-saude-3', 'saude-e-prevencao', 'relacionar-agente-transmissao-e-prevencao', 'intermediate', 'interpretation', false, 'A tabela apresenta a cobertura vacinal contra o sarampo em um município e o número de casos registrados:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-3', 'A', 'Não há relação entre as duas colunas, pois correlação não implica causalidade.', false, 'A cautela é válida em geral, mas aqui há mecanismo biológico conhecido que sustenta a relação.', 'aplicar a máxima sem considerar o mecanismo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-3', 'B', 'A vacinação deveria ser interrompida, já que os casos aumentaram mesmo com sua aplicação.', false, 'Os casos aumentaram justamente onde a vacinação diminuiu.', 'inverter a leitura dos dados');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-3', 'C', 'A queda da cobertura vacinal ampliou o número de pessoas suscetíveis, o que favoreceu a retomada da transmissão.', true, 'Quanto menor a cobertura, maior a proporção de suscetíveis. Em uma doença muito transmissível, isso reativa cadeias de transmissão — o que a série mostra com clareza.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-3', 'D', 'Os dados mostram que a vacina perdeu eficácia ao longo do tempo.', false, 'A série mostra queda de cobertura, não de eficácia individual da vacina.', 'confundir cobertura com eficácia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-3', 'E', 'O aumento de casos decorre exclusivamente do crescimento populacional.', false, 'Um crescimento populacional não explicaria salto de 0 para 156 casos com queda simultânea de cobertura.', 'atribuir a variável irrelevante');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-saude-4', 'saude-e-prevencao', 'relacionar-agente-transmissao-e-prevencao', 'challenging', 'comparison', false, 'Compare duas situações de prevenção:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-4', 'A', 'Apenas a medida I é eficaz, por agir diretamente sobre o agente causador.', false, 'O mosquiteiro age sobre o vetor, não sobre o protozoário; e a medida II é eficaz em sua própria via.', 'errar o alvo da medida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-4', 'B', 'Nenhuma das duas previne doenças, pois só a vacinação é preventiva.', false, 'Controle de vetores e saneamento estão entre as medidas preventivas mais eficazes conhecidas.', 'restringir prevenção à vacina');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-4', 'C', 'As duas medidas são intercambiáveis, pois ambas previnem doenças infecciosas.', false, 'Cada uma interrompe uma via específica: trocá-las tornaria ambas ineficazes.', 'ignorar a via de transmissão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-4', 'D', 'Apenas a medida II é eficaz, por ser estrutural.', false, 'Ser estrutural não torna a outra ineficaz: mosquiteiros reduzem comprovadamente a transmissão da malária.', 'hierarquizar sem critério técnico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-4', 'E', 'Cada medida interrompe a cadeia de transmissão específica da sua doença: a I atua sobre o vetor alado e a II sobre a veiculação hídrica e o contato com o solo contaminado.', true, 'A escolha da medida depende da via: malária é transmitida por mosquito, e verminoses, sobretudo por água, alimentos e solo contaminados por fezes.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-saude-5', 'saude-e-prevencao', 'relacionar-agente-transmissao-e-prevencao', 'challenging', 'integration', false, 'Dois bairros de uma mesma cidade apresentam incidências muito diferentes de doenças de veiculação hídrica. O bairro com maior incidência tem menor renda média, cobertura de esgoto incompleta e abastecimento de água intermitente.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-5', 'A', 'A solução depende apenas de campanhas educativas sobre fervura de água.', false, 'Educação ajuda, mas não substitui infraestrutura de saneamento.', 'reduzir política pública a comunicação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-5', 'B', 'Os determinantes sociais — saneamento, regularidade do abastecimento e renda — condicionam a exposição ao agente, de modo que a prevenção eficaz exige investimento em infraestrutura, além de ações educativas e assistenciais.', true, 'A exposição depende de condições materiais: sem esgoto e com abastecimento intermitente, o contato com água contaminada é mais provável independentemente do cuidado individual. Por isso a resposta combina infraestrutura, educação e assistência.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-5', 'C', 'A diferença decorre exclusivamente de hábitos de higiene dos moradores.', false, 'Higiene depende de acesso a água e esgoto; atribuir tudo ao comportamento ignora a condição material.', 'culpar o indivíduo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-5', 'D', 'A diferença é genética, o que explicaria a maior suscetibilidade em um dos bairros.', false, 'Não há base para atribuir a diferença a fatores genéticos entre bairros.', 'invocar explicação biológica indevida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-5', 'E', 'A diferença é aleatória e não permite planejamento de saúde pública.', false, 'O padrão descrito é sistemático e é justamente a base para o planejamento.', 'negar padrão observável');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-saude-rec-1', 'saude-e-prevencao', 'relacionar-agente-transmissao-e-prevencao', 'intro', 'concept', true, 'A imunidade coletiva contra uma doença transmissível é alcançada quando:', 'Imunidade coletiva é efeito de população: alta cobertura interrompe cadeias de transmissão e protege os não imunizáveis.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-rec-1', 'A', 'Cada pessoa se protege individualmente, sem relação com as demais.', false, 'A imunidade coletiva é, por definição, um efeito de população.', 'individualizar o conceito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-rec-1', 'B', 'Uma proporção suficientemente alta da população está imunizada, o que reduz a circulação do agente e protege inclusive quem não pôde se vacinar.', true, 'Com poucos suscetíveis, cada caso encontra poucas pessoas capazes de adoecer, e as cadeias de transmissão se interrompem.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-rec-1', 'C', 'A doença desaparece naturalmente após algumas gerações.', false, 'Não há desaparecimento espontâneo garantido; depende da interrupção da transmissão.', 'supor extinção natural');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-rec-1', 'D', 'Todas as pessoas, sem exceção, são vacinadas.', false, 'A imunidade coletiva não exige 100% de cobertura, e algumas pessoas não podem ser vacinadas.', 'exigir cobertura total');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-saude-rec-1', 'E', 'O agente infeccioso sofre mutação e perde a capacidade de causar doença.', false, 'Mutações podem ocorrer em qualquer direção e não definem imunidade coletiva.', 'trocar o mecanismo');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-saude-1', 'saude-e-prevencao', 'relacionar-agente-transmissao-e-prevencao', 'intro', 'concept', false, 'Antibióticos são indicados para o tratamento de infecções causadas por:', 'Antibiótico age sobre estruturas bacterianas. Usá-lo contra vírus não trata nada e ainda pressiona a seleção de bactérias resistentes.', 'Antibiótico age sobre estruturas bacterianas. Usá-lo contra vírus não trata nada e ainda pressiona a seleção de bactérias resistentes.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-1', 'A', 'qualquer micro-organismo, desde que a dose seja adequada.', false, 'A ação é específica para bactérias.', 'generalização incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-1', 'B', 'bactérias, atuando sobre estruturas ou processos que elas possuem.', true, 'Parede celular, ribossomos bacterianos e enzimas específicas são alvos que os vírus não apresentam.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-1', 'C', 'fungos, como os causadores de micoses.', false, 'Micoses são tratadas com antifúngicos.', 'agente incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-1', 'D', 'protozoários, como o causador da malária.', false, 'Protozoários exigem antiparasitários específicos.', 'agente incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-1', 'E', 'vírus, como o da gripe e o do resfriado comum.', false, 'Antibióticos não agem sobre vírus, que têm estrutura e replicação distintas.', 'agente incorreto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-saude-2', 'saude-e-prevencao', 'relacionar-agente-transmissao-e-prevencao', 'intermediate', 'applied', false, 'Em uma comunidade com alta cobertura vacinal, uma pessoa que não pôde ser vacinada por razões médicas fica menos exposta à doença. Esse efeito é chamado de:', 'Imunidade coletiva não imuniza o indivíduo: ela reduz a chance de encontro entre o agente e quem está suscetível.', 'Imunidade coletiva não imuniza o indivíduo: ela reduz a chance de encontro entre o agente e quem está suscetível.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-2', 'A', 'erradicação da doença na comunidade.', false, 'Redução da circulação não equivale a erradicação.', 'confundir controle com erradicação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-2', 'B', 'imunidade passiva, transferida pelos vizinhos vacinados.', false, 'Imunidade passiva envolve transferência de anticorpos, e não ocorre entre vizinhos.', 'conceito trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-2', 'C', 'imunidade coletiva: com poucos suscetíveis, a transmissão encontra menos caminhos e a circulação do agente diminui.', true, 'A proteção vem da interrupção das cadeias de transmissão, e não de uma resposta imune na pessoa não vacinada.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-2', 'D', 'imunidade adquirida por exposição natural ao agente.', false, 'A pessoa não foi exposta; ela é protegida pela redução da circulação.', 'mecanismo trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-2', 'E', 'efeito placebo coletivo.', false, 'Trata-se de um efeito epidemiológico mensurável.', 'conceito incompatível');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-saude-3', 'saude-e-prevencao', 'relacionar-agente-transmissao-e-prevencao', 'intermediate', 'interpretation', false, 'Uma campanha de combate à dengue insiste na eliminação de água parada em vez de focar apenas na pulverização de inseticida. A justificativa técnica dessa escolha é que:', 'Controle de vetor eficaz age sobre o elo mais vulnerável do ciclo. Sem criadouro não há nova geração, por mais adultos que se eliminem hoje.', 'Controle de vetor eficaz age sobre o elo mais vulnerável do ciclo. Sem criadouro não há nova geração, por mais adultos que se eliminem hoje.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-3', 'A', 'o mosquito não é afetado por inseticidas.', false, 'Ele é afetado, embora possa desenvolver resistência.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-3', 'B', 'a água parada transmite o vírus diretamente às pessoas.', false, 'A água é criadouro do vetor, e não via direta de transmissão.', 'mecanismo trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-3', 'C', 'o vírus se multiplica na água antes de infectar o mosquito.', false, 'O vírus se multiplica no mosquito e no ser humano, não na água.', 'ciclo incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-3', 'D', 'o inseticida atinge apenas o mosquito adulto, enquanto eliminar criadouros interrompe o ciclo antes das novas gerações.', true, 'Atacar ovos e larvas reduz a população futura; matar adultos resolve apenas o momento presente.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-3', 'E', 'o inseticida é proibido em áreas urbanas.', false, 'Ele é usado em situações específicas, com regras próprias.', 'afirmação incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-saude-4', 'saude-e-prevencao', 'relacionar-agente-transmissao-e-prevencao', 'intermediate', 'comparison', false, 'Comparando prevenção primária, secundária e terciária, o exame de rastreamento em pessoas sem sintomas corresponde a:', 'Primária evita adoecer, secundária encontra cedo, terciária limita o dano. Rastreamento em assintomáticos pertence ao segundo grupo.', 'Primária evita adoecer, secundária encontra cedo, terciária limita o dano. Rastreamento em assintomáticos pertence ao segundo grupo.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-4', 'A', 'nenhum nível de prevenção, por se tratar de diagnóstico.', false, 'Rastreamento é reconhecido como ação preventiva de segundo nível.', 'classificação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-4', 'B', 'prevenção quaternária, por evitar excesso de intervenção.', false, 'A quaternária trata de evitar intervenções desnecessárias, o que não descreve o rastreamento em si.', 'nível trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-4', 'C', 'prevenção primária, pois ocorre antes dos sintomas.', false, 'A primária evita que a doença se instale; o rastreamento busca a doença já iniciada.', 'nível trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-4', 'D', 'prevenção secundária, pois busca detectar precocemente uma doença já instalada.', true, 'Detectar cedo permite tratar antes que a doença avance, ainda que ela já exista.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-4', 'E', 'prevenção terciária, pois reduz sequelas.', false, 'A terciária atua depois do adoecimento manifesto, para limitar dano e reabilitar.', 'nível trocado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-saude-5', 'saude-e-prevencao', 'relacionar-agente-transmissao-e-prevencao', 'challenging', 'integration', false, 'Um bairro sem saneamento apresenta alta incidência de verminoses. A intervenção com maior efeito duradouro sobre esse quadro é:', 'Verminoses de transmissão fecal-oral são doenças de saneamento. Sem cortar a via de transmissão, o tratamento é reiniciado a cada ciclo.', 'Verminoses de transmissão fecal-oral são doenças de saneamento. Sem cortar a via de transmissão, o tratamento é reiniciado a cada ciclo.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-5', 'A', 'distribuir vermífugo periodicamente a toda a população.', false, 'O tratamento em massa reduz a carga, mas a reinfecção ocorre enquanto a exposição permanece.', 'tratar sem alterar a causa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-5', 'B', 'orientar cada família a lavar as mãos com mais frequência.', false, 'A orientação ajuda, mas esbarra na ausência de água tratada e esgoto.', 'transferir a responsabilidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-5', 'C', 'ampliar o número de leitos hospitalares na região.', false, 'Leitos atendem casos graves e não reduzem a transmissão.', 'atuar no fim do processo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-5', 'D', 'implantar rede de água tratada e esgotamento sanitário, associada a tratamento dos casos existentes.', true, 'Interromper a via de transmissão fecal-oral resolve a causa, e o tratamento cuida de quem já adoeceu.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-saude-5', 'E', 'isolar as famílias afetadas até o fim do tratamento.', false, 'Isolamento não se aplica a essa via de transmissão e não altera a exposição ambiental.', 'medida incompatível');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-mec-1', 'mecanica', 'aplicar-leis-do-movimento-e-conservacao', 'intro', 'concept', false, 'Um corpo de 4 kg recebe uma força resultante de 12 N. A aceleração adquirida por esse corpo é de:', 'F = m·a, logo a = F/m. A unidade confirma: N/kg = m/s².', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-1', 'A', '16 m/s²', false, 'Corresponde a somar força e massa.', 'somar grandezas diferentes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-1', 'B', '8 m/s²', false, 'Não corresponde a nenhuma operação correta com os dados.', 'estimar sem calcular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-1', 'C', '48 m/s²', false, 'Corresponde a multiplicar força por massa.', 'inverter a operação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-1', 'D', '3 m/s²', true, 'Pela segunda lei de Newton, a = F/m = 12/4 = 3 m/s².', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-1', 'E', '0,33 m/s²', false, 'Corresponde a dividir a massa pela força.', 'inverter a razão');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-mec-2', 'mecanica', 'aplicar-leis-do-movimento-e-conservacao', 'intro', 'applied', false, 'Um passageiro em pé dentro de um ônibus é projetado para a frente quando o veículo freia bruscamente.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-2', 'A', 'Por uma força que empurra o passageiro para a frente durante a frenagem.', false, 'Não há força aplicada para a frente; o que existe é a tendência de manter o movimento.', 'inventar força inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-2', 'B', 'Pela terceira lei de Newton, já que o ônibus reage à frenagem.', false, 'A terceira lei trata de pares de forças em corpos diferentes, não do deslocamento do passageiro.', 'aplicar a lei errada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-2', 'C', 'Pelo princípio da inércia: o corpo tende a manter seu estado de movimento enquanto o ônibus desacelera.', true, 'O ônibus recebe força de frenagem; o passageiro, não. Ele continua com a velocidade que tinha, o que produz o deslocamento relativo para a frente.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-2', 'D', 'Pela ação da gravidade sobre o corpo do passageiro.', false, 'A gravidade atua verticalmente e não explica o deslocamento horizontal.', 'trocar a força atuante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-2', 'E', 'Pela conservação da energia cinética do ônibus.', false, 'A energia do ônibus é dissipada na frenagem, e isso não explica o movimento do passageiro.', 'aplicar conceito inadequado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-mec-3', 'mecanica', 'aplicar-leis-do-movimento-e-conservacao', 'intermediate', 'interpretation', false, 'Um gráfico de velocidade por tempo mostra: de 0 a 4 s, a velocidade sobe uniformemente de 0 a 8 m/s; de 4 s a 10 s, permanece constante em 8 m/s.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-3', 'A', '48 m', false, 'Considera apenas a fase de velocidade constante.', 'ignorar a primeira fase');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-3', 'B', '80 m', false, 'Considera apenas a segunda fase, sem a área do triângulo.', 'ignorar uma das fases');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-3', 'C', '32 m', false, 'Corresponde a tratar a primeira fase como retângulo.', 'errar a forma da área');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-3', 'D', '96 m', false, 'Corresponde a somar 32 m (retângulo indevido) com 64 m.', 'errar as duas áreas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-3', 'E', '64 m', true, 'Primeira fase: área do triângulo = (4 × 8)/2 = 16 m. Segunda fase: 8 × 6 = 48 m. Total: 64 m.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-mec-4', 'mecanica', 'aplicar-leis-do-movimento-e-conservacao', 'challenging', 'comparison', false, 'Dois carros idênticos freiam com a mesma desaceleração. O carro A trafega a 30 km/h e o carro B, a 60 km/h.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-4', 'A', 'As distâncias são iguais, pois a desaceleração é a mesma.', false, 'A mesma desaceleração aplicada a velocidades diferentes produz distâncias diferentes.', 'ignorar a velocidade inicial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-4', 'B', 'O carro B precisa de metade da distância, por ter mais energia para dissipar.', false, 'Mais energia exige mais distância, não menos.', 'inverter a relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-4', 'C', 'A energia cinética é o dobro e a distância é quatro vezes maior.', false, 'Energia e distância crescem no mesmo fator quadrático.', 'misturar as relações');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-4', 'D', 'O carro B precisa de aproximadamente quatro vezes a distância do carro A, e sua energia cinética também é quatro vezes maior.', true, 'Tanto a energia cinética quanto a distância de frenagem variam com o quadrado da velocidade: dobrar v multiplica ambas por quatro.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-4', 'E', 'O carro B precisa do dobro da distância, pois sua velocidade é o dobro.', false, 'A relação é quadrática, não linear.', 'supor proporcionalidade direta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-mec-5', 'mecanica', 'aplicar-leis-do-movimento-e-conservacao', 'challenging', 'integration', false, 'Uma cidade estuda reduzir o limite de velocidade em vias urbanas de 60 km/h para 40 km/h. Um grupo argumenta que a redução é pequena demais para produzir efeito.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-5', 'A', 'A física não permite avaliar políticas de trânsito, que dependem apenas de estatísticas.', false, 'A relação quadrática entre velocidade e energia é justamente o fundamento físico dessas políticas.', 'separar indevidamente física e política pública');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-5', 'B', 'A redução de 33% na velocidade produz uma redução equivalente de 33% na energia envolvida em uma colisão.', false, 'A energia depende do quadrado da velocidade, e a redução é bem maior que a percentual da velocidade.', 'aplicar proporcionalidade direta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-5', 'C', 'A redução não altera a distância de frenagem, que depende apenas do sistema de freios do veículo.', false, 'A distância de frenagem depende também da velocidade inicial, ao quadrado.', 'ignorar a velocidade inicial');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-5', 'D', 'A redução diminui a energia cinética em cerca de 56% e encurta proporcionalmente a distância de frenagem, o que amplia bastante a chance de sobrevivência de um pedestre atropelado.', true, 'Como a energia varia com v², passar de 60 para 40 km/h reduz a energia para (40/60)² ≈ 44% do valor original — uma queda de cerca de 56%. A distância de frenagem cai na mesma proporção, e ambos os efeitos aumentam muito a chance de sobrevivência.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-5', 'E', 'A mudança só teria efeito se acompanhada da proibição total de veículos na região.', false, 'Medidas graduais têm efeito mensurável e não exigem proibição total.', 'exigir solução extrema');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-mec-rec-1', 'mecanica', 'aplicar-leis-do-movimento-e-conservacao', 'intro', 'concept', true, 'Um objeto é abandonado de uma altura de 45 m. Desprezando a resistência do ar e adotando g = 10 m/s², a velocidade com que ele chega ao solo é:', 'A energia potencial se converte em cinética: m·g·h = m·v²/2, e a massa se cancela.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-rec-1', 'A', '15 m/s', false, 'Corresponde à metade do valor correto.', 'errar a conta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-rec-1', 'B', '10 m/s', false, 'Corresponde ao valor da gravidade, não da velocidade final.', 'confundir grandezas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-rec-1', 'C', '45 m/s', false, 'Confunde a altura com a velocidade final.', 'copiar o dado do enunciado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-rec-1', 'D', '900 m/s', false, 'É o valor de v², antes de extrair a raiz.', 'esquecer a raiz quadrada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-mec-rec-1', 'E', '30 m/s', true, 'v² = 2·g·h = 2 × 10 × 45 = 900, logo v = 30 m/s.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-mec-1', 'mecanica', 'aplicar-leis-do-movimento-e-conservacao', 'intro', 'concept', false, 'Um passageiro em pé no ônibus é lançado para a frente quando o veículo freia bruscamente. Esse fenômeno é explicado por:', 'Inércia é a resistência à mudança de estado de movimento. Na frenagem, quem muda é o ônibus; o corpo continua como estava.', 'Inércia é a resistência à mudança de estado de movimento. Na frenagem, quem muda é o ônibus; o corpo continua como estava.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-1', 'A', 'pela ação da gravidade durante a frenagem.', false, 'A gravidade age para baixo e não explica o deslocamento horizontal.', 'força trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-1', 'B', 'pelo aumento do peso do passageiro na desaceleração.', false, 'O peso não se altera com a frenagem.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-1', 'C', 'pela inércia: o corpo tende a manter sua velocidade enquanto o ônibus desacelera.', true, 'Sem força suficiente atuando sobre ele, o passageiro continua no estado de movimento anterior.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-1', 'D', 'pela transferência de energia do motor para o passageiro.', false, 'Na frenagem o motor não impulsiona o veículo.', 'mecanismo trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-1', 'E', 'uma força que surge e empurra o passageiro para a frente.', false, 'Nenhuma força para a frente aparece; o que falta é força para desacelerá-lo.', 'inventar força');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-mec-2', 'mecanica', 'aplicar-leis-do-movimento-e-conservacao', 'intermediate', 'applied', false, 'Um carrinho de 2 kg move-se a 3 m/s e colide frontalmente com outro de 4 kg em repouso, ficando os dois unidos após o choque. A velocidade do conjunto imediatamente após a colisão é de:', 'Em colisões, a quantidade de movimento total se conserva. Em choques inelásticos, parte da energia cinética se converte em deformação e calor.', 'Em colisões, a quantidade de movimento total se conserva. Em choques inelásticos, parte da energia cinética se converte em deformação e calor.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-2', 'A', '1 m/s.', true, 'Quantidade de movimento inicial: 2 × 3 = 6 kg·m/s. Massa final: 6 kg. Velocidade: 6 ÷ 6 = 1 m/s.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-2', 'B', '2 m/s, pela média das massas.', false, 'Média de massas não é procedimento válido aqui.', 'procedimento inventado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-2', 'C', '0 m/s, pois o carrinho parado absorve o impacto.', false, 'O conjunto continua se movendo, já que havia movimento antes do choque.', 'contradizer a conservação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-2', 'D', '3 m/s, pois a velocidade se conserva.', false, 'O que se conserva é a quantidade de movimento, não a velocidade.', 'grandeza trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-2', 'E', '1,5 m/s, dividindo a velocidade inicial por dois.', false, 'A divisão precisa considerar a massa total, que é o triplo da massa em movimento.', 'massa incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-mec-3', 'mecanica', 'aplicar-leis-do-movimento-e-conservacao', 'intermediate', 'interpretation', false, 'Um gráfico mostra a velocidade de um objeto em função do tempo como uma reta horizontal acima do eixo. A leitura correta desse gráfico é que o objeto:', 'Em gráficos de velocidade por tempo, a inclinação é a aceleração e a área é o deslocamento. Reta horizontal significa velocidade constante.', 'Em gráficos de velocidade por tempo, a inclinação é a aceleração e a área é o deslocamento. Reta horizontal significa velocidade constante.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-3', 'A', 'está parado, pois a linha é horizontal.', false, 'Linha horizontal em gráfico de velocidade indica velocidade constante e não nula.', 'confundir com gráfico de posição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-3', 'B', 'move-se com velocidade constante, e a área sob a reta corresponde à distância percorrida.', true, 'Reta horizontal significa aceleração nula; a área sob a curva de velocidade dá o deslocamento.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-3', 'C', 'está acelerando uniformemente.', false, 'Aceleração uniforme apareceria como reta inclinada.', 'leitura incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-3', 'D', 'retorna ao ponto de partida ao fim do intervalo.', false, 'Velocidade sempre positiva indica movimento em um único sentido.', 'inferência incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-3', 'E', 'tem aceleração igual à sua velocidade.', false, 'A aceleração é nula, pois a velocidade não varia.', 'grandezas confundidas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-mec-4', 'mecanica', 'aplicar-leis-do-movimento-e-conservacao', 'intermediate', 'comparison', false, 'Comparando massa e peso de um mesmo objeto levado da Terra à Lua, é correto afirmar que:', 'Massa é propriedade do corpo; peso é interação com o astro. Trocar uma pela outra é o erro mais comum em mecânica básica.', 'Massa é propriedade do corpo; peso é interação com o astro. Trocar uma pela outra é o erro mais comum em mecânica básica.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-4', 'A', 'ambos são medidos em quilogramas e variam juntos.', false, 'Peso é força e se mede em newtons.', 'unidade incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-4', 'B', 'a massa permanece a mesma e o peso diminui, por depender da gravidade local.', true, 'Massa é quantidade de matéria; peso é a força com que o astro atrai o objeto.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-4', 'C', 'os dois diminuem, pois a gravidade lunar é menor.', false, 'A massa não depende da gravidade local.', 'igualar as grandezas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-4', 'D', 'os dois permanecem iguais, pois pertencem ao objeto.', false, 'O peso depende da gravidade e muda entre os dois astros.', 'igualar as grandezas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-4', 'E', 'a massa diminui e o peso permanece igual.', false, 'A relação está invertida.', 'inverter as grandezas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-mec-5', 'mecanica', 'aplicar-leis-do-movimento-e-conservacao', 'challenging', 'integration', false, 'Airbags e zonas de deformação em automóveis reduzem lesões em colisões porque:', 'Impulso é força vezes tempo. Como a variação de quantidade de movimento está dada, alongar o tempo do impacto é o que reduz a força sofrida.', 'Impulso é força vezes tempo. Como a variação de quantidade de movimento está dada, alongar o tempo do impacto é o que reduz a força sofrida.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-5', 'A', 'aumentam o tempo em que a variação de velocidade ocorre, reduzindo a força média sobre o corpo.', true, 'A variação de quantidade de movimento é praticamente a mesma; distribuí-la em mais tempo diminui a força a cada instante.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-5', 'B', 'reduzem a variação de velocidade sofrida pelo ocupante.', false, 'A variação é imposta pela colisão e permanece essencialmente a mesma.', 'grandeza incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-5', 'C', 'eliminam a inércia do ocupante durante o impacto.', false, 'A inércia não pode ser eliminada.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-5', 'D', 'absorvem toda a energia cinética do veículo.', false, 'Parte é absorvida, mas a explicação da proteção está no tempo de interação.', 'explicação incompleta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-mec-5', 'E', 'aumentam a massa efetiva do ocupante, reduzindo a aceleração.', false, 'A massa do ocupante não é alterada.', 'afirmação incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-elet-1', 'eletricidade', 'analisar-circuitos-e-consumo-eletrico', 'intro', 'concept', false, 'Um resistor de 20 Ω é submetido a uma tensão de 120 V. A corrente que o percorre é:', 'V = R·I, logo I = V/R. A unidade confirma: V/Ω = A.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-1', 'A', '140 A', false, 'Corresponde a somar tensão e resistência.', 'somar grandezas diferentes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-1', 'B', '2.400 A', false, 'Corresponde a multiplicar tensão por resistência.', 'inverter a operação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-1', 'C', '6 A', true, 'Pela lei de Ohm, I = V/R = 120/20 = 6 A.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-1', 'D', '0,17 A', false, 'Corresponde a dividir a resistência pela tensão.', 'inverter a razão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-1', 'E', '100 A', false, 'Corresponde a subtrair a resistência da tensão.', 'subtrair grandezas diferentes');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-elet-2', 'eletricidade', 'analisar-circuitos-e-consumo-eletrico', 'intermediate', 'applied', false, 'Uma residência usa um ferro de passar de 1.200 W durante 2 horas por semana. Considerando 4 semanas no mês e tarifa de R$ 0,75 por kWh, o custo mensal desse aparelho é de aproximadamente:', 'Consumo em kWh é potência em kW multiplicada pelas horas de uso. A conversão de W para kW é o passo mais esquecido.', NULL, 'Divida a potência por 1.000 antes de qualquer outra conta.', NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-2', 'A', 'R$ 7,20', true, 'Consumo: 1,2 kW × 2 h × 4 semanas = 9,6 kWh. Custo: 9,6 × 0,75 = R$ 7,20.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-2', 'B', 'R$ 72,00', false, 'Corresponde a usar 1.200 W sem converter para quilowatts.', 'esquecer a conversão de unidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-2', 'C', 'R$ 1,80', false, 'Considera apenas uma semana de uso.', 'ignorar o período total');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-2', 'D', 'R$ 14,40', false, 'Corresponde a dobrar o tempo de uso informado.', 'errar o tempo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-2', 'E', 'R$ 3,60', false, 'Corresponde à metade do consumo real.', 'errar a multiplicação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-elet-3', 'eletricidade', 'analisar-circuitos-e-consumo-eletrico', 'intermediate', 'interpretation', false, 'A tabela mostra a potência e o tempo médio de uso diário de alguns aparelhos de uma residência:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-3', 'A', 'O chuveiro, por ter a maior potência.', false, 'O chuveiro consome 2,7 kWh/dia; a geladeira, 2,88 kWh/dia. A potência sozinha não decide.', 'decidir pela potência isolada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-3', 'B', 'A geladeira, que consome 2,88 kWh por dia contra 2,7 kWh do chuveiro.', true, 'Geladeira: 0,12 kW × 24 h = 2,88 kWh. Chuveiro: 5,4 kW × 0,5 h = 2,7 kWh. O tempo de uso compensa a diferença de potência.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-3', 'C', 'A televisão, por ficar ligada várias horas.', false, 'Televisão: 0,09 × 5 = 0,45 kWh/dia, bem abaixo dos demais.', 'ignorar a ordem de grandeza');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-3', 'D', 'As lâmpadas, por estarem distribuídas pela casa.', false, 'Lâmpadas: 0,06 × 6 = 0,36 kWh/dia, o menor consumo da lista.', 'confundir quantidade com consumo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-3', 'E', 'Todos consomem o mesmo, pois potência e tempo se compensam.', false, 'Os valores calculados são diferentes entre si.', 'supor equivalência sem calcular');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-elet-4', 'eletricidade', 'analisar-circuitos-e-consumo-eletrico', 'challenging', 'comparison', false, 'Dois resistores idênticos de 10 Ω podem ser associados em série ou em paralelo, sob a mesma tensão de 20 V.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-4', 'A', 'Em paralelo, a resistência equivalente é maior que a de cada resistor isolado.', false, 'Em paralelo, a equivalente é sempre menor que a menor resistência do conjunto.', 'inverter a propriedade do paralelo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-4', 'B', 'Em série a resistência equivalente é 20 Ω e a potência dissipada é 20 W; em paralelo a equivalente é 5 Ω e a potência é 80 W.', true, 'Série: R = 20 Ω, I = 1 A, P = 20 W. Paralelo: R = 5 Ω, I = 4 A, P = 80 W. Sob a mesma tensão, o paralelo dissipa quatro vezes mais.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-4', 'C', 'A resistência equivalente é 20 Ω em ambos os casos.', false, 'Em paralelo, a equivalente é 5 Ω.', 'somar em paralelo também');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-4', 'D', 'A associação em série dissipa mais potência, pois tem maior resistência.', false, 'Sob tensão fixa, maior resistência significa menor corrente e menor potência.', 'inverter a relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-4', 'E', 'A corrente é a mesma nas duas associações.', false, 'Em série, I = 1 A; em paralelo, I = 4 A.', 'ignorar a mudança da resistência equivalente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-elet-5', 'eletricidade', 'analisar-circuitos-e-consumo-eletrico', 'challenging', 'integration', false, 'Uma família quer reduzir a conta de luz e avalia duas medidas:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-5', 'A', 'A troca das lâmpadas economiza mais: cerca de 92 kWh por mês, contra cerca de 55 kWh da redução do banho.', true, 'Lâmpadas: dez unidades economizam 51 W cada, ou 0,51 kW × 6 h ≈ 3,06 kWh/dia ≈ 92 kWh/mês. Banho: 20 minutos a menos por dia com 5,5 kW dão 5,5 × 0,33 ≈ 1,83 kWh/dia ≈ 55 kWh/mês.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-5', 'B', 'Nenhuma das duas produz efeito relevante, pois ambas envolvem valores pequenos de potência.', false, 'As duas somam quase 150 kWh mensais evitados, o que é bastante significativo em uma conta residencial.', 'descartar medidas eficazes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-5', 'C', 'A troca das lâmpadas é desnecessária, pois LEDs consomem mais energia ao longo do tempo.', false, 'LEDs consomem menos para o mesmo brilho e duram mais.', 'inverter o dado técnico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-5', 'D', 'As duas medidas economizam praticamente o mesmo, pois potência e tempo se compensam.', false, 'Os valores calculados são bem diferentes: cerca de 92 kWh contra 55 kWh por mês.', 'supor equivalência sem calcular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-5', 'E', 'A redução do banho economiza mais, porque o chuveiro tem a maior potência da casa.', false, 'A potência do chuveiro é maior, mas ele funciona poucos minutos por dia; o cálculo do consumo precisa incluir o tempo.', 'decidir pela potência isolada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-elet-rec-1', 'eletricidade', 'analisar-circuitos-e-consumo-eletrico', 'intro', 'concept', true, 'Um aparelho de 100 W permanece ligado 10 horas por dia. Seu consumo diário de energia elétrica é de:', 'Consumo em kWh = potência em kW × horas de uso.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-rec-1', 'A', '1.000 kWh', false, 'Corresponde a não converter watts em quilowatts.', 'esquecer a conversão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-rec-1', 'B', '10 kWh', false, 'Corresponde a usar a potência em kW como se fosse 1 kW.', 'errar a conversão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-rec-1', 'C', '1 kWh', true, '100 W = 0,1 kW. Consumo: 0,1 × 10 = 1 kWh por dia.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-rec-1', 'D', '0,1 kWh', false, 'Considera apenas uma hora de uso.', 'ignorar o tempo total');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-elet-rec-1', 'E', '100 kWh', false, 'Confunde a potência com o consumo.', 'confundir grandezas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ele-1', 'eletricidade', 'analisar-circuitos-e-consumo-eletrico', 'intro', 'concept', false, 'Em uma instalação residencial, as tomadas são ligadas em paralelo. A principal razão dessa escolha é que, em paralelo:', 'Em paralelo, todos os pontos recebem a mesma tensão e cada ramo é independente. Em série, um dispositivo desligado interromperia todos.', 'Em paralelo, todos os pontos recebem a mesma tensão e cada ramo é independente. Em série, um dispositivo desligado interromperia todos.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-1', 'A', 'o consumo total diminui em relação à ligação em série.', false, 'O consumo depende dos aparelhos ligados, não do tipo de associação.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-1', 'B', 'cada aparelho recebe a mesma tensão e funciona de forma independente dos demais.', true, 'Em paralelo a tensão é comum a todos os ramos, e desligar um não interrompe os outros.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-1', 'C', 'a resistência total aumenta com o número de aparelhos.', false, 'Em paralelo a resistência equivalente diminui à medida que se acrescentam ramos.', 'propriedade invertida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-1', 'D', 'os aparelhos podem ser ligados sem disjuntor de proteção.', false, 'A proteção é necessária em qualquer associação.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-1', 'E', 'a corrente é a mesma em todos os aparelhos.', false, 'Corrente igual em todos os pontos é característica da ligação em série.', 'propriedade trocada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ele-2', 'eletricidade', 'analisar-circuitos-e-consumo-eletrico', 'intermediate', 'applied', false, 'Um resistor de 20 ohms é ligado a uma fonte de 120 V. A corrente que o atravessa e a potência dissipada são, respectivamente:', 'A lei de Ohm dá a corrente pela razão entre tensão e resistência. A potência é o produto da tensão pela corrente.', 'A lei de Ohm dá a corrente pela razão entre tensão e resistência. A potência é o produto da tensão pela corrente.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-2', 'A', '6 A e 720 W.', true, 'Corrente: 120 ÷ 20 = 6 A. Potência: 120 × 6 = 720 W.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-2', 'B', '2.400 A e 288.000 W.', false, 'Esses valores vêm de multiplicar tensão por resistência em vez de dividir.', 'operação invertida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-2', 'C', '6 A e 120 W.', false, 'A corrente está correta, mas a potência precisa considerar tensão vezes corrente.', 'potência incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-2', 'D', '0,17 A e 20 W.', false, 'Esse valor de corrente resulta de dividir a resistência pela tensão.', 'razão invertida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-2', 'E', '6 A e 2.400 W apenas se a fonte for contínua.', false, 'A relação vale igualmente para o caso descrito, sem essa condição.', 'condição inventada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ele-3', 'eletricidade', 'analisar-circuitos-e-consumo-eletrico', 'intermediate', 'interpretation', false, 'A etiqueta de uma geladeira informa consumo de 40 kWh por mês. Um consumidor conclui que a geladeira "tem potência de 40 quilowatts". Sobre essa leitura:', 'Watt mede a taxa; watt-hora mede o total acumulado. Dividir a energia pelo tempo devolve a potência média.', 'Watt mede a taxa; watt-hora mede o total acumulado. Dividir a energia pelo tempo devolve a potência média.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-3', 'A', 'está errada: 40 kWh é energia acumulada no mês; a potência média é de cerca de 55 W.', true, 'Dividindo 40 kWh por 720 horas do mês obtém-se aproximadamente 0,055 kW.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-3', 'B', 'está errada porque geladeiras não consomem energia constantemente.', false, 'O funcionamento intermitente é real, mas o erro apontado é de unidade.', 'deslocar o erro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-3', 'C', 'está correta, pois quilowatt e quilowatt-hora são equivalentes.', false, 'Uma unidade mede potência e a outra, energia acumulada em um tempo.', 'igualar unidades');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-3', 'D', 'está correta apenas se a geladeira funcionar uma hora por mês.', false, 'Nesse caso a potência seria de fato 40 kW, mas a leitura proposta não faz essa ressalva e a geladeira funciona continuamente.', 'condição irreal');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-3', 'E', 'está errada porque a etiqueta se refere ao consumo anual.', false, 'A etiqueta informa consumo mensal.', 'contradizer o enunciado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ele-4', 'eletricidade', 'analisar-circuitos-e-consumo-eletrico', 'intermediate', 'comparison', false, 'Comparando duas lâmpadas que produzem a mesma iluminação, uma de 60 W e outra de 9 W, é correto afirmar que:', 'Potência informa quanto se consome, não quanto se ilumina. Comparar lâmpadas exige olhar lúmens ao lado dos watts.', 'Potência informa quanto se consome, não quanto se ilumina. Comparar lâmpadas exige olhar lúmens ao lado dos watts.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-4', 'A', 'a de 60 W ilumina mais, por consumir mais.', false, 'O enunciado estabelece que a iluminação é a mesma.', 'contradizer o enunciado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-4', 'B', 'a de 9 W é mais eficiente, pois entrega a mesma luz consumindo menos energia.', true, 'Eficiência é a razão entre resultado útil e energia consumida, e aqui o resultado é igual com consumo bem menor.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-4', 'C', 'as duas consomem a mesma energia por hora.', false, 'O consumo por hora é proporcional à potência, que difere.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-4', 'D', 'a potência mede diretamente a quantidade de luz emitida.', false, 'Potência mede consumo; luz emitida se mede em lúmens.', 'grandeza trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-4', 'E', 'a de 60 W é preferível por durar mais.', false, 'Durabilidade é outra variável e não decorre da potência.', 'critério trocado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-ele-5', 'eletricidade', 'analisar-circuitos-e-consumo-eletrico', 'challenging', 'integration', false, 'Um disjuntor de 20 A protege um circuito de 127 V. Ao ligar simultaneamente um chuveiro de 4.400 W e uma torneira elétrica de 2.500 W nesse circuito, o esperado é que:', 'O disjuntor protege contra excesso de corrente no circuito inteiro. Converter potência em corrente é o passo que revela o problema.', 'O disjuntor protege contra excesso de corrente no circuito inteiro. Converter potência em corrente é o passo que revela o problema.', 'Antes de ligar aparelhos de alta potência no mesmo circuito, some as potências e divida pela tensão. Compare o resultado com o disjuntor.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-5', 'A', 'os aparelhos funcionem com potência reduzida automaticamente.', false, 'Os aparelhos não reduzem potência por conta própria.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-5', 'B', 'o disjuntor desarme somente se os aparelhos forem ligados na mesma tomada.', false, 'O limite se aplica ao circuito, e não a uma tomada específica.', 'escopo incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-5', 'C', 'o disjuntor desarme, pois a corrente exigida ultrapassa 50 A, muito acima do limite.', true, 'Potência total de 6.900 W a 127 V exige cerca de 54 A, bem além dos 20 A de proteção.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-5', 'D', 'nada aconteça, pois o disjuntor só atua acima de 100 A.', false, 'O valor nominal do disjuntor é justamente o limite de atuação.', 'ignorar o valor nominal');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-ele-5', 'E', 'a tensão do circuito caia para metade, sem desarme.', false, 'Queda de tensão pode ocorrer, mas a proteção atua pela corrente.', 'mecanismo trocado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-sol-1', 'solucoes', 'calcular-e-interpretar-concentracoes', 'intro', 'concept', false, 'Uma solução foi preparada dissolvendo 25 g de um sal em água suficiente para completar 500 mL de solução. A concentração comum dessa solução é:', 'Concentração comum é massa do soluto dividida pelo volume da solução em litros.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-1', 'A', '0,05 g/L', false, 'Corresponde a dividir a massa pelo volume em mililitros.', 'esquecer a conversão de unidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-1', 'B', '25 g/L', false, 'Corresponde a supor 1 L de solução.', 'ignorar o volume informado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-1', 'C', '50 g/L', true, 'C = m/V = 25 g ÷ 0,5 L = 50 g/L.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-1', 'D', '12,5 g/L', false, 'Corresponde a multiplicar a massa pelo volume em litros.', 'inverter a operação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-1', 'E', '500 g/L', false, 'Confunde o volume com a concentração.', 'trocar as grandezas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-sol-2', 'solucoes', 'calcular-e-interpretar-concentracoes', 'intermediate', 'applied', false, 'Um laboratório precisa preparar 400 mL de solução 0,5 mol/L a partir de uma solução estoque de 2 mol/L. O volume da solução estoque necessário é:', 'A concentração cai quatro vezes, então o volume inicial é um quarto do final: 100 mL de estoque completados até 400 mL.', NULL, 'Confira sempre pelo fator: concentração dividida por 4 significa volume multiplicado por 4.', NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-2', 'A', '50 mL', false, 'Corresponde a uma diluição de 1:8.', 'errar o fator de diluição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-2', 'B', '100 mL', true, 'C₁V₁ = C₂V₂ → 2 × V₁ = 0,5 × 400 → V₁ = 200/2 = 100 mL. Completa-se com água até 400 mL.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-2', 'C', '400 mL', false, 'Não haveria diluição alguma.', 'ignorar a mudança de concentração');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-2', 'D', '1.600 mL', false, 'Corresponde a inverter a relação entre as concentrações.', 'inverter a razão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-2', 'E', '200 mL', false, 'Corresponde a uma diluição de 1:2, e não de 1:4.', 'errar o fator de diluição');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-sol-3', 'solucoes', 'calcular-e-interpretar-concentracoes', 'intermediate', 'interpretation', false, 'A tabela mostra a solubilidade de um sal em água:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-3', 'A', '35 g', false, 'Esse seria o resultado para 100 g de água; a solução tem 300 g.', 'não ajustar a massa de água');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-3', 'B', '105 g', true, 'A 60 °C, 300 g de água dissolvem 65 × 3 = 195 g. A 20 °C, dissolvem 30 × 3 = 90 g. Precipitam 195 − 90 = 105 g.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-3', 'C', '195 g', false, 'É a massa total dissolvida a 60 °C, não o precipitado.', 'confundir total com diferença');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-3', 'D', '90 g', false, 'É a massa que permanece dissolvida a 20 °C.', 'responder a parte que permanece');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-3', 'E', '45 g', false, 'Corresponde à solubilidade a 40 °C, temperatura que não aparece no problema.', 'usar a linha errada da tabela');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-sol-4', 'solucoes', 'calcular-e-interpretar-concentracoes', 'challenging', 'comparison', false, 'Compare dois procedimentos para dissolver açúcar em água:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-4', 'A', 'Nenhum dos dois tem efeito, pois a solubilidade é uma constante imutável.', false, 'A solubilidade depende da temperatura, e a velocidade depende das condições do processo.', 'tratar solubilidade como constante absoluta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-4', 'B', 'I acelera a dissolução sem alterar a quantidade máxima dissolvida; II aumenta a solubilidade, permitindo dissolver mais açúcar.', true, 'Trituração e agitação aumentam a superfície de contato e o transporte, o que acelera o processo. Já a temperatura desloca o equilíbrio e aumenta a quantidade máxima que se dissolve.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-4', 'C', 'Os dois procedimentos aumentam a solubilidade na mesma proporção.', false, 'Agitação não altera a solubilidade máxima.', 'igualar efeitos distintos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-4', 'D', 'Os dois apenas aceleram a dissolução, sem alterar a solubilidade.', false, 'O aquecimento altera a solubilidade da maioria dos sólidos.', 'ignorar o efeito da temperatura');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-4', 'E', 'I aumenta a solubilidade e II apenas acelera o processo.', false, 'Os efeitos estão trocados.', 'inverter os efeitos');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-sol-5', 'solucoes', 'calcular-e-interpretar-concentracoes', 'challenging', 'integration', false, 'Uma estação de tratamento precisa dosar cloro na água. O manual recomenda concentração final entre 0,5 e 1,0 mg/L em um reservatório de 200.000 litros. O operador dispõe de uma solução concentrada de 50 g/L.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-5', 'A', 'Qualquer quantidade serve, desde que o cloro seja diluído antes da aplicação.', false, 'Concentração fora da faixa compromete a desinfecção ou a potabilidade.', 'ignorar limites técnicos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-5', 'B', 'A solução concentrada deve ser aplicada diretamente, sem cálculo, pois o volume do reservatório é muito grande.', false, 'Volume grande não dispensa cálculo: é justamente o que determina a massa necessária.', 'dispensar o cálculo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-5', 'C', 'São necessários 100 litros da solução concentrada para atingir 0,5 mg/L.', false, 'Esse volume produziria concentração mil vezes maior que a recomendada.', 'errar a ordem de grandeza');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-5', 'D', 'A dosagem não pode ser calculada sem conhecer a temperatura da água.', false, 'A temperatura afeta a estabilidade do cloro, mas não impede o cálculo da dosagem.', 'exigir dado desnecessário para o cálculo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-5', 'E', 'Para 0,5 mg/L são necessários 2 litros da solução, e para 1,0 mg/L, 4 litros — faixa dentro da qual a dosagem deve ser mantida e monitorada.', true, 'Massa necessária para 0,5 mg/L: 0,5 mg × 200.000 = 100.000 mg = 100 g. Como a solução tem 50 g/L, são 2 L. Para 1,0 mg/L, 200 g, ou 4 L. A dosagem deve permanecer nessa faixa e ser verificada.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-sol-rec-1', 'solucoes', 'calcular-e-interpretar-concentracoes', 'intro', 'concept', true, 'Uma solução em que a quantidade de soluto dissolvido é a máxima possível naquela temperatura é chamada de:', 'Saturada é a solução no limite de dissolução para aquela temperatura.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-rec-1', 'A', 'Coloidal.', false, 'Coloide é outro tipo de dispersão, com partículas maiores.', 'trocar o tipo de mistura');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-rec-1', 'B', 'Insaturada.', false, 'Insaturada é aquela que ainda pode dissolver mais soluto.', 'trocar a classificação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-rec-1', 'C', 'Saturada.', true, 'A solução saturada contém exatamente a quantidade máxima de soluto que se dissolve naquela temperatura.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-rec-1', 'D', 'Supersaturada.', false, 'Supersaturada contém mais soluto do que o máximo estável, e é instável.', 'confundir com estado instável');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-sol-rec-1', 'E', 'Diluída.', false, 'Diluída indica baixa concentração, sem referência ao limite de saturação.', 'confundir com concentração baixa');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-sol-1', 'solucoes', 'calcular-e-interpretar-concentracoes', 'intro', 'concept', false, 'Uma solução é chamada de saturada quando:', 'Saturada é uma solução no limite de dissolução para aquela temperatura. Concentrada apenas indica muito soluto, sem referência ao limite.', 'Saturada é uma solução no limite de dissolução para aquela temperatura. Concentrada apenas indica muito soluto, sem referência ao limite.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-1', 'A', 'apresenta corpo de fundo em qualquer temperatura.', false, 'Corpo de fundo indica excesso além da saturação, e depende da temperatura.', 'condição incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-1', 'B', 'não admite aumento de temperatura sem precipitar.', false, 'Aquecer costuma aumentar a solubilidade de sólidos em água.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-1', 'C', 'tem soluto e solvente em massas iguais.', false, 'A igualdade de massas não define saturação.', 'critério inventado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-1', 'D', 'contém a quantidade máxima de soluto que o solvente dissolve naquela temperatura.', true, 'Saturação é um limite dependente da temperatura, e não uma quantidade absoluta.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-1', 'E', 'contém grande quantidade de soluto dissolvido.', false, 'Muita quantidade descreve uma solução concentrada, que pode não estar saturada.', 'confundir com concentrada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-sol-2', 'solucoes', 'calcular-e-interpretar-concentracoes', 'intro', 'applied', false, 'Dissolvendo 30 g de sal em água suficiente para 500 mL de solução, a concentração em massa por volume é de:', 'Concentração comum é massa de soluto dividida por volume de solução em litros. Meio litro dobra o valor por litro.', 'Concentração comum é massa de soluto dividida por volume de solução em litros. Meio litro dobra o valor por litro.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-2', 'A', '60 g/L.', true, 'Volume: 0,5 L. Concentração: 30 ÷ 0,5 = 60 g/L.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-2', 'B', '30 g/L.', false, 'Esse valor supõe volume de um litro.', 'ignorar o volume real');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-2', 'C', '600 g/L.', false, 'Esse valor resulta de um erro de fator dez na conversão.', 'erro de conversão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-2', 'D', '0,06 g/L.', false, 'Esse valor divide a massa pelo volume em mililitros.', 'unidade incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-2', 'E', '15 g/L.', false, 'Esse valor multiplica a massa por 0,5 em vez de dividir.', 'operação invertida');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-sol-3', 'solucoes', 'calcular-e-interpretar-concentracoes', 'intermediate', 'interpretation', false, 'Um rótulo indica "soro fisiológico 0,9%". Essa informação significa que em 100 mL de solução há:', 'Percentual em soluções precisa de referência explícita. Nesse caso, é massa de soluto por volume de solução: 0,9 g em 100 mL.', 'Percentual em soluções precisa de referência explícita. Nesse caso, é massa de soluto por volume de solução: 0,9 g em 100 mL.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-3', 'A', '0,9 g de cloreto de sódio dissolvidos.', true, 'A convenção para essa preparação é massa em gramas por 100 mL de solução.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-3', 'B', '0,9 g de sal para cada 100 g de água.', false, 'A referência é o volume de solução, não a massa de água.', 'referência incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-3', 'C', '9 g de sal em cada litro de água pura.', false, 'São 9 g por litro de solução, e não de água pura.', 'referência incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-3', 'D', '0,9% do peso corporal de quem recebe o soro.', false, 'O percentual não tem relação com o peso do paciente.', 'referência incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-3', 'E', '0,9 mL de sal e 99,1 mL de água.', false, 'O sal é sólido; o percentual expressa massa por volume de solução.', 'unidade incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-sol-4', 'solucoes', 'calcular-e-interpretar-concentracoes', 'intermediate', 'comparison', false, 'Comparando o efeito da temperatura sobre a solubilidade de um sal e de um gás em água, espera-se que, ao aquecer a água:', 'Sólidos e gases respondem de modo oposto ao aquecimento. É por isso que refrigerante gelado retém mais gás e água quente dissolve mais açúcar.', 'Sólidos e gases respondem de modo oposto ao aquecimento. É por isso que refrigerante gelado retém mais gás e água quente dissolve mais açúcar.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-4', 'A', 'a maioria dos sais se dissolva mais, enquanto os gases se dissolvam menos.', true, 'Aquecer favorece a dissolução da maioria dos sólidos e diminui a de gases, que ganham energia para deixar a solução.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-4', 'B', 'a temperatura não afete a solubilidade de nenhum dos dois.', false, 'A solubilidade é fortemente dependente da temperatura.', 'negar a relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-4', 'C', 'ambos se dissolvam mais.', false, 'Gases tendem a escapar da solução com o aquecimento.', 'igualar as tendências');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-4', 'D', 'ambos se dissolvam menos.', false, 'A maioria dos sais aumenta a solubilidade com a temperatura.', 'igualar as tendências');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-4', 'E', 'o sal se dissolva menos e o gás, mais.', false, 'A relação está invertida para os dois casos.', 'inverter as tendências');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-sol-5', 'solucoes', 'calcular-e-interpretar-concentracoes', 'challenging', 'integration', false, 'Para preparar 2 litros de solução a 5 g/L a partir de uma solução estoque a 40 g/L, o volume de estoque necessário e o procedimento correto são:', 'Em diluição, a massa de soluto não muda: concentração vezes volume permanece constante. O volume final se atinge completando, não somando.', 'Em diluição, a massa de soluto não muda: concentração vezes volume permanece constante. O volume final se atinge completando, não somando.', 'Calcule primeiro a massa de soluto exigida pela solução final. Depois pergunte que volume do estoque contém essa massa.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-5', 'A', '800 mL de estoque, completando até 2 litros.', false, 'Esse volume corresponde a 32 g de soluto.', 'massa incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-5', 'B', '2 litros de estoque diluídos pela metade.', false, 'Isso resultaria em 20 g/L, muito acima do alvo.', 'diluição insuficiente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-5', 'C', '250 mL de estoque, completando com água até 2 litros.', true, 'A massa necessária é 10 g. No estoque, 10 g ocupam 10 ÷ 40 = 0,25 L. O volume final é completado até 2 L.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-5', 'D', '250 mL de estoque somados a 2 litros de água.', false, 'Isso produziria 2,25 L e concentração menor que a desejada.', 'somar em vez de completar');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-sol-5', 'E', '500 mL de estoque, completando até 2 litros.', false, 'Esse volume levaria 20 g de soluto, o dobro do necessário.', 'massa incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-esteq-1', 'estequiometria-introdutoria', 'calcular-quantidades-em-reacoes-quimicas', 'intro', 'concept', false, 'Considere a reação balanceada: 2 H₂ + O₂ → 2 H₂O. A partir de 4 mol de H₂, com oxigênio em excesso, a quantidade de água formada é:', 'Os coeficientes 2 e 2 estabelecem proporção 1:1 entre H₂ e H₂O.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-1', 'A', '8 mol', false, 'Corresponde a dobrar indevidamente a quantidade.', 'errar a proporção');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-1', 'B', '4 mol', true, 'A proporção é 2 H₂ para 2 H₂O, ou seja, 1:1. Assim, 4 mol de H₂ produzem 4 mol de H₂O.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-1', 'C', '1 mol', false, 'Corresponde à quantidade de O₂ necessária dividida por dois.', 'responder outra grandeza');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-1', 'D', '16 mol', false, 'Não corresponde a nenhuma proporção da equação.', 'estimar sem calcular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-1', 'E', '2 mol', false, 'Corresponde a metade do valor correto.', 'inverter a proporção');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-esteq-2', 'estequiometria-introdutoria', 'calcular-quantidades-em-reacoes-quimicas', 'intermediate', 'applied', false, 'Na reação CaCO₃ → CaO + CO₂, a decomposição de 400 g de carbonato de cálcio produz, teoricamente, uma massa de óxido de cálcio igual a: (massas molares: CaCO₃ = 100 g/mol; CaO = 56 g/mol)', 'Percorra sempre massa → mol → proporção → mol → massa. A verificação: 224 g de CaO + 176 g de CO₂ = 400 g.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-2', 'A', '100 g', false, 'Corresponde à massa molar do reagente, não ao resultado.', 'confundir dado com resposta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-2', 'B', '176 g', false, 'Corresponde à massa de CO₂ liberada.', 'responder o outro produto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-2', 'C', '224 g', true, 'mols de CaCO₃ = 400/100 = 4 mol. Proporção 1:1 → 4 mol de CaO. Massa = 4 × 56 = 224 g.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-2', 'D', '56 g', false, 'Corresponde a 1 mol de CaO apenas.', 'esquecer a quantidade de mols');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-2', 'E', '400 g', false, 'Ignora a liberação de CO₂, que carrega parte da massa.', 'supor conservação total no sólido');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-esteq-3', 'estequiometria-introdutoria', 'calcular-quantidades-em-reacoes-quimicas', 'intermediate', 'interpretation', false, 'Um experimento previa a produção teórica de 90 g de um produto. Foram obtidos 72 g. O rendimento da reação foi de:', 'Rendimento compara o que se obteve com o que a estequiometria previa: sempre obtido sobre teórico.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-3', 'A', '125%', false, 'Corresponde a dividir o teórico pelo obtido; rendimento não pode passar de 100%.', 'inverter a razão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-3', 'B', '80%', true, 'Rendimento = obtido ÷ teórico × 100 = 72 ÷ 90 × 100 = 80%.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-3', 'C', '18%', false, 'Corresponde à perda, e não ao rendimento.', 'responder o complementar em valor absoluto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-3', 'D', '72%', false, 'Confunde a massa obtida com o percentual.', 'copiar o dado como resposta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-3', 'E', '20%', false, 'É o percentual de perda, não o rendimento.', 'responder o complementar');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-esteq-4', 'estequiometria-introdutoria', 'calcular-quantidades-em-reacoes-quimicas', 'challenging', 'comparison', false, 'Na reação N₂ + 3 H₂ → 2 NH₃, são colocados para reagir 2 mol de N₂ e 3 mol de H₂.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-4', 'A', 'Formam-se 3 mol de NH₃, correspondendo aos mols de H₂ disponíveis.', false, 'A proporção é 3 H₂ para 2 NH₃, e não 1:1.', 'ignorar os coeficientes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-4', 'B', 'O H₂ é o reagente limitante e formam-se 2 mol de NH₃, restando 1 mol de N₂ sem reagir.', true, 'Por N₂: 2 mol → 4 mol de NH₃. Por H₂: 3/3 = 1 → 2 mol de NH₃. O menor valor manda: 2 mol de NH₃, com 1 mol de N₂ sobrando.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-4', 'C', 'O N₂ é o limitante, pois está em menor quantidade em massa.', false, 'Massa não define o limitante; a razão entre mols e coeficientes define.', 'usar massa como critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-4', 'D', 'Formam-se 4 mol de NH₃, pois há 2 mol de N₂ disponíveis.', false, 'Não há hidrogênio suficiente para consumir todo o N₂.', 'ignorar o limitante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-4', 'E', 'Nenhum reagente é limitante, pois ambos estão presentes.', false, 'Sempre que a proporção não é exata, um dos reagentes limita.', 'negar a existência do limitante');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-esteq-5', 'estequiometria-introdutoria', 'calcular-quantidades-em-reacoes-quimicas', 'challenging', 'integration', false, 'Uma indústria calcula que precisa de 500 kg de um reagente para produzir determinada quantidade de produto. Na prática, o rendimento do processo é de 80% e parte do reagente contém 5% de impurezas.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-5', 'A', 'Não é possível corrigir o cálculo, pois rendimento e pureza são imprevisíveis.', false, 'Ambos são medidos e usados rotineiramente no planejamento industrial.', 'tratar variáveis conhecidas como imprevisíveis');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-5', 'B', 'É preciso corrigir o cálculo pelos dois fatores, o que eleva a necessidade para cerca de 658 kg do reagente comercial.', true, 'Primeiro corrige-se o rendimento: 500 ÷ 0,80 = 625 kg de reagente puro. Depois a pureza: 625 ÷ 0,95 ≈ 658 kg do material comercial. Os dois efeitos se multiplicam, não se cancelam.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-5', 'C', 'Basta aumentar a quantidade de reagente em 20% para compensar o rendimento.', false, 'A correção do rendimento é necessária, mas não é a única: a pureza também reduz a massa efetivamente reagente.', 'considerar apenas um fator');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-5', 'D', 'Basta aumentar a quantidade em 5% para compensar as impurezas.', false, 'Faltaria compensar a perda de rendimento.', 'considerar apenas um fator');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-5', 'E', 'O rendimento e a pureza se cancelam, de modo que 500 kg são suficientes.', false, 'Os dois fatores atuam na mesma direção: ambos reduzem o produto obtido.', 'supor cancelamento inexistente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-esteq-rec-1', 'estequiometria-introdutoria', 'calcular-quantidades-em-reacoes-quimicas', 'intro', 'concept', true, 'A massa de 3 mol de água (massa molar 18 g/mol) é de:', 'Para converter mol em massa, multiplique pela massa molar.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-rec-1', 'A', '54 g', true, 'Massa = mols × massa molar = 3 × 18 = 54 g.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-rec-1', 'B', '21 g', false, 'Corresponde a somar 3 e 18.', 'somar em vez de multiplicar');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-rec-1', 'C', '0,17 g', false, 'Corresponde a dividir 3 por 18.', 'inverter a razão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-rec-1', 'D', '6 g', false, 'Corresponde a dividir a massa molar pela quantidade de mols.', 'inverter a operação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-esteq-rec-1', 'E', '18 g', false, 'Corresponde a 1 mol apenas.', 'ignorar a quantidade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-est3-1', 'estequiometria-introdutoria', 'calcular-quantidades-em-reacoes-quimicas', 'intro', 'concept', false, 'Os coeficientes de uma equação química balanceada indicam:', 'Coeficientes são proporções de quantidade de matéria. Convertê-los em massa exige passar pela massa molar de cada substância.', 'Coeficientes são proporções de quantidade de matéria. Convertê-los em massa exige passar pela massa molar de cada substância.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-1', 'A', 'a velocidade com que cada substância é consumida.', false, 'Velocidade depende de condições cinéticas, não dos coeficientes.', 'grandeza trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-1', 'B', 'a ordem em que as substâncias devem ser misturadas.', false, 'A equação não prescreve procedimento experimental.', 'interpretação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-1', 'C', 'a proporção em número de partículas ou em mols entre reagentes e produtos.', true, 'Balancear garante que a proporção entre quantidades de matéria seja respeitada, refletindo a conservação dos átomos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-1', 'D', 'a energia liberada por cada substância na reação.', false, 'Energia aparece em outra notação, não nos coeficientes.', 'grandeza trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-1', 'E', 'as massas em gramas de cada substância envolvida.', false, 'Massas dependem também da massa molar de cada substância.', 'confundir proporção com massa');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-est3-2', 'estequiometria-introdutoria', 'calcular-quantidades-em-reacoes-quimicas', 'intermediate', 'applied', false, 'Na reação em que 2 mols de hidrogênio reagem com 1 mol de oxigênio formando 2 mols de água, a quantidade de água obtida a partir de 5 mols de hidrogênio, com oxigênio em excesso, é de:', 'A proporção 2:2 entre hidrogênio e água simplifica para 1:1. Com oxigênio em excesso, o hidrogênio determina a quantidade formada.', 'A proporção 2:2 entre hidrogênio e água simplifica para 1:1. Com oxigênio em excesso, o hidrogênio determina a quantidade formada.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-2', 'A', '10 mols.', false, 'Esse valor dobra indevidamente a quantidade.', 'fator incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-2', 'B', '1 mol.', false, 'Esse valor corresponde ao oxigênio consumido em outra escala.', 'substância trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-2', 'C', 'Não é possível calcular sem a massa das substâncias.', false, 'A proporção em mols basta para a resposta pedida.', 'exigir dado desnecessário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-2', 'D', '2,5 mols.', false, 'Esse valor aplicaria a proporção de forma invertida.', 'razão invertida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-2', 'E', '5 mols.', true, 'A proporção entre hidrogênio e água é de 2 para 2, ou seja, de 1 para 1.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-est3-3', 'estequiometria-introdutoria', 'calcular-quantidades-em-reacoes-quimicas', 'intermediate', 'interpretation', false, 'Um estudante afirma que, se dobrar a quantidade de um reagente, o produto formado sempre dobra. Sobre essa afirmação:', 'Quem determina a quantidade de produto é o reagente limitante. Aumentar o que já estava sobrando não muda o resultado.', 'Quem determina a quantidade de produto é o reagente limitante. Aumentar o que já estava sobrando não muda o resultado.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-3', 'A', 'está correta desde que a temperatura seja constante.', false, 'A temperatura afeta velocidade e equilíbrio, mas não é o que invalida a afirmação.', 'condição trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-3', 'B', 'está correta, pois as proporções são fixas.', false, 'As proporções são fixas, mas o outro reagente pode acabar antes.', 'ignorar o limitante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-3', 'C', 'está correta apenas em reações reversíveis.', false, 'A reversibilidade não é o ponto em discussão.', 'condição trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-3', 'D', 'está incorreta: só vale se o reagente dobrado for o limitante e o outro estiver em excesso suficiente.', true, 'Se o reagente dobrado já estava em excesso, dobrar sua quantidade não altera o produto formado.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-3', 'E', 'está incorreta porque proporções estequiométricas não existem na prática.', false, 'Elas existem e são a base do cálculo.', 'negar a estequiometria');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-est3-4', 'estequiometria-introdutoria', 'calcular-quantidades-em-reacoes-quimicas', 'intermediate', 'comparison', false, 'Comparando rendimento teórico e rendimento real de uma reação em laboratório, é correto afirmar que:', 'O rendimento teórico é um teto calculado. O real mede quanto desse teto se alcançou nas condições concretas do experimento.', 'O rendimento teórico é um teto calculado. O real mede quanto desse teto se alcançou nas condições concretas do experimento.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-4', 'A', 'o rendimento real costuma superar o teórico.', false, 'Superar o teórico indicaria erro de medida ou impureza no produto.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-4', 'B', 'o rendimento teórico depende da habilidade do operador.', false, 'O teórico decorre da estequiometria; a habilidade afeta o real.', 'inverter os conceitos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-4', 'C', 'o rendimento real independe da pureza dos reagentes.', false, 'Impurezas reduzem a quantidade efetiva de reagente disponível.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-4', 'D', 'o teórico é o máximo previsto pela estequiometria e o real costuma ser menor, por perdas, reações incompletas e impurezas.', true, 'A diferença entre os dois é justamente o que o rendimento percentual quantifica.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-4', 'E', 'os dois devem coincidir sempre que o cálculo estiver correto.', false, 'Perdas experimentais e reações incompletas afastam um do outro mesmo com cálculo correto.', 'ignorar perdas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-est3-5', 'estequiometria-introdutoria', 'calcular-quantidades-em-reacoes-quimicas', 'challenging', 'integration', false, 'Na reação entre carbono e oxigênio formando dióxido de carbono, sabendo que as massas molares são 12 g/mol para o carbono, 32 g/mol para o oxigênio molecular e 44 g/mol para o dióxido, a massa de dióxido obtida a partir de 24 g de carbono, com oxigênio em excesso, é de:', 'Cálculos estequiométricos passam sempre pela quantidade de matéria: converta massa em mols, aplique a proporção e volte para massa.', 'Cálculos estequiométricos passam sempre pela quantidade de matéria: converta massa em mols, aplique a proporção e volte para massa.', 'Nunca opere diretamente com gramas. Massa vira mol, mol aplica a proporção da equação, e só então o resultado volta a gramas.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-5', 'A', '44 g.', false, 'Esse valor corresponde a apenas 1 mol de dióxido.', 'quantidade de matéria incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-5', 'B', '56 g.', false, 'Esse valor soma massas sem respeitar a proporção em mols.', 'somar massas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-5', 'C', '24 g.', false, 'Essa é a massa de carbono empregada, não a de produto.', 'confundir reagente com produto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-5', 'D', '32 g.', false, 'Essa é a massa molar do oxigênio molecular.', 'valor de tabela');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-est3-5', 'E', '88 g.', true, '24 g de carbono correspondem a 2 mols. A proporção é de 1 para 1, então formam-se 2 mols de dióxido: 2 × 44 = 88 g.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qamb-1', 'quimica-ambiental', 'relacionar-processos-quimicos-e-impactos-ambientais', 'intro', 'concept', false, 'A intensificação do efeito estufa observada nas últimas décadas está associada principalmente ao aumento da concentração atmosférica de:', 'CO₂, CH₄ e N₂O são os principais gases cujas concentrações aumentaram por ação humana e que intensificam o efeito estufa.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-1', 'A', 'Gás nitrogênio (N₂) e gás oxigênio (O₂).', false, 'São os gases mais abundantes da atmosfera e não absorvem radiação infravermelha de forma significativa.', 'confundir abundância com efeito estufa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-1', 'B', 'Clorofluorcarbonos, responsáveis pela destruição do ozônio estratosférico.', false, 'CFCs afetam a camada de ozônio; sua contribuição não é o principal fator do aquecimento observado.', 'trocar os dois fenômenos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-1', 'C', 'Ozônio estratosférico, que retém o calor na superfície.', false, 'O ozônio estratosférico filtra radiação ultravioleta e não é o principal gás de efeito estufa.', 'confundir os fenômenos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-1', 'D', 'Dióxido de carbono, metano e óxido nitroso.', true, 'Esses gases absorvem e reemitem radiação infravermelha na troposfera, e suas concentrações aumentaram com a queima de combustíveis fósseis, a agropecuária e os resíduos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-1', 'E', 'Vapor de água exclusivamente, por ser o gás mais abundante da atmosfera.', false, 'O vapor d''água responde à temperatura, funcionando como amplificador; o forçamento inicial vem dos gases emitidos por atividade humana.', 'inverter causa e efeito');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qamb-2', 'quimica-ambiental', 'relacionar-processos-quimicos-e-impactos-ambientais', 'intermediate', 'applied', false, 'Em uma região com muitas indústrias que queimam combustíveis com alto teor de enxofre, observa-se acidificação de lagos e corrosão de monumentos de mármore.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-2', 'A', 'O ozônio troposférico se decompõe e forma ácidos que corroem estruturas.', false, 'O ozônio troposférico é um poluente relevante, mas não é o mecanismo da chuva ácida descrita.', 'trocar o poluente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-2', 'B', 'Os CFCs liberados reagem com a água da chuva formando ácido clorídrico.', false, 'CFCs atuam na estratosfera sobre o ozônio, e não são a causa da chuva ácida.', 'misturar os fenômenos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-2', 'C', 'O nitrogênio atmosférico se dissolve na chuva, tornando-a ácida.', false, 'O N₂ é praticamente inerte nessas condições; são os óxidos de nitrogênio, formados em altas temperaturas, que contribuem.', 'confundir N₂ com NOₓ');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-2', 'D', 'O CO₂ liberado na queima forma ácido carbônico, que dissolve o mármore rapidamente.', false, 'O CO₂ contribui para a acidez natural da chuva, mas não explica a acidificação intensa nem a corrosão acelerada descrita.', 'atribuir ao gás errado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-2', 'E', 'O SO₂ liberado é oxidado e reage com a água atmosférica formando ácido sulfúrico, que acidifica os lagos e reage com o carbonato de cálcio do mármore.', true, 'A queima de combustíveis com enxofre libera SO₂; na atmosfera ele forma H₂SO₄, que precipita, acidifica corpos d''água e reage com o CaCO₃ das estruturas de mármore.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qamb-3', 'quimica-ambiental', 'relacionar-processos-quimicos-e-impactos-ambientais', 'intermediate', 'interpretation', false, 'A tabela mostra o pH da água da chuva medido em quatro pontos de uma região:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-3', 'A', 'A área portuária tem chuva alcalina, por estar próxima ao mar.', false, 'pH 4,5 é ácido, bem abaixo do neutro.', 'confundir ácido com alcalino');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-3', 'B', 'Os dados não permitem comparação, pois o pH varia naturalmente.', false, 'A variação natural é conhecida, e é justamente o que permite identificar o desvio antrópico.', 'descartar dado comparável');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-3', 'C', 'Os quatro pontos apresentam chuva ácida de origem antrópica.', false, 'O ponto rural está no valor de referência da chuva não poluída.', 'incluir o valor de referência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-3', 'D', 'A diferença entre 5,6 e 4,2 é pequena, pois corresponde a pouco mais de um ponto na escala.', false, 'A escala é logarítmica: essa diferença corresponde a cerca de 25 vezes mais íons H⁺.', 'ler a escala como linear');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-3', 'E', 'O centro industrial apresenta a chuva mais ácida, com concentração de íons H⁺ cerca de 25 vezes maior que a do ponto rural.', true, 'Cada unidade de pH corresponde a um fator de dez. A diferença de 1,4 unidade entre 5,6 e 4,2 equivale a 10^1,4 ≈ 25 vezes mais íons H⁺.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qamb-4', 'quimica-ambiental', 'relacionar-processos-quimicos-e-impactos-ambientais', 'challenging', 'comparison', false, 'Compare dois destinos para resíduos sólidos urbanos:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-4', 'A', 'O aterro sanitário elimina completamente os impactos ambientais dos resíduos.', false, 'Ele reduz e controla impactos, mas ocupa área, gera emissões residuais e tem vida útil limitada.', 'supor solução sem impacto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-4', 'B', 'O lixão é preferível, pois permite a decomposição natural dos resíduos.', false, 'A decomposição em lixão contamina solo e água e libera metano sem controle.', 'confundir ausência de estrutura com processo natural benéfico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-4', 'C', 'A diferença entre eles é apenas estética e de organização do espaço.', false, 'A diferença é de contaminação de solo, água e ar.', 'minimizar impactos técnicos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-4', 'D', 'O lixão contamina solo e águas subterrâneas pelo chorume e libera metano sem controle; o aterro reduz esses impactos, mas ainda ocupa área, tem vida útil limitada e não substitui a redução na geração de resíduos.', true, 'A comparação correta reconhece a superioridade técnica do aterro sanitário sem tratá-lo como solução definitiva: a hierarquia de resíduos começa em reduzir e reutilizar.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-4', 'E', 'Os dois produzem os mesmos impactos, já que ambos acumulam resíduos no solo.', false, 'A impermeabilização e o tratamento do chorume mudam radicalmente o impacto sobre solo e água.', 'ignorar as diferenças técnicas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qamb-5', 'quimica-ambiental', 'relacionar-processos-quimicos-e-impactos-ambientais', 'challenging', 'integration', false, 'Um município avalia trocar a frota de ônibus a diesel por veículos elétricos, com energia proveniente majoritariamente de hidrelétricas.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-5', 'A', 'O benefício é apenas econômico, sem efeito ambiental relevante.', false, 'A redução de material particulado e NOₓ tem efeito ambiental e sanitário direto.', 'negar o efeito ambiental');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-5', 'B', 'A análise deve considerar apenas as emissões de CO₂, já que são as mais relevantes para o clima.', false, 'Material particulado e NOₓ têm efeito imediato sobre a saúde e não podem ser ignorados na análise urbana.', 'reduzir a análise a um poluente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-5', 'C', 'A troca elimina as emissões locais de material particulado e óxidos de nitrogênio, com ganho direto para a saúde urbana, mas a avaliação completa exige considerar a matriz energética, a produção e o descarte das baterias e os impactos das próprias hidrelétricas.', true, 'A queima de diesel emite material particulado e NOₓ, que afetam diretamente a saúde nas vias urbanas. A eletrificação remove essa emissão no ponto de uso; o balanço final depende de como a eletricidade é gerada e do ciclo de vida das baterias.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-5', 'D', 'A medida não traz benefício algum, pois a energia elétrica também precisa ser gerada.', false, 'Com matriz predominantemente hidrelétrica, o balanço de emissões é bastante favorável.', 'anular o ganho pela existência de geração');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-5', 'E', 'A medida elimina completamente os impactos ambientais do transporte público.', false, 'Produção de veículos, baterias e infraestrutura mantêm impactos relevantes.', 'supor impacto zero');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-qamb-rec-1', 'quimica-ambiental', 'relacionar-processos-quimicos-e-impactos-ambientais', 'intro', 'concept', true, 'Na estação de tratamento de água, a etapa de desinfecção tem como objetivo principal:', 'Desinfecção elimina microrganismos causadores de doenças; as etapas anteriores cuidam das partículas em suspensão.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-rec-1', 'A', 'Retirar sais dissolvidos da água.', false, 'A remoção de sais dissolvidos exige processos como osmose reversa, que não fazem parte do tratamento convencional.', 'atribuir função de outro processo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-rec-1', 'B', 'Aumentar a temperatura da água antes da distribuição.', false, 'Não há aquecimento no tratamento convencional de água potável.', 'inventar etapa inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-rec-1', 'C', 'Remover partículas sólidas em suspensão.', false, 'Essa é a função das etapas de coagulação, floculação, decantação e filtração.', 'trocar a etapa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-rec-1', 'D', 'Corrigir o pH da água tratada.', false, 'A correção de pH é uma etapa distinta, feita ao final do processo.', 'trocar a etapa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-qamb-rec-1', 'E', 'Eliminar microrganismos patogênicos presentes na água.', true, 'A desinfecção, geralmente com cloro, inativa bactérias, vírus e protozoários que causam doenças.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-qamb-1', 'quimica-ambiental', 'relacionar-processos-quimicos-e-impactos-ambientais', 'intro', 'concept', false, 'A chuva ácida se forma principalmente pela reação, na atmosfera, entre água e:', 'Toda chuva é levemente ácida por causa do gás carbônico. O que caracteriza a chuva ácida é o acréscimo de óxidos de enxofre e nitrogênio.', 'Toda chuva é levemente ácida por causa do gás carbônico. O que caracteriza a chuva ácida é o acréscimo de óxidos de enxofre e nitrogênio.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-1', 'A', 'gás oxigênio liberado pelas plantas.', false, 'O oxigênio não acidifica a água da chuva.', 'substância incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-1', 'B', 'vapor de água em excesso na atmosfera.', false, 'Vapor de água é o próprio solvente, não o agente acidificante.', 'substância incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-1', 'C', 'gás nitrogênio presente naturalmente no ar.', false, 'O nitrogênio molecular é pouco reativo em condições ambientais.', 'substância incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-1', 'D', 'óxidos de enxofre e de nitrogênio, liberados sobretudo pela queima de combustíveis fósseis.', true, 'Esses óxidos reagem com a água formando ácidos que reduzem significativamente o pH da chuva.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-1', 'E', 'metano liberado pela decomposição de matéria orgânica.', false, 'O metano é gás de efeito estufa, mas não é precursor da chuva ácida.', 'substância incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-qamb-2', 'quimica-ambiental', 'relacionar-processos-quimicos-e-impactos-ambientais', 'intermediate', 'applied', false, 'Uma indústria despeja efluente ácido em um rio. Uma medida corretiva imediata e quimicamente coerente é:', 'Correção de pH em efluente se faz por neutralização controlada antes do lançamento. Diluir apenas espalha o problema.', 'Correção de pH em efluente se faz por neutralização controlada antes do lançamento. Diluir apenas espalha o problema.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-2', 'A', 'aquecer o efluente antes do descarte.', false, 'O aquecimento não altera a acidez e acrescenta poluição térmica.', 'medida incompatível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-2', 'B', 'filtrar o efluente para remover o ácido dissolvido.', false, 'Filtração remove material particulado, não espécies dissolvidas.', 'processo incompatível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-2', 'C', 'aumentar o volume de água despejado, para diluir o efluente.', false, 'Diluir reduz a concentração no ponto de lançamento, mas não retira a carga ácida do sistema.', 'diluição como solução');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-2', 'D', 'tratar o efluente com uma base antes do lançamento, ajustando o pH à faixa permitida.', true, 'A neutralização converte o excesso de ácido em sal e água, corrigindo a causa antes que ela chegue ao rio.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-2', 'E', 'adicionar mais ácido para estabilizar o pH.', false, 'Isso agravaria a acidez.', 'medida contrária');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-qamb-3', 'quimica-ambiental', 'relacionar-processos-quimicos-e-impactos-ambientais', 'intermediate', 'interpretation', false, 'Um relatório informa que determinado plástico leva séculos para se degradar no ambiente. Do ponto de vista químico, essa persistência decorre principalmente de:', 'Degradação depende de haver organismos capazes de romper as ligações presentes. Polímeros sintéticos apresentam estruturas para as quais isso é raro.', 'Degradação depende de haver organismos capazes de romper as ligações presentes. Polímeros sintéticos apresentam estruturas para as quais isso é raro.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-3', 'A', 'sua origem sintética, que impede qualquer reação química.', false, 'Materiais sintéticos participam de reações; o ponto é a velocidade da degradação biológica.', 'afirmação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-3', 'B', 'sua cor, que reflete a radiação solar.', false, 'A cor influencia pouco a degradação química de fundo.', 'propriedade irrelevante');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-3', 'C', 'sua dureza mecânica elevada.', false, 'Dureza é propriedade física e não determina resistência à degradação biológica.', 'propriedade trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-3', 'D', 'sua baixa densidade, que o mantém flutuando.', false, 'A flutuação afeta a distribuição no ambiente, não a velocidade de degradação.', 'propriedade trocada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-3', 'E', 'cadeias longas e ligações estáveis que os micro-organismos não conseguem quebrar com facilidade.', true, 'A estrutura polimérica não corresponde às moléculas que as enzimas microbianas evoluíram para degradar.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-qamb-4', 'quimica-ambiental', 'relacionar-processos-quimicos-e-impactos-ambientais', 'intermediate', 'comparison', false, 'Comparando o efeito estufa natural e o efeito estufa intensificado, é correto afirmar que:', 'O efeito estufa não é o problema: o problema é a sua intensificação. Distinguir os dois é condição para discutir causas e soluções.', 'O efeito estufa não é o problema: o problema é a sua intensificação. Distinguir os dois é condição para discutir causas e soluções.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-4', 'A', 'os dois envolvem apenas o gás carbônico.', false, 'Vapor de água, metano e óxido nitroso também participam.', 'reduzir a um gás');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-4', 'B', 'o efeito intensificado ocorre apenas em áreas urbanas.', false, 'A alteração da composição atmosférica tem efeito global.', 'escala incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-4', 'C', 'o natural mantém a temperatura média compatível com a vida, e o intensificado resulta do acréscimo de gases pela atividade humana.', true, 'O processo é o mesmo; o que muda é a concentração dos gases e, com ela, a quantidade de energia retida.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-4', 'D', 'ambos são prejudiciais e devem ser eliminados.', false, 'Sem o efeito estufa natural a temperatura média do planeta seria muito baixa para a vida como a conhecemos.', 'condenar o processo natural');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-4', 'E', 'o natural é causado pelo homem e o intensificado, pela natureza.', false, 'A relação está invertida.', 'inverter as causas');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-qamb-5', 'quimica-ambiental', 'relacionar-processos-quimicos-e-impactos-ambientais', 'challenging', 'integration', false, 'Um município substitui a queima de lixo a céu aberto pela coleta seletiva com reciclagem e compostagem. Do ponto de vista químico-ambiental, os principais ganhos são:', 'A mudança age em duas frentes: corta emissões tóxicas da queima e recoloca matéria em ciclo, reduzindo a pressão sobre recursos naturais.', 'A mudança age em duas frentes: corta emissões tóxicas da queima e recoloca matéria em ciclo, reduzindo a pressão sobre recursos naturais.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-5', 'A', 'evitar a emissão de poluentes da combustão incompleta e devolver matéria orgânica ao solo, reduzindo a extração de matéria-prima nova.', true, 'A queima a céu aberto libera material particulado e compostos tóxicos; compostar e reciclar mantêm matéria em ciclo em vez de degradá-la.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-5', 'B', 'eliminar por completo a geração de resíduos no município.', false, 'A geração continua; o que muda é a destinação.', 'consequência exagerada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-5', 'C', 'reduzir o consumo de energia elétrica das residências.', false, 'Não há relação direta entre destinação de resíduos e consumo elétrico domiciliar.', 'relação inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-5', 'D', 'aumentar a emissão de gases pela decomposição controlada.', false, 'A compostagem aeróbia gera menos metano que a decomposição em aterro sem controle.', 'efeito invertido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-qamb-5', 'E', 'dispensar a necessidade de aterro sanitário.', false, 'Parte dos rejeitos continua exigindo destinação final adequada.', 'consequência exagerada');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-red-1', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'intro', 'concept', false, 'Sobre o tema "Desafios para a permanência de jovens no ensino médio no Brasil", qual das formulações abaixo constitui uma tese adequada para um texto dissertativo-argumentativo?', 'Tese é posição contestável e delimitada — não anúncio, constatação nem consenso.', NULL, 'Teste da frase contrária: se o oposto da sua tese for absurdo, ela é óbvia demais.', NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-1', 'A', 'A escola é uma instituição muito importante para a sociedade brasileira.', false, 'É uma obviedade: ninguém discorda e não há o que sustentar ao longo do texto.', 'confundir consenso com tese');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-1', 'B', 'A evasão no ensino médio resulta principalmente da incompatibilidade entre a jornada escolar e a necessidade de trabalho dos estudantes, o que exige políticas de permanência e não apenas de acesso.', true, 'É contestável, delimita a causa apontada e já orienta o tipo de proposta. Alguém poderia defender outra causa principal — e é isso que caracteriza uma tese.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-1', 'C', 'Este texto vai discutir os desafios para a permanência de jovens no ensino médio.', false, 'É um anúncio do que será feito, não uma posição sobre o problema.', 'metatexto no lugar de tese');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-1', 'D', 'Muitos jovens abandonam a escola no Brasil todos os anos.', false, 'É uma constatação factual: descreve o problema sem oferecer explicação nem posição.', 'confundir dado com tese');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-1', 'E', 'Os jovens deveriam valorizar mais a oportunidade de estudar.', false, 'Atribui o problema exclusivamente ao indivíduo, sem sustentação, e desconsidera as condições que produzem a evasão.', 'individualizar problema estrutural');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-red-2', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'intermediate', 'applied', false, 'Leia o trecho de um parágrafo de desenvolvimento:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-2', 'A', 'Citações filosóficas não devem aparecer em redações.', false, 'Repertório filosófico é bem-vindo quando conectado ao argumento.', 'criar regra inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-2', 'B', 'O trecho apresenta erro gramatical que compromete o sentido.', false, 'Não há erro gramatical: o problema é de construção argumentativa.', 'confundir gramática com argumentação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-2', 'C', 'O repertório é apresentado sem análise que o conecte à afirmação, funcionando como enfeite.', true, 'Falta a etapa que liga a citação ao argumento: nada explica por que a afirmação de Locke sustenta a conclusão sobre transporte público. O salto lógico deixa o repertório improdutivo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-2', 'D', 'O autor citado é inadequado para textos escolares.', false, 'Locke é repertório legítimo; o problema está no uso, não na escolha.', 'julgar a fonte em vez do uso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-2', 'E', 'O trecho é longo demais para um parágrafo de desenvolvimento.', false, 'O trecho é curto; a extensão não é o problema.', 'avaliar forma em vez de raciocínio');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-red-3', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'intermediate', 'interpretation', false, 'Analise a proposta de intervenção:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-3', 'A', 'Propostas de intervenção são opcionais no texto dissertativo-argumentativo.', false, 'A proposta é parte esperada da conclusão nesse tipo de texto.', 'desconsiderar exigência do gênero');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-3', 'B', 'A proposta deveria vir na introdução, e não na conclusão.', false, 'A conclusão é o lugar usual da proposta, após a argumentação que a justifica.', 'errar a posição estrutural');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-3', 'C', 'Investimento em educação nunca resolve problemas sociais.', false, 'A crítica é à falta de especificidade da proposta, não ao mérito do investimento.', 'trocar crítica de forma por juízo de conteúdo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-3', 'D', 'Apesar de indicar um agente genérico, não especifica ação concreta, meio de execução, finalidade nem detalhamento.', true, '"Investir mais em educação" não diz o que fazer, como fazer, por meio de qual instrumento, para qual público ou com que objetivo verificável. Faltam quatro dos cinco elementos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-3', 'E', 'Menciona o governo, e propostas não devem envolver o poder público.', false, 'O poder público é agente legítimo e frequente em propostas de intervenção.', 'criar restrição inexistente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-red-4', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'challenging', 'comparison', false, 'Um estudante defende a tese de que a principal barreira ao acesso à cultura em cidades médias é a **concentração geográfica** dos equipamentos culturais nos centros urbanos.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-4', 'A', 'A população deve valorizar mais os espaços culturais disponíveis em sua cidade.', false, 'Transfere ao indivíduo a solução de uma barreira estrutural e não indica ação, meio nem detalhamento.', 'individualizar solução estrutural');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-4', 'B', 'O governo deve construir um grande centro cultural no centro da cidade, com programação diversificada.', false, 'Reforça exatamente a concentração que a tese aponta como problema.', 'proposta que contradiz a própria tese');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-4', 'C', 'É preciso que haja mais cultura para todos, com apoio de toda a sociedade.', false, 'Formulação genérica, sem nenhum dos cinco elementos.', 'proposta vaga');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-4', 'D', 'A secretaria municipal de cultura deve criar programação itinerante em equipamentos já existentes nos bairros periféricos — escolas e centros comunitários —, por meio de editais com contrapartida de transporte, a fim de aproximar a oferta cultural de quem está distante do centro.', true, 'Responde exatamente à barreira apontada (distância) e traz os cinco elementos: agente, ação, meio, finalidade e detalhamento.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-4', 'E', 'O Ministério da Educação deve incluir disciplinas de história da arte no currículo nacional para ampliar o repertório dos estudantes.', false, 'É uma proposta bem formulada, mas responde a outro problema — repertório —, não à concentração geográfica defendida na tese.', 'proposta coerente com outro problema');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-red-5', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'challenging', 'integration', false, 'Um texto defende que o principal obstáculo à saúde mental de adolescentes é a ausência de acolhimento nas escolas. Os dois parágrafos de desenvolvimento tratam, respectivamente, da falta de profissionais especializados nas redes de ensino e da ausência de formação de professores para identificar sinais de sofrimento.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-5', 'A', 'A tese está incorreta, pois saúde mental é responsabilidade exclusiva da família.', false, 'A avaliação pedida é da estrutura argumentativa, e a tese é legítima e defensável.', 'substituir análise por opinião sobre o mérito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-5', 'B', 'Faltaria um terceiro parágrafo de desenvolvimento para que o texto fosse válido.', false, 'Dois desenvolvimentos bem construídos são estrutura adequada e usual.', 'criar exigência formal inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-5', 'C', 'O texto deveria abandonar a tese inicial e tratar de outros fatores de saúde mental.', false, 'Delimitar é qualidade do texto dissertativo; abandonar a tese quebraria a coerência.', 'confundir delimitação com limitação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-5', 'D', 'Há progressão adequada: os dois parágrafos abordam ângulos distintos da mesma tese — recurso especializado e capacitação —, sustentando o obstáculo apontado.', true, 'Ambos tratam da mesma tese (ausência de acolhimento escolar), mas por caminhos diferentes: um trata da existência de profissionais, outro da preparação de quem já está lá. Isso é progressão, não repetição.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-5', 'E', 'Os parágrafos são redundantes, pois ambos tratam de pessoal escolar.', false, 'Tratar do mesmo campo não é redundância: contratar especialistas e formar professores são medidas distintas, com custos e efeitos diferentes.', 'confundir tema comum com repetição');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-red-rec-1', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'intro', 'concept', true, 'Em um texto dissertativo-argumentativo, a função do parágrafo de introdução é:', 'Introdução: problema + tese.', NULL, NULL, NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-rec-1', 'A', 'Apresentar o problema e explicitar a tese que será defendida.', true, 'A introdução situa o leitor no problema e deixa claro qual posição o texto vai sustentar.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-rec-1', 'B', 'Desenvolver integralmente o primeiro argumento.', false, 'O desenvolvimento dos argumentos ocorre nos parágrafos seguintes.', 'confundir com o desenvolvimento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-rec-1', 'C', 'Apresentar a proposta de intervenção.', false, 'A proposta pertence à conclusão, após a argumentação que a justifica.', 'antecipar a conclusão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-rec-1', 'D', 'Listar todas as fontes que serão citadas.', false, 'O gênero não exige lista de fontes.', 'aplicar convenção de outro gênero');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-rec-1', 'E', 'Resumir o texto motivador da prova.', false, 'Copiar ou resumir o texto motivador não constrói tese própria.', 'depender do texto motivador');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-red-rec-2', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'intermediate', 'applied', true, 'Qual elemento está ausente na proposta: "As escolas devem promover rodas de conversa mensais sobre saúde mental, com apoio de psicólogos da rede pública"?', 'Falta a finalidade: para que a ação existe.', NULL, 'Confira os cinco na ordem: quem, o quê, como, para quê, com que recorte.', NULL, 'AUTORAL_SEED', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-rec-2', 'A', 'O meio — não se indica como executar.', false, 'O meio é o apoio de psicólogos da rede pública.', 'não localizar o meio');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-rec-2', 'B', 'Nenhum elemento está ausente.', false, 'A finalidade não aparece de forma explícita.', 'não conferir os cinco elementos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-rec-2', 'C', 'A finalidade — não se explicita o objetivo que a ação pretende alcançar.', true, 'Agente (escolas), ação (rodas de conversa), meio (apoio de psicólogos) e detalhamento (mensais) estão presentes. Falta dizer para quê: reduzir evasão, ampliar identificação precoce de sofrimento, criar canal de escuta.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-rec-2', 'D', 'O agente — não há responsável indicado.', false, 'As escolas são indicadas como agente.', 'não localizar o agente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-rec-2', 'E', 'A ação — não se sabe o que fazer.', false, 'A ação é promover rodas de conversa.', 'não localizar a ação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-red-6', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'intro', 'concept', false, 'Tema: “Desafios para ampliar o acesso a espaços públicos de cultura”. Qual formulação apresenta uma tese defensável e delimitada?', 'Uma tese útil responde ao problema e antecipa caminhos de desenvolvimento; concentração territorial e comunicação formam dois eixos claros.', 'Uma tese útil responde ao problema e antecipa caminhos de desenvolvimento; concentração territorial e comunicação formam dois eixos claros.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-6', 'A', 'Espaços públicos de cultura.', false, 'Apenas repete o tema e não assume posição.', 'ausência de posicionamento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-6', 'B', 'O acesso permanece desigual porque equipamentos se concentram em áreas centrais e a divulgação não alcança parte da população.', true, 'A formulação assume posição e apresenta dois eixos argumentativos.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-6', 'C', 'A cultura é muito importante para todo mundo.', false, 'A afirmação é genérica e não delimita o problema de acesso.', 'generalidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-6', 'D', 'Existem museus, bibliotecas, teatros e centros culturais.', false, 'A enumeração informa, mas não defende uma interpretação.', 'confundir repertório com tese');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-6', 'E', 'Será que todos frequentam espaços culturais?', false, 'A pergunta pode introduzir o tema, mas não apresenta a posição do texto.', 'interrogação sem resposta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-red-7', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'intermediate', 'applied', false, 'Um estudante defende que escolas devem ampliar projetos de leitura. Qual evidência melhor sustenta um argumento sobre continuidade da prática?', 'O argumento sobre continuidade pede evidência longitudinal e comparativa, não apenas uma opinião ou registro de evento isolado.', 'O argumento sobre continuidade pede evidência longitudinal e comparativa, não apenas uma opinião ou registro de evento isolado.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-7', 'A', 'Uma fotografia da inauguração da biblioteca.', false, 'A imagem comprova um evento, não a continuidade do uso.', 'confundir inauguração com prática');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-7', 'B', 'Uma lista dos livros preferidos do estudante.', false, 'Preferência individual não demonstra continuidade de um projeto escolar.', 'evidência anedótica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-7', 'C', 'A afirmação de que ler é sempre bom.', false, 'A frase é valorativa e não comprova efeito de uma política continuada.', 'petição de princípio');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-7', 'D', 'O preço médio de capas de livros antigos.', false, 'O dado não se relaciona diretamente à manutenção da prática escolar.', 'irrelevância');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-7', 'E', 'Dados de frequência mostrando participação ao longo do ano, comparados entre projetos pontuais e recorrentes.', true, 'A comparação mede precisamente continuidade e adesão no tempo.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-red-8', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'intermediate', 'interpretation', false, 'Leia o período: “A entrega de computadores pode ampliar o acesso digital; contudo, sem conexão estável e formação docente, o equipamento tende a ter uso limitado.” A relação entre as partes constrói:', 'A concessão fortalece a tese ao reconhecer um ganho real e impedir que ele seja tratado como solução suficiente.', 'A concessão fortalece a tese ao reconhecer um ganho real e impedir que ele seja tratado como solução suficiente.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-8', 'A', 'Uma negação de qualquer utilidade dos computadores.', false, 'O início reconhece que eles podem ampliar o acesso.', 'apagar concessão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-8', 'B', 'Uma sequência temporal entre compra e descarte.', false, 'Não há cronologia de descarte; há condição de efetividade.', 'confundir relação lógica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-8', 'C', 'Uma definição técnica de conexão estável.', false, 'O conceito é citado, mas não definido.', 'confundir menção com definição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-8', 'D', 'Uma comparação entre professores e estudantes.', false, 'Os grupos não são colocados em oposição comparativa.', 'criar oposição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-8', 'E', 'Uma concessão que reconhece o benefício e delimita condições para que ele se realize.', true, 'O texto admite potencial positivo antes de apresentar limites necessários.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-red-9', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'challenging', 'comparison', false, 'Compare duas propostas de intervenção para combater o desperdício de alimentos: I. “É preciso conscientizar a sociedade.” II. “Secretarias municipais, em parceria com feiras, devem publicar rotinas de doação e treinar comerciantes para separar alimentos próprios ao consumo.” A segunda é mais consistente porque:', 'Uma intervenção consistente explicita quem faz o quê e como, mantendo relação direta com a causa discutida.', 'Uma intervenção consistente explicita quem faz o quê e como, mantendo relação direta com a causa discutida.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-9', 'A', 'Responsabiliza apenas consumidores individuais.', false, 'A proposta atua sobre poder público e comerciantes.', 'ler agentes incorretamente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-9', 'B', 'Evita qualquer participação do setor público.', false, 'Secretarias municipais são explicitamente centrais.', 'contradição textual');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-9', 'C', 'Promete eliminar completamente o desperdício.', false, 'A proposta não faz promessa total.', 'atribuir garantia');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-9', 'D', 'Usa mais palavras e, por isso, é automaticamente melhor.', false, 'Extensão não garante viabilidade ou pertinência.', 'critério formal');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-9', 'E', 'Define agentes, ações e meios ligados ao problema.', true, 'Secretarias e feiras são agentes; publicação e treinamento são ações com meios concretos.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-red-10', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'challenging', 'integration', false, 'Para defender a ampliação de áreas verdes urbanas, um texto articula ilhas de calor, saúde respiratória e convivência comunitária. Essa integração é produtiva quando:', 'Repertórios diversos fortalecem a argumentação quando têm função demonstrável e convergem para a tese, em vez de formar uma lista desconectada.', 'Repertórios diversos fortalecem a argumentação quando têm função demonstrável e convergem para a tese, em vez de formar uma lista desconectada.', NULL, NULL, 'AUTORAL_EXPANSAO_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-10', 'A', 'Saúde respiratória é citada apenas como frase de efeito.', false, 'Sem mecanismo ou evidência, a citação não sustenta a tese.', 'afirmação gratuita');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-10', 'B', 'Convivência substitui completamente a discussão ambiental.', false, 'Os aspectos podem se complementar; não precisam se excluir.', 'falsa oposição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-10', 'C', 'Os conceitos explicam efeitos ambientais e sociais diferentes da mesma política, ligados por relações claras.', true, 'A integração mostra múltiplos efeitos sem perder o eixo da política urbana.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-10', 'D', 'Cada conceito aparece em um parágrafo sem ligação com a tese.', false, 'A simples presença de conceitos não constrói argumento.', 'repertório decorativo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-red-10', 'E', 'O texto afirma que uma praça resolve todos os problemas urbanos.', false, 'A generalização enfraquece a credibilidade.', 'solução absoluta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-tese-1', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'intro', 'concept', false, 'Sobre o que distingue uma tese de um mero anúncio de tema em uma redação dissertativo-argumentativa, é correto afirmar que a tese:', 'Tese é posição, não apresentação. O teste é simples: se é possível discordar dela com razões, é tese; se não, é anúncio de assunto.', 'Tese é posição, não apresentação. O teste é simples: se é possível discordar dela com razões, é tese; se não, é anúncio de assunto.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-1', 'A', 'assume uma posição discutível sobre o tema, que os parágrafos seguintes precisarão sustentar.', true, 'Uma tese comprometente cria a obrigação argumentativa que estrutura o resto do texto.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-1', 'B', 'resume os argumentos que serão desenvolvidos ao longo do texto.', false, 'O resumo dos argumentos é um recurso possível, mas não é o que define a tese.', 'confundir recurso com definição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-1', 'C', 'apresenta o assunto que será discutido no texto.', false, 'Apresentar o assunto é anunciar o tema, não assumir posição sobre ele.', 'confundir tema com tese');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-1', 'D', 'deve aparecer obrigatoriamente na última linha da introdução.', false, 'A posição usual é o fim da introdução, mas isso é convenção, não definição.', 'confundir posição com natureza');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-1', 'E', 'precisa ser uma afirmação com a qual ninguém possa discordar.', false, 'Se ninguém pode discordar, não há o que argumentar.', 'inverter o critério');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-tese-2', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'intermediate', 'applied', false, 'Um candidato escreve: "A evasão escolar no Brasil é um problema muito grave e precisa ser resolvido com urgência." Para transformar essa frase em tese, a reescrita mais adequada é:', 'Uma tese ganha força quando aponta causa, hierarquiza fatores ou recusa uma explicação corrente. Adjetivos intensos não substituem posição.', 'Uma tese ganha força quando aponta causa, hierarquiza fatores ou recusa uma explicação corrente. Adjetivos intensos não substituem posição.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-2', 'A', '"A evasão escolar decorre menos da falta de interesse dos jovens do que da incapacidade da escola de dialogar com a realidade em que vivem."', true, 'A frase atribui causa, exclui outra explicação corrente e cria compromisso argumentativo verificável.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-2', 'B', '"Neste texto, discutirei as causas e as consequências da evasão escolar."', false, 'Anunciar o percurso do texto não é assumir posição sobre o tema.', 'anúncio de percurso');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-2', 'C', '"A evasão escolar é um tema que preocupa educadores, famílias e governos."', false, 'A frase descreve a repercussão do tema, sem tomar partido.', 'contextualização sem tese');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-2', 'D', '"A evasão escolar no Brasil é um problema gravíssimo e urgentíssimo."', false, 'Intensificar adjetivos não acrescenta posição defensável.', 'intensificar sem posicionar');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-2', 'E', '"Muitos jovens abandonam a escola no Brasil todos os anos."', false, 'Essa é uma constatação factual, sem posição a defender.', 'constatação sem tese');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-tese-3', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'intermediate', 'interpretation', false, 'Um parágrafo argumentativo afirma: "Isso é verdade porque todo mundo sabe que a educação é a base de tudo." O problema argumentativo desse trecho é que ele:', 'Apelar ao que "todo mundo sabe" evita argumentar. A justificativa precisa trazer razão, dado ou exemplo que o leitor possa examinar.', 'Apelar ao que "todo mundo sabe" evita argumentar. A justificativa precisa trazer razão, dado ou exemplo que o leitor possa examinar.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-3', 'A', 'apoia a conclusão em um consenso presumido, sem oferecer razão, dado ou exemplo.', true, 'Dizer que todos sabem transfere o ônus da prova para o leitor em vez de sustentar a afirmação.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-3', 'B', 'apresenta dois argumentos contraditórios no mesmo período.', false, 'Não há contradição interna no trecho.', 'diagnóstico incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-3', 'C', 'contém um erro de concordância verbal.', false, 'A concordância está adequada.', 'diagnóstico incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-3', 'D', 'não apresenta conectivo entre as orações.', false, 'O conectivo está presente e é justamente o que introduz a justificativa frágil.', 'diagnóstico incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-3', 'E', 'usa uma linguagem informal inadequada ao gênero.', false, 'O registro é informal, mas o problema apontado é de estrutura argumentativa.', 'reduzir a registro');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-tese-4', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'intermediate', 'comparison', false, 'Comparando um texto que ignora as objeções à sua tese e outro que as apresenta antes de respondê-las, é correto afirmar que o segundo:', 'Antecipar objeções não é conceder: é mostrar que a tese foi testada. O que fragiliza é fingir que a objeção não existe.', 'Antecipar objeções não é conceder: é mostrar que a tese foi testada. O que fragiliza é fingir que a objeção não existe.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-4', 'A', 'é mais longo e por isso menos objetivo.', false, 'Extensão não é o critério em discussão.', 'critério trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-4', 'B', 'deixa de ser dissertativo-argumentativo ao expor outra opinião.', false, 'A contra-argumentação é procedimento próprio do gênero.', 'classificação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-4', 'C', 'só funciona quando a objeção é fraca.', false, 'Responder a uma objeção forte é o que mais fortalece o texto.', 'inverter o critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-4', 'D', 'ganha força, porque mostra que a tese resiste ao exame das objeções mais sérias.', true, 'Uma posição que enfrenta a melhor versão do argumento contrário se torna mais difícil de recusar.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-4', 'E', 'enfraquece sua posição, pois dá espaço ao adversário.', false, 'Apresentar e responder à objeção demonstra domínio e antecipa a resistência do leitor.', 'supor enfraquecimento');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-tese-5', 'tese-e-argumentacao', 'formular-tese-e-sustentar-com-argumentos', 'challenging', 'integration', false, 'Um texto defende que "o acesso à internet deve ser tratado como direito básico". No desenvolvimento, apresenta dados sobre exclusão digital, cita uma política pública de conectividade e discute o impacto na escolarização. Sobre a articulação entre tese e desenvolvimento:', 'O que transforma informação em argumento é o elo explícito com a tese. Sem esse elo, o parágrafo informa, mas não defende.', 'O que transforma informação em argumento é o elo explícito com a tese. Sem esse elo, o parágrafo informa, mas não defende.', 'Depois de cada dado ou exemplo, escreva uma frase que responda: o que isso prova a respeito da minha tese?', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-5', 'A', 'a tese é inadequada, pois trata de tema técnico.', false, 'O tema admite tratamento dissertativo-argumentativo sem dificuldade.', 'avaliação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-5', 'B', 'o texto deveria apresentar apenas um dos três elementos, para não perder foco.', false, 'A variedade de sustentação é desejável, desde que articulada.', 'restrição desnecessária');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-5', 'C', 'os três elementos sustentam a tese se cada um for explicitamente ligado à ideia de direito básico, e não apenas justapostos.', true, 'Dado, política pública e impacto só argumentam quando o texto mostra o que cada um prova em relação à posição defendida.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-5', 'D', 'os três elementos, por si só, já comprovam a tese.', false, 'Informação acumulada não é argumentação: falta o elo entre o dado e a conclusão.', 'confundir informação com argumento');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-tese-5', 'E', 'a citação de política pública é desnecessária em uma dissertação.', false, 'Ela é repertório legítimo e pode sustentar a tese.', 'excluir recurso válido');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-repertorio-1', 'repertorio-sociocultural', 'selecionar-e-articular-repertorio-sociocultural', 'intro', 'concept', false, 'Em uma redação dissertativa-argumentativa, um repertório sociocultural é considerado produtivo quando:', 'Produtivo é o repertório que, se retirado, deixa um buraco no raciocínio — não o que apenas decora o parágrafo.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-1', 'A', 'Traz uma frase de efeito capaz de emocionar o leitor.', false, 'Emoção pode acompanhar o texto, mas não é o que caracteriza repertório produtivo.', 'trocar argumentação por efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-1', 'B', 'É extenso e ocupa boa parte do parágrafo de desenvolvimento.', false, 'Extensão não é critério: uma referência longa e desconectada continua improdutiva.', 'confundir tamanho com função');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-1', 'C', 'Cita um autor consagrado, independentemente da relação com o tema.', false, 'A consagração do autor não substitui a pertinência ao argumento.', 'apelar à autoridade sem conexão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-1', 'D', 'Aparece na introdução para demonstrar conhecimento prévio.', false, 'A posição no texto não define a produtividade da referência.', 'confundir posição com função');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-1', 'E', 'É pertinente ao tema, apresentado com precisão e explicitamente relacionado ao argumento defendido.', true, 'Repertório produtivo sustenta o raciocínio: entra com precisão, é analisado e volta à tese de forma explícita.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-repertorio-2', 'repertorio-sociocultural', 'selecionar-e-articular-repertorio-sociocultural', 'intermediate', 'applied', false, 'Um estudante escreve, em um texto sobre mobilidade urbana:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-2', 'A', 'Não apresenta dados estatísticos sobre transporte público.', false, 'Dados ajudariam, mas o problema apontado é a ausência de articulação da referência usada.', 'apontar ausência em vez do defeito presente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-2', 'B', 'Usa uma citação longa demais para o parágrafo.', false, 'A citação é curta; o problema não é a extensão.', 'diagnosticar o problema errado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-2', 'C', 'Apresenta um argumento contrário à tese defendida.', false, 'A citação não contradiz a tese; ela simplesmente não a sustenta.', 'inverter o diagnóstico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-2', 'D', 'Introduz uma referência genérica e não estabelece nenhuma relação analítica entre ela e o argumento sobre transporte.', true, 'Não há identificação do autor, não há explicação do que a frase significa e não há ponte entre a citação e a mobilidade urbana: o "por isso" liga duas ideias que não se conectam.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-2', 'E', 'Cita um filósofo antigo, quando o tema exige referências atuais.', false, 'Referências clássicas são plenamente válidas quando bem articuladas.', 'desqualificar a fonte pela época');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-repertorio-3', 'repertorio-sociocultural', 'selecionar-e-articular-repertorio-sociocultural', 'intermediate', 'interpretation', false, 'Leia o parágrafo autoral:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-3', 'A', 'Apresenta um argumento sem qualquer repertório de apoio.', false, 'A segunda frase traz a referência sobre conectividade escolar.', 'ignorar a referência presente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-3', 'B', 'Utiliza o repertório apenas como enfeite, sem relação com a tese.', false, 'A terceira frase estabelece exatamente essa relação.', 'contrariar o texto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-3', 'C', 'Depende de uma citação de autoridade para se sustentar.', false, 'Não há citação de autor; há uso analítico de informação.', 'confundir dado com citação de autoridade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-3', 'D', 'Apresenta tópico frasal, repertório e análise que conecta a referência à desigualdade educacional afirmada no início.', true, 'A primeira frase enuncia o argumento; a segunda traz a referência; a terceira interpreta o dado e retorna ao ponto inicial, fechando o raciocínio.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-3', 'E', 'Apresenta apenas repertório, sem argumento próprio.', false, 'A primeira e a terceira frases contêm o argumento do autor.', 'ignorar as frases de argumentação');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-repertorio-4', 'repertorio-sociocultural', 'selecionar-e-articular-repertorio-sociocultural', 'challenging', 'comparison', false, 'Compare dois usos de repertório em textos sobre desperdício de alimentos:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-4', 'A', 'Apenas I é adequado, por ser mais objetivo e conciso.', false, 'Concisão não substitui a análise que o texto argumentativo exige.', 'confundir concisão com qualidade argumentativa');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-4', 'B', 'Ambos são improdutivos, por não citarem a fonte exata.', false, 'A qualificação da fonte é adequada; a diferença entre os dois está na análise.', 'deslocar o critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-4', 'C', 'A diferença entre eles é apenas de extensão do período.', false, 'A diferença é funcional: II acrescenta interpretação e conclusão.', 'reduzir a diferença ao tamanho');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-4', 'D', 'São equivalentes, pois apresentam a mesma informação.', false, 'A informação é a mesma, mas apenas II a transforma em argumento.', 'confundir informação com argumentação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-4', 'E', 'Apenas II articula o repertório, pois interpreta o dado e o converte em um argumento sobre a causa do problema.', true, 'Em I o dado aparece e para. Em II, o mesmo dado é lido e sustenta uma tese específica: o problema é de distribuição, não de produção.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-repertorio-5', 'repertorio-sociocultural', 'selecionar-e-articular-repertorio-sociocultural', 'challenging', 'integration', false, 'Um estudante precisa escolher duas referências para um texto sobre saúde mental na adolescência. Ele dispõe de: (a) uma frase motivacional de autoria desconhecida; (b) legislação que estabelece diretrizes de saúde mental na atenção básica; (c) um estudo sobre relação entre uso intensivo de redes sociais e indicadores de ansiedade; (d) uma citação célebre sobre felicidade, sem relação direta com o tema.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-5', 'A', '(d) e (b), unindo tradição filosófica e norma legal.', false, 'A citação sobre felicidade não tem relação direta com o tema e exigiria uma ponte forçada.', 'escolher referência sem pertinência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-5', 'B', 'Apenas (c), pois um único repertório bem usado dispensa qualquer outro.', false, 'Um repertório pode bastar em um parágrafo, mas o texto ganha ao articular causa e resposta pública.', 'reduzir demais o repertório');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-5', 'C', '(b) e (c), porque uma trata da resposta institucional prevista e a outra de um fator associado ao problema, o que permite desenvolver causa e política pública e sustentar a proposta de intervenção.', true, 'As duas são verificáveis, pertinentes e complementares: (c) ajuda a explicar o problema e (b) sustenta o que já está previsto e não se efetiva, o que dá base à proposta de intervenção no fim do texto.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-5', 'D', '(a) e (d), por serem mais acessíveis ao leitor e criarem empatia.', false, 'Nenhuma das duas oferece base verificável nem sustenta um argumento específico.', 'trocar argumentação por efeito');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-5', 'E', '(a) e (c), combinando emoção e evidência.', false, 'A frase de autoria desconhecida não acrescenta base argumentativa.', 'aceitar repertório sem procedência');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-repertorio-rec-1', 'repertorio-sociocultural', 'selecionar-e-articular-repertorio-sociocultural', 'intro', 'concept', true, 'Ao usar um dado estatístico em uma redação, o procedimento mais adequado, quando não se lembra do número exato, é:', 'Qualificar a informação preserva a honestidade e mantém a força argumentativa; inventar números coloca todo o texto sob suspeita.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-rec-1', 'A', 'Citar o dado como se fosse de conhecimento geral, sem qualquer qualificação.', false, 'Apresentar informação incerta como consensual é igualmente arriscado.', 'disfarçar a incerteza');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-rec-1', 'B', 'Substituir o dado por uma opinião pessoal enfática.', false, 'Opinião enfática não cumpre a função argumentativa do repertório.', 'trocar evidência por ênfase');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-rec-1', 'C', 'Inventar um número aproximado, já que o corretor não verificará a fonte.', false, 'Informação falsa compromete a credibilidade do texto e pode ser percebida.', 'apostar na não verificação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-rec-1', 'D', 'Usar uma formulação qualificada, indicando a tendência sem afirmar um número que não se conhece.', true, 'Escrever "levantamentos recentes indicam que a maior parte..." mantém a honestidade e ainda sustenta o argumento.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-repertorio-rec-1', 'E', 'Omitir completamente qualquer referência a dados no texto.', false, 'A omissão total empobrece o texto quando havia informação útil disponível.', 'renunciar ao repertório');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rep3-1', 'repertorio-sociocultural', 'selecionar-e-articular-repertorio-sociocultural', 'intro', 'concept', false, 'Um repertório sociocultural é considerado produtivo em uma redação quando:', 'Repertório produtivo é aquele que faz o argumento avançar. Citação que poderia ser removida sem prejuízo não estava trabalhando.', 'Repertório produtivo é aquele que faz o argumento avançar. Citação que poderia ser removida sem prejuízo não estava trabalhando.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-1', 'A', 'é pouco conhecido, o que impressiona o leitor.', false, 'Originalidade sem função argumentativa não acrescenta.', 'critério de raridade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-1', 'B', 'ocupa pelo menos três linhas do parágrafo.', false, 'Extensão não é critério de qualidade.', 'critério de tamanho');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-1', 'C', 'provém de uma fonte prestigiada, como um filósofo clássico.', false, 'Prestígio da fonte não garante função argumentativa no texto.', 'critério de prestígio');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-1', 'D', 'aparece logo na introdução, para demonstrar conhecimento.', false, 'Posição não define produtividade.', 'critério de posição');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-1', 'E', 'está articulado à tese, esclarecendo ou sustentando o argumento em que aparece.', true, 'O repertório precisa fazer trabalho argumentativo, e não apenas demonstrar leitura.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rep3-2', 'repertorio-sociocultural', 'selecionar-e-articular-repertorio-sociocultural', 'intermediate', 'applied', false, 'Ao discutir a desigualdade no acesso à cultura, um candidato quer usar como repertório a existência de bibliotecas públicas em seu município. A forma mais produtiva de empregar esse repertório é:', 'Repertório local é legítimo e muitas vezes mais preciso. O que decide é a consequência que o texto extrai dele.', 'Repertório local é legítimo e muitas vezes mais preciso. O que decide é a consequência que o texto extrai dele.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-2', 'A', 'elogiar a política cultural do município em termos gerais.', false, 'O elogio genérico não faz trabalho argumentativo.', 'avaliação sem função');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-2', 'B', 'substituir o exemplo local por uma citação de um autor estrangeiro.', false, 'A troca não é necessária: repertório local bem articulado funciona.', 'substituição desnecessária');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-2', 'C', 'listar o número de bibliotecas de várias cidades brasileiras.', false, 'Acúmulo de dados sem articulação não avança o argumento.', 'acumular sem articular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-2', 'D', 'mencionar que a cidade possui bibliotecas públicas e passar ao próximo parágrafo.', false, 'A menção isolada não sustenta nada: falta dizer o que ela demonstra.', 'citar sem articular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-2', 'E', 'mostrar que a existência do equipamento não garante acesso quando ele está distante das periferias e funciona em horário comercial.', true, 'O repertório passa a sustentar a tese ao revelar a distância entre oferta formal e acesso efetivo.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rep3-3', 'repertorio-sociocultural', 'selecionar-e-articular-repertorio-sociocultural', 'intermediate', 'interpretation', false, 'Um texto abre o segundo parágrafo com uma citação atribuída a um filósofo, seguida de "portanto, o problema persiste no Brasil". Sobre esse uso:', 'Conectivo não cria relação lógica: ele sinaliza uma relação que o texto precisa ter construído. O elo ausente aparece como salto.', 'Conectivo não cria relação lógica: ele sinaliza uma relação que o texto precisa ter construído. O elo ausente aparece como salto.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-3', 'A', 'está adequado, pois a citação confere autoridade ao argumento.', false, 'Autoridade não substitui o raciocínio que liga a citação à conclusão.', 'autoridade como prova');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-3', 'B', 'está adequado, desde que a citação seja literal.', false, 'Fidelidade é necessária, mas não resolve a ausência de articulação.', 'condição insuficiente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-3', 'C', 'está inadequado porque citações não devem abrir parágrafos.', false, 'Abrir com citação é procedimento comum e aceitável.', 'regra inventada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-3', 'D', 'está inadequado: o conectivo anuncia uma conclusão que a citação, sozinha, não sustenta.', true, 'Entre a citação e a conclusão falta o passo que explica por que aquela ideia se aplica ao caso brasileiro.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-3', 'E', 'está inadequado porque filósofos não servem como repertório em temas sociais.', false, 'Eles servem, desde que a articulação seja feita.', 'restrição incorreta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rep3-4', 'repertorio-sociocultural', 'selecionar-e-articular-repertorio-sociocultural', 'intermediate', 'comparison', false, 'Comparando o uso de um dado estatístico e o de um exemplo narrativo como repertório, é correto afirmar que:', 'Dado responde "quanto"; exemplo responde "como". Um texto forte costuma articular os dois em vez de escolher entre eles.', 'Dado responde "quanto"; exemplo responde "como". Um texto forte costuma articular os dois em vez de escolher entre eles.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-4', 'A', 'os dois cumprem exatamente a mesma função no texto.', false, 'Um mostra dimensão do fenômeno; o outro torna visível o mecanismo.', 'igualar funções');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-4', 'B', 'apenas o dado estatístico exige indicação de fonte.', false, 'Exemplos também ganham com indicação de origem quando são factuais.', 'restrição indevida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-4', 'C', 'o dado indica a dimensão do problema e o exemplo torna visível como ele se realiza, e a combinação costuma ser mais forte que cada um isolado.', true, 'Escala e mecanismo respondem a perguntas diferentes, e um argumento sólido costuma precisar das duas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-4', 'D', 'o dado estatístico é sempre superior, por ser objetivo.', false, 'Dado sem articulação é tão inerte quanto exemplo sem função.', 'hierarquia absoluta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-4', 'E', 'o exemplo narrativo é sempre superior, por ser concreto.', false, 'Concretude ajuda, mas não substitui a demonstração de abrangência.', 'hierarquia absoluta');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-rep3-5', 'repertorio-sociocultural', 'selecionar-e-articular-repertorio-sociocultural', 'challenging', 'integration', false, 'Um candidato tem repertório sobre a Revolução Industrial e precisa escrever sobre trabalho por aplicativos. A decisão mais consistente é:', 'Transpor repertório exige marcar a semelhança que sustenta o argumento e a diferença que impede a analogia de virar exagero.', 'Transpor repertório exige marcar a semelhança que sustenta o argumento e a diferença que impede a analogia de virar exagero.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-5', 'A', 'citar apenas o nome do período, sem desenvolver.', false, 'A menção solta não faz trabalho argumentativo.', 'citar sem articular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-5', 'B', 'usar o repertório para mostrar que a disputa por regulação da jornada não é nova, explicitando semelhança e diferença entre os dois contextos.', true, 'A transposição funciona quando o texto nomeia o que se repete e o que mudou, em vez de sugerir identidade entre épocas.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-5', 'C', 'descrever a Revolução Industrial em detalhe e depois falar de aplicativos.', false, 'Justapor os dois assuntos não constrói relação argumentativa.', 'justapor sem articular');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-5', 'D', 'abandonar o repertório por ser de outro período histórico.', false, 'Repertório histórico é produtivo quando a relação é construída.', 'descarte desnecessário');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-rep3-5', 'E', 'afirmar que o trabalho por aplicativo é idêntico ao do século XIX.', false, 'A identidade é falsa e fragiliza o texto.', 'analogia sem limite');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-coe-1', 'coesao-e-progressao', 'construir-coesao-e-progressao-no-texto', 'intro', 'concept', false, 'Considere as frases: "A cidade investiu em ciclovias. ______, o número de acidentes com ciclistas caiu pela metade."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-1', 'A', 'Como resultado', true, 'A segunda frase apresenta a consequência do investimento descrito na primeira, e o conectivo explicita essa relação.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-1', 'B', 'Por outro lado', false, 'Marca contraposição entre pontos de vista, o que não ocorre aqui.', 'usar contraposição inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-1', 'C', 'Apesar disso', false, 'Indica que o efeito contraria a expectativa, o que não é o caso.', 'inverter a relação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-1', 'D', 'No entanto', false, 'Anuncia contraste, mas a segunda frase confirma o efeito esperado do investimento.', 'usar oposição onde há consequência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-1', 'E', 'Embora', false, 'Introduz concessão e exigiria outra construção sintática.', 'trocar a relação lógica');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-coe-2', 'coesao-e-progressao', 'construir-coesao-e-progressao-no-texto', 'intermediate', 'applied', false, 'Leia o trecho: "A prefeitura ampliou o número de leitos. Portanto, o tempo de espera nos hospitais permaneceu inalterado."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-2', 'A', 'Falta uma vírgula antes do conectivo.', false, 'A pontuação está correta; o problema é semântico.', 'diagnosticar problema de pontuação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-2', 'B', 'O trecho apresenta duas ideias sem relação possível entre si.', false, 'As ideias se relacionam, sim — por contraste, e não por consequência.', 'negar a relação existente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-2', 'C', 'O conectivo "portanto" anuncia consequência, mas a segunda oração apresenta um contraste em relação ao esperado.', true, 'Se os leitos aumentaram, esperava-se redução da espera. Como isso não ocorreu, a relação é adversativa: caberia "ainda assim" ou "no entanto".', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-2', 'D', 'O trecho deveria começar pela segunda oração.', false, 'A ordem está adequada; o defeito é a escolha do conectivo.', 'propor mudança que não corrige o problema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-2', 'E', 'O verbo "permanecer" está mal empregado no contexto.', false, 'O verbo está adequado; o problema é a relação lógica anunciada pelo conectivo.', 'diagnosticar erro inexistente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-coe-3', 'coesao-e-progressao', 'construir-coesao-e-progressao-no-texto', 'intermediate', 'interpretation', false, 'Leia o parágrafo autoral:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-3', 'A', 'Ausência de recursos coesivos, com frases justapostas.', false, 'O parágrafo é claramente articulado.', 'contrariar o texto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-3', 'B', 'Um conectivo adversativo e expressões resumitivas que retomam ideias anteriores sem repeti-las.', true, '"Contudo" marca o contraste; "essa expansão" e "tal desigualdade" retomam, de forma condensada, o que foi dito antes, o que evita repetição e faz o texto progredir.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-3', 'C', 'Apenas repetições lexicais do termo "coleta seletiva".', false, 'O termo não é repetido: é retomado por expressões diferentes.', 'ignorar as retomadas');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-3', 'D', 'Apenas conectivos de adição ao longo de todo o parágrafo.', false, 'O conectivo presente é adversativo, não aditivo.', 'errar a classificação do conectivo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-3', 'E', 'Uso exclusivo de pronomes pessoais para retomar os termos.', false, 'As retomadas são feitas por expressões nominais, não por pronomes pessoais.', 'trocar o recurso empregado');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-coe-4', 'coesao-e-progressao', 'construir-coesao-e-progressao-no-texto', 'challenging', 'comparison', false, 'Compare dois segundos parágrafos de desenvolvimento, escritos para o mesmo texto sobre evasão escolar (cujo primeiro desenvolvimento tratou da necessidade de trabalho precoce):
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-4', 'A', 'Ambos apresentam boa progressão, pois iniciam com conectivos adequados.', false, 'O conectivo de I é adequado, mas o conteúdo repete o parágrafo anterior.', 'confundir conectivo com progressão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-4', 'B', 'Apenas II apresenta progressão, pois retoma o argumento anterior e introduz uma causa distinta, enquanto I repete o que já havia sido dito.', true, 'I reapresenta a mesma causa com outras palavras, ocupando linhas sem avançar. II amarra o que veio antes e acrescenta um segundo fator, o que faz o texto progredir.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-4', 'C', 'Apenas I apresenta progressão, por ser mais direto e objetivo.', false, 'Objetividade não substitui a introdução de conteúdo novo.', 'confundir concisão com progressão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-4', 'D', 'Os dois são equivalentes, pois tratam do mesmo tema.', false, 'Tratar do mesmo tema é o esperado; a diferença está em acrescentar ou repetir.', 'ignorar o critério de progressão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-4', 'E', 'Nenhum dos dois progride, pois ambos citam o parágrafo anterior.', false, 'Retomar o anterior é justamente um recurso de coesão; o problema seria apenas repetir.', 'confundir retomada com repetição');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-coe-5', 'coesao-e-progressao', 'construir-coesao-e-progressao-no-texto', 'challenging', 'integration', false, 'Um estudante escreveu: "O programa foi criado em 2015 e ampliado em 2019. Ele não alcançou as regiões mais afastadas, o que reduziu seu impacto. Isso mostra que ele precisa de revisão."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-5', 'A', 'Substituir todos os pronomes por repetições do termo "programa", garantindo clareza absoluta.', false, 'A repetição excessiva resolve a ambiguidade criando outro problema de estilo.', 'trocar um defeito por outro');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-5', 'B', 'Unir os três períodos em um só, ligados por vírgulas.', false, 'A junção sem conectivos adequados não resolve a ambiguidade nem melhora a articulação.', 'alterar a forma sem tratar o problema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-5', 'C', 'Acrescentar mais conectivos entre as frases, como "além disso" e "portanto".', false, 'Acrescentar conectivos sem corrigir os referentes mantém o problema central.', 'empilhar conectivos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-5', 'D', 'Retirar o último período, por apresentar uma conclusão precipitada.', false, 'A conclusão é pertinente; o problema está na clareza dos referentes.', 'remover conteúdo válido');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-5', 'E', 'Explicitar os referentes ambíguos e articular as frases pelo sentido, por exemplo: "Criado em 2015 e ampliado em 2019, o programa não chegou às regiões mais afastadas, limitação que reduziu seu impacto e justifica uma revisão de seu desenho."', true, 'A reescrita elimina o "ele" e o "isso" sem referente claro, condensa a informação, marca a relação de causa e consequência e mantém a conclusão — resolvendo coesão referencial e articulação ao mesmo tempo.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-coe-rec-1', 'coesao-e-progressao', 'construir-coesao-e-progressao-no-texto', 'intro', 'concept', true, 'Na frase "O secretário conversou com o diretor e ele afirmou que o projeto seria mantido", o problema de coesão é:', 'Quando há mais de um referente possível, o pronome gera ambiguidade — e clareza vale mais que evitar repetição.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-rec-1', 'A', 'A ausência de vírgula antes de "e".', false, 'A vírgula não resolveria a ambiguidade do pronome.', 'confundir pontuação com referência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-rec-1', 'B', 'A ambiguidade do pronome "ele", que pode retomar tanto o secretário quanto o diretor.', true, 'Com dois substantivos masculinos candidatos antes do pronome, o leitor não sabe quem afirmou. A solução é repetir o termo ou reorganizar a frase.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-rec-1', 'C', 'O tempo verbal de "seria", inadequado ao contexto.', false, 'O futuro do pretérito é adequado ao discurso indireto.', 'diagnosticar erro verbal inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-rec-1', 'D', 'A repetição excessiva de termos ao longo da frase.', false, 'Não há repetição: o problema é justamente o oposto.', 'inverter o diagnóstico');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-coe-rec-1', 'E', 'O uso incorreto do conectivo "e".', false, 'O conectivo aditivo está adequado à sequência de ações.', 'diagnosticar problema inexistente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-coe-1', 'coesao-e-progressao', 'construir-coesao-e-progressao-no-texto', 'intro', 'concept', false, 'Em um texto dissertativo, a diferença entre coesão e coerência pode ser formulada assim:', 'É possível encadear frases com conectivos corretos e ainda assim dizer algo sem sentido. Coesão é costura; coerência é o desenho que resulta dela.', 'É possível encadear frases com conectivos corretos e ainda assim dizer algo sem sentido. Coesão é costura; coerência é o desenho que resulta dela.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-1', 'A', 'coesão trata do conteúdo e coerência, da gramática.', false, 'A relação está invertida.', 'inverter os termos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-1', 'B', 'coesão é obrigatória e coerência é opcional.', false, 'As duas são exigidas em um texto bem construído.', 'hierarquia incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-1', 'C', 'coesão é a amarração explícita entre partes do texto; coerência é a consistência do sentido construído no conjunto.', true, 'Conectivos e retomadas fazem a costura visível; a coerência garante que o todo faça sentido.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-1', 'D', 'coesão só existe entre parágrafos, e coerência só dentro deles.', false, 'Ambas operam nos dois níveis.', 'escopo incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-1', 'E', 'os dois termos designam a mesma propriedade textual.', false, 'Um texto pode ser coeso e incoerente, o que mostra que são distintos.', 'igualar os conceitos');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-coe-2', 'coesao-e-progressao', 'construir-coesao-e-progressao-no-texto', 'intermediate', 'applied', false, 'Leia: "A cidade ampliou as ciclovias. Portanto, o número de acidentes com ciclistas aumentou." O problema desse período está em:', 'Conectivo é promessa: quem escreve "portanto" se compromete com uma relação de consequência que o texto precisa sustentar.', 'Conectivo é promessa: quem escreve "portanto" se compromete com uma relação de consequência que o texto precisa sustentar.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-2', 'A', 'repetir o assunto nas duas orações.', false, 'A retomada do assunto é adequada e favorece a coesão.', 'diagnóstico incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-2', 'B', 'usar duas orações curtas em sequência.', false, 'A extensão das orações não é o problema.', 'diagnóstico incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-2', 'C', 'omitir o sujeito da segunda oração.', false, 'O sujeito está expresso na segunda oração.', 'diagnóstico incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-2', 'D', 'usar um conectivo de conclusão para uma relação que o texto não estabeleceu.', true, 'A conclusão anunciada não decorre da premissa: seria preciso explicar por que a ampliação levaria a mais acidentes.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-2', 'E', 'empregar o pretérito perfeito nas duas orações.', false, 'A escolha de tempo verbal é adequada.', 'diagnóstico incorreto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-coe-3', 'coesao-e-progressao', 'construir-coesao-e-progressao-no-texto', 'intermediate', 'interpretation', false, 'Um parágrafo repete cinco vezes a palavra "violência" em oito linhas. Além do efeito de repetição, o problema textual mais relevante é que:', 'Boa retomada faz dois trabalhos ao mesmo tempo: liga ao que veio antes e acrescenta uma qualificação nova. Repetir só faz o primeiro.', 'Boa retomada faz dois trabalhos ao mesmo tempo: liga ao que veio antes e acrescenta uma qualificação nova. Repetir só faz o primeiro.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-3', 'A', 'a ausência de retomadas variadas desperdiça oportunidades de acrescentar informação sobre o termo a cada menção.', true, 'Substituições como "esse fenômeno" ou "tal agravamento" retomam e ao mesmo tempo qualificam, fazendo o texto progredir.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-3', 'B', 'a palavra repetida deve ser trocada por sinônimo em toda ocorrência.', false, 'A substituição sistemática pode prejudicar a clareza; o critério é a função de cada retomada.', 'regra rígida');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-3', 'C', 'a repetição indica erro gramatical.', false, 'Não há erro gramatical envolvido.', 'diagnóstico incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-3', 'D', 'o parágrafo ficou longo demais para uma dissertação.', false, 'Oito linhas é extensão normal para um parágrafo argumentativo.', 'diagnóstico incorreto');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-3', 'E', 'a repetição torna o texto informal.', false, 'Repetição não desloca o registro para o informal.', 'diagnóstico incorreto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-coe-4', 'coesao-e-progressao', 'construir-coesao-e-progressao-no-texto', 'intermediate', 'comparison', false, 'Comparando dois textos, um em que cada parágrafo começa retomando a ideia final do anterior e outro em que os parágrafos apenas se somam sem ligação explícita, é correto afirmar que:', 'Progressão é o que distingue argumentação de enumeração. Sem articulação entre parágrafos, o leitor recebe blocos, não um raciocínio.', 'Progressão é o que distingue argumentação de enumeração. Sem articulação entre parágrafos, o leitor recebe blocos, não um raciocínio.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-4', 'A', 'o segundo é preferível, por evitar repetições.', false, 'Evitar repetição não compensa a perda de encadeamento.', 'critério trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-4', 'B', 'o primeiro tende a ficar prolixo pela retomada constante.', false, 'A retomada bem feita é breve e não implica prolixidade.', 'avaliação incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-4', 'C', 'a articulação entre parágrafos é opcional em textos curtos.', false, 'Mesmo em textos curtos o encadeamento orienta a leitura.', 'exceção inventada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-4', 'D', 'o primeiro constrói progressão, permitindo ao leitor acompanhar como o argumento avança de uma etapa à seguinte.', true, 'Encadear parágrafos transforma uma lista de ideias em um percurso argumentativo.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-4', 'E', 'os dois se equivalem, desde que cada parágrafo seja bem escrito internamente.', false, 'Parágrafos bons isolados podem formar um texto que não avança.', 'ignorar o encadeamento');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-coe-5', 'coesao-e-progressao', 'construir-coesao-e-progressao-no-texto', 'challenging', 'integration', false, 'Um texto usa "além disso" para introduzir o terceiro parágrafo, que na verdade apresenta uma objeção à ideia defendida no segundo. Analisando essa escolha:', 'Conectivo é instrução de leitura. Quando ele aponta para um lado e o parágrafo vai para outro, o leitor perde o fio do argumento.', 'Conectivo é instrução de leitura. Quando ele aponta para um lado e o parágrafo vai para outro, o leitor perde o fio do argumento.', 'Antes de escolher o conectivo, nomeie a relação: acréscimo, contraste, causa, conclusão ou concessão. A palavra vem depois da relação.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-5', 'A', 'o problema é o uso de conectivo no início do parágrafo.', false, 'Iniciar parágrafo com conectivo é procedimento comum e adequado.', 'regra inventada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-5', 'B', 'a solução é retirar o conectivo e deixar os parágrafos justapostos.', false, 'Retirar a marca de relação piora o encadeamento em vez de corrigi-lo.', 'solução inadequada');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-5', 'C', 'o erro está no segundo parágrafo, que não deveria admitir objeção.', false, 'Admitir objeção é desejável; o problema está na sinalização da relação.', 'deslocar o problema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-5', 'D', 'o conectivo desorienta o leitor, que espera acréscimo e encontra contraste; a escolha adequada seria um conectivo adversativo ou concessivo.', true, 'O conectivo cria uma expectativa de continuidade que o parágrafo contraria, obrigando o leitor a reler para entender a relação.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-coe-5', 'E', 'a escolha é indiferente, pois o conteúdo do parágrafo esclarece a relação.', false, 'Se o leitor precisa reler para reconstruir a relação, o conectivo falhou.', 'minimizar o efeito');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-prop-1', 'proposta-de-intervencao', 'elaborar-proposta-de-intervencao-detalhada', 'intro', 'concept', false, 'Em uma proposta de intervenção completa, os elementos esperados são:', 'Agente, ação, meio, finalidade e detalhamento são os cinco componentes que tornam uma proposta concreta.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-1', 'A', 'Repertório, dado estatístico e citação de autoridade.', false, 'São recursos de argumentação, não elementos da proposta.', 'trocar recursos por componentes');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-1', 'B', 'Tese, argumento e conclusão.', false, 'Esses são elementos da estrutura geral do texto, não da proposta.', 'confundir estrutura do texto com estrutura da proposta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-1', 'C', 'Introdução, desenvolvimento e fechamento.', false, 'Também descrevem a organização do texto, não a proposta em si.', 'confundir os planos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-1', 'D', 'Causa, consequência e solução.', false, 'São etapas do raciocínio argumentativo, não os componentes da proposta.', 'trocar o objeto da pergunta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-1', 'E', 'Agente, ação, meio, finalidade e detalhamento.', true, 'Quem faz, o que faz, como faz, para quê e com qual especificação: é essa combinação que torna a proposta avaliável.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-prop-2', 'proposta-de-intervencao', 'elaborar-proposta-de-intervencao-detalhada', 'intermediate', 'applied', false, 'Leia a proposta: "É preciso que a sociedade se conscientize sobre a importância da reciclagem para que o meio ambiente seja preservado."
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-2', 'A', 'Não indica agente específico nem meio de execução, limitando-se a um apelo genérico à conscientização.', true, '"A sociedade" não é um agente com competência definida, e não há indicação de como a conscientização aconteceria. Sem agente e sem meio, a proposta não pode ser avaliada nem executada.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-2', 'B', 'Apresenta finalidade incorreta, pois preservar o meio ambiente não é objetivo da reciclagem.', false, 'A finalidade é pertinente; o problema está na ausência de agente e meio.', 'diagnosticar problema inexistente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-2', 'C', 'É longa demais para uma conclusão de texto dissertativo.', false, 'A proposta é curta; o defeito não é a extensão.', 'diagnosticar o problema errado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-2', 'D', 'Deveria propor uma lei em vez de uma ação educativa.', false, 'Ações educativas são propostas legítimas, desde que detalhadas.', 'restringir o tipo de proposta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-2', 'E', 'Utiliza vocabulário técnico inadequado ao gênero.', false, 'O vocabulário é acessível e adequado.', 'apontar defeito inexistente');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-prop-3', 'proposta-de-intervencao', 'elaborar-proposta-de-intervencao-detalhada', 'intermediate', 'interpretation', false, 'Leia a proposta autoral:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-3', 'A', 'Apresenta apenas finalidade, sem indicação de responsável.', false, 'O agente é nomeado logo na primeira palavra.', 'ignorar o agente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-3', 'B', 'É inviável, pois formação continuada não é atribuição de secretarias de educação.', false, 'Formação continuada de professores está entre as atribuições típicas dessas secretarias.', 'errar a competência do agente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-3', 'C', 'Fere direitos ao estabelecer prioridade entre escolas.', false, 'Priorizar territórios mais afetados é critério de equidade, não violação de direitos.', 'confundir priorização com discriminação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-3', 'D', 'Apresenta os cinco elementos: agente, ação, meio, finalidade e detalhamento, este último expresso no critério de priorização.', true, 'Secretarias estaduais (agente) devem oferecer formação (ação) por meio de módulos no calendário existente (meio), para que o tema seja trabalhado de modo transversal (finalidade), priorizando regiões com maior endividamento (detalhamento).', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-3', 'E', 'Apresenta agente e ação, mas não indica meio nem finalidade.', false, 'O meio ("módulos on-line vinculados ao calendário existente") e a finalidade ("a fim de que o tema seja trabalhado") estão explícitos.', 'ignorar elementos presentes');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-prop-4', 'proposta-de-intervencao', 'elaborar-proposta-de-intervencao-detalhada', 'challenging', 'comparison', false, 'Compare duas propostas para um texto que discutiu a falta de acesso à internet em escolas rurais:
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-4', 'A', 'A proposta I é superior, por envolver a comunidade escolar de forma mais ampla.', false, 'Alcance amplo não compensa a ausência de relação com o problema discutido.', 'confundir abrangência com pertinência');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-4', 'B', 'Apenas II responde ao problema discutido, pois trata da infraestrutura de conectividade, com agente, meio, finalidade e recursos indicados.', true, 'O texto discutiu falta de acesso à internet. Campanhas de valorização não resolvem infraestrutura. A proposta II nomeia agentes, indica o meio, aponta fonte de recursos e explicita a finalidade pedagógica.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-4', 'C', 'Apenas I é viável, pois campanhas custam menos que ampliação de rede.', false, 'Custo menor não torna uma proposta pertinente ao problema.', 'confundir viabilidade financeira com adequação');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-4', 'D', 'Nenhuma das duas é adequada, pois conectividade não é atribuição do Ministério da Educação.', false, 'Programas de conectividade escolar são executados com participação do MEC, em articulação com outros órgãos.', 'errar a competência do agente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-4', 'E', 'Ambas respondem ao problema, variando apenas no grau de detalhamento.', false, 'A proposta I não trata do problema levantado, que é de infraestrutura.', 'ignorar a desconexão temática');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-prop-5', 'proposta-de-intervencao', 'elaborar-proposta-de-intervencao-detalhada', 'challenging', 'integration', false, 'Um texto discutiu dois problemas relacionados ao descarte de medicamentos vencidos: a ausência de pontos de coleta acessíveis e o desconhecimento da população sobre os riscos ambientais.
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-5', 'A', 'Propor a criação de uma nova indústria de reciclagem de medicamentos no país.', false, 'A proposta introduz um tema não discutido no texto e é inviável como fechamento.', 'introduzir assunto novo');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-5', 'B', 'Propor a proibição da venda de medicamentos em farmácias sem serviço de coleta, com multa aos estabelecimentos irregulares.', false, 'A medida ataca um dos pontos, mas ignora a dimensão informativa e recai em uma restrição de alcance discutível como resposta principal.', 'responder parcialmente com medida desproporcional');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-5', 'C', 'Propor que a vigilância sanitária, junto às redes de farmácias, instale pontos de devolução em todas as unidades e que a informação sobre riscos e locais de descarte conste na embalagem e na receita, a fim de resolver ao mesmo tempo o acesso e o desconhecimento.', true, 'A proposta responde aos dois problemas do texto: cria a estrutura de coleta onde as pessoas já vão e leva a informação ao momento em que o medicamento é adquirido ou prescrito.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-5', 'D', 'Propor campanhas publicitárias em horário nobre sobre a importância do meio ambiente.', false, 'A campanha genérica não trata do acesso e nem informa sobre onde descartar.', 'responder com medida vaga');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-5', 'E', 'Propor que a população procure informações sobre descarte correto na internet.', false, 'Transferir a responsabilidade ao indivíduo não resolve a ausência de estrutura.', 'individualizar o problema');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q-prop-rec-1', 'proposta-de-intervencao', 'elaborar-proposta-de-intervencao-detalhada', 'intro', 'concept', true, 'Uma proposta de intervenção que sugira a suspensão de direitos de um grupo específico como forma de resolver um problema social:', 'O respeito aos direitos humanos é um limite inegociável da proposta de intervenção.', NULL, NULL, NULL, 'AUTORAL_LEVA_2', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-rec-1', 'A', 'É aceitável se o texto explicar bem as consequências.', false, 'Explicação não converte a medida em proposta legítima.', 'confundir clareza com legitimidade');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-rec-1', 'B', 'É aceitável, desde que seja detalhada e viável.', false, 'Detalhamento e viabilidade não tornam legítima uma medida que suprime direitos.', 'avaliar apenas por critérios técnicos');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-rec-1', 'C', 'É aceitável se aplicada temporariamente.', false, 'A temporalidade não altera o problema de fundo.', 'relativizar pela duração');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-rec-1', 'D', 'Não é aceitável, pois propostas devem respeitar os direitos humanos.', true, 'O respeito aos direitos humanos é condição da proposta, e sua violação compromete integralmente a avaliação do texto.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q-prop-rec-1', 'E', 'É aceitável quando apoiada por dados estatísticos.', false, 'Dados não legitimam a supressão de direitos.', 'confundir evidência com legitimidade');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-prop-1', 'proposta-de-intervencao', 'elaborar-proposta-de-intervencao-detalhada', 'intro', 'concept', false, 'Uma proposta de intervenção completa em redação dissertativo-argumentativa costuma articular cinco elementos. São eles:', 'A proposta responde a cinco perguntas: quem, o quê, como, para quê e com que especificação. Faltando uma, ela fica genérica.', 'A proposta responde a cinco perguntas: quem, o quê, como, para quê e com que especificação. Faltando uma, ela fica genérica.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-1', 'A', 'agente, ação e finalidade, apenas.', false, 'Faltam o meio de execução e o detalhamento.', 'proposta incompleta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-1', 'B', 'agente, ação, meio ou modo de execução, finalidade e detalhamento.', true, 'Quem faz, o que faz, como faz, para que faz e um esclarecimento que torne a proposta concreta.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-1', 'C', 'agente, orçamento, prazo, meta e indicador.', false, 'Esse é o formato de um projeto administrativo, não da proposta pedida no gênero.', 'formato trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-1', 'D', 'problema, causa, consequência, solução e avaliação.', false, 'Essa é uma estrutura de análise, não a da proposta.', 'formato trocado');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-1', 'E', 'tema, tese, argumento, exemplo e conclusão.', false, 'Esses são elementos do texto como um todo, não da proposta.', 'confundir com estrutura do texto');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-prop-2', 'proposta-de-intervencao', 'elaborar-proposta-de-intervencao-detalhada', 'intermediate', 'applied', false, 'Um candidato escreve: "O governo deve investir mais em educação para resolver o problema." Para completar essa proposta, o elemento mais urgente a acrescentar é:', '"Investir mais" nomeia agente, ação e finalidade, mas não diz como. É o meio de execução que separa proposta de desejo.', '"Investir mais" nomeia agente, ação e finalidade, mas não diz como. É o meio de execução que separa proposta de desejo.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-2', 'A', 'a menção ao problema tratado no texto.', false, 'O problema já está pressuposto pela redação.', 'elemento já presente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-2', 'B', 'a repetição da tese defendida na introdução.', false, 'Repetir a tese não acrescenta operacionalidade.', 'repetição sem função');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-2', 'C', 'a indicação do valor exato a ser investido.', false, 'Precisão orçamentária não é exigida no gênero.', 'exigência incompatível');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-2', 'D', 'um adjetivo que reforce a urgência do investimento.', false, 'Intensificar a linguagem não torna a proposta executável.', 'intensificar sem detalhar');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-2', 'E', 'o meio de execução: por qual instrumento e em que frente o investimento se daria.', true, 'Sem indicar como a ação se realiza, a proposta permanece uma intenção genérica.', NULL);
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-prop-3', 'proposta-de-intervencao', 'elaborar-proposta-de-intervencao-detalhada', 'intermediate', 'interpretation', false, 'Uma proposta afirma: "As escolas devem conscientizar os alunos por meio de palestras semanais sobre o tema, a fim de reduzir o problema." Sobre essa formulação:', 'Marcar os cinco elementos é o mínimo. O que distingue uma proposta forte é o grau de especificação de cada um deles.', 'Marcar os cinco elementos é o mínimo. O que distingue uma proposta forte é o grau de especificação de cada um deles.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-3', 'A', 'tem os cinco elementos, mas o detalhamento é frágil: "palestras sobre o tema" não especifica conteúdo, público nem articulação com o currículo.', true, 'A presença formal dos elementos não garante que a proposta seja concreta o bastante para ser avaliada.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-3', 'B', 'está incompleta, pois falta o agente.', false, 'O agente está indicado: as escolas.', 'elemento presente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-3', 'C', 'está incompleta, pois falta a finalidade.', false, 'A finalidade está expressa na oração final.', 'elemento presente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-3', 'D', 'está incompleta, pois falta a ação.', false, 'A ação está indicada como conscientizar.', 'elemento presente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-3', 'E', 'está completa e adequada, sem reparos possíveis.', false, 'Os elementos estão presentes, mas o detalhamento é fraco e o meio é genérico.', 'aceitar sem exame');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-prop-4', 'proposta-de-intervencao', 'elaborar-proposta-de-intervencao-detalhada', 'intermediate', 'comparison', false, 'Comparando uma proposta que atribui a ação ao Ministério da Educação e outra que a atribui a "a sociedade", é correto afirmar que:', 'Agente difuso dilui responsabilidade. Nomear quem tem competência para agir é o que permite avaliar se a proposta faz sentido.', 'Agente difuso dilui responsabilidade. Nomear quem tem competência para agir é o que permite avaliar se a proposta faz sentido.', NULL, NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-4', 'A', 'a segunda é melhor, por envolver todos os cidadãos.', false, 'Envolver todos, na prática, é não atribuir responsabilidade a ninguém.', 'confundir abrangência com precisão');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-4', 'B', 'a primeira é inadequada por citar um órgão específico.', false, 'Citar órgão competente é justamente o que se espera.', 'inverter o critério');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-4', 'C', 'a primeira é mais adequada, porque nomeia um agente com competência definida e passível de ser responsabilizado.', true, 'Agente identificável torna a proposta verificável: é possível dizer quem deve agir e sob qual atribuição.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-4', 'D', 'nenhuma serve, pois propostas devem indicar pessoas físicas.', false, 'Instituições são agentes legítimos e usuais.', 'exigência incorreta');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-4', 'E', 'as duas são equivalentes, pois ambas indicam um agente.', false, 'Um agente que não pode ser cobrado não cumpre a função do elemento.', 'igualar os agentes');
INSERT INTO questions (slug, topic_slug, skill_slug, difficulty, cognitive_format, is_recovery, stem, explanation_summary, explanation_detailed, explanation_strategy, explanation_concept_recap, origin, license) VALUES ('q3-prop-5', 'proposta-de-intervencao', 'elaborar-proposta-de-intervencao-detalhada', 'challenging', 'integration', false, 'Um texto defende que a evasão escolar decorre da necessidade de trabalho precoce, mas propõe como intervenção campanhas de conscientização sobre a importância do estudo. Sobre a relação entre diagnóstico e proposta:', 'Proposta é a continuação do diagnóstico. Se o texto atribui o problema a uma causa material, intervir apenas sobre percepção deixa a causa intocada.', 'Proposta é a continuação do diagnóstico. Se o texto atribui o problema a uma causa material, intervir apenas sobre percepção deixa a causa intocada.', 'Antes de escrever a proposta, releia a causa que você defendeu no desenvolvimento. A intervenção precisa agir sobre ela, e não sobre outra.', NULL, 'AUTORAL_LEVA_3_2026_08', 'Conteúdo autoral de desenvolvimento — Conscious Knowledge');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-5', 'A', 'bastaria acrescentar mais um agente à proposta para corrigi-la.', false, 'Somar agentes não corrige o desencontro entre causa e ação.', 'correção insuficiente');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-5', 'B', 'há incoerência: a proposta atua sobre percepção, enquanto o texto atribuiu a evasão a uma necessidade material.', true, 'Se a causa apontada é a renda familiar, a intervenção precisa tocar essa condição, por meio de auxílio, bolsa ou jornada compatível.', NULL);
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-5', 'C', 'a proposta é adequada, pois conscientizar sempre ajuda.', false, 'Ajuda genérica não responde à causa que o próprio texto estabeleceu.', 'aceitar solução genérica');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-5', 'D', 'a incoerência é irrelevante, pois a proposta aparece no último parágrafo.', false, 'A coerência entre diagnóstico e proposta é justamente o que se avalia.', 'minimizar o problema');
INSERT INTO question_options (question_slug, label, body, is_correct, rationale, error_hint) VALUES ('q3-prop-5', 'E', 'o problema está no diagnóstico, que deveria citar falta de interesse.', false, 'O diagnóstico apresentado é plausível; o desencontro está na proposta.', 'deslocar o problema');
INSERT INTO study_methods (slug, title, summary, how_it_works, when_to_use, steps, example, limitations, minutes, suitable_topics, display_order) VALUES ('estudo-ativo', 'Estudo ativo', 'Tentar responder antes de ver a solução.', 'Antes de ler a explicação, você tenta resolver ou explicar por conta própria. O esforço de tentar — mesmo errando — prepara o cérebro para aproveitar melhor a correção.', 'Quando você já teve algum contato com o tema. Funciona mal como primeiro contato com um assunto totalmente novo.', '["Leia o enunciado ou a pergunta com atenção.","Escreva o que você acha, mesmo incompleto.","Só então veja a explicação.","Marque a diferença entre o que você escreveu e o que era esperado."]'::jsonb, 'Antes de ler o resumo sobre porcentagem, tente responder: "de 80 para 100, o aumento é de quantos por cento?". Depois compare com a explicação.', 'Frustra quem não tem nenhuma base no assunto. Se você não faz ideia por onde começar, leia uma explicação curta antes de tentar.', 20, '["porcentagem-e-variacao","interpretacao-e-inferencia","funcoes-e-relacoes"]'::jsonb, 1);
INSERT INTO study_methods (slug, title, summary, how_it_works, when_to_use, steps, example, limitations, minutes, suitable_topics, display_order) VALUES ('recuperacao', 'Recuperação (lembrar sem consultar)', 'Resgatar a informação da memória em vez de reler.', 'Você fecha o material e tenta lembrar. O ato de recuperar fortalece a memória muito mais que reler — reler cria a sensação de saber sem criar a capacidade de lembrar.', 'Depois de já ter estudado o conteúdo pelo menos uma vez.', '["Feche o resumo.","Escreva ou fale tudo o que lembrar do tema.","Abra o material e marque o que faltou.","Repita só a parte que faltou, depois de algumas horas."]'::jsonb, 'Depois de estudar ecologia, feche o material e escreva a diferença entre fluxo de energia e ciclagem de matéria. Só então confira.', 'Pode gerar desconforto no começo, porque expõe o que você não sabe. Esse desconforto é parte do processo, mas não deve virar desânimo: comece por trechos curtos.', 10, '["ecologia-e-ciclos","cidadania-e-direitos","transformacoes-quimicas"]'::jsonb, 2);
INSERT INTO study_methods (slug, title, summary, how_it_works, when_to_use, steps, example, limitations, minutes, suitable_topics, display_order) VALUES ('revisao-espacada', 'Revisão espaçada', 'O conteúdo volta em intervalos crescentes, com questões diferentes.', 'Em vez de revisar tudo de uma vez, o mesmo conteúdo retorna depois de 1, 3, 7, 14 e 30 dias. Cada retorno é feito com um item diferente, para evitar que você decore o enunciado no lugar do conceito.', 'Sempre que houver um intervalo longo até a prova. É o método que mais protege contra o esquecimento.', '["Estude o conteúdo pela primeira vez.","Revise no dia seguinte.","Aumente o intervalo a cada revisão bem-sucedida.","Ao errar, volte ao intervalo inicial."]'::jsonb, 'Você estudou funções na segunda. A plataforma traz uma questão nova de funções na terça, na sexta e duas semanas depois.', 'Exige constância ao longo de semanas. Não substitui o primeiro entendimento: revisar algo que você nunca compreendeu apenas repete a confusão.', 15, '["funcoes-e-relacoes","energia-e-transformacoes","urbanizacao-e-desigualdade"]'::jsonb, 3);
INSERT INTO study_methods (slug, title, summary, how_it_works, when_to_use, steps, example, limitations, minutes, suitable_topics, display_order) VALUES ('pratica-intercalada', 'Prática intercalada', 'Alternar tópicos relacionados em vez de repetir o mesmo em bloco.', 'Em vez de dez questões seguidas do mesmo assunto, a sessão mistura tópicos relacionados. Isso obriga você a decidir qual estratégia usar — que é exatamente o que a prova cobra.', 'Quando você já acerta questões isoladas de um tópico, mas erra quando ele aparece misturado.', '["Escolha dois ou três tópicos relacionados.","Alterne as questões entre eles.","Antes de resolver, identifique de qual tópico é a questão.","Registre os casos em que você identificou errado."]'::jsonb, 'Alternar questões de porcentagem, leitura de gráficos e funções em uma mesma sessão de 30 minutos.', 'Parece mais difícil e produz mais erros no curto prazo que a prática em bloco. Isso é esperado — mas pode desanimar quem está começando um tópico agora.', 30, '["porcentagem-e-variacao","leitura-de-graficos-e-tabelas","funcoes-e-relacoes"]'::jsonb, 4);
INSERT INTO study_methods (slug, title, summary, how_it_works, when_to_use, steps, example, limitations, minutes, suitable_topics, display_order) VALUES ('caderno-de-erros', 'Caderno de erros', 'Registrar o motivo do erro e transformá-lo em uma próxima ação.', 'Cada erro vira um registro com o motivo (não sabia, não entendi o enunciado, errei a conta, faltou atenção) e uma ação: revisar o conceito, resolver questão semelhante ou refazer depois.', 'Sempre. É o método que transforma erro em informação útil.', '["Ao errar, registre o motivo antes de ver a explicação completa.","Escreva com suas palavras o que faltou.","Escolha a ação: conceito, questão semelhante ou refazer depois.","Volte ao registro depois de alguns dias."]'::jsonb, 'Você errou uma questão de variação percentual por usar o valor final como base. O registro vira: "conferir sempre de onde eu saí antes de dividir".', 'Vira lista morta se você só anotar e nunca voltar. O valor está na ação seguinte, não no registro.', 10, '[]'::jsonb, 5);
INSERT INTO study_methods (slug, title, summary, how_it_works, when_to_use, steps, example, limitations, minutes, suitable_topics, display_order) VALUES ('explicacao-com-as-proprias-palavras', 'Explicação com as próprias palavras', 'Escrever uma explicação curta antes de conferir a oficial.', 'Você escreve, em duas ou três frases, como explicaria o conceito para alguém. Onde a explicação trava é exatamente onde a compreensão falha.', 'Depois de ler a explicação de um tópico, antes de partir para as questões.', '["Escolha um conceito do tópico.","Escreva a explicação sem consultar o material.","Compare com a explicação oficial.","Marque os pontos em que você travou."]'::jsonb, 'Explicar por que a eutrofização mata peixes sem usar a palavra "poluição" — o exercício obriga a descrever o mecanismo.', 'Exige escrever, o que consome tempo. Em sessões muito curtas, use apenas para o conceito central da sessão.', 10, '["ecologia-e-ciclos","tese-e-argumentacao","meio-ambiente-e-sociedade"]'::jsonb, 6);
INSERT INTO study_methods (slug, title, summary, how_it_works, when_to_use, steps, example, limitations, minutes, suitable_topics, display_order) VALUES ('sessao-de-foco-curto', 'Sessão de foco curto', 'Um bloco de 10 a 20 minutos com um único objetivo.', 'Você define um objetivo único e trabalha só nele por um tempo curto e determinado. Sem trocar de assunto, sem abrir outra coisa.', 'Quando o tempo é escasso ou quando começar é a parte mais difícil.', '["Escolha um objetivo único e específico.","Defina o tempo antes de começar.","Deixe o material pronto antes de iniciar a contagem.","Ao terminar, anote onde parou."]'::jsonb, '15 minutos apenas para resolver três questões de interpretação e registrar o motivo de cada erro.', 'Não é suficiente para conteúdos que exigem construção longa, como uma redação completa. Nesses casos, use blocos curtos para etapas (planejar, escrever, revisar).', 15, '[]'::jsonb, 7);
INSERT INTO study_methods (slug, title, summary, how_it_works, when_to_use, steps, example, limitations, minutes, suitable_topics, display_order) VALUES ('simulado-com-analise', 'Simulado com análise', 'Conjunto cronometrado seguido da interpretação dos erros e do tempo.', 'A parte que ensina não é o simulado: é a análise depois dele. Você examina onde errou, quanto tempo gastou por questão e que padrão apareceu.', 'Quando você já tem base nos conteúdos e precisa treinar estratégia, ritmo e resistência.', '["Resolva o conjunto sem interromper, respeitando o tempo.","Só depois confira o gabarito.","Classifique cada erro por motivo.","Separe o que foi falta de conteúdo do que foi falta de estratégia."]'::jsonb, 'Depois de um simulado por área, você descobre que 4 dos 6 erros foram por tempo, não por desconhecimento. A ação passa a ser treino de ritmo.', 'Simulado sem análise é apenas cansaço. E aplicar simulados com frequência alta, sem tempo de estudar entre eles, mede sem ensinar.', 60, '[]'::jsonb, 8);
INSERT INTO simulations (slug, title, description, kind, area_slug, question_count, minutes, blueprint) VALUES ('simulado-linguagens', 'Simulado curto de Linguagens', 'Dez questões de interpretação, gêneros textuais e argumentação, com dificuldade equilibrada.', 'area', 'linguagens', 10, 25, '{"areas":{"linguagens":10},"difficulty":{"intro":3,"intermediate":5,"challenging":2},"topics":{"interpretacao-e-inferencia":4,"generos-textuais-e-funcao-social":4,"tese-e-argumentacao":2}}'::jsonb);
